    async function waitClosedLoopReplyDoneStable(runId, round, options = {}) {
      const requiredStableCount = Math.max(
        1,
        Number(options.requiredStableCount || closedLoopContinueState.replyDoneRequiredStableCount || 3),
      );
      const pollMs = Math.max(500, Number(options.pollMs || 1500));
      const timeoutMs = Math.max(30000, Number(options.timeoutMs || 30 * 60 * 1000));
      const startMs = Date.now();
      let stableCount = 0;
      let lastBusyState = null;
      setClosedLoopPhase(CLOSED_LOOP_PHASES.WAITING_REPLY, {
        reason: 'wait-reply-stable-start',
      });
      closedLoopContinueState.waitingReplySinceMs = startMs;
      closedLoopContinueState.replyDoneStableCount = 0;
      beginClosedLoopReplyWait(`wait-reply-stable-round-${round}`);
      ToolboxShell.appendLog(
        [
          '[CLOSED_LOOP][WAIT_REPLY_STABLE_START]',
          `runId=${runId}`,
          `round=${round}`,
          `requiredStableCount=${requiredStableCount}`,
          `pollMs=${pollMs}`,
          `timeoutMs=${timeoutMs}`,
        ].join(' '),
      );
      while (closedLoopContinueState.running && closedLoopContinueState.runId === runId) {
        const elapsedMs = Date.now() - startMs;
        if (elapsedMs > timeoutMs) {
          ToolboxShell.appendLog(
            [
              '[CLOSED_LOOP][WAIT_REPLY_STABLE_TIMEOUT]',
              `runId=${runId}`,
              `round=${round}`,
              `elapsedMs=${elapsedMs}`,
              `stableCount=${stableCount}`,
            ].join(' '),
          );
          return {
            ok: false,
            reason: 'timeout',
            stableCount,
            elapsedMs,
          };
        }
        const runtime = getClosedLoopComposerRuntimeState(`wait-reply-stable:${round}`);
        const composer = getClosedLoopComposerTextState(`wait-reply-stable:${round}`);
        if (runtime.busy) {
          stableCount = 0;
          closedLoopContinueState.replyDoneStableCount = 0;
          lastBusyState = runtime;
          ToolboxShell.appendLog(
            [
              '[CLOSED_LOOP][WAIT_REPLY_BUSY]',
              `runId=${runId}`,
              `round=${round}`,
              `elapsedMs=${elapsedMs}`,
              'stableCount=0',
              `responseState=${runtime.responseState || '-'}`,
              `responseReason=${runtime.responseReason || '-'}`,
              `stopButton=${runtime.hasStopButton ? 1 : 0}`,
            ].join(' '),
          );
          await sleep(pollMs);
          continue;
        }
        if (!composer.empty) {
          stableCount = 0;
          closedLoopContinueState.replyDoneStableCount = 0;
          ToolboxShell.appendLog(
            [
              '[CLOSED_LOOP][WAIT_REPLY_COMPOSER_NOT_EMPTY]',
              `runId=${runId}`,
              `round=${round}`,
              `elapsedMs=${elapsedMs}`,
              `textLen=${composer.textLen}`,
              `hasUploadPayload=${composer.hasUploadPayload ? 1 : 0}`,
              'action=reset-stable-count',
            ].join(' '),
          );
          await sleep(pollMs);
          continue;
        }
        stableCount += 1;
        closedLoopContinueState.replyDoneStableCount = stableCount;
        closedLoopContinueState.lastReplyDoneCheckMs = Date.now();
        if (runtime.latestTurnId) {
          closedLoopContinueState.lastObservedTurnId = runtime.latestTurnId;
        }
        ToolboxShell.appendLog(
          [
            '[CLOSED_LOOP][WAIT_REPLY_STABLE_TICK]',
            `runId=${runId}`,
            `round=${round}`,
            `stableCount=${stableCount}/${requiredStableCount}`,
            `elapsedMs=${elapsedMs}`,
            `responseState=${runtime.responseState || '-'}`,
            `inputable=${runtime.inputable ? 1 : 0}`,
            `sendable=${runtime.sendable ? 1 : 0}`,
            `turnId=${runtime.latestTurnId || '-'}`,
          ].join(' '),
        );
        if (stableCount >= requiredStableCount) {
          setClosedLoopPhase(CLOSED_LOOP_PHASES.REPLY_DONE_STABLE, {
            reason: 'stable-count-reached',
          });
          ToolboxShell.appendLog(
            [
              '[CLOSED_LOOP][WAIT_REPLY_STABLE_DONE]',
              `runId=${runId}`,
              `round=${round}`,
              `stableCount=${stableCount}`,
              `elapsedMs=${Date.now() - startMs}`,
            ].join(' '),
          );
          return {
            ok: true,
            reason: 'stable-done',
            stableCount,
            elapsedMs: Date.now() - startMs,
            lastBusyState,
          };
        }
        await sleep(pollMs);
      }
      return {
        ok: false,
        reason: 'stopped-or-runid-changed',
        stableCount,
        elapsedMs: Date.now() - startMs,
      };
    }

    async function waitClosedLoopPostReplyDelay(runId, round, delayMs) {
      const safeDelayMs = Math.max(0, Math.min(600000, Math.round(Number(delayMs) || 0)));
      const startMs = Date.now();
      const untilMs = startMs + safeDelayMs;
      closedLoopContinueState.postReplyDelayRunning = true;
      closedLoopContinueState.postReplyDelayStartedAtMs = startMs;
      closedLoopContinueState.postReplyDelayUntilMs = untilMs;
      closedLoopContinueState.postReplyDelayMs = safeDelayMs;
      closedLoopContinueState.nextStepCountdownEndAt = untilMs;
      closedLoopContinueState.nextStepDelayMs = safeDelayMs;
      closedLoopContinueState.waitKind = 'next-step';
      setClosedLoopPhase(CLOSED_LOOP_PHASES.POST_REPLY_DELAY, {
        reason: 'post-reply-delay-start',
      });
      startClosedLoopButtonCountdownTick(`post-reply-delay-round-${round}`);
      ToolboxShell.appendLog(
        [
          '[CLOSED_LOOP][POST_REPLY_DELAY_START]',
          `runId=${runId}`,
          `round=${round}`,
          `delayMs=${safeDelayMs}`,
          `delaySec=${Math.round(safeDelayMs / 1000)}`,
          `untilMs=${untilMs}`,
        ].join(' '),
      );
      while (closedLoopContinueState.running && closedLoopContinueState.runId === runId) {
        const now = Date.now();
        const remainingMs = Math.max(0, untilMs - now);
        if (remainingMs <= 0) {
          break;
        }
        ToolboxShell.appendLog(
          [
            '[CLOSED_LOOP][POST_REPLY_DELAY_TICK]',
            `runId=${runId}`,
            `round=${round}`,
            `remainingMs=${remainingMs}`,
            `remainingSec=${Math.ceil(remainingMs / 1000)}`,
          ].join(' '),
        );
        if (typeof renderClosedLoopContinueButtons === 'function') {
          renderClosedLoopContinueButtons();
        }
        if (typeof scheduleUploadRender === 'function') {
          scheduleUploadRender('closed-loop-post-delay-tick');
        }
        await sleep(Math.min(1000, remainingMs));
      }
      endClosedLoopNextStepWait('post-reply-delay-done');
      closedLoopContinueState.postReplyDelayRunning = false;
      closedLoopContinueState.postReplyDelayUntilMs = 0;
      closedLoopContinueState.postReplyDelayMs = 0;
      if (!closedLoopContinueState.running || closedLoopContinueState.runId !== runId) {
        ToolboxShell.appendLog(
          [
            '[CLOSED_LOOP][POST_REPLY_DELAY_ABORTED]',
            `runId=${runId}`,
            `round=${round}`,
            'reason=stopped-or-runid-changed',
          ].join(' '),
        );
        return {
          ok: false,
          reason: 'stopped-or-runid-changed',
        };
      }
      ToolboxShell.appendLog(
        [
          '[CLOSED_LOOP][POST_REPLY_DELAY_DONE]',
          `runId=${runId}`,
          `round=${round}`,
          `elapsedMs=${Date.now() - startMs}`,
        ].join(' '),
      );
      return {
        ok: true,
        reason: 'delay-done',
        elapsedMs: Date.now() - startMs,
      };
    }

    function checkClosedLoopReadyForNextSend(runId, round, reason = '') {
      const runtime = getClosedLoopComposerRuntimeState(`final-check:${reason || '-'}:${round}`);
      const composer = getClosedLoopComposerTextState(`final-check:${reason || '-'}:${round}`);
      if (runtime.busy) {
        ToolboxShell.appendLog(
          [
            '[CLOSED_LOOP][POST_DELAY_FINAL_CHECK_BUSY]',
            `runId=${runId}`,
            `round=${round}`,
            `responseState=${runtime.responseState || '-'}`,
            `responseReason=${runtime.responseReason || '-'}`,
            `stopButton=${runtime.hasStopButton ? 1 : 0}`,
            'action=back-to-wait-reply',
          ].join(' '),
        );
        return {
          ok: false,
          reason: 'busy',
          runtime,
          composer,
        };
      }
      if (!composer.empty) {
        ToolboxShell.appendLog(
          [
            '[CLOSED_LOOP][POST_DELAY_FINAL_CHECK_COMPOSER_NOT_EMPTY]',
            `runId=${runId}`,
            `round=${round}`,
            `textLen=${composer.textLen}`,
            `hasUploadPayload=${composer.hasUploadPayload ? 1 : 0}`,
            'action=block-next-send',
          ].join(' '),
        );
        return {
          ok: false,
          reason: 'composer-not-empty',
          runtime,
          composer,
        };
      }
      ToolboxShell.appendLog(
        [
          '[CLOSED_LOOP][POST_DELAY_FINAL_CHECK_OK]',
          `runId=${runId}`,
          `round=${round}`,
          `responseState=${runtime.responseState || '-'}`,
          `inputable=${runtime.inputable ? 1 : 0}`,
          `sendable=${runtime.sendable ? 1 : 0}`,
        ].join(' '),
      );
      return {
        ok: true,
        reason: 'ready',
        runtime,
        composer,
      };
    }

    function clearClosedLoopTimersAndLocks(reason = '') {
      if (closedLoopContinueState.nextStepTimer) {
        clearTimeout(closedLoopContinueState.nextStepTimer);
        closedLoopContinueState.nextStepTimer = null;
      }
      if (closedLoopContinueState.timerId) {
        clearTimeout(closedLoopContinueState.timerId);
        closedLoopContinueState.timerId = null;
      }
      closedLoopContinueState.currentStepRunning = false;
      closedLoopContinueState.currentStepToken = '';
      closedLoopContinueState.postReplyDelayRunning = false;
      closedLoopContinueState.postReplyDelayStartedAtMs = 0;
      closedLoopContinueState.postReplyDelayUntilMs = 0;
      closedLoopContinueState.postReplyDelayMs = 0;
      closedLoopContinueState.replyDoneStableCount = 0;
      closedLoopContinueState.waitingReplySinceMs = 0;
      ToolboxShell.appendLog(
        `[CLOSED_LOOP][CLEAR_TIMERS_AND_LOCKS] runId=${closedLoopContinueState.runId || '-'} reason=${reason || '-'}`,
      );
    }

    function guardClosedLoopBeforeSend(runId, round, sourceTag = '') {
      const beforeSendRuntime = getClosedLoopComposerRuntimeState(`before-send:${round}:${sourceTag}`);
      if (beforeSendRuntime.busy) {
        ToolboxShell.appendLog(
          [
            '[CLOSED_LOOP][SEND_BLOCKED_BUSY]',
            `runId=${runId}`,
            `round=${round}`,
            `source=${sourceTag || '-'}`,
            `responseState=${beforeSendRuntime.responseState || '-'}`,
            `responseReason=${beforeSendRuntime.responseReason || '-'}`,
            `stopButton=${beforeSendRuntime.hasStopButton ? 1 : 0}`,
          ].join(' '),
        );
        recoverClosedLoopContinue(runId, 'busy-before-send', {
          delayMs: 5000,
        });
        return false;
      }
      return true;
    }

    function isClosedLoopEveryRoundUploadMode(mode) {
      return String(mode || '').trim() === CLOSED_LOOP_CONTINUE_MODES.WITH_HOTKEY_EVERY_ROUND;
    }

    function getClosedLoopEffectiveUploadInterval(mode, cfg = null) {
      if (isClosedLoopEveryRoundUploadMode(mode)) {
        return 1;
      }
      const closedLoopCfg = cfg && typeof cfg === 'object'
        ? cfg
        : getClosedLoopAutomationConfig();
      const interval = Number(closedLoopCfg.autoUploadInterval || 5);
      return Number.isFinite(interval) && interval > 0 ? Math.floor(interval) : 5;
    }

    function getClosedLoopUploadPolicyText(mode, cfg = null) {
      const interval = getClosedLoopEffectiveUploadInterval(mode, cfg);
      return interval <= 1 ? '每一轮上传' : `每${interval}轮上传`;
    }

    function getClosedLoopStepSourcePolicyTag(mode) {
      return isClosedLoopEveryRoundUploadMode(mode) ? 'every-round' : 'every-n';
    }

    function getClosedLoopStepSourceTag(mode, round) {
      const n = Math.max(0, Number(round) || 0);
      return `closed-loop-${getClosedLoopStepSourcePolicyTag(mode)}-${n}`;
    }

    function isClosedLoopStepSource(sourceText) {
      return /^closed-loop-every(?:5|n|round)-\d+$/.test(String(sourceText || ''));
    }

    function parseClosedLoopStepRound(sourceText) {
      const match = String(sourceText || '').match(/closed-loop-every(?:5|n|round)-(\d+)/);
      return match ? Number(match[1]) || 0 : 0;
    }

    function getClosedLoopUploadFailedSource(useHotkey, round, mode) {
      const uploadEveryRound = isClosedLoopEveryRoundUploadMode(mode);
      if (useHotkey) {
        return round === 1
          ? 'closed-loop-hotkey-initial-upload'
          : (uploadEveryRound ? 'closed-loop-hotkey-every-round-upload' : 'closed-loop-hotkey-every-n-upload');
      }
      return round === 1
        ? 'closed-loop-initial-upload'
        : (uploadEveryRound ? 'closed-loop-every-round-upload' : 'closed-loop-every-n-upload');
    }

    function getClosedLoopButtonLabel(mode) {
      const closedLoopCfg = getClosedLoopAutomationConfig();
      const intervalText = getClosedLoopUploadPolicyText(mode, closedLoopCfg);
      if (mode === CLOSED_LOOP_CONTINUE_MODES.WITHOUT_HOTKEY) {
        return `闭环-仅对话+${intervalText}`;
      }
      return `闭环-快捷键模式+${intervalText}`;
    }

    function getClosedLoopModeLabel(mode) {
      return getClosedLoopButtonLabel(mode);
    }

    function getClosedLoopContinueActionDef(mode) {
      if (mode === CLOSED_LOOP_CONTINUE_MODES.WITHOUT_HOTKEY) {
        return CLOSED_LOOP_CONTINUE_ACTIONS.WITHOUT_HOTKEY;
      }
      if (mode === CLOSED_LOOP_CONTINUE_MODES.WITH_HOTKEY_EVERY_ROUND) {
        return CLOSED_LOOP_CONTINUE_ACTIONS.WITH_HOTKEY_EVERY_ROUND;
      }
      return CLOSED_LOOP_CONTINUE_ACTIONS.WITH_HOTKEY;
    }

    function syncClosedLoopRound(round, reason = '') {
      const value = Math.max(0, Number(round) || 0);
      closedLoopContinueState.round = value;
      closedLoopContinueState.currentRound = value;
      const task = ensureCopyHotkeyUploadVerifyLoopTask();
      task.cycleIndex = value;
      copyHotkeyUploadVerifyLoopCount = value;
      if (reason !== 'retry-current-round') {
        closedLoopContinueState.hotkeyContinueSendFailCount = 0;
        closedLoopContinueState.lastProcessedReplyKey = '';
        closedLoopContinueState.lastProcessedRound = 0;
      }
      if (reason) {
        ToolboxShell.appendLog(`[CLOSED_LOOP][ROUND_SYNC] round=${value} reason=${reason}`);
      }
    }

    function buildClosedLoopContinueButtonsHtml() {
      const hotkeyDef = CLOSED_LOOP_CONTINUE_ACTIONS.WITH_HOTKEY;
      const everyRoundDef = CLOSED_LOOP_CONTINUE_ACTIONS.WITH_HOTKEY_EVERY_ROUND;
      const plainDef = CLOSED_LOOP_CONTINUE_ACTIONS.WITHOUT_HOTKEY;
      const everyRoundModeAttr = everyRoundDef.datasetClosedLoopMode
        ? ` data-closed-loop-mode="${everyRoundDef.datasetClosedLoopMode}"`
        : '';
      const plainModeAttr = plainDef.datasetClosedLoopMode
        ? ` data-closed-loop-mode="${plainDef.datasetClosedLoopMode}"`
        : '';
      return `
            <button type="button" class="${hotkeyDef.className}" id="${hotkeyDef.id}" data-action="${hotkeyDef.action}" title="${hotkeyDef.title}">${getClosedLoopModeLabel(CLOSED_LOOP_CONTINUE_MODES.WITH_HOTKEY)}</button>
            <button type="button" class="${everyRoundDef.className}" id="${everyRoundDef.id}" data-action="${everyRoundDef.action}"${everyRoundModeAttr} title="${everyRoundDef.title}">${getClosedLoopModeLabel(CLOSED_LOOP_CONTINUE_MODES.WITH_HOTKEY_EVERY_ROUND)}</button>
            <button type="button" class="${plainDef.className}" id="${plainDef.id}" data-action="${plainDef.action}"${plainModeAttr} title="${plainDef.title}">${getClosedLoopModeLabel(CLOSED_LOOP_CONTINUE_MODES.WITHOUT_HOTKEY)}</button>`;
    }

    function applyClosedLoopContinueButtonDef(btn, actionDef) {
      if (!(btn instanceof HTMLElement) || !actionDef) {
        return;
      }
      btn.id = actionDef.id;
      btn.dataset.action = actionDef.action;
      btn.dataset.cgptBaseAction = actionDef.action;
      btn.textContent = getClosedLoopModeLabel(actionDef.mode);
      btn.title = actionDef.title;
      if (actionDef.datasetClosedLoopMode) {
        btn.dataset.closedLoopMode = actionDef.datasetClosedLoopMode;
      }
      const CLOSED_LOOP_STRIP_CLASSES = [
        'cyan',
        'purple',
        'teal',
        'green',
        'primary',
        'warning',
        'orange',
        'cgpt-btn-copy-hotkey',
        'cgpt-btn-upload',
        'cgpt-auto-continue',
        'cgpt-btn-danger',
        'cgpt-btn-stop',
        'cgpt-action-running',
        'cgpt-btn-closed-loop-idle',
      ];
      CLOSED_LOOP_STRIP_CLASSES.forEach((cls) => btn.classList.remove(cls));
      btn.dataset.cgptButtonGroup = 'closed-loop';
      String(actionDef.className || 'cgpt-btn cyan cgpt-btn-closed-loop cgpt-btn-closed-loop-idle')
        .split(/\s+/)
        .map((cls) => cls.trim())
        .filter(Boolean)
        .forEach((cls) => btn.classList.add(cls));
    }

    function isClosedLoopUserCancelledReason(reason) {
      const text = String(reason || '').trim().toLowerCase();
      if (!text) {
        return false;
      }
      return (
        text === 'cancelled'
        || text.includes('cancelled')
        || text.includes('user-stop')
        || text.includes('user_stop')
        || text.includes('button-toggle')
      );
    }

    const CLOSED_LOOP_PHASES = Object.freeze({
      IDLE: 'idle',
      SENDING: 'sending',
      WAITING_REPLY: 'waiting_reply',
      REPLY_DONE_STABLE: 'reply_done_stable',
      POST_REPLY_DELAY: 'post_reply_delay',
      READY_NEXT_ROUND: 'ready_next_round',
      STOPPING: 'stopping',
    });

    const CLOSED_LOOP_DEFAULT_CONTINUE_TEXT = '继续';

    const closedLoopContinueState = {
      running: false,
      stopping: false,
      cancelRequested: false,
      cancelReason: '',
      phase: CLOSED_LOOP_PHASES.IDLE,
      runId: 0,
      timerId: null,
      nextStepTimer: null,
      retryTimerId: null,
      retryAttempts: 0,
      round: 0,
      currentRound: 0,
      currentStepRunning: false,
      currentStepToken: '',
      lastReason: '',
      mode: CLOSED_LOOP_CONTINUE_MODES.WITH_HOTKEY,
      doneVerificationRunning: false,
      doneVerificationSent: false,
      doneVerificationRound: 0,
      homeNavigationRunning: false,
      lastHomeNavigationRound: 0,
      sendFailedStreak: 0,
      hotkeyContinueSendFailCount: 0,
      finishFinalStatus: '',
      retryingCurrentRound: false,
      lastProcessedReplyKey: '',
      lastProcessedRound: 0,
      waitingReplySinceMs: 0,
      replyDoneStableCount: 0,
      replyDoneRequiredStableCount: 3,
      lastReplyDoneCheckMs: 0,
      lastObservedTurnId: '',
      lastSentTurnId: '',
      lastSentAtMs: 0,
      lastSendRound: 0,
      postReplyDelayRunning: false,
      postReplyDelayStartedAtMs: 0,
      postReplyDelayUntilMs: 0,
      postReplyDelayMs: 0,
      lastScheduleReason: '',
      lastScheduleAtMs: 0,
      waitKind: 'idle',
      waitStartedAt: 0,
      nextStepDelayMs: 0,
      nextStepCountdownEndAt: 0,
      countdownTickTimer: 0,
      lastReplyWaitLogSec: -1,
      startPending: null,
    };

    function getClosedLoopStartPending() {
      const pending = closedLoopContinueState.startPending;
      return pending && typeof pending === 'object' ? pending : null;
    }

    function setClosedLoopStartPending(mode, source = 'button') {
      const normalizedMode = String(mode || CLOSED_LOOP_CONTINUE_MODES.WITH_HOTKEY).trim()
        || CLOSED_LOOP_CONTINUE_MODES.WITH_HOTKEY;
      const action = getCurrentClosedLoopOwnerActionForMode(normalizedMode);
      const responseReason = (() => {
        try {
          if (typeof detectComposerResponseState === 'function') {
            const snap = detectComposerResponseState({ light: true, reason: 'closed-loop-start-pending' }) || {};
            return String(snap.response_state_reason || snap.responseStateReason || 'assistant_busy').trim()
              || 'assistant_busy';
          }
        } catch (detectErr) {
          console.error('[CLOSED_LOOP][START_PENDING_DETECT_FAILED]', detectErr);
        }
        return 'assistant_busy';
      })();
      closedLoopContinueState.startPending = {
        mode: normalizedMode,
        action,
        source: String(source || 'button').trim() || 'button',
        createdAt: Date.now(),
        reason: responseReason,
      };
      ToolboxShell.appendLog(
        `[CLOSED_LOOP][WAIT_CURRENT_REPLY_BEFORE_START] action=${action} reason=${responseReason}`,
      );
      setStatus('页面正在回复，已排队等待回复完成后启动闭环', 'running');
      renderClosedLoopContinueButtons();
      startClosedLoopStartPendingWatcher('set-closed-loop-start-pending');
    }

    function clearClosedLoopStartPending(reason = '-') {
      const old = getClosedLoopStartPending();
      closedLoopContinueState.startPending = null;
      if (old) {
        ToolboxShell.appendLog(
          `[CLOSED_LOOP][START_PENDING_CLEAR] action=${old.action || '-'} reason=${String(reason || '-')}`,
        );
      }
      stopClosedLoopStartPendingWatcher(`clear:${reason}`);
      renderClosedLoopContinueButtons();
    }

    function getCurrentClosedLoopOwnerActionForMode(mode) {
      const normalizedMode = String(mode || '').trim();
      if (normalizedMode === CLOSED_LOOP_CONTINUE_MODES.WITH_HOTKEY_EVERY_ROUND) {
        return 'closed-loop-with-hotkey-upload-every-round';
      }
      if (normalizedMode === CLOSED_LOOP_CONTINUE_MODES.WITHOUT_HOTKEY) {
        return 'closed-loop-without-hotkey';
      }
      return 'closed-loop-with-hotkey';
    }

    function startClosedLoopStartPendingWatcher(reason = '-') {
      startSendLikePendingWatcher(`closed-loop-pending:${reason}`);
    }

    function stopClosedLoopStartPendingWatcher(reason = '-') {
      stopSendLikePendingWatcher(`closed-loop-pending:${reason}`);
    }

    async function flushClosedLoopStartPendingIfReady(reason = '-') {
      const pending = getClosedLoopStartPending();
      if (!pending) {
        return;
      }
      if (closedLoopContinueState.running) {
        clearClosedLoopStartPending('already-running');
        return;
      }
      if (isAssistantGeneratingNow('closed-loop-start-pending-flush', { skipDetectComposerState: false })) {
        return;
      }
      const action = String(pending.action || getCurrentClosedLoopOwnerActionForMode(pending.mode)).trim();
      clearClosedLoopStartPending(`flush-ready:${reason}`);
      ToolboxShell.appendLog(
        `[CLOSED_LOOP][START_AFTER_REPLY_DONE] action=${action}`,
      );
      await startClosedLoopContinue({
        reason: pending.source || `pending-flush:${reason}`,
        mode: pending.mode,
      });
    }

    function isPageGeneratingForClosedLoopStart(snapshot = null) {
      const snap = snapshot && typeof snapshot === 'object'
        ? snapshot
        : buildUploadButtonRenderSnapshot();
      if (
        typeof ClosedLoopButtonVm !== 'undefined'
        && typeof ClosedLoopButtonVm.isPageGeneratingForClosedLoop === 'function'
      ) {
        return ClosedLoopButtonVm.isPageGeneratingForClosedLoop(snap);
      }
      return snap.assistantBusy === true || snap.pageGenerating === true;
    }

    function isClosedLoopButtonDomVisible(btn) {
      if (!(btn instanceof HTMLElement)) {
        return false;
      }
      const style = window.getComputedStyle(btn);
      return style.display !== 'none' && style.visibility !== 'hidden';
    }

    function setClosedLoopPhase(phase, meta = {}) {
      const prev = closedLoopContinueState.phase || CLOSED_LOOP_PHASES.IDLE;
      closedLoopContinueState.phase = phase;
      ToolboxShell.appendLog(
        [
          '[CLOSED_LOOP][PHASE]',
          `prev=${prev}`,
          `next=${phase}`,
          `runId=${closedLoopContinueState.runId || '-'}`,
          `round=${Number(closedLoopContinueState.currentRound || closedLoopContinueState.round || 0)}`,
          `reason=${meta.reason || '-'}`,
        ].join(' '),
      );
    }

    function getClosedLoopRunningButtonText(baseStopText = '停止闭环继续') {
      const now = Date.now();
      const phase = closedLoopContinueState.phase;
      if (
        phase === CLOSED_LOOP_PHASES.POST_REPLY_DELAY
        && closedLoopContinueState.postReplyDelayUntilMs > now
      ) {
        const remainSec = Math.max(
          0,
          Math.ceil((closedLoopContinueState.postReplyDelayUntilMs - now) / 1000),
        );
        return `${baseStopText}（等待 ${remainSec}s）`;
      }
      if (
        phase === CLOSED_LOOP_PHASES.WAITING_REPLY
        && closedLoopContinueState.waitingReplySinceMs > 0
      ) {
        const elapsedSec = Math.max(
          0,
          Math.floor((now - closedLoopContinueState.waitingReplySinceMs) / 1000),
        );
        return `${baseStopText}（回复中 ${elapsedSec}s）`;
      }
      if (phase === CLOSED_LOOP_PHASES.REPLY_DONE_STABLE) {
        return `${baseStopText}（确认完成）`;
      }
      if (phase === CLOSED_LOOP_PHASES.SENDING) {
        return `${baseStopText}（发送中）`;
      }
      return baseStopText;
    }

    function normalizeClosedLoopActionName(action) {
      return String(action || '').trim();
    }

    function isClosedLoopStartAction(action) {
      const name = normalizeClosedLoopActionName(action);
      return name === 'closed-loop-with-hotkey'
        || name === 'closed-loop-with-hotkey-upload-every-round'
        || name === 'closed-loop-without-hotkey';
    }

    function getCurrentClosedLoopOwnerAction() {
      const mode = String(closedLoopContinueState.mode || '').trim();
      if (mode === CLOSED_LOOP_CONTINUE_MODES.WITH_HOTKEY_EVERY_ROUND) {
        return 'closed-loop-with-hotkey-upload-every-round';
      }
      if (mode === CLOSED_LOOP_CONTINUE_MODES.WITHOUT_HOTKEY) {
        return 'closed-loop-without-hotkey';
      }
      if (mode === CLOSED_LOOP_CONTINUE_MODES.WITH_HOTKEY) {
        return 'closed-loop-with-hotkey';
      }
      return '';
    }

    function isCurrentClosedLoopStopClick(action, target = null) {
      if (closedLoopContinueState.running !== true) {
        return false;
      }
      const button = target instanceof HTMLElement ? target : null;
      const resolvedAction = normalizeClosedLoopActionName(action);
      const isClosedLoopBtn = (
        typeof UploadButtonVm !== 'undefined'
        && typeof UploadButtonVm.isClosedLoopModeButton === 'function'
        && (
          UploadButtonVm.isClosedLoopModeButton(button)
          || UploadButtonVm.isClosedLoopModeButton(resolvedAction)
        )
      );
      if (!isClosedLoopBtn) {
        return false;
      }
      const id = button && button.id ? String(button.id) : '';
      if (
        closedLoopContinueState.mode === CLOSED_LOOP_CONTINUE_MODES.WITH_HOTKEY_EVERY_ROUND
        && id === 'cgpt-closed-loop-upload-every-round-hotkey-btn'
      ) {
        return true;
      }
      if (
        closedLoopContinueState.mode === CLOSED_LOOP_CONTINUE_MODES.WITH_HOTKEY
        && id === 'cgpt-closed-loop-upload-every5-hotkey-btn'
      ) {
        return true;
      }
      if (
        closedLoopContinueState.mode === CLOSED_LOOP_CONTINUE_MODES.WITHOUT_HOTKEY
        && id === 'cgpt-closed-loop-upload-every5-btn'
      ) {
        return true;
      }
      return false;
    }

    function shouldStopClosedLoopRun(runId) {
      return closedLoopContinueState.running !== true
        || closedLoopContinueState.cancelRequested === true
        || Number(closedLoopContinueState.runId || 0) !== Number(runId || 0);
    }

    function tryInterceptClosedLoopStopClick(action, button, source, event) {
      const resolvedAction = normalizeClosedLoopActionName(action);
      if (!isCurrentClosedLoopStopClick(resolvedAction, button)) {
        return false;
      }
      if (event && typeof event.preventDefault === 'function') {
        event.preventDefault();
      }
      if (event && typeof event.stopPropagation === 'function') {
        event.stopPropagation();
      }
      if (event && typeof event.stopImmediatePropagation === 'function') {
        event.stopImmediatePropagation();
      }
      ToolboxShell.appendLog(
        `[CLOSED_LOOP][STOP_BUTTON_CLICK] action=${resolvedAction || '-'} id=${button && button.id ? button.id : '-'} mode=${closedLoopContinueState.mode || '-'} source=${source || '-'}`,
      );
      stopClosedLoopContinue('button-click-stop');
      return true;
    }

    function getClosedLoopWaitVisualSnapshot() {
      const running = closedLoopContinueState.running === true;
      const phase = closedLoopContinueState.phase || CLOSED_LOOP_PHASES.IDLE;
      let waitKind = closedLoopContinueState.waitKind || 'idle';
      const now = Date.now();

      let replyWaitElapsedMs = 0;
      let nextStepRemainingMs = 0;
      let postReplyDelayRemainingMs = 0;

      if (
        running
        && phase === CLOSED_LOOP_PHASES.WAITING_REPLY
        && closedLoopContinueState.waitingReplySinceMs > 0
      ) {
        waitKind = 'reply';
        replyWaitElapsedMs = Math.max(0, now - closedLoopContinueState.waitingReplySinceMs);
      } else if (running && waitKind === 'reply' && closedLoopContinueState.waitStartedAt > 0) {
        replyWaitElapsedMs = Math.max(0, now - closedLoopContinueState.waitStartedAt);
      }

      if (
        running
        && phase === CLOSED_LOOP_PHASES.POST_REPLY_DELAY
        && closedLoopContinueState.postReplyDelayUntilMs > now
      ) {
        waitKind = 'next-step';
        postReplyDelayRemainingMs = Math.max(
          0,
          closedLoopContinueState.postReplyDelayUntilMs - now,
        );
        nextStepRemainingMs = postReplyDelayRemainingMs;
      } else if (running && waitKind === 'next-step' && closedLoopContinueState.nextStepCountdownEndAt > 0) {
        nextStepRemainingMs = Math.max(0, closedLoopContinueState.nextStepCountdownEndAt - now);
        postReplyDelayRemainingMs = nextStepRemainingMs;
      }

      return {
        running,
        waitKind,
        phase,
        replyWaitElapsedMs,
        nextStepDelayMs: Math.max(0, Number(closedLoopContinueState.nextStepDelayMs || 0)),
        nextStepRemainingMs,
        postReplyDelayRemainingMs,
        runningButtonText: running ? getClosedLoopRunningButtonText() : '',
      };
    }

    function clearClosedLoopButtonWaitState(reason = 'unknown') {
      const src = String(reason || 'unknown').trim() || 'unknown';
      if (closedLoopContinueState.waitKind === 'next-step') {
        endClosedLoopNextStepWait(`clear:${src}`);
        return;
      }
      if (closedLoopContinueState.countdownTickTimer) {
        clearInterval(closedLoopContinueState.countdownTickTimer);
        closedLoopContinueState.countdownTickTimer = 0;
      }
      closedLoopContinueState.waitKind = 'idle';
      closedLoopContinueState.waitStartedAt = 0;
      closedLoopContinueState.nextStepDelayMs = 0;
      closedLoopContinueState.nextStepCountdownEndAt = 0;
      closedLoopContinueState.lastReplyWaitLogSec = -1;
    }

    function startClosedLoopButtonCountdownTick(reason = 'closed-loop-button-countdown') {
      if (closedLoopContinueState.countdownTickTimer) {
        clearInterval(closedLoopContinueState.countdownTickTimer);
        closedLoopContinueState.countdownTickTimer = 0;
      }

      closedLoopContinueState.countdownTickTimer = setInterval(() => {
        if (closedLoopContinueState.running !== true) {
          clearInterval(closedLoopContinueState.countdownTickTimer);
          closedLoopContinueState.countdownTickTimer = 0;
          return;
        }

        if (
          closedLoopContinueState.waitKind !== 'reply'
          && closedLoopContinueState.waitKind !== 'next-step'
        ) {
          clearInterval(closedLoopContinueState.countdownTickTimer);
          closedLoopContinueState.countdownTickTimer = 0;
          return;
        }

        if (closedLoopContinueState.waitKind === 'next-step') {
          const remainingMs = Math.max(
            0,
            Number(closedLoopContinueState.nextStepCountdownEndAt || 0) - Date.now(),
          );
          const secText = (remainingMs / 1000).toFixed(1);
          ToolboxShell.appendLog(
            `[CLOSED_LOOP][WAIT_VISUAL_COUNTDOWN_TICK] remainingMs=${remainingMs} runId=${closedLoopContinueState.runId || '-'} round=${closedLoopContinueState.round || 0}`,
          );
          ToolboxShell.appendLog(
            `停止闭环继续（等待下一轮 ${secText}s）`,
          );
        } else if (closedLoopContinueState.waitKind === 'reply') {
          const elapsedMs = Math.max(
            0,
            Date.now() - Number(closedLoopContinueState.waitStartedAt || 0),
          );
          const sec = Math.floor(elapsedMs / 1000);
          if (sec !== closedLoopContinueState.lastReplyWaitLogSec) {
            closedLoopContinueState.lastReplyWaitLogSec = sec;
            ToolboxShell.appendLog(`停止闭环继续（回复中 ${sec}s）`);
          }
        }

        if (typeof renderClosedLoopContinueButtons === 'function') {
          renderClosedLoopContinueButtons();
        }
      }, 500);
    }

    function beginClosedLoopReplyWait(reason = 'unknown') {
      if (closedLoopContinueState.running !== true) {
        return;
      }
      const src = String(reason || 'unknown').trim() || 'unknown';
      closedLoopContinueState.waitKind = 'reply';
      closedLoopContinueState.waitStartedAt = Date.now();
      closedLoopContinueState.nextStepDelayMs = 0;
      closedLoopContinueState.nextStepCountdownEndAt = 0;
      ToolboxShell.appendLog(
        `[CLOSED_LOOP][WAIT_VISUAL_REPLY_START] reason=${src} runId=${closedLoopContinueState.runId || '-'} round=${closedLoopContinueState.round || 0}`,
      );
      startClosedLoopButtonCountdownTick(`reply-${src}`);
      renderClosedLoopContinueButtons();
    }

    function endClosedLoopReplyWait(reason = 'unknown') {
      if (closedLoopContinueState.waitKind !== 'reply') {
        return;
      }
      const src = String(reason || 'unknown').trim() || 'unknown';
      closedLoopContinueState.waitKind = 'idle';
      closedLoopContinueState.waitStartedAt = 0;
      ToolboxShell.appendLog(
        `[CLOSED_LOOP][REPLY_WAIT_END] reason=${src} runId=${closedLoopContinueState.runId || '-'} round=${closedLoopContinueState.round || 0}`,
      );
    }

    function endClosedLoopNextStepWait(reason = 'unknown') {
      if (closedLoopContinueState.waitKind !== 'next-step') {
        return;
      }
      const src = String(reason || 'unknown').trim() || 'unknown';
      const runId = closedLoopContinueState.runId || '-';
      const round = closedLoopContinueState.round || 0;
      ToolboxShell.appendLog(
        `[CLOSED_LOOP][WAIT_VISUAL_COUNTDOWN_END] runId=${runId} round=${round} reason=${src}`,
      );
      if (closedLoopContinueState.countdownTickTimer) {
        clearInterval(closedLoopContinueState.countdownTickTimer);
        closedLoopContinueState.countdownTickTimer = 0;
      }
      closedLoopContinueState.waitKind = 'idle';
      closedLoopContinueState.waitStartedAt = 0;
      closedLoopContinueState.nextStepDelayMs = 0;
      closedLoopContinueState.nextStepCountdownEndAt = 0;
    }

    function beginClosedLoopNextStepWait(delayMs, reason = 'unknown') {
      if (closedLoopContinueState.running !== true) {
        return;
      }
      const src = String(reason || 'unknown').trim() || 'unknown';
      const waitMs = Math.max(0, Number(delayMs || 0));
      const runId = closedLoopContinueState.runId || '-';
      const round = closedLoopContinueState.round || 0;
      closedLoopContinueState.waitKind = 'next-step';
      closedLoopContinueState.waitStartedAt = Date.now();
      closedLoopContinueState.nextStepDelayMs = waitMs;
      closedLoopContinueState.nextStepCountdownEndAt = Date.now() + waitMs;
      setCopyHotkeyUploadVerifyLoopPhase('post_reply_delay', `next-step:${src}`, {
        cycleIndex: round,
        currentSubtask: 'post-reply-delay',
      });
      ToolboxShell.appendLog(
        `[CLOSED_LOOP][WAIT_VISUAL_COUNTDOWN_START] delayMs=${waitMs} runId=${runId} round=${round} reason=${src}`,
      );
      const initialSec = (waitMs / 1000).toFixed(1);
      ToolboxShell.appendLog(`停止闭环继续（等待下一轮 ${initialSec}s）`);
      startClosedLoopButtonCountdownTick(`next-step-${src}`);
      renderClosedLoopContinueButtons();
      if (typeof renderUploadButtonsOnly === 'function') {
        renderUploadButtonsOnly({
          immediate: true,
          force: true,
          buttonTasksReason: `post-reply-delay-start:${src}`,
        });
      }
    }

    function syncToolboxRunningOwner(source = '') {
      const src = String(source || 'sync').trim() || 'sync';
      if (closedLoopContinueState.running || closedLoopContinueState.stopping) {
        const mode = closedLoopContinueState.mode || CLOSED_LOOP_CONTINUE_MODES.WITH_HOTKEY;
        const actionDef = getClosedLoopContinueActionDef(mode);
        window.__cgptToolboxRunningOwner = {
          action: actionDef.action,
          buttonId: actionDef.buttonId || actionDef.id,
          taskKey: 'copyHotkeyUploadVerifyLoop',
          runId: closedLoopContinueState.runId,
        };
        return window.__cgptToolboxRunningOwner;
      }

      if (
        typeof window !== 'undefined'
        && window.__cgptToolboxRunningOwner
        && String(window.__cgptToolboxRunningOwner.taskKey || '') === 'copyHotkeyUploadVerifyLoop'
      ) {
        window.__cgptToolboxRunningOwner = null;
        ToolboxShell.appendLog(`[BUTTON_COLOR][RUNNING_OWNER_CLEAR] source=${src}`);
      }
      return null;
    }

    const autoContinueUnifiedHomeState = {
      active: false,
      mode: '',
      round: 0,
      prevWaitingReply: false,
      homeNavigationRunning: false,
      skipNextHomeCheck: false,
    };

    function resolveDefaultDoneSignal() {
      if (typeof getDefaultDoneSignal === 'function') {
        return getDefaultDoneSignal();
      }
      if (typeof DEFAULT_BATCH_DONE_SIGNAL === 'string' && DEFAULT_BATCH_DONE_SIGNAL) {
        return DEFAULT_BATCH_DONE_SIGNAL;
      }
      if (typeof DEFAULT_COPY_HOTKEY_CONTINUE_STOP_SIGNAL === 'string' && DEFAULT_COPY_HOTKEY_CONTINUE_STOP_SIGNAL) {
        return DEFAULT_COPY_HOTKEY_CONTINUE_STOP_SIGNAL;
      }
      return '<<<XZ_TOOLBOX_BATCH_TASK_STOP_7F3B9C>>>';
    }

    let uploadUiActionLastKey = '';
    let uploadUiActionLastAt = 0;

    /**
     * 上传区域动作级防抖记录。
     *
     * 用途：
     * 1. 防止 delegated-click、mousedown、pointerdown 等事件重复触发同一个上传动作。
     * 2. 防止开始上传、发送、自动继续等按钮在极短时间内重复进入流程。
     * 3. 必须定义在 UploadModule 闭包内，否则 shouldSkipAction() 会抛 ReferenceError。
     */

    let quickPromptActiveCategory = typeof PromptCategoryState !== 'undefined'
      && typeof PromptCategoryState.getActiveCategory === 'function'
      ? PromptCategoryState.getActiveCategory()
      : '全部';
    let lastManualUploadGroupAt = 0;

    const COPY_HOTKEY_CONTINUE_CANCELLABLE_PHASES = new Set([
      'waiting_reply',
      'copying',
      'sending_hotkey',
      'sending_continue',
    ]);
    const COPY_HOTKEY_ONCE_CANCELLABLE_PHASES = new Set([
      'waiting_reply',
      'copying',
      'confirming_clipboard',
      'sending_hotkey',
    ]);

    const COPY_HOTKEY_LOOP_STOP_PHASES = new Set([
      'running',
      'waiting_reply',
      'copying',
      'sending_hotkey',
      'sending_continue',
      'waiting_next_reply',
      'auto_uploading',
      'home_navigation',
    ]);

    function createUploadTaskRunId(prefix = 'task') {
      if (typeof ButtonTasks !== 'undefined' && typeof ButtonTasks.createTaskRunId === 'function') {
        return ButtonTasks.createTaskRunId(prefix);
      }
      return `${String(prefix || 'task')}_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
    }

    function haltClosedLoopCompanionAutomation(source = 'unknown') {
      const src = String(source || 'unknown').trim() || 'unknown';

      if (
        typeof AutoQueueModule !== 'undefined'
        && AutoQueueModule
        && typeof AutoQueueModule.getState === 'function'
        && typeof AutoQueueModule.stop === 'function'
      ) {
        const autoState = AutoQueueModule.getState();
        if (autoState && (autoState.running || autoState.waitingReply)) {
          AutoQueueModule.stop({ reason: `closed-loop-stop:${src}`, logStop: true });
          ToolboxShell.appendLog(`[CLOSED_LOOP][AUTO_CONTINUE_STOP] source=${src}`);
          if (typeof refreshUploadAutoContinueButton === 'function') {
            refreshUploadAutoContinueButton(`closed-loop-stop:${src}`);
          }
        }
      }

      if (isCopyHotkeyContinueActive()) {
        cancelCopyHotkeyContinue(`closed-loop-stop:${src}`);
      }

      if (state.waitingReply) {
        stopWaitingReplyCheck();
        ToolboxShell.appendLog(`[CLOSED_LOOP][WAITING_REPLY_STOP] source=${src}`);
      }

      if (uploadTimers.has('upload-render', 'raf')) {
        uploadTimers.clearRaf('upload-render');
        ToolboxShell.appendLog(`[CLOSED_LOOP][TIMER_STOP] name=upload-render source=${src}`);
      }
    }

    function invalidateCopyHotkeyContinueLoopRun(source = 'unknown') {
      const src = String(source || 'unknown').trim() || 'unknown';
      const task = ensureCopyHotkeyContinueLoopTask();
      const previousRunId = task.runId || '-';

      copyHotkeyContinueLoopRunGeneration += 1;
      copyHotkeyContinueLoopStopRequested = true;
      task.stopRequested = true;
      task.runId = createUploadTaskRunId('copy_hotkey_loop_stopped');

      if (task.abortController && typeof task.abortController.abort === 'function') {
        task.abortController.abort();
        task.abortController = null;
      }

      ToolboxShell.appendLog(
        `[COPY_HOTKEY_CONTINUE_LOOP][RUN_INVALIDATED] source=${src}`
        + ` previousRunId=${previousRunId}`
        + ` nextRunId=${task.runId}`
        + ` runGen=${copyHotkeyContinueLoopRunGeneration}`,
      );

      return copyHotkeyContinueLoopRunGeneration;
    }

    function buildCopyHotkeyContinueLoopShouldStop(runId) {
      const expectedRunId = String(runId || '').trim();
      const loopTask = ensureCopyHotkeyContinueLoopTask();

      return () => !!(
        copyHotkeyContinueLoopStopRequested
        || loopTask.stopRequested
        || (expectedRunId && loopTask.runId !== expectedRunId)
      );
    }

    function abortCopyHotkeyContinueLoopAtCheckpoint(runId, checkpoint, source = '') {
      const shouldStop = buildCopyHotkeyContinueLoopShouldStop(runId);
      if (!shouldStop()) {
        return false;
      }

      const loopTask = ensureCopyHotkeyContinueLoopTask();
      ToolboxShell.appendLog(
        `[COPY_HOTKEY_CONTINUE_LOOP][ABORT] checkpoint=${checkpoint || '-'}`
        + ` source=${source || '-'}`
        + ` expectedRunId=${runId || '-'}`
        + ` currentRunId=${loopTask.runId || '-'}`
        + ` runGen=${copyHotkeyContinueLoopRunGeneration}`
        + ` stopRequested=${copyHotkeyContinueLoopStopRequested || loopTask.stopRequested ? 1 : 0}`,
      );
      return true;
    }

    function ensureSendHotkeyTask() {
      if (!state.sendHotkeyTask || typeof state.sendHotkeyTask !== 'object') {
        state.sendHotkeyTask = { phase: 'idle', runId: '', lastError: null };
      }
      return state.sendHotkeyTask;
    }

    function setSendHotkeyPhase(phase, reason = '') {
      const task = ensureSendHotkeyTask();
      const normalized = String(phase || 'idle').trim().toLowerCase();
      task.phase = normalized;
      if (reason) {
        task.lastReason = String(reason);
      }
      scheduleRenderUpload(`sendHotkey:${normalized}:${reason || '-'}`);
    }

    async function runSendHotkeyOnce(source = 'unknown') {
      const src = String(source || 'unknown').trim() || 'unknown';
      const task = ensureSendHotkeyTask();

      if (task.phase === 'sending_hotkey') {
        ToolboxShell.appendLog(`[SEND_HOTKEY][skip] source=${src} reason=already-running runId=${task.runId || '-'}`);
        return { ok: false, reason: 'already-running' };
      }

      const runId = createUploadTaskRunId('send_hotkey');
      task.runId = runId;
      task.lastError = null;
      setSendHotkeyPhase('sending_hotkey', src);

      try {
        const ok = await triggerSendHotkeyOnce();
        if (task.runId !== runId) {
          return { ok: false, reason: 'stale-run' };
        }
        if (ok) {
          setSendHotkeyPhase('success', src);
          window.setTimeout(() => {
            if (state.sendHotkeyTask && state.sendHotkeyTask.runId === runId) {
              state.sendHotkeyTask.runId = '';
              setSendHotkeyPhase('idle', 'success-reset');
            }
          }, 1200);
          return { ok: true, reason: 'ok' };
        }

        task.lastError = 'hotkey-failed';
        setSendHotkeyPhase('failed', src);
        window.setTimeout(() => {
          if (state.sendHotkeyTask && state.sendHotkeyTask.runId === runId) {
            state.sendHotkeyTask.runId = '';
            setSendHotkeyPhase('idle', 'failed-reset');
          }
        }, 1500);
        return { ok: false, reason: 'hotkey-failed' };
      } catch (error) {
        const errText = formatToolboxError(error);
        console.error('[SEND_HOTKEY][FAILED]', {
          source: src,
          error_type: error && error.name,
          error: errText,
          stack: error && error.stack,
        });
        if (task.runId === runId) {
          task.lastError = errText;
          setSendHotkeyPhase('failed', src);
          window.setTimeout(() => {
            if (state.sendHotkeyTask && state.sendHotkeyTask.runId === runId) {
              state.sendHotkeyTask.runId = '';
              setSendHotkeyPhase('idle', 'failed-reset');
            }
          }, 1500);
        }
        ToolboxShell.appendLog(`[SEND_HOTKEY][FAILED] source=${src} error=${errText}`);
        setStatus(`发送 Ctrl+Alt+I 失败：${errText}`, 'error');
        return { ok: false, reason: 'exception', detail: errText };
      }
    }

    function ensureHomeTask() {
      if (!state.homeTask || typeof state.homeTask !== 'object') {
        state.homeTask = { phase: 'idle', runId: '', lastError: null };
      }
      return state.homeTask;
    }

    function setHomePhase(phase, reason = '') {
      const task = ensureHomeTask();
      let normalized = String(phase || 'idle').trim().toLowerCase();
      if (normalized === 'jumping') {
        normalized = 'running';
      }
      task.phase = normalized;
      if (reason) {
        task.lastReason = String(reason);
      }
      scheduleRenderUpload(`home:${normalized}:${reason || '-'}`);
    }

    async function runGoHomeOnce(source = 'unknown', navOptions = {}) {
      const src = String(source || 'unknown').trim() || 'unknown';
      const navOpts = navOptions && typeof navOptions === 'object' ? navOptions : {};
      const task = ensureHomeTask();

      if (task.phase === 'running') {
        ToolboxShell.appendLog(`[HOME][skip] source=${src} reason=already-running runId=${task.runId || '-'}`);
        return { ok: false, reason: 'already-running' };
      }

      const runId = createUploadTaskRunId('home');
      task.runId = runId;
      task.lastError = null;
      setHomePhase('running', src);

      try {
        const result = await goHomeByClickNewChat(src, navOpts);
        if (task.runId !== runId) {
          return result;
        }
        if (result && result.ok) {
          setHomePhase('success', src);
          window.setTimeout(() => {
            if (state.homeTask && state.homeTask.runId === runId) {
              state.homeTask.runId = '';
              setHomePhase('idle', 'success-reset');
            }
          }, 1200);
        } else {
          task.lastError = result && result.reason ? String(result.reason) : 'failed';
          setHomePhase('failed', src);
          window.setTimeout(() => {
            if (state.homeTask && state.homeTask.runId === runId) {
              state.homeTask.runId = '';
              setHomePhase('idle', 'failed-reset');
            }
          }, 1500);
        }
        return result;
      } catch (error) {
        const errText = formatToolboxError(error);
        console.error('[HOME][FAILED]', { source: src, error: errText, stack: error && error.stack });
        if (task.runId === runId) {
          task.lastError = errText;
          setHomePhase('failed', src);
          window.setTimeout(() => {
            if (state.homeTask && state.homeTask.runId === runId) {
              state.homeTask.runId = '';
              setHomePhase('idle', 'failed-reset');
            }
          }, 1500);
        }
        ToolboxShell.appendLog(`[HOME][FAILED] source=${src} error=${errText}`);
        setStatus(`回到首页失败：${errText}`, 'error');
        return { ok: false, reason: 'exception', detail: errText };
      } finally {
        scheduleRenderUpload(`jump-home:${src}`);
      }
    }

    async function runJumpHome(source = 'unknown', navOptions = {}) {
      const src = String(source || 'unknown').trim() || 'unknown';
      const navOpts = navOptions && typeof navOptions === 'object' ? navOptions : {};
      ToolboxShell.appendLog(`[HOME][RUN] source=${src}`);
      if (
        typeof AutoQueueModule !== 'undefined'
        && AutoQueueModule
        && typeof AutoQueueModule.blockNavigationDuringWaitingReply === 'function'
        && AutoQueueModule.blockNavigationDuringWaitingReply(`runJumpHome:${src}`, navOpts)
      ) {
        return { ok: false, reason: 'blocked-waiting-reply' };
      }
      try {
        return await runGoHomeOnce(src, navOpts);
      } catch (error) {
        console.error('[UPLOAD_UI_ACTION][jump-home:failed]', error);
        throw error;
      }
    }

    async function runAutoContinueOnce(source = 'unknown') {
      const src = String(source || 'unknown').trim() || 'unknown';

      if (
        !AutoQueueModule
        || typeof AutoQueueModule.toggleContinueLoopFromUpload !== 'function'
      ) {
        console.error('[UPLOAD_AUTO_CONTINUE][toggle-failed]', { reason: 'module-unavailable' });
        refreshUploadAutoContinueButton('toggle-unavailable');
        setStatus('自动继续模块不可用', 'warn');
        return { ok: false, reason: 'auto-continue-unavailable' };
      }

      const actionLock = claimUploadActionLock('auto-continue', { timeoutMs: 120000 });
      if (!actionLock.ok) {
        ToolboxShell.appendLog(
          `[UPLOAD_AUTO_CONTINUE][skip] source=${src} reason=${actionLock.reason} runningMs=${actionLock.runningMs || 0}`,
        );
        return { ok: false, reason: actionLock.reason || 'task-running' };
      }

      try {
        const result = AutoQueueModule.toggleContinueLoopFromUpload(
          src === 'delegated-click' ? 'upload-button' : src,
        );
        refreshUploadAutoContinueButton('click-toggle');

        const autoState = typeof AutoQueueModule.getState === 'function'
          ? AutoQueueModule.getState()
          : null;
        const view = getAutoContinueButtonView(autoState);
        const active = view.phase === 'running' || view.phase === 'waiting_reply';

        ToolboxShell.setStatus(
          active ? '自动继续已开启' : '自动继续已停止',
          active ? 'success' : 'warn',
          { owner: 'autoqueue' },
        );

        return result;
      } catch (error) {
        const errText = formatToolboxError(error);
        console.error('[UPLOAD_AUTO_CONTINUE][toggle-failed]', {
          error_type: error && error.name,
          error: errText,
          stack: error && error.stack,
        });
        ToolboxShell.appendLog(`[UPLOAD_AUTO_CONTINUE][toggle-failed] error=${errText}`);
        refreshUploadAutoContinueButton('toggle-exception');
        setStatus(`自动继续失败：${errText}`, 'error');
        return { ok: false, reason: 'exception', detail: errText };
      } finally {
        releaseUploadActionLock('auto-continue');
        scheduleRenderUpload(`auto-continue:done:${src}`);
      }
    }

    async function runAutoContinueUntilDone(source = 'unknown') {
      const src = String(source || 'unknown').trim() || 'unknown';

      if (
        typeof AutoQueueModule === 'undefined'
        || !AutoQueueModule
        || typeof AutoQueueModule.startContinueUntilDoneFromUpload !== 'function'
      ) {
        console.error('[UPLOAD_AUTO_CONTINUE_UNTIL_DONE][toggle-failed]', { reason: 'module-unavailable' });
        setStatus('自动继续直到完成模块不可用', 'warn');
        ToolboxShell.appendLog('[UPLOAD_AUTO_CONTINUE_UNTIL_DONE][toggle-failed] reason=module-unavailable');
        return { ok: false, reason: 'auto-continue-until-done-unavailable' };
      }

      const actionLock = claimUploadActionLock('auto-continue-until-done', { timeoutMs: 120000 });
      if (!actionLock.ok) {
        ToolboxShell.appendLog(
          `[UPLOAD_AUTO_CONTINUE_UNTIL_DONE][skip] source=${src} reason=${actionLock.reason} runningMs=${actionLock.runningMs || 0}`,
        );
        return { ok: false, reason: actionLock.reason || 'task-running' };
      }

      try {
        const result = AutoQueueModule.startContinueUntilDoneFromUpload(
          src === 'delegated-click' ? 'upload-until-done-button' : src,
        );

        refreshUploadAutoContinueButton('until-done-toggle');

        const untilDoneBtn = resolveAutoContinueUntilDoneButton(rootElRef);
        if (untilDoneBtn) {
          applyAutoContinueUntilDoneButtonState(untilDoneBtn, {
            reason: 'until-done-toggle',
          });
        }

        return result;
      } catch (error) {
        const errText = formatToolboxError(error);
        console.error('[UPLOAD_AUTO_CONTINUE_UNTIL_DONE][toggle-failed]', {
          error_type: error && error.name,
          error: errText,
          stack: error && error.stack,
        });
        ToolboxShell.appendLog(`[UPLOAD_AUTO_CONTINUE_UNTIL_DONE][toggle-failed] error=${errText}`);
        setStatus(`自动继续直到完成失败：${errText}`, 'error');
        return { ok: false, reason: 'exception', detail: errText };
      } finally {
        releaseUploadActionLock('auto-continue-until-done');
        scheduleRenderUpload(`auto-continue-until-done:done:${src}`);
      }
    }

    function logTaskSourceConsistency(taskName, phase, runningFlag, active, reason = '') {
      ToolboxShell.appendLog(
        `[BUTTON_STATE][TASK_SOURCE] task=${taskName} phase=${phase || '-'} runningFlag=${runningFlag ? 1 : 0}`
        + ` active=${active ? 1 : 0} reason=${reason || '-'}`,
      );
    }

    function logButtonTasksMigration(oldField, task, phase) {
      ToolboxShell.appendLog(
        `[STATE_SCHEMA][MIGRATE_TO_BUTTON_TASKS] oldField=${oldField || '-'} task=${task || '-'} phase=${phase || '-'}`,
      );
    }

    function isCopyHotkeyTaskPhaseActive(phase) {
      const normalized = String(phase || 'idle').trim().toLowerCase();
      return normalized !== 'idle'
        && normalized !== 'success'
        && normalized !== 'failed'
        && normalized !== 'cancelled';
    }

    function isCopyHotkeyLoopTaskPhaseActive(phase) {
      const normalized = String(phase || 'idle').trim().toLowerCase();
      return normalized !== 'idle'
        && normalized !== 'stopped'
        && normalized !== 'success'
        && normalized !== 'failed'
        && normalized !== 'cancelled';
    }

    const COPY_HOTKEY_ONCE_OWNER_BUTTON_ID = 'cgpt-copy-hotkey-once';
    const COPY_HOTKEY_ONCE_ACTION = 'copy-hotkey-once';
    const COPY_HOTKEY_ONCE_TASK_KEY = 'copy-hotkey-once';

    function ensureCopyHotkeyOnceTask() {
      if (!state.copyHotkeyOnceTask || typeof state.copyHotkeyOnceTask !== 'object') {
        state.copyHotkeyOnceTask = {
          running: false,
          phase: 'idle',
          action: '',
          taskKey: '',
          ownerButtonId: '',
          runId: '',
          cancelRequested: false,
          startedAt: 0,
          lastError: null,
          lastReason: '',
          abortController: null,
        };
      }
      return state.copyHotkeyOnceTask;
    }

    function setCopyHotkeyOncePhase(phase, reason = '') {
      const task = ensureCopyHotkeyOnceTask();
      const normalized = String(phase || 'idle').trim().toLowerCase();
      task.phase = normalized;

      const activePhases = new Set([
        'waiting_reply',
        'copying',
        'confirming_clipboard',
        'sending_hotkey',
        'cancelling',
      ]);
      copyHotkeyOnceTaskRunning = activePhases.has(normalized);
      task.running = copyHotkeyOnceTaskRunning;
      if (copyHotkeyOnceTaskRunning) {
        task.action = COPY_HOTKEY_ONCE_ACTION;
        task.taskKey = COPY_HOTKEY_ONCE_TASK_KEY;
        task.ownerButtonId = COPY_HOTKEY_ONCE_OWNER_BUTTON_ID;
        if (!task.startedAt) {
          task.startedAt = Date.now();
          copyHotkeyOnceTaskStartedAt = task.startedAt;
        }
      } else {
        task.action = '';
        task.taskKey = '';
        task.ownerButtonId = '';
        task.startedAt = 0;
        copyHotkeyOnceTaskStartedAt = 0;
      }

      if (reason) {
        task.lastReason = String(reason);
      }
      if (typeof ButtonTasks !== 'undefined' && typeof ButtonTasks.setTaskPhase === 'function') {
        ButtonTasks.setTaskPhase('copyHotkeyOnce', normalized, reason || 'phase-sync', {
          cancelRequested: !!task.cancelRequested,
          runId: task.runId || '',
        });
      }
      logButtonTasksMigration('copyHotkeyOnceTaskRunning', 'copyHotkeyOnce', normalized);

      logTaskSourceConsistency(
        'copyHotkeyOnce',
        normalized,
        copyHotkeyOnceTaskRunning,
        isCopyHotkeyOnceActive(),
        reason,
      );
      scheduleRenderUpload(`copyHotkeyOnce:${normalized}:${reason || '-'}`);
    }

    function isCopyHotkeyOnceActive() {
      const task = ensureCopyHotkeyOnceTask();
      const fromPhase = isCopyHotkeyTaskPhaseActive(task.phase);
      if (fromPhase !== !!copyHotkeyOnceTaskRunning) {
        copyHotkeyOnceTaskRunning = fromPhase;
      }
      return fromPhase;
    }

    function isCopyHotkeyOnceCancelled(runId = '') {
      const task = ensureCopyHotkeyOnceTask();
      if (runId && task.runId && task.runId !== runId) {
        return true;
      }
      return !!task.cancelRequested
        || task.phase === 'cancelling'
        || task.phase === 'cancelled';
    }

    function cancelCopyHotkeyOnce(source = 'unknown') {
      const task = ensureCopyHotkeyOnceTask();
      const src = String(source || 'unknown').trim() || 'unknown';
      const phase = String(task.phase || 'idle').trim().toLowerCase();
      if (phase === 'idle' || phase === 'cancelled' || phase === 'success' || phase === 'failed') {
        ToolboxShell.appendLog(`[COPY_HOTKEY_ONCE][cancel-ignore] source=${src} phase=${phase}`);
        return false;
      }
      if (phase === 'cancelling') {
        ToolboxShell.appendLog(`[COPY_HOTKEY_ONCE][cancel-ignore] source=${src} phase=cancelling`);
        return true;
      }
      if (!COPY_HOTKEY_ONCE_CANCELLABLE_PHASES.has(phase)) {
        ToolboxShell.appendLog(`[COPY_HOTKEY_ONCE][cancel-ignore] source=${src} phase=${phase}`);
        return false;
      }
      task.cancelRequested = true;
      if (task.abortController && typeof task.abortController.abort === 'function') {
        task.abortController.abort();
      }
      setCopyHotkeyOncePhase('cancelling', src);
      setStatus('正在取消复制+快捷键等待任务...', 'warn');
      ToolboxShell.appendLog(
        `[COPY_HOTKEY_ONCE][CANCEL] source=${src} phase=${phase} runId=${task.runId || '-'}`,
      );
      scheduleRenderUpload(`copy-hotkey-once-cancel:${src}`);
      return true;
    }

    function finishCopyHotkeyOnceTask(outcome, runId, source = '') {
      const task = ensureCopyHotkeyOnceTask();
      if (runId && task.runId && task.runId !== runId) {
        return;
      }
      task.abortController = null;
      task.cancelRequested = false;
      const normalized = String(outcome || 'idle').trim().toLowerCase();
      setCopyHotkeyOncePhase(normalized, source || outcome);
      const resetMs = normalized === 'cancelled'
        ? 400
        : (normalized === 'success' ? 900 : 1200);
      window.setTimeout(() => {
        const currentTask = ensureCopyHotkeyOnceTask();
        if (!runId || !currentTask.runId || currentTask.runId === runId) {
          currentTask.runId = '';
          currentTask.lastError = null;
          currentTask.cancelRequested = false;
          currentTask.abortController = null;
          setCopyHotkeyOncePhase('idle', 'auto-reset');
        }
      }, resetMs);
    }

    const SEND_COPY_HOTKEY_ACTIVE_PHASES = new Set([
      'running',
      'waiting_input',
      'waiting_ready',
      'waiting_current_reply_done',
      'waiting_composer_ready',
      'auto_upload_before_send',
      'waiting_native_send',
      'waiting_send',
      'native_send_confirmed',
      'sending',
      'waiting_response',
      'waiting_reply',
      'answering',
      'paused_background_throttled',
      'reply_done_waiting_copy',
      'copy_hotkey',
      'copying',
      'hotkey_sending',
      'sending_hotkey',
      'cancelling',
    ]);

    const SEND_COPY_HOTKEY_COMPOSER_READY_TIMEOUT_MS = 15000;

    const SEND_COPY_HOTKEY_WAIT_REPLY_MAX_MS = 5 * 60 * 1000;
    let sendCopyHotkeyPostActionRunning = false;
    let sendCopyHotkeyReconcileRunning = false;
    let sendCopyHotkeyLastAssistantTextHash = '';
    let sendCopyHotkeyLastAssistantTextChangedAt = 0;
    let sendCopyHotkeyBackgroundResumeStreak = 0;

    function computeSendCopyHotkeyRealComposerPayload({
      composerTextLen = 0,
      composerCount = 0,
      composerUploading = false,
      localFileCount = 0,
    } = {}) {
      return composerTextLen > 0
        || composerCount > 0
        || composerUploading === true
        || localFileCount > 0;
    }

    function getSendCopyHotkeyBrowserRuntimeState(reason = '-') {
      if (typeof BrowserRuntimeHealth !== 'undefined' && typeof BrowserRuntimeHealth.getRuntimeState === 'function') {
        return BrowserRuntimeHealth.getRuntimeState(reason);
      }
      return {
        hidden: !!document.hidden,
        throttled: !!document.hidden,
        visibilityState: document.visibilityState || '-',
        hasFocus: typeof document.hasFocus === 'function' ? document.hasFocus() : false,
      };
    }

    function isSendCopyHotkeyBackgroundThrottled() {
      const rt = getSendCopyHotkeyBrowserRuntimeState('send-copy-hotkey-bg-check');
      return isSendCopyHotkeyRuntimeThrottled(rt);
    }

    function isSendCopyHotkeyRuntimeThrottled(runtimeState = null) {
      const rt = runtimeState && typeof runtimeState === 'object'
        ? runtimeState
        : getSendCopyHotkeyBrowserRuntimeState('send-copy-hotkey-throttle-check');
      if (rt.hidden === true || rt.throttled === true) {
        return true;
      }
      const maxDriftMs = Number(rt.maxDriftMs != null ? rt.maxDriftMs : rt.max_drift_ms || 0);
      return maxDriftMs > 5000;
    }

    function canSendHotkeyAfterCopy(state = {}) {
      const responseState = String(state?.responseState || state?.response_state || '').trim().toLowerCase();
      const waitingReply = Boolean(state?.waitingReply || state?.waiting_reply);
      const copied = Boolean(state?.copied || state?.copyOk || state?.copy_ok);
      const replyDone = Boolean(state?.replyDone || state?.reply_done);
      if (responseState === 'generating') {
        return { ok: false, reason: 'response-generating' };
      }
      if (waitingReply) {
        return { ok: false, reason: 'waiting-reply' };
      }
      if (!replyDone) {
        return { ok: false, reason: 'reply-not-done' };
      }
      if (!copied) {
        return { ok: false, reason: 'copy-not-ok' };
      }
      return { ok: true, reason: 'ok' };
    }

    function shouldApplyHotkeyAfterCopyGate(reason = '') {
      const normalized = String(reason || '').trim().toLowerCase();
      return normalized.includes('send-copy-hotkey')
        || normalized.includes('copy-and-hotkey')
        || normalized.includes('copy-hotkey');
    }

    function readLiveHotkeyGateSignals() {
      const bridgeState = (typeof window !== 'undefined' && window.__cgptBridgeState) || {};
      let responseState = String(
        bridgeState.response_state
        || bridgeState.responseState
        || (typeof window !== 'undefined' && window.__cgptLastResponseState)
        || '',
      ).trim().toLowerCase();
      let waitingReply = state.waitingReply === true;
      if (
        !responseState
        && typeof detectComposerResponseState === 'function'
      ) {
        try {
          const snap = detectComposerResponseState({
            light: true,
            reason: 'hotkey-gate',
          }) || {};
          responseState = String(
            snap.response_state
            || snap.responseState
            || snap.state
            || '',
          ).trim().toLowerCase();
          if (snap.waiting_reply != null) {
            waitingReply = !!snap.waiting_reply;
          } else if (snap.waitingReply != null) {
            waitingReply = !!snap.waitingReply;
          }
        } catch (readErr) {
          console.error('[SEND_COPY_HOTKEY][HOTKEY_GATE_READ_FAILED]', readErr);
          ToolboxShell.appendLog(
            `[SEND_COPY_HOTKEY][HOTKEY_GATE_READ_FAILED] error=${readErr && readErr.message ? readErr.message : String(readErr)}`,
          );
        }
      }
      if (
        responseState === 'generating'
        || responseState === 'responding'
        || responseState === 'attachment_processing'
        || isAssistantGeneratingNow('hotkey-gate')
        || isChatGptResponseBusyForSend()
      ) {
        waitingReply = true;
      }
      return {
        responseState,
        waitingReply,
      };
    }

    function buildSendCopyHotkeyHotkeyGateState(overrides = {}) {
      const copyHotkeyTask = ensureSendCopyHotkeyTask();
      const live = readLiveHotkeyGateSignals();
      const copyPhase = String(copyHotkeyTask.phase || '').trim().toLowerCase();
      const waitingFromPhase = isSendCopyHotkeyWaitingReplyPhase(copyPhase)
        || copyPhase === 'paused_background_throttled';
      return {
        runId: String(
          overrides.runId
          || getSendCopyHotkeyRootRunId(copyHotkeyTask)
          || '',
        ).trim(),
        ownerButtonId: String(
          overrides.ownerButtonId
          || sendMessageTaskState.ownerButtonId
          || copyHotkeyTask.ownerButtonId
          || 'cgpt-send-copy-hotkey-once',
        ).trim(),
        phase: String(overrides.phase || copyPhase || sendMessageTaskState.phase || '').trim(),
        responseState: String(
          overrides.responseState != null ? overrides.responseState : live.responseState,
        ).trim().toLowerCase(),
        waitingReply: overrides.waitingReply != null
          ? !!overrides.waitingReply
          : !!(live.waitingReply || waitingFromPhase),
        replyDone: overrides.replyDone != null
          ? !!overrides.replyDone
          : !!copyHotkeyTask.replyDone,
        copied: overrides.copied != null
          ? !!overrides.copied
          : !!copyHotkeyTask.copied,
      };
    }

    function logSendCopyHotkeyHotkeyGateDecision(gateState, gateResult, tag) {
      const fields = [
        `runId=${gateState.runId || '-'}`,
        `ownerButtonId=${gateState.ownerButtonId || '-'}`,
        `phase=${gateState.phase || '-'}`,
        `responseState=${gateState.responseState || '-'}`,
        `waitingReply=${gateState.waitingReply ? 1 : 0}`,
        `replyDone=${gateState.replyDone ? 1 : 0}`,
        `copied=${gateState.copied ? 1 : 0}`,
        `reason=${gateResult.reason || '-'}`,
      ].join(' ');
      ToolboxShell.appendLog(`[SEND_COPY_HOTKEY][${tag}] ${fields}`);
    }

    function reconcileSendCopyHotkeyOwnerRunningState(reason = '-') {
      const copyHotkeyTask = ensureSendCopyHotkeyTask();
      const phase = String(copyHotkeyTask.phase || '').trim().toLowerCase();
      if (!SEND_COPY_HOTKEY_ACTIVE_PHASES.has(phase)) {
        return;
      }
      const ownerButtonId = String(
        sendMessageTaskState.ownerButtonId
        || copyHotkeyTask.ownerButtonId
        || 'cgpt-send-copy-hotkey-once',
      ).trim() || 'cgpt-send-copy-hotkey-once';
      const rootRunId = getSendCopyHotkeyRootRunId(copyHotkeyTask);
      const wasRunning = sendMessageTaskState.running === true ? 1 : 0;
      const ownerBefore = String(sendMessageTaskState.ownerButtonId || '-').trim() || '-';
      const liveSignals = readLiveHotkeyGateSignals();
      if (
        (phase === 'waiting_reply' && wasRunning === 0)
        || (ownerButtonId !== '-' && ownerBefore === '-')
      ) {
        ToolboxShell.appendLog(
          `[SEND_COPY_HOTKEY][STATE_INCONSISTENT] runId=${rootRunId || '-'} phase=${phase} running=${wasRunning} owner=${ownerBefore} ownerButtonId=${ownerButtonId} currentAction=${sendMessageTaskState.action || '-'} responseState=${liveSignals.responseState || '-'} waitingReply=${liveSignals.waitingReply ? 1 : 0} reason=${reason || '-'}`,
        );
      }
      if (rootRunId && !copyHotkeyTask.rootRunId) {
        copyHotkeyTask.rootRunId = rootRunId;
      }
      if (rootRunId && !copyHotkeyTask.runId) {
        copyHotkeyTask.runId = rootRunId;
      }
      copyHotkeyTask.ownerButtonId = ownerButtonId;
      sendMessageTaskState.running = true;
      sendMessageTaskState.action = 'send-copy-hotkey';
      sendMessageTaskState.plan = buildSendTaskPlanFromAction('send-copy-hotkey');
      sendMessageTaskState.ownerButtonId = ownerButtonId;
      if (!sendMessageTaskState.runId && rootRunId) {
        sendMessageTaskState.runId = rootRunId;
      }
    }

    function isSendCopyHotkeyTransactionComplete(task = {}) {
      return !!(
        task.nativeSendConfirmed === true
        && task.replyDone === true
        && task.copied === true
        && task.hotkeySent === true
      );
    }

    function getSendCopyHotkeyRootRunId(task = {}) {
      return String(task.rootRunId || task.runId || '').trim();
    }

    function isSendCopyHotkeyRunCancelled(task = {}, runId = '') {
      const expectedRunId = String(runId || '').trim();
      const rootRunId = getSendCopyHotkeyRootRunId(task);
      if (task.cancelRequested === true) {
        return true;
      }
      if (!expectedRunId || !rootRunId) {
        return false;
      }
      return rootRunId !== expectedRunId;
    }

    function logSendCopyHotkeyTaskMilestone(task, phase, reason = '-') {
      ToolboxShell.appendLog(
        `[SEND_COPY_HOTKEY][TASK] rootRunId=${task.rootRunId || task.runId || '-'} postRunId=${task.postRunId || '-'} `
        + `phase=${phase || task.phase || '-'} ownerButtonId=${task.ownerButtonId || sendMessageTaskState.ownerButtonId || '-'} `
        + `nativeSendConfirmed=${task.nativeSendConfirmed ? 1 : 0} replyDone=${task.replyDone ? 1 : 0} `
        + `copied=${task.copied ? 1 : 0} hotkeySent=${task.hotkeySent ? 1 : 0} reason=${reason || '-'}`,
      );
    }

    function reconcileSendCopyHotkeyBackgroundThrottle(reason = '-') {
      const copyHotkeyTask = ensureSendCopyHotkeyTask();
      const copyPhase = String(copyHotkeyTask.phase || '').trim().toLowerCase();
      const postSendPhases = new Set([
        'waiting_reply',
        'sent_waiting_response',
        'answering',
        'reply_done_waiting_copy',
        'copying',
        'hotkey_sending',
        'sending_hotkey',
        'paused_background_throttled',
      ]);
      const waitingReply = postSendPhases.has(copyPhase)
        || isSendCopyHotkeyWaitingReplyPhase(copyPhase);
      if (!waitingReply) {
        return false;
      }

      const rt = getSendCopyHotkeyBrowserRuntimeState(`throttle:${reason}`);
      const throttled = isSendCopyHotkeyRuntimeThrottled(rt);
      if (throttled) {
        sendCopyHotkeyBackgroundResumeStreak = 0;
        if (copyPhase !== 'paused_background_throttled') {
          ToolboxShell.appendLog(
            `[SEND_COPY_HOTKEY][PAUSE_THROTTLED] reason=${reason || '-'} hidden=${rt.hidden ? 1 : 0} `
            + `visibility=${rt.visibilityState || '-'} throttled=${rt.throttled ? 1 : 0} `
            + `max_drift_ms=${rt.maxDriftMs != null ? rt.maxDriftMs : rt.max_drift_ms != null ? rt.max_drift_ms : '-'} `
            + `phase=${copyPhase || '-'}`,
          );
          setSendCopyHotkeyPhase('paused_background_throttled', `background-pause:${reason}`);
        }
        return true;
      }

      if (copyPhase !== 'paused_background_throttled') {
        sendCopyHotkeyBackgroundResumeStreak = 0;
        return false;
      }

      sendCopyHotkeyBackgroundResumeStreak += 1;
      if (sendCopyHotkeyBackgroundResumeStreak < 2) {
        return true;
      }

      let responseReadable = false;
      try {
        const responseState = typeof detectComposerResponseState === 'function'
          ? detectComposerResponseState()
          : null;
        const responseText = String(
          responseState?.response_state
          || responseState?.state
          || '',
        ).trim();
        responseReadable = !!responseText;
      } catch (readErr) {
        console.error('[SEND_COPY_HOTKEY][RESUME_RESPONSE_READ_FAILED]', readErr);
      }

      if (rt.hidden === true || !responseReadable) {
        return true;
      }

      sendCopyHotkeyBackgroundResumeStreak = 0;
      ToolboxShell.appendLog(
        `[SEND_COPY_HOTKEY][RESUME_THROTTLED] reason=${reason || '-'} visibility=${rt.visibilityState || '-'} `
        + `throttled=${rt.throttled ? 1 : 0} max_drift_ms=${rt.maxDriftMs != null ? rt.maxDriftMs : rt.max_drift_ms != null ? rt.max_drift_ms : '-'} responseReadable=1`,
      );
      setSendCopyHotkeyPhase('waiting_reply', `background-resume:${reason}`);
      return true;
    }

    function isToolboxDomNode(el) {
      if (!el) {
        return false;
      }
      if (typeof isInsideToolbox === 'function') {
        return isInsideToolbox(el);
      }
      if (typeof isInsideToolboxOrPanel === 'function') {
        return isInsideToolboxOrPanel(el);
      }
      if (typeof isInToolbox === 'function') {
        return isInToolbox(el);
      }
      return false;
    }

    function isAssistantReplyFinishedNow(reason = '-') {
      const bridgeState = (typeof window !== 'undefined' && window.__cgptBridgeState) || {};
      const responseState = String(
        bridgeState.response_state
        || bridgeState.responseState
        || (typeof window !== 'undefined' && window.__cgptLastResponseState)
        || '',
      ).trim().toLowerCase();
      const responseReason = String(
        bridgeState.response_state_reason
        || bridgeState.responseStateReason
        || (typeof window !== 'undefined' && window.__cgptLastResponseStateReason)
        || '',
      ).trim().toLowerCase();

      if (
        !responseState
        && !responseReason
        && typeof detectComposerResponseState === 'function'
      ) {
        try {
          const snap = detectComposerResponseState({
            light: true,
            reason: `isAssistantReplyFinishedNow:${reason}`,
          }) || {};
          const snapState = String(snap.response_state || snap.responseState || '').trim().toLowerCase();
          const snapReason = String(
            snap.response_state_reason || snap.responseStateReason || snap.reason || '',
          ).trim().toLowerCase();
          if (snapState) {
            return isAssistantReplyFinishedNowFromSignals(snapState, snapReason, reason);
          }
        } catch (detectErr) {
          console.error('[SEND_COPY_HOTKEY][REPLY_FINISHED_DETECT_FAILED]', detectErr);
          ToolboxShell.appendLog(
            `[SEND_COPY_HOTKEY][REPLY_FINISHED_DETECT_FAILED] reason=${reason || '-'} error=${detectErr && detectErr.message ? detectErr.message : String(detectErr)}`,
          );
        }
      }

      return isAssistantReplyFinishedNowFromSignals(responseState, responseReason, reason);
    }

    function isAssistantReplyFinishedNowFromSignals(responseState, responseReason, reason = '-') {
      void reason;
      const stopButton = document.querySelector(
        'button[data-testid="stop-button"], button[aria-label*="停止"], button[aria-label*="Stop"], button[aria-label*="stop"]',
      );
      const hasNativeStopButton = stopButton instanceof HTMLButtonElement
        && !isToolboxDomNode(stopButton);

      if (hasNativeStopButton) {
        return false;
      }

      if (responseState === 'generating' || responseReason === 'assistant_busy') {
        return false;
      }

      if (
        responseState === 'idle'
        || responseState === 'ready'
        || responseReason === 'empty_composer'
        || responseReason === 'assistant_done'
        || responseReason === 'reply_done'
      ) {
        return true;
      }

      const bridgePoll = typeof BridgePollRuntime !== 'undefined' && BridgePollRuntime
        ? BridgePollRuntime
        : {};
      const bridgeInputable = bridgePoll.inputable === true || bridgePoll.inputable === 1;
      const bridgeState = String(bridgePoll.response_state || bridgePoll.responseState || '').trim().toLowerCase();
      const bridgeReason = String(
        bridgePoll.response_state_reason || bridgePoll.responseStateReason || '',
      ).trim().toLowerCase();
      if (
        bridgeInputable
        && (bridgeState === 'idle' || bridgeState === 'ready' || bridgeReason === 'empty_composer')
      ) {
        return true;
      }

      return false;
    }

    function isSendCopyHotkeyComposedFlowInProgress() {
      const copyHotkeyTask = ensureSendCopyHotkeyTask();
      const phase = String(copyHotkeyTask.phase || '').trim().toLowerCase();
      const composedPhases = new Set([
        'sending',
        'waiting_response',
        'copy_hotkey',
      ]);
      return !!(copyHotkeyTask.rootRunId || copyHotkeyTask.runId)
        && composedPhases.has(phase);
    }

    function resetSendCopyHotkeyReplyStableTracking() {
      sendCopyHotkeyLastAssistantTextHash = '';
      sendCopyHotkeyLastAssistantTextChangedAt = 0;
    }

    function getSendCopyHotkeyWaitElapsedMs() {
      const task = sendMessageTaskState;
      if (!task) {
        return 0;
      }
      const startAt = Number(
        task.responseStartedAt
        || task.sentAt
        || task.nativeSendClickedAt
        || task.startedAtMs
        || 0,
      );
      if (!startAt) {
        const copyHotkeyTask = ensureSendCopyHotkeyTask();
        const copyStartAt = Number(
          copyHotkeyTask.responseStartedAt
          || copyHotkeyTask.sentAt
          || copyHotkeyTask.startedAt
          || 0,
        );
        if (!copyStartAt) {
          return 0;
        }
        return Date.now() - copyStartAt;
      }
      return Date.now() - startAt;
    }

    function getLatestAssistantTextSnapshotForWaitDone() {
      const messageNodes = Array.from(document.querySelectorAll('[data-message-author-role="assistant"]'));
      const lastNode = messageNodes.length ? messageNodes[messageNodes.length - 1] : null;
      const text = lastNode ? String(lastNode.innerText || lastNode.textContent || '').trim() : '';
      return {
        ok: !!text,
        text,
        length: text.length,
      };
    }

    function checkSendCopyHotkeyReplyStableDone(reason = '-') {
      if (isSendCopyHotkeyComposedFlowInProgress()) {
        return false;
      }

      const task = sendMessageTaskState;
      if (!task || task.running !== true) {
        const copyHotkeyTask = ensureSendCopyHotkeyTask();
        const copyPhase = String(copyHotkeyTask.phase || '').trim().toLowerCase();
        if (!isSendCopyHotkeyWaitingReplyPhase(copyPhase)) {
          return false;
        }
      }

      const action = String(
        task?.action || task?.plan?.mode || '',
      ).trim();
      if (action !== 'send-copy-hotkey' && action !== 'send-copy-hotkey-continue') {
        const copyHotkeyTask = ensureSendCopyHotkeyTask();
        const copyPhase = String(copyHotkeyTask.phase || '').trim().toLowerCase();
        if (!isSendCopyHotkeyWaitingReplyPhase(copyPhase)) {
          return false;
        }
      }

      const copyHotkeyTask = ensureSendCopyHotkeyTask();
      const copyPhase = String(copyHotkeyTask.phase || '').trim().toLowerCase();
      const sendPhase = String(task?.phase || '').trim().toLowerCase();
      const waiting = isSendCopyHotkeyWaitingReplyPhase(copyPhase)
        || (task?.running === true && isSendCopyHotkeyWaitingReplyPhase(sendPhase));
      if (!waiting) {
        return false;
      }

      if (reconcileSendCopyHotkeyBackgroundThrottle(reason)) {
        return false;
      }

      if (isSendCopyHotkeyBackgroundThrottled()) {
        return false;
      }

      if (copyHotkeyTask.nativeSendConfirmed === true && isAssistantReplyFinishedNow(reason)) {
        const pageSnap = typeof buildUploadButtonRenderSnapshot === 'function'
          ? buildUploadButtonRenderSnapshot(`reply-stable-fast:${reason}`)
          : {};
        const pageFields = readWaitReplySnapshotFields(pageSnap);
        const pageDone = (pageFields.responseState === 'idle' || pageFields.responseState === 'ready')
          && !hasVisibleNativeStopButtonForWaitReply();
        if (pageDone) {
          ToolboxShell.appendLog(
            `[SEND_COPY_HOTKEY][REPLY_STABLE_FAST_DONE] reason=${reason || '-'} responseState=${pageFields.responseState || '-'} reasonCode=${pageFields.reason || '-'} inputable=${pageFields.inputable ? 1 : 0}`,
          );
          void continueSendCopyHotkeyAfterReplyDone('reply-stable-fast-done');
          return true;
        }
      }

      const snapshot = getLatestAssistantTextSnapshotForWaitDone();
      if (!snapshot.ok || snapshot.length <= 0) {
        return false;
      }

      const textHash = `${snapshot.length}:${snapshot.text.slice(-80)}`;
      if (textHash !== sendCopyHotkeyLastAssistantTextHash) {
        sendCopyHotkeyLastAssistantTextHash = textHash;
        sendCopyHotkeyLastAssistantTextChangedAt = Date.now();
        ToolboxShell.appendLog(
          `[SEND_COPY_HOTKEY][REPLY_TEXT_CHANGED] reason=${reason || '-'} length=${snapshot.length}`,
        );
        return false;
      }

      const stableMs = Date.now() - Number(sendCopyHotkeyLastAssistantTextChangedAt || 0);
      const stopButton = document.querySelector(
        'button[data-testid="stop-button"], button[aria-label*="停止"], button[aria-label*="Stop"], button[aria-label*="stop"]',
      );
      const hasNativeStopButton = stopButton instanceof HTMLButtonElement
        && !isToolboxDomNode(stopButton);

      if (!hasNativeStopButton && isAssistantReplyFinishedNow(reason)) {
        const gateState = buildSendCopyHotkeyHotkeyGateState({ replyDone: true, copied: false });
        if (gateState.responseState === 'generating' || gateState.waitingReply) {
          return false;
        }
        ToolboxShell.appendLog(
          `[SEND_COPY_HOTKEY][REPLY_STABLE_DONE] reason=${reason || '-'} stableMs=${stableMs} length=${snapshot.length} stopButton=0 via=reply-finished-now`,
        );
        void continueSendCopyHotkeyAfterReplyDone('reply-stable-done');
        return true;
      }

      if (hasNativeStopButton && stableMs < 30000) {
        return false;
      }

      if (isSendCopyHotkeyBackgroundThrottled()) {
        return false;
      }

      if (stableMs >= 30000) {
        const gateState = buildSendCopyHotkeyHotkeyGateState({ replyDone: true, copied: false });
        if (gateState.responseState === 'generating' || gateState.waitingReply) {
          return false;
        }
        ToolboxShell.appendLog(
          `[SEND_COPY_HOTKEY][REPLY_STABLE_DONE] reason=${reason || '-'} stableMs=${stableMs} length=${snapshot.length} stopButton=${hasNativeStopButton ? 1 : 0}`,
        );
        void continueSendCopyHotkeyAfterReplyDone('reply-stable-done');
        return true;
      }

      return false;
    }

    function isSendCopyHotkeyWaitingReplyPhase(phase = '') {
      const normalized = String(phase || '').trim().toLowerCase();
      return normalized === 'waiting_reply'
        || normalized === 'waiting_response'
        || normalized === 'sent_waiting_response'
        || normalized === 'answering';
    }

    function getSendCopyHotkeyWaitingReplyStartedAt() {
      const copyHotkeyTask = ensureSendCopyHotkeyTask();
      return Number(
        copyHotkeyTask.responseStartedAt
        || sendMessageTaskState.responseStartedAt
        || copyHotkeyTask.sentAt
        || sendMessageTaskState.sentAt
        || copyHotkeyTask.startedAt
        || sendMessageTaskState.startedAtMs
        || 0,
      ) || 0;
    }

    function checkSendCopyHotkeyWaitReplyTimeout(reason = '-') {
      if (isSendCopyHotkeyComposedFlowInProgress()) {
        return false;
      }

      const task = sendMessageTaskState;
      const copyHotkeyTask = ensureSendCopyHotkeyTask();
      const action = String(
        task.action || task.plan?.mode || '',
      ).trim();
      const copyPhase = String(copyHotkeyTask.phase || '').trim().toLowerCase();
      const sendPhase = String(task.phase || '').trim().toLowerCase();
      const sendTaskPhase = String(getSendTaskPhase() || '').trim().toLowerCase();
      const isSendCopyHotkey = action === 'send-copy-hotkey' || action === 'send-copy-hotkey-continue';
      const waiting = isSendCopyHotkeyWaitingReplyPhase(copyPhase)
        || (task.running === true && isSendCopyHotkey && isSendCopyHotkeyWaitingReplyPhase(sendPhase))
        || (isSendCopyHotkey && isSendCopyHotkeyWaitingReplyPhase(sendTaskPhase));

      if (!waiting) {
        return false;
      }

      const elapsedMs = getSendCopyHotkeyWaitElapsedMs();
      if (elapsedMs <= 0 || elapsedMs <= SEND_COPY_HOTKEY_WAIT_REPLY_MAX_MS) {
        return false;
      }

      const nativeSendConfirmed = copyHotkeyTask.nativeSendConfirmed === true;
      const finalSnapshot = typeof buildUploadButtonRenderSnapshot === 'function'
        ? buildUploadButtonRenderSnapshot('wait-reply-timeout-reconcile-final')
        : {};
      const {
        responseState: finalResponseState,
        reason: finalReason,
        inputable: finalInputable,
      } = readWaitReplySnapshotFields(finalSnapshot);
      const finalAssistantBusy = finalResponseState === 'generating'
        || finalResponseState === 'responding'
        || finalResponseState === 'answering'
        || finalReason === 'assistant_busy'
        || hasVisibleNativeStopButtonForWaitReply();
      if (
        nativeSendConfirmed
        && !finalAssistantBusy
        && (
          finalResponseState === 'idle'
          || finalResponseState === 'ready'
          || finalReason === 'empty_composer'
          || finalInputable
        )
      ) {
        ToolboxShell.appendLog(
          `[SEND_COPY_HOTKEY][WAIT_REPLY_TIMEOUT_RECOVER_AS_DONE] reason=${reason || '-'} responseState=${finalResponseState || '-'} pageReason=${finalReason || '-'} elapsedMs=${elapsedMs}`,
        );
        copyHotkeyTask.replyDone = true;
        void continueSendCopyHotkeyAfterReplyDone('wait-reply-timeout-recovered');
        return true;
      }

      ToolboxShell.appendLog(
        `[SEND_COPY_HOTKEY][WAIT_REPLY_TIMEOUT] reason=${reason || '-'} action=${action || '-'} phase=${copyPhase || sendPhase || sendTaskPhase || '-'} elapsedMs=${elapsedMs}`,
      );
      finishSendCopyHotkeyTask({
        ok: false,
        reason: 'wait-reply-timeout',
        copied: false,
        hotkeySent: false,
      });
      return true;
    }

    const checkSendCopyHotkeyWaitTimeout = checkSendCopyHotkeyWaitReplyTimeout;

    function finishSendCopyHotkeyTask(result = {}) {
      const oldSendPhase = String(sendMessageTaskState.phase || '-');
      const oldOwner = String(sendMessageTaskState.ownerButtonId || '-');
      const action = String(
        sendMessageTaskState.action || sendMessageTaskState.plan?.mode || 'send-copy-hotkey',
      ).trim() || 'send-copy-hotkey';
      const copyHotkeyTask = ensureSendCopyHotkeyTask();
      const oldCopyPhase = String(copyHotkeyTask.phase || '-');

      sendMessageTaskState.running = false;
      sendMessageTaskState.ownerButtonId = '';
      sendMessageTaskState.action = '';
      sendMessageTaskState.plan = null;
      sendMessageTaskState.cancelRequested = false;
      sendMessageTaskState.responseStartedAt = 0;

      if (sendMessageTaskState.phase !== SEND_MESSAGE_PHASES.IDLE) {
        finishSendMessageTask({
          ok: !!result.ok,
          reason: result.reason || (result.ok ? 'done' : 'failed'),
        });
      } else {
        sendMessageTaskState.action = 'send-message';
        sendMessageTaskState.plan = buildSendTaskPlanFromAction('send-message');
      }

      if (state.sendTask && isSendCopyHotkeyWaitingReplyPhase(getSendTaskPhase())) {
        setAuthoritativeSendTaskState(
          { phase: 'idle', runId: '' },
          `send-copy-hotkey-finish:${result.reason || '-'}`,
        );
      }

      if (state.waitingReply) {
        stopWaitingReplyCheck();
        state.waitingReply = false;
      }

      resetSendCopyHotkeyReplyStableTracking();

      if (result.copied === true) {
        copyHotkeyTask.copied = true;
      }
      if (result.hotkeySent === true) {
        copyHotkeyTask.hotkeySent = true;
      }
      if (result.replyDone === true) {
        copyHotkeyTask.replyDone = true;
      }
      if (result.nativeSendConfirmed === true) {
        copyHotkeyTask.nativeSendConfirmed = true;
      }

      const transactionComplete = result.ok === true && isSendCopyHotkeyTransactionComplete(copyHotkeyTask);
      const nextCopyPhase = transactionComplete
        ? 'success'
        : (result.ok ? 'failed' : (copyHotkeyTask.cancelRequested ? 'cancelled' : 'failed'));
      const finishLastError = transactionComplete
        ? null
        : (result.error || (result.ok ? 'transaction-incomplete' : null));
      setSendCopyHotkeyPhase(nextCopyPhase, `finish:${result.reason || '-'}`, {
        runId: transactionComplete ? (copyHotkeyTask.rootRunId || copyHotkeyTask.runId || '') : '',
        lastError: finishLastError,
        ownerButtonId: '',
        cancelRequested: false,
      });

      if (transactionComplete) {
        window.setTimeout(() => {
          const currentTask = ensureSendCopyHotkeyTask();
          if (
            String(currentTask.phase || '').trim().toLowerCase() === 'success'
            && isSendCopyHotkeyTransactionComplete(currentTask)
          ) {
            setSendCopyHotkeyPhase('idle', 'success-reset', {
              runId: '',
              rootRunId: '',
              postRunId: '',
              nativeSendConfirmed: false,
              replyDone: false,
              copied: false,
              hotkeySent: false,
            });
          }
        }, 1200);
      } else if (nextCopyPhase === 'failed' || nextCopyPhase === 'cancelled') {
        window.setTimeout(() => {
          const currentTask = ensureSendCopyHotkeyTask();
          const phaseNow = String(currentTask.phase || '').trim().toLowerCase();
          if (phaseNow === 'failed' || phaseNow === 'cancelled') {
            setSendCopyHotkeyPhase('idle', `${nextCopyPhase}-reset`, {
              runId: '',
              rootRunId: '',
              postRunId: '',
              nativeSendConfirmed: false,
              replyDone: false,
              copied: false,
              hotkeySent: false,
            });
            safeRenderUploadButtonsOnly({
              immediate: true,
              force: true,
              buttonTasksReason: `send-copy-hotkey-${nextCopyPhase}-reset`,
            });
          }
        }, 1200);
      }

      logSendCopyHotkeyTaskMilestone(copyHotkeyTask, nextCopyPhase, `finish:${result.reason || '-'}`);
      ToolboxShell.appendLog(
        `[SEND_COPY_HOTKEY][FINISH] ok=${result.ok ? 1 : 0} transactionComplete=${transactionComplete ? 1 : 0} action=${action} oldSendPhase=${oldSendPhase} oldCopyPhase=${oldCopyPhase} oldOwner=${oldOwner} reason=${result.reason || '-'} copied=${copyHotkeyTask.copied ? 1 : 0} hotkeySent=${copyHotkeyTask.hotkeySent ? 1 : 0}`,
      );
      safeRenderUploadButtonsOnly({
        immediate: true,
        force: true,
        buttonTasksReason: `send-copy-hotkey-finish:${result.reason || '-'}`,
      });
    }

    async function continueSendCopyHotkeyAfterReplyDone(reason = '-') {
      if (isSendCopyHotkeyComposedFlowInProgress()) {
        ToolboxShell.appendLog(
          `[SEND_COPY_HOTKEY][POST_ACTION_SKIP] reason=composed-flow-active source=${reason || '-'}`,
        );
        return {
          ok: false,
          reason: 'composed-flow-active',
        };
      }

      if (sendCopyHotkeyPostActionRunning) {
        ToolboxShell.appendLog('[SEND_COPY_HOTKEY][POST_ACTION_SKIP] reason=already-running');
        return {
          ok: false,
          reason: 'already-running',
        };
      }

      const action = String(
        sendMessageTaskState.action || sendMessageTaskState.plan?.mode || '',
      ).trim();
      const copyHotkeyTask = ensureSendCopyHotkeyTask();
      const copyPhase = String(copyHotkeyTask.phase || '').trim().toLowerCase();
      const sendRunning = sendMessageTaskState.running === true;
      const isSendCopyHotkey = action === 'send-copy-hotkey' || action === 'send-copy-hotkey-continue';
      const waiting = isSendCopyHotkeyWaitingReplyPhase(copyPhase)
        || copyPhase === 'reply_done_waiting_copy'
        || (sendRunning && isSendCopyHotkey && isSendCopyHotkeyWaitingReplyPhase(sendMessageTaskState.phase));

      if (!waiting && copyPhase !== 'reply_done_waiting_copy') {
        return {
          ok: false,
          reason: 'not-waiting',
        };
      }

      if (reconcileSendCopyHotkeyBackgroundThrottle(`post-action:${reason}`)) {
        return {
          ok: false,
          reason: 'paused_background_throttled',
        };
      }

      if (isSendCopyHotkeyRuntimeThrottled()) {
        reconcileSendCopyHotkeyBackgroundThrottle(`post-action-throttled:${reason}`);
        return {
          ok: false,
          reason: 'paused_background_throttled',
        };
      }

      const preCopyGateState = buildSendCopyHotkeyHotkeyGateState({
        replyDone: copyHotkeyTask.replyDone === true,
        copied: false,
      });
      if (
        preCopyGateState.responseState === 'generating'
        || preCopyGateState.waitingReply
        || !isAssistantReplyFinishedNow(`post-action:${reason}`)
      ) {
        logSendCopyHotkeyHotkeyGateDecision(
          preCopyGateState,
          { ok: false, reason: preCopyGateState.responseState === 'generating' ? 'response-generating' : 'waiting-reply' },
          'HOTKEY_BLOCKED',
        );
        return {
          ok: false,
          reason: 'reply-not-done',
        };
      }

      sendCopyHotkeyPostActionRunning = true;
      try {
        if (typeof cancelCopyHotkeyOnce === 'function' && typeof isCopyHotkeyOnceActive === 'function' && isCopyHotkeyOnceActive()) {
          cancelCopyHotkeyOnce(`send-copy-hotkey-reconcile:${reason}`);
        }

        copyHotkeyTask.replyDone = true;
        setSendCopyHotkeyPhase('copying', `send-copy-hotkey-copying:${reason}`);
        ToolboxShell.appendLog(
          `[SEND_COPY_HOTKEY][COPY_START] reason=${reason || '-'} owner=${sendMessageTaskState.ownerButtonId || '-'} rootRunId=${copyHotkeyTask.rootRunId || copyHotkeyTask.runId || '-'}`,
        );

        const copyResult = await copyLatestAssistantReplyUnified({
          reason: `send-copy-hotkey:${reason}`,
          scrollBeforeCopy: true,
        });

        if (!copyResult || copyResult.ok !== true) {
          throw new Error(`copy failed: ${copyResult && copyResult.reason ? copyResult.reason : 'unknown'}`);
        }
        copyHotkeyTask.copied = true;

        if (typeof playCopySuccessBeepSafe === 'function') {
          void playCopySuccessBeepSafe(`send-copy-hotkey:${reason}`, 'sendCopyHotkey');
        }

        const hotkeyGateState = buildSendCopyHotkeyHotkeyGateState({
          replyDone: true,
          copied: true,
          waitingReply: false,
        });
        const hotkeyGate = canSendHotkeyAfterCopy(hotkeyGateState);
        if (!hotkeyGate.ok) {
          logSendCopyHotkeyHotkeyGateDecision(hotkeyGateState, hotkeyGate, 'HOTKEY_BLOCKED');
          throw new Error(`hotkey blocked: ${hotkeyGate.reason}`);
        }
        logSendCopyHotkeyHotkeyGateDecision(hotkeyGateState, hotkeyGate, 'HOTKEY_SEND_ALLOWED');

        setSendCopyHotkeyPhase('hotkey_sending', `send-copy-hotkey-hotkey:${reason}`);
        ToolboxShell.appendLog(
          `[SEND_COPY_HOTKEY][HOTKEY_START] reason=${reason || '-'} rootRunId=${copyHotkeyTask.rootRunId || copyHotkeyTask.runId || '-'}`,
        );

        const hotkeyResult = await sendHotkeyAfterCopy({
          copiedText: copyResult.text || '',
          reason: 'send-copy-hotkey',
          gateState: hotkeyGateState,
          skipHotkeyGate: true,
          shouldStop: () => isSendCopyHotkeyRunCancelled(copyHotkeyTask, getSendCopyHotkeyRootRunId(copyHotkeyTask)),
        });

        if (!hotkeyResult || hotkeyResult.ok !== true) {
          throw new Error(`hotkey failed: ${hotkeyResult && hotkeyResult.reason ? hotkeyResult.reason : 'unknown'}`);
        }
        copyHotkeyTask.hotkeySent = true;

        finishSendCopyHotkeyTask({
          ok: true,
          reason: 'done',
          copied: true,
          hotkeySent: true,
          replyDone: true,
          nativeSendConfirmed: copyHotkeyTask.nativeSendConfirmed === true,
        });
        return {
          ok: true,
          copied: true,
          hotkeySent: true,
        };
      } catch (error) {
        console.error('[SEND_COPY_HOTKEY][POST_ACTION_FAILED]', error);
        ToolboxShell.appendLog(
          `[SEND_COPY_HOTKEY][POST_ACTION_FAILED] error_type=${error && error.name ? error.name : '-'} error=${error && error.message ? error.message : String(error)} reason=${reason || '-'}`,
        );
        ToolboxShell.appendLog(
          `[SEND_COPY_HOTKEY][ERROR] runId=${getSendCopyHotkeyRootRunId(copyHotkeyTask) || '-'} phase=${copyHotkeyTask.phase || '-'} action=post-action errorName=${error && error.name ? error.name : '-'} errorMessage=${error && error.message ? error.message : String(error)} stack=${error && error.stack ? String(error.stack).replace(/\s+/g, ' ').slice(0, 400) : '-'}`,
        );
        finishSendCopyHotkeyTask({
          ok: false,
          reason: 'post-action-failed',
          error: error && error.message ? error.message : String(error),
        });
        return {
          ok: false,
          reason: 'post-action-failed',
          error: error && error.message ? error.message : String(error),
        };
      } finally {
        sendCopyHotkeyPostActionRunning = false;
      }
    }

    async function reconcileSendCopyHotkeyWaitingReply(reason = '-') {
      if (sendCopyHotkeyReconcileRunning) {
        return false;
      }

      const action = String(
        sendMessageTaskState.action || sendMessageTaskState.plan?.mode || '',
      ).trim();
      const copyHotkeyTask = ensureSendCopyHotkeyTask();
      const copyPhase = String(copyHotkeyTask.phase || '').trim().toLowerCase();
      const sendPhase = String(sendMessageTaskState.phase || '').trim().toLowerCase();
      const sendTaskPhase = String(getSendTaskPhase() || '').trim().toLowerCase();
      const isSendCopyHotkey = action === 'send-copy-hotkey' || action === 'send-copy-hotkey-continue';

      const inWaitingState = isSendCopyHotkeyWaitingReplyPhase(copyPhase)
        || (sendMessageTaskState.running && isSendCopyHotkey && isSendCopyHotkeyWaitingReplyPhase(sendPhase))
        || (isSendCopyHotkey && isSendCopyHotkeyWaitingReplyPhase(sendTaskPhase));

      if (!inWaitingState) {
        return false;
      }

      if (reconcileSendCopyHotkeyBackgroundThrottle(reason)) {
        return false;
      }

      if (!isAssistantReplyFinishedNow(reason)) {
        return false;
      }

      const gateState = buildSendCopyHotkeyHotkeyGateState({ replyDone: true, copied: false });
      if (gateState.responseState === 'generating' || gateState.waitingReply) {
        return false;
      }

      if (sendCopyHotkeyPostActionRunning) {
        return false;
      }

      sendCopyHotkeyReconcileRunning = true;
      try {
        ToolboxShell.appendLog(
          `[SEND_COPY_HOTKEY][REPLY_DONE_DETECTED] reason=${reason || '-'} action=${action || copyPhase} oldPhase=${copyPhase || sendPhase || sendTaskPhase} owner=${sendMessageTaskState.ownerButtonId || '-'}`,
        );

        copyHotkeyTask.phase = 'reply_done_waiting_copy';
        copyHotkeyTask.replyDone = true;
        copyHotkeyTask.updatedAt = Date.now();
        logSendCopyHotkeyTaskMilestone(copyHotkeyTask, 'reply_done_waiting_copy', reason);
        if (sendMessageTaskState.running && isSendCopyHotkey) {
          setSendMessageTaskPhase(SEND_MESSAGE_PHASES.SENT_WAITING_RESPONSE, `reply-done-detected:${reason}`);
        }

        safeRenderUploadButtonsOnly({
          immediate: true,
          force: true,
          buttonTasksReason: `send-copy-hotkey-reply-done:${reason}`,
        });

        await continueSendCopyHotkeyAfterReplyDone(reason);
        return true;
      } finally {
        sendCopyHotkeyReconcileRunning = false;
      }
    }

    function recoverSendTaskWaitingComposerIfReady(reason = '-') {
      if (!sendMessageTaskState || !sendMessageTaskState.running) {
        return false;
      }
      if (!isSendTaskWaitingComposerPhase()) {
        return false;
      }
      if (sendMessageTaskState.recoveringFromWaitingComposer === true) {
        return false;
      }
      const text = typeof ComposerApi !== 'undefined'
        && ComposerApi
        && typeof ComposerApi.getComposerText === 'function'
        ? String(ComposerApi.getComposerText() || '').trim()
        : '';
      const hasAttachment = typeof ComposerApi !== 'undefined'
        && ComposerApi
        && typeof ComposerApi.hasComposerAttachmentUnified === 'function'
        && ComposerApi.hasComposerAttachmentUnified();
      let nativeReady = false;
      let btn = null;
      if (
        typeof ComposerApi !== 'undefined'
        && ComposerApi
        && typeof ComposerApi.findSendButton === 'function'
      ) {
        btn = ComposerApi.findSendButton({ silent: true });
      }
      if (
        btn instanceof HTMLButtonElement
        && typeof ComposerApi !== 'undefined'
        && ComposerApi
        && typeof ComposerApi.isSendButtonReady === 'function'
      ) {
        nativeReady = ComposerApi.isSendButtonReady(btn);
      }
      if (!(nativeReady && (text.length > 0 || hasAttachment))) {
        return false;
      }
      sendMessageTaskState.recoveringFromWaitingComposer = true;
      ToolboxShell.appendLog(
        `[SEND_TASK][WAITING_COMPOSER_RECOVER_READY] reason=${reason || '-'} textLen=${text.length} hasAttachment=${hasAttachment ? 1 : 0} nativeReady=${nativeReady ? 1 : 0}`,
      );
      setSendMessageTaskPhase(
        SEND_MESSAGE_PHASES.READY_TO_CLICK,
        `waiting-composer-recover:${reason || '-'}`,
      );
      Promise.resolve()
        .then(() => sendExistingComposerBySendMessageButtonCore({
          source: `waiting-composer-recover:${reason || '-'}`,
          logSource: `waiting-composer-recover:${reason || '-'}`,
          manualSend: true,
          text: '',
          allowReplaceDraft: false,
        }))
        .then((result) => {
          ToolboxShell.appendLog(
            `[SEND_TASK][WAITING_COMPOSER_RECOVER_RESULT] reason=${reason || '-'} ok=${result && result.ok ? 1 : 0} detail=${result && result.reason ? result.reason : '-'}`,
          );
        })
        .catch((err) => {
          const errText = err && err.stack ? err.stack : (err && err.message ? err.message : String(err));
          console.error('[SEND_TASK][WAITING_COMPOSER_RECOVER_FAILED]', err);
          ToolboxShell.appendLog(
            `[SEND_TASK][WAITING_COMPOSER_RECOVER_FAILED] reason=${reason || '-'} error=${errText}`,
          );
        })
        .finally(() => {
          sendMessageTaskState.recoveringFromWaitingComposer = false;
        });
      return true;
    }

    function reconcileSendCopyHotkeyWaitState(reason = '-') {
      if (reconcileSendCopyHotkeyBackgroundThrottle(reason)) {
        return true;
      }
      if (
        typeof checkSendCopyHotkeyWaitTimeout === 'function'
        && checkSendCopyHotkeyWaitTimeout(reason)
      ) {
        return true;
      }
      if (
        typeof checkSendCopyHotkeyReplyStableDone === 'function'
        && checkSendCopyHotkeyReplyStableDone(reason)
      ) {
        return true;
      }
      if (typeof recoverSendTaskWaitingComposerIfReady === 'function') {
        const recovered = recoverSendTaskWaitingComposerIfReady(`reconcile:${reason || '-'}`);
        if (recovered) {
          return true;
        }
      }

      const action = String(
        sendMessageTaskState.action || sendMessageTaskState.plan?.mode || '',
      ).trim();
      const copyHotkeyTask = ensureSendCopyHotkeyTask();
      const copyPhase = String(copyHotkeyTask.phase || '').trim().toLowerCase();
      const sendPhase = String(sendMessageTaskState.phase || '').trim().toLowerCase();
      const isSendCopyHotkey = action === 'send-copy-hotkey' || action === 'send-copy-hotkey-continue';
      const waiting = isSendCopyHotkeyWaitingReplyPhase(copyPhase)
        || (sendMessageTaskState.running && isSendCopyHotkey && isSendCopyHotkeyWaitingReplyPhase(sendPhase));

      if (!waiting) {
        return false;
      }

      void reconcileSendCopyHotkeyWaitingReply(reason).catch((reconcileErr) => {
        console.error('[SEND_COPY_HOTKEY][RECONCILE_FAILED]', reconcileErr);
        ToolboxShell.appendLog(
          `[SEND_COPY_HOTKEY][RECONCILE_FAILED] reason=${reason || '-'} error=${reconcileErr && reconcileErr.message ? reconcileErr.message : String(reconcileErr)}`,
        );
      });
      return false;
    }

    function maybeReconcileSendCopyHotkeyWaitingReply(reason = '-') {
      if (typeof recoverSendTaskWaitingComposerIfReady === 'function') {
        const recovered = recoverSendTaskWaitingComposerIfReady(`maybe-reconcile:${reason || '-'}`);
        if (recovered) {
          return;
        }
      }
      reconcileSendCopyHotkeyWaitState(reason);
    }

    function findNativeSendButtonForAssert() {
      if (typeof findUploadComposerSendButton === 'function') {
        const btn = findUploadComposerSendButton();
        if (btn instanceof HTMLButtonElement) {
          return btn;
        }
      }
      if (typeof getComposerSendButtonSnapshot === 'function') {
        const snap = getComposerSendButtonSnapshot({ silent: true });
        if (snap && snap.button instanceof HTMLButtonElement) {
          return snap.button;
        }
      }
      return null;
    }

    function isNativeButtonStopButton(button) {
      if (!(button instanceof HTMLButtonElement)) {
        return false;
      }
      if (typeof isStopComposerButton === 'function' && isStopComposerButton(button)) {
        return true;
      }
      const aria = String(button.getAttribute('aria-label') || '').trim();
      const text = String(button.textContent || '').trim();
      return /停止|stop/i.test(aria) || /停止|stop/i.test(text);
    }

    function assertNativeButtonIsSendButton(button, reason = '-') {
      if (!button) {
        ToolboxShell.appendLog(`[NATIVE_SEND][ASSERT_FAIL] reason=${reason} missing-button`);
        return false;
      }
      if (isNativeButtonStopButton(button)) {
        const aria = String(button.getAttribute('aria-label') || '').trim();
        const text = String(button.textContent || '').trim();
        ToolboxShell.appendLog(
          `[NATIVE_SEND][ASSERT_FAIL] reason=${reason} button-is-stop aria=${aria} text=${text}`,
        );
        return false;
      }
      return true;
    }

    function isChatGptResponseBusyForSend() {
      let responseState = {};
      try {
        responseState = typeof detectComposerResponseState === 'function'
          ? detectComposerResponseState()
          : {};
      } catch (err) {
        const errText = err && err.message ? err.message : String(err);
        console.warn('[SEND_LIKE_PENDING][RESPONSE_STATE_FAILED]', err);
        ToolboxShell.appendLog(
          `[SEND_LIKE_PENDING][RESPONSE_STATE_FAILED] error=${errText}`,
        );
        responseState = {};
      }
      const responseStateText = String(
        responseState.response_state
          || responseState.responseState
          || responseState.state
          || '',
      ).trim().toLowerCase();
      const reason = String(
        responseState.response_state_reason
          || responseState.responseStateReason
          || responseState.reason
          || '',
      ).trim().toLowerCase();
      if (
        responseStateText === 'streaming'
        || responseStateText === 'answering'
        || responseStateText === 'generating'
        || responseStateText === 'busy'
        || responseStateText === 'not_ready'
        || responseStateText === 'responding'
      ) {
        return true;
      }
      if (
        reason.includes('generating')
        || reason.includes('streaming')
        || reason.includes('stop_button')
        || reason.includes('stop-generating')
        || reason === 'assistant_busy'
      ) {
        return true;
      }
      if (
        responseState.is_responding === true
        || responseState.responding === true
        || responseState.busy === true
      ) {
        return true;
      }
      try {
        const cap = typeof getUploadPageCapability === 'function'
          ? getUploadPageCapability({ heavy: false })
          : {};
        if (cap && (cap.isResponding || cap.is_responding || cap.responding)) {
          return true;
        }
      } catch (capErr) {
        const errText = capErr && capErr.message ? capErr.message : String(capErr);
        console.warn('[SEND_LIKE_PENDING][CAPABILITY_BUSY_CHECK_FAILED]', capErr);
        ToolboxShell.appendLog(`[SEND_LIKE_PENDING][CAPABILITY_BUSY_CHECK_FAILED] error=${errText}`);
      }
      const nativeButton = findNativeSendButtonForAssert();
      if (isNativeButtonStopButton(nativeButton)) {
        return true;
      }
      return false;
    }

    function hasComposerPayloadForSendLikePending() {
      const preflight = getSendCopyHotkeyPreflightState('send-like-pending-check');
      return preflight.code !== 'empty-composer';
    }

    function isComposerActuallySendableForSendLike() {
      if (isChatGptResponseBusyForSend()) {
        return false;
      }
      const nativeButton = findNativeSendButtonForAssert();
      if (nativeButton && !assertNativeButtonIsSendButton(nativeButton, 'send-like-flush')) {
        return false;
      }
      const preflight = getSendCopyHotkeyPreflightState('send-like-flush');
      return preflight.ok === true;
    }

    function getCurrentSendLikePendingTask() {
      const task = state.sendLikePendingTask;
      return task && typeof task === 'object' ? task : null;
    }

    function setCurrentSendLikePendingTask(task) {
      const next = {
        action: String(task.action || '').trim(),
        taskKey: String(task.taskKey || task.action || '').trim(),
        phase: String(task.phase || 'waiting_reply').trim(),
        text: String(task.text || '').trim(),
        source: String(task.source || '-').trim(),
        ownerButtonId: String(task.ownerButtonId || '').trim(),
        fromSendCopyHotkey: task.fromSendCopyHotkey === true,
        createdAt: Date.now(),
      };
      if (next.action === 'send-copy-hotkey' && !next.ownerButtonId) {
        next.ownerButtonId = 'cgpt-send-copy-hotkey-once';
      }
      if (next.action === 'send-copy-hotkey' && !next.source.startsWith('send-copy-hotkey')) {
        next.fromSendCopyHotkey = next.fromSendCopyHotkey || next.source.includes('send-copy-hotkey');
      }
      const old = getCurrentSendLikePendingTask();
      if (old && old.action && old.action !== next.action) {
        ToolboxShell.appendLog(
          `[SEND_LIKE_PENDING][SWITCH] old=${old.action}:${old.phase} new=${next.action}:${next.phase} reason=user-click`,
        );
      }
      state.sendLikePendingTask = next;
      ToolboxShell.appendLog(
        `[SEND_LIKE_PENDING][SET] old=${old ? `${old.action}:${old.phase}` : '-'} new=${next.action}:${next.phase} source=${next.source}`,
      );
      syncUploadTaskStateFromSendLikePending('set-current-send-like-pending-task');
    }

    function clearCurrentSendLikePendingTask(reason = '-') {
      const old = getCurrentSendLikePendingTask();
      state.sendLikePendingTask = null;
      ToolboxShell.appendLog(
        `[SEND_LIKE_PENDING][CLEAR] old=${old ? `${old.action}:${old.phase}` : '-'} reason=${reason}`,
      );
      syncUploadTaskStateFromSendLikePending(`clear:${reason}`);
      safeRenderUploadButtonsOnly({
        immediate: true,
        force: true,
        buttonTasksReason: `clear-send-like-pending:${reason}`,
      });
    }

    function syncUploadTaskStateFromSendLikePending(reason = '-') {
      const pending = getCurrentSendLikePendingTask();
      if (!pending) {
        const task = ensureSendCopyHotkeyTask();
        const phase = String(task.phase || 'idle').trim().toLowerCase();
        if (phase === 'waiting_ready' || phase === 'waiting_input') {
          setSendCopyHotkeyPhase('idle', `send-like-pending-cleared:${reason}`, { runId: '' });
        }
        return;
      }
      if (pending.action === 'send-copy-hotkey') {
        let nextPhase = 'waiting_ready';
        if (pending.phase === 'waiting_input') {
          nextPhase = 'waiting_input';
        } else if (pending.phase === 'waiting_current_reply_done') {
          nextPhase = 'waiting_current_reply_done';
        } else if (pending.phase === 'waiting_composer_ready') {
          nextPhase = 'waiting_composer_ready';
        }
        const task = ensureSendCopyHotkeyTask();
        Object.assign(task, {
          runId: task.runId || createUploadTaskRunId('send_like_pending'),
          cancelRequested: false,
          pendingText: pending.text,
          source: pending.source,
        });
        setSendCopyHotkeyPhase(nextPhase, reason, { pendingText: pending.text });
        const deferSendMessageTask = nextPhase === 'waiting_current_reply_done'
          || nextPhase === 'waiting_composer_ready';
        if (!deferSendMessageTask) {
          if (!sendMessageTaskState.running) {
            startSendMessageTask(`send-like-pending:${reason}`, 'send-copy-hotkey');
          } else if (
            String(sendMessageTaskState.action || sendMessageTaskState.plan?.mode || '').trim() !== 'send-copy-hotkey'
          ) {
            switchPendingSendTaskAction('send-copy-hotkey', {
              source: reason,
              buttonId: getButtonIdBySendAction('send-copy-hotkey'),
            });
          }
          setSendMessageTaskPhase(SEND_MESSAGE_PHASES.WAITING_COMPOSER, `send-like-pending:${reason}`);
        }
      }
      safeRenderUploadButtonsOnly({
        immediate: true,
        force: true,
        buttonTasksReason: `sync-send-like-pending:${reason}`,
      });
    }

    function startSendLikePendingWatcher(reason = '-') {
      if (sendLikePendingWatcherTimer) {
        return;
      }
      ToolboxShell.appendLog(`[SEND_LIKE_PENDING][WATCH_START] reason=${reason}`);
      sendLikePendingWatcherTimer = window.setInterval(() => {
        void flushClosedLoopStartPendingIfReady('interval');
        void flushSendLikePendingTaskIfReady('interval');
      }, 500);
    }

    function stopSendLikePendingWatcher(reason = '-') {
      if (getClosedLoopStartPending()) {
        return;
      }
      if (!sendLikePendingWatcherTimer) {
        return;
      }
      window.clearInterval(sendLikePendingWatcherTimer);
      sendLikePendingWatcherTimer = 0;
      ToolboxShell.appendLog(`[SEND_LIKE_PENDING][WATCH_STOP] reason=${reason}`);
    }

    async function flushSendLikePendingTaskIfReady(reason = '-') {
      const pending = getCurrentSendLikePendingTask();
      if (!pending) {
        stopSendLikePendingWatcher('no-pending-task');
        return;
      }
      if (pending.action === 'send-copy-hotkey') {
        if (pending.phase === 'waiting_current_reply_done' && isChatGptResponseBusyForSend()) {
          return;
        }
        const src = pending.source || `pending-flush:${reason}`;
        clearCurrentSendLikePendingTask(`flush-ready:${reason}`);
        stopSendLikePendingWatcher(`flush-ready:${reason}`);
        ToolboxShell.appendLog(`[SEND_LIKE_PENDING][FLUSH] action=send-copy-hotkey reason=${reason}`);
        await runSendCopyHotkeyComposed(src);
        return;
      }
      if (pending.phase === 'waiting_composer_ready') {
        const elapsedMs = Date.now() - Number(pending.createdAt || 0);
        if (elapsedMs > SEND_COPY_HOTKEY_COMPOSER_READY_TIMEOUT_MS) {
          const snap = readSendCopyHotkeyPageSnapshot('composer-not-ready-timeout');
          const sendableFlag = snap.sendable === false ? 0 : 1;
          const inputableFlag = snap.inputable === false ? 0 : 1;
          console.error('[SEND_COPY_HOTKEY][FAILED] composer-not-ready-timeout', {
            sendable: snap.sendable,
            inputable: snap.inputable,
            elapsedMs,
          });
          ToolboxShell.appendLog(
            `[SEND_COPY_HOTKEY][FAILED] reason=composer-not-ready-timeout sendable=${sendableFlag} inputable=${inputableFlag} elapsedMs=${elapsedMs}`,
          );
          setStatus('输入框未就绪，发送+复制+快捷键已超时', 'error');
          finishSendCopyHotkeyTask({
            ok: false,
            reason: 'composer-not-ready-timeout',
          });
          clearCurrentSendLikePendingTask('composer-not-ready-timeout');
          stopSendLikePendingWatcher('composer-not-ready-timeout');
          return;
        }
        if (!isComposerActuallySendableForSendLike()) {
          ToolboxShell.appendLog(
            `[SEND_LIKE_PENDING][NOT_SENDABLE_YET] action=${pending.action} phase=${pending.phase} reason=${reason} elapsedMs=${elapsedMs}`,
          );
          return;
        }
      }
      if (pending.phase === 'waiting_input') {
        if (!hasComposerPayloadForSendLikePending()) {
          return;
        }
        pending.phase = 'waiting_reply';
        pending.text = resolveSendLikePendingText(pending.action, 'waiting_reply');
        state.sendLikePendingTask = pending;
        ToolboxShell.appendLog(
          `[SEND_LIKE_PENDING][INPUT_READY] action=${pending.action} reason=${reason}`,
        );
        syncUploadTaskStateFromSendLikePending('send-like-input-ready');
      }
      if (pending.phase === 'waiting_current_reply_done' && isChatGptResponseBusyForSend()) {
        return;
      }
      if (isChatGptResponseBusyForSend()) {
        return;
      }
      if (!isComposerActuallySendableForSendLike()) {
        ToolboxShell.appendLog(
          `[SEND_LIKE_PENDING][NOT_SENDABLE_YET] action=${pending.action} reason=${reason}`,
        );
        return;
      }
      const action = pending.action;
      clearCurrentSendLikePendingTask(`flush-ready:${reason}`);
      stopSendLikePendingWatcher(`flush-ready:${reason}`);
      ToolboxShell.appendLog(`[SEND_LIKE_PENDING][FLUSH] action=${action} reason=${reason}`);
      if (action === 'send-message') {
        const runId = state.autoSendRunId || Date.now();
        if (state.pendingSendAfterReply) {
          await trySendPendingAfterReplyOpportunity(runId);
        } else {
          await triggerSendFromToolbox(pending.source || `pending-flush:${reason}`, {
            rawSource: pending.source || `pending-flush:${reason}`,
          });
        }
        return;
      }
      ToolboxShell.appendLog(`[SEND_LIKE_PENDING][UNKNOWN_ACTION] action=${action}`);
    }

    function composeSleep(ms) {
      return new Promise((resolve) => window.setTimeout(resolve, ms));
    }

    async function waitOrchSendCopyHotkeyActive(timeoutMs = 2500) {
      const startedAt = Date.now();
      while (Date.now() - startedAt < timeoutMs) {
        const orchViews = typeof BRIDGE_STATE !== 'undefined'
          ? (BRIDGE_STATE.orch_button_views || {})
          : {};
        const view = orchViews['cgpt-send-copy-hotkey-once'];
        if (view && view.active === true) {
          return true;
        }
        await composeSleep(100);
      }
      return false;
    }

    function isNativeChatGptSendButtonReadyForCompose() {
      if (typeof document === 'undefined') {
        return false;
      }
      const candidates = [
        document.querySelector('button#composer-submit-button'),
        document.querySelector('button[data-testid="send-button"]'),
        document.querySelector('button[aria-label*="发送"]'),
        document.querySelector('button[aria-label*="Send"]'),
      ].filter(Boolean);
      for (const btn of candidates) {
        if (!(btn instanceof HTMLButtonElement)) {
          continue;
        }
        const aria = String(btn.getAttribute('aria-label') || '').trim();
        const text = String(btn.textContent || '').trim();
        const merged = `${aria} ${text}`;
        if (
          /移除文件|删除文件|移除附件|删除附件|添加文件|上传文件|开始听写|启动语音|停止回答|打开图片/i.test(merged)
        ) {
          continue;
        }
        const disabled =
          btn.disabled
          || btn.getAttribute('aria-disabled') === 'true'
          || btn.dataset.disabled === 'true';
        if (!disabled) {
          return true;
        }
      }
      return false;
    }

    function canComposeSendDespiteInputableBlock(responseState, responseReason, sendable) {
      const responseText = String(responseState || '').trim().toLowerCase();
      const reasonText = String(responseReason || '').trim().toLowerCase();
      const readyOverride =
        responseText === 'ready'
        && reasonText === 'home_new_chat_composer_ready_override';
      if (sendable !== false && sendable !== 0) {
        return true;
      }
      if (readyOverride || responseText === 'ready') {
        return true;
      }
      return isNativeChatGptSendButtonReadyForCompose();
    }

    async function waitComposerSendReadyForCompose(options = {}) {
      const {
        source = 'send-copy-hotkey',
        timeoutMs = 20000,
      } = options;
      const startedAt = Date.now();
      const src = String(source || 'send-copy-hotkey').trim() || 'send-copy-hotkey';
      ToolboxShell.appendLog(
        `[SEND_COPY_HOTKEY][WAIT_SEND_READY_START] source=${src} timeoutMs=${timeoutMs}`,
      );
      while (Date.now() - startedAt < timeoutMs) {
        const snapshot = typeof buildUploadButtonRenderSnapshot === 'function'
          ? buildUploadButtonRenderSnapshot(`wait-send-ready:${src}`)
          : {};
        const capability = snapshot && snapshot.capability && typeof snapshot.capability === 'object'
          ? snapshot.capability
          : {};
        const responseState = String(
          snapshot.response_state
          || snapshot.responseState
          || capability.response_state
          || capability.responseState
          || '',
        ).trim();
        const reason = String(
          snapshot.response_state_reason
          || snapshot.responseStateReason
          || capability.response_state_reason
          || capability.responseStateReason
          || '',
        ).trim();
        const inputable = (
          snapshot.inputable === true
          || snapshot.inputable === 1
          || snapshot.can_accept_input === true
          || snapshot.canAcceptInput === true
          || capability.inputable === true
          || capability.inputable === 1
          || capability.can_accept_input === true
          || capability.canAcceptInput === true
        );
        const sendable = (
          snapshot.sendable === true
          || snapshot.sendable === 1
          || snapshot.can_send_now === true
          || snapshot.canSendNow === true
          || capability.sendable === true
          || capability.sendable === 1
          || capability.can_send_now === true
          || capability.canSendNow === true
        );
        const readyOverride =
          responseState === 'ready'
          && reason === 'home_new_chat_composer_ready_override';
        const nativeSendButtonReady = isNativeChatGptSendButtonReadyForCompose();
        const composerTextLen = Number(
          snapshot.composerTextLen
          || snapshot.textLen
          || capability.composerTextLen
          || capability.textLength
          || 0,
        ) || 0;
        const composerCount = Number(
          snapshot.composerCount
          || snapshot.composerReady
          || snapshot.composerFileCount
          || 0,
        ) || 0;
        ToolboxShell.appendLog(
          `[SEND_COPY_HOTKEY][WAIT_SEND_READY_CHECK] source=${src} responseState=${responseState || '-'} reason=${reason || '-'} inputable=${inputable ? 1 : 0} sendable=${sendable ? 1 : 0} nativeSendReady=${nativeSendButtonReady ? 1 : 0} readyOverride=${readyOverride ? 1 : 0} composerTextLen=${composerTextLen} composerCount=${composerCount}`,
        );
        if (
          nativeSendButtonReady
          || (sendable && inputable)
          || (sendable && readyOverride)
          || (sendable && responseState === 'ready')
        ) {
          ToolboxShell.appendLog(
            `[SEND_COPY_HOTKEY][WAIT_SEND_READY_DONE] source=${src} elapsedMs=${Date.now() - startedAt} responseState=${responseState || '-'} reason=${reason || '-'} inputable=${inputable ? 1 : 0} sendable=${sendable ? 1 : 0} nativeSendReady=${nativeSendButtonReady ? 1 : 0}`,
          );
          return {
            ok: true,
            reason: 'send-ready',
            responseState,
            responseStateReason: reason,
          };
        }
        const shouldWait =
          reason === 'home_new_chat_payload_but_send_button_missing'
          || reason === 'send_button_not_found'
          || reason === 'send_button_disabled'
          || reason === 'attachment_processing'
          || responseState === 'attachment_processing'
          || responseState === 'not_ready'
          || responseState === '';
        const waitLabel =
          reason === 'attachment_processing' || responseState === 'attachment_processing'
            ? '等待附件'
            : '等待发送按钮';
        setSendCopyHotkeyPhase('waiting_input', `wait-send-ready:${reason || responseState || '-'}`, {
          pendingText: waitLabel,
        });
        if (!shouldWait) {
          ToolboxShell.appendLog(
            `[SEND_COPY_HOTKEY][WAIT_SEND_READY_UNEXPECTED_STATE] source=${src} responseState=${responseState || '-'} reason=${reason || '-'} inputable=${inputable ? 1 : 0} sendable=${sendable ? 1 : 0} nativeSendReady=${nativeSendButtonReady ? 1 : 0}`,
          );
        }
        await composeSleep(300);
      }
      ToolboxShell.appendLog(
        `[SEND_COPY_HOTKEY][WAIT_SEND_READY_TIMEOUT] source=${src} timeoutMs=${timeoutMs}`,
      );
      return {
        ok: false,
        reason: 'send-ready-timeout',
      };
    }

    function isSendCopyHotkeyRunning() {
      return isSendCopyHotkeyActive();
    }

    function requestCancelSendCopyHotkeyTask(source = 'user-click') {
      return cancelSendCopyHotkey(source);
    }

    async function runSendMessageCoreForCompose(source = 'send-copy-hotkey') {
      const src = String(source || 'send-copy-hotkey').trim() || 'send-copy-hotkey';
      const ready = await waitComposerSendReadyForCompose({
        source: src,
        timeoutMs: 20000,
      });
      if (!ready || ready.ok !== true) {
        const reason = ready && ready.reason ? ready.reason : 'send-ready-timeout';
        const failText = reason === 'send-ready-timeout'
          ? '等待发送按钮超时，未能发送'
          : `无法发送：${reason}`;
        setStatus(failText, 'error');
        return {
          ok: false,
          reason,
        };
      }
      ToolboxShell.appendLog(
        `[SEND_COPY_HOTKEY][DELEGATE_SEND_MESSAGE] source=${src}`,
      );
      reconcileSendCopyHotkeyOwnerRunningState('runSendMessageCoreForCompose');
      const sendOk = await triggerSendFromToolbox('send-copy-hotkey-compose', {
        parentAction: 'send-copy-hotkey',
        rawSource: src,
        suppressSendButtonFailureUi: true,
      });
      if (sendOk === true) {
        const task = ensureSendCopyHotkeyTask();
        task.nativeSendConfirmed = true;
        return {
          ok: true,
          reason: 'sent',
        };
      }
      const reason = String(lastUploadSendPanelFailReason || 'send-message-failed').trim()
        || 'send-message-failed';
      return {
        ok: false,
        reason,
      };
    }

    async function runCopyHotkeyCoreForCompose(source = 'send-copy-hotkey') {
      const src = String(source || 'send-copy-hotkey').trim() || 'send-copy-hotkey';
      ToolboxShell.appendLog(
        `[SEND_COPY_HOTKEY][DELEGATE_COPY_HOTKEY] source=${src}`,
      );
      const copyHotkeyTask = ensureSendCopyHotkeyTask();
      const shouldStop = () => isSendCopyHotkeyRunCancelled(
        copyHotkeyTask,
        getSendCopyHotkeyRootRunId(copyHotkeyTask),
      );
      if (shouldStop()) {
        return {
          ok: false,
          reason: 'cancelled',
        };
      }

      const copyResult = await copyLatestAssistantReplyUnified({
        reason: `send-copy-hotkey-compose:${src}`,
        scrollBeforeCopy: true,
      });
      if (!copyResult || copyResult.ok !== true) {
        return {
          ok: false,
          reason: copyResult && copyResult.reason ? copyResult.reason : 'copy-failed',
          copied: false,
          hotkeySent: false,
        };
      }
      copyHotkeyTask.copied = true;
      copyHotkeyTask.replyDone = true;

      if (typeof playCopySuccessBeepSafe === 'function') {
        void playCopySuccessBeepSafe(`send-copy-hotkey-compose:${src}`, 'sendCopyHotkey');
      }

      setSendCopyHotkeyPhase('hotkey_sending', 'composed-hotkey-send', {
        pendingText: '复制+快捷键中',
      });

      const hotkeyGateState = buildSendCopyHotkeyHotkeyGateState({
        replyDone: true,
        copied: true,
        waitingReply: false,
      });
      const hotkeyResult = await sendHotkeyAfterCopy({
        copiedText: copyResult.text || '',
        reason: 'send-copy-hotkey-compose',
        gateState: hotkeyGateState,
        skipHotkeyGate: true,
        shouldStop,
      });
      if (!hotkeyResult || hotkeyResult.ok !== true) {
        return {
          ok: false,
          reason: hotkeyResult && hotkeyResult.reason ? hotkeyResult.reason : 'hotkey-failed',
          copied: true,
          hotkeySent: false,
        };
      }
      copyHotkeyTask.hotkeySent = true;
      return {
        ok: true,
        reason: 'copy-hotkey-done',
        copied: true,
        hotkeySent: true,
      };
    }

    function readWaitReplySnapshotFields(snapshot = {}) {
      const cap = snapshot.capability && typeof snapshot.capability === 'object'
        ? snapshot.capability
        : {};
      const bridgePoll = typeof BridgePollRuntime !== 'undefined' && BridgePollRuntime
        ? BridgePollRuntime
        : {};
      const responseState = String(
        snapshot.response_state
        || snapshot.responseState
        || cap.response_state
        || cap.responseState
        || bridgePoll.response_state
        || '',
      ).trim().toLowerCase();
      const reason = String(
        snapshot.response_state_reason
        || snapshot.responseStateReason
        || cap.response_state_reason
        || cap.responseStateReason
        || bridgePoll.response_state_reason
        || '',
      ).trim().toLowerCase();
      const inputable = !!(
        snapshot.inputable === true
        || snapshot.inputable === 1
        || cap.inputable === true
        || cap.inputable === 1
        || cap.can_accept_input
        || cap.canAcceptInput
        || bridgePoll.inputable === true
        || bridgePoll.inputable === 1
      );
      const sendable = !!(
        snapshot.sendable === true
        || snapshot.sendable === 1
        || cap.sendable === true
        || cap.sendable === 1
        || cap.can_send_now
        || cap.canSendNow
        || bridgePoll.sendable === true
        || bridgePoll.sendable === 1
      );
      return { responseState, reason, inputable, sendable };
    }

    function hasVisibleNativeStopButtonForWaitReply() {
      if (typeof document === 'undefined') {
        return false;
      }
      const stopButtonCandidates = Array.from(document.querySelectorAll([
        '[data-testid="stop-button"]',
        'button[aria-label*="停止回答"]',
        'button[aria-label*="停止生成"]',
        'button[aria-label*="Stop"]',
        'button[aria-label*="stop"]',
      ].join(',')));
      return stopButtonCandidates.some((btn) => {
        if (!(btn instanceof HTMLElement)) {
          return false;
        }
        if (typeof isNativeStopButtonElement === 'function' && !isNativeStopButtonElement(btn)) {
          return false;
        }
        const rect = btn.getBoundingClientRect();
        return rect.width > 0 && rect.height > 0;
      });
    }

    async function waitAssistantReplyDoneForCompose(options = {}) {
      const {
        source = 'send-copy-hotkey',
        runId = Date.now(),
        timeoutMs = 180000,
      } = options;
      const startedAt = Date.now();
      let sawGenerating = false;
      let stableIdleCount = 0;
      const task = ensureSendCopyHotkeyTask();
      const nativeSendConfirmed = task.nativeSendConfirmed === true;
      ToolboxShell.appendLog(
        `[SEND_COPY_HOTKEY][WAIT_REPLY_START] source=${source} runId=${runId} timeoutMs=${timeoutMs} nativeSendConfirmed=${nativeSendConfirmed ? 1 : 0}`,
      );
      while (Date.now() - startedAt < timeoutMs) {
        if (isSendCopyHotkeyRunCancelled(task, runId)) {
          ToolboxShell.appendLog(
            `[SEND_COPY_HOTKEY][WAIT_REPLY_CANCELLED] runId=${runId}`,
          );
          return {
            ok: false,
            reason: 'cancelled',
            sawGenerating,
          };
        }
        const snapshot = typeof buildUploadButtonRenderSnapshot === 'function'
          ? buildUploadButtonRenderSnapshot(`wait-reply:${source}`)
          : {};
        const {
          responseState,
          reason: reasonText,
          inputable,
          sendable,
        } = readWaitReplySnapshotFields(snapshot);
        const isIdle = responseState === 'idle' || responseState === 'ready';
        const isAssistantBusy = responseState === 'generating'
          || responseState === 'responding'
          || responseState === 'answering'
          || reasonText === 'assistant_busy'
          || reasonText === 'response_in_progress'
          || hasVisibleNativeStopButtonForWaitReply();
        const isEmptyComposer = reasonText === 'empty_composer';
        if (isAssistantBusy) {
          sawGenerating = true;
          stableIdleCount = 0;
          setSendCopyHotkeyPhase('waiting_response', 'assistant-generating', {
            runId,
            pendingText: '等待回复',
          });
          await composeSleep(500);
          continue;
        }
        const canAcceptIdleDone = isIdle
          && !isAssistantBusy
          && (
            inputable
            || isEmptyComposer
            || nativeSendConfirmed
          );
        if (canAcceptIdleDone) {
          stableIdleCount += 1;
          if (stableIdleCount >= 2) {
            ToolboxShell.appendLog(
              `[SEND_COPY_HOTKEY][WAIT_REPLY_DONE] runId=${runId} responseState=${responseState || '-'} reason=${reasonText || '-'} inputable=${inputable ? 1 : 0} sendable=${sendable ? 1 : 0} nativeSendConfirmed=${nativeSendConfirmed ? 1 : 0} sawGenerating=${sawGenerating ? 1 : 0}`,
            );
            task.replyDone = true;
            return {
              ok: true,
              reason: 'reply-done-idle-empty-composer',
              responseState,
              responseStateReason: reasonText,
              sawGenerating,
            };
          }
        } else {
          stableIdleCount = 0;
        }
        await composeSleep(500);
      }

      const finalSnapshot = typeof buildUploadButtonRenderSnapshot === 'function'
        ? buildUploadButtonRenderSnapshot('wait-reply-timeout-final-check')
        : {};
      const {
        responseState: finalResponseState,
        reason: finalReason,
        inputable: finalInputable,
      } = readWaitReplySnapshotFields(finalSnapshot);
      const finalAssistantBusy = finalResponseState === 'generating'
        || finalResponseState === 'responding'
        || finalResponseState === 'answering'
        || finalReason === 'assistant_busy'
        || finalReason === 'response_in_progress'
        || hasVisibleNativeStopButtonForWaitReply();
      if (
        nativeSendConfirmed
        && !finalAssistantBusy
        && (
          finalResponseState === 'idle'
          || finalResponseState === 'ready'
          || finalReason === 'empty_composer'
          || finalInputable
        )
      ) {
        ToolboxShell.appendLog(
          `[SEND_COPY_HOTKEY][WAIT_REPLY_TIMEOUT_RECOVER_AS_DONE] runId=${runId} responseState=${finalResponseState || '-'} reason=${finalReason || '-'} inputable=${finalInputable ? 1 : 0}`,
        );
        task.replyDone = true;
        return {
          ok: true,
          reason: 'timeout-recovered-as-reply-done',
          responseState: finalResponseState,
          responseStateReason: finalReason,
          sawGenerating,
        };
      }

      ToolboxShell.appendLog(
        `[SEND_COPY_HOTKEY][WAIT_REPLY_TIMEOUT] runId=${runId} timeoutMs=${timeoutMs} sawGenerating=${sawGenerating ? 1 : 0}`,
      );
      return {
        ok: false,
        reason: 'wait-reply-timeout',
        sawGenerating,
      };
    }

    async function maybeWaitCurrentReplyBeforeComposeSend(runId) {
      const pageBusy = isAssistantGeneratingNow('compose-pre-send')
        || isChatGptResponseBusyForSend();
      if (!pageBusy) {
        return {
          ok: true,
          reason: 'not-busy',
        };
      }
      const hasPayload = typeof detectPendingComposerPayloadForSend === 'function'
        ? detectPendingComposerPayloadForSend()
        : false;
      if (!hasPayload) {
        return {
          ok: true,
          reason: 'no-payload-defer-to-send-core',
        };
      }
      ToolboxShell.appendLog(
        '[SEND_COPY_HOTKEY][WAIT_CURRENT_REPLY_BEFORE_SEND] reason=page-busy-with-payload',
      );
      setSendCopyHotkeyPhase('waiting_response', 'wait-current-reply-before-send', {
        runId,
        pendingText: '等待当前回复',
      });
      return waitAssistantReplyDoneForCompose({
        source: 'pre-send',
        runId,
        timeoutMs: 180000,
      });
    }

    async function runSendCopyHotkeyComposed(source = 'button') {
      const src = String(source || 'button').trim() || 'button';
      const runId = createUploadTaskRunId('send_copy_hotkey');
      const task = ensureSendCopyHotkeyTask();
      Object.assign(task, {
        runId,
        rootRunId: runId,
        postRunId: '',
        cancelRequested: false,
        startedAt: Date.now(),
        updatedAt: Date.now(),
        lastError: null,
        source: src,
        ownerButtonId: 'cgpt-send-copy-hotkey-once',
        nativeSendConfirmed: false,
        replyDone: false,
        copied: false,
        hotkeySent: false,
      });
      ToolboxShell.appendLog(
        `[SEND_COPY_HOTKEY][COMPOSED_START] source=${src} runId=${runId}`,
      );
      setSendCopyHotkeyPhase('sending', 'composed-start', {
        runId,
        pendingText: '发送中',
      });
      try {
        const preWaitResult = await maybeWaitCurrentReplyBeforeComposeSend(runId);
        if (!preWaitResult || preWaitResult.ok === false) {
          const reason = preWaitResult && preWaitResult.reason
            ? preWaitResult.reason
            : 'wait-current-reply-failed';
          ToolboxShell.appendLog(
            `[SEND_COPY_HOTKEY][COMPOSED_PRE_WAIT_FAILED] runId=${runId} reason=${reason}`,
          );
          finishSendCopyHotkeyTask({
            ok: false,
            reason,
          });
          return {
            ok: false,
            reason,
          };
        }

        setSendCopyHotkeyPhase('sending', 'composed-send', {
          runId,
          pendingText: '发送中',
        });
        const sendResult = await runSendMessageCoreForCompose(src);
        if (!sendResult || sendResult.ok === false) {
          const reason = sendResult && sendResult.reason ? sendResult.reason : 'send-message-failed';
          const failMessage = typeof mapUploadSendFailureMessage === 'function'
            ? mapUploadSendFailureMessage(reason)
            : '';
          setStatus(failMessage || `发送失败：${reason}`, 'error');
          ToolboxShell.appendLog(
            `[SEND_COPY_HOTKEY][COMPOSED_SEND_FAILED] runId=${runId} reason=${reason}`,
          );
          finishSendCopyHotkeyTask({
            ok: false,
            reason,
          });
          return {
            ok: false,
            reason,
          };
        }
        ToolboxShell.appendLog(
          `[SEND_COPY_HOTKEY][COMPOSED_SEND_DONE] runId=${runId}`,
        );

        setSendCopyHotkeyPhase('waiting_response', 'composed-wait-response', {
          runId,
          pendingText: '等待回复',
        });
        const waitResult = await waitAssistantReplyDoneForCompose({
          source: 'send-copy-hotkey',
          runId,
          timeoutMs: 180000,
        });
        if (!waitResult || waitResult.ok === false) {
          const reason = waitResult && waitResult.reason ? waitResult.reason : 'wait-response-failed';
          const statusText = reason === 'wait-reply-timeout'
            ? '等待回复超时，未执行复制+快捷键'
            : (reason === 'cancelled' ? '已取消发送+复制+快捷键' : `等待回复失败：${reason}`);
          setStatus(statusText, reason === 'cancelled' ? 'warn' : 'error');
          ToolboxShell.appendLog(
            `[SEND_COPY_HOTKEY][COMPOSED_WAIT_FAILED] runId=${runId} reason=${reason}`,
          );
          finishSendCopyHotkeyTask({
            ok: false,
            reason,
          });
          return {
            ok: false,
            reason,
          };
        }
        ToolboxShell.appendLog(
          `[SEND_COPY_HOTKEY][COMPOSED_REPLY_DONE] runId=${runId}`,
        );

        setSendCopyHotkeyPhase('copy_hotkey', 'composed-copy-hotkey', {
          runId,
          pendingText: '复制+快捷键中',
        });
        const copyHotkeyResult = await runCopyHotkeyCoreForCompose(src);
        if (!copyHotkeyResult || copyHotkeyResult.ok === false) {
          const reason = copyHotkeyResult && copyHotkeyResult.reason
            ? copyHotkeyResult.reason
            : 'copy-hotkey-failed';
          setStatus(`复制+快捷键失败：${reason}`, 'error');
          ToolboxShell.appendLog(
            `[SEND_COPY_HOTKEY][COMPOSED_COPY_HOTKEY_FAILED] runId=${runId} reason=${reason}`,
          );
          finishSendCopyHotkeyTask({
            ok: false,
            reason,
            copied: copyHotkeyResult && copyHotkeyResult.copied === true,
            hotkeySent: copyHotkeyResult && copyHotkeyResult.hotkeySent === true,
          });
          return {
            ok: false,
            reason,
          };
        }
        ToolboxShell.appendLog(
          `[SEND_COPY_HOTKEY][COMPOSED_DONE] runId=${runId}`,
        );
        finishSendCopyHotkeyTask({
          ok: true,
          reason: 'composed-done',
          nativeSendConfirmed: true,
          replyDone: true,
          copied: true,
          hotkeySent: true,
        });
        setStatus('发送+复制+快捷键已完成', 'success');
        return {
          ok: true,
          reason: 'composed-done',
        };
      } catch (err) {
        const errText = err && err.message ? err.message : String(err);
        console.error('[SEND_COPY_HOTKEY][COMPOSED_EXCEPTION]', err);
        ToolboxShell.appendLog(
          `[SEND_COPY_HOTKEY][COMPOSED_EXCEPTION] runId=${runId} error=${errText}`,
        );
        finishSendCopyHotkeyTask({
          ok: false,
          reason: 'composed-exception',
          error: errText,
        });
        setStatus(`发送+复制+快捷键失败：${errText}`, 'error');
        return {
          ok: false,
          reason: 'composed-exception',
          error: errText,
        };
      }
    }

    async function runSendCopyHotkeyAction(source = 'button', options = {}) {
      const src = String(source || (options && options.source) || 'button').trim() || 'button';
      return runSendCopyHotkeyComposed(src);
    }

    async function runSendCopyHotkeyNow(source = 'button', options = {}) {
      const src = String(source || (options && options.source) || 'button').trim() || 'button';
      return runSendCopyHotkeyComposed(src);
    }

    async function handleSendCopyHotkeyAction(source = 'manual-click') {
      const src = String(source || 'manual-click').trim() || 'manual-click';
      ToolboxShell.appendLog(`[SEND_COPY_HOTKEY][CLICK] source=${src}`);

      if (isSendCopyHotkeyRunning()) {
        ToolboxShell.appendLog(
          `[SEND_COPY_HOTKEY][CANCEL_REQUEST] source=${src}`,
        );
        requestCancelSendCopyHotkeyTask('user-click');
        return {
          ok: true,
          reason: 'cancel-requested',
        };
      }

      const pending = getCurrentSendLikePendingTask();
      if (pending && pending.action === 'send-copy-hotkey') {
        clearCurrentSendLikePendingTask('user-cancel-send-copy-hotkey');
        stopSendLikePendingWatcher('user-cancel-send-copy-hotkey');
      }

      const orchEnabled =
        typeof OrchAtomicClient !== 'undefined'
        && OrchAtomicClient
        && typeof OrchAtomicClient.isOrchSendCopyHotkeyEnabled === 'function'
        && OrchAtomicClient.isOrchSendCopyHotkeyEnabled();

      if (!orchEnabled) {
        ToolboxShell.appendLog(
          `[SEND_COPY_HOTKEY][RUN_LOCAL] source=${src} reason=orch-disabled`,
        );
        return runSendCopyHotkeyComposed(src);
      }

      const orchViews = typeof BRIDGE_STATE !== 'undefined'
        ? (BRIDGE_STATE.orch_button_views || {})
        : {};
      const orchView = orchViews['cgpt-send-copy-hotkey-once'];
      if (orchView && orchView.active === true) {
        await OrchAtomicClient.requestOrchTaskCancel({
          owner_button_id: 'cgpt-send-copy-hotkey-once',
          run_id: orchView.runId || orchView.run_id || '',
          source: src,
        });
        return {
          ok: true,
          reason: 'orch-cancel-requested',
        };
      }

      setSendCopyHotkeyPhase('waiting_input', 'orch-try', {
        pendingText: '编排接管中',
      });
      ToolboxShell.appendLog(
        `[SEND_COPY_HOTKEY][ORCH_TRY] source=${src} timeoutMs=2500`,
      );
      try {
        await OrchAtomicClient.requestOrchTaskStart('send_copy_hotkey_once', {
          source: src,
          owner_button_id: 'cgpt-send-copy-hotkey-once',
        });
        const orchStarted = await waitOrchSendCopyHotkeyActive(2500);
        if (orchStarted) {
          ToolboxShell.appendLog(
            `[SEND_COPY_HOTKEY][ORCH_ACCEPTED] source=${src}`,
          );
          return {
            ok: true,
            reason: 'orch-accepted',
          };
        }
        ToolboxShell.appendLog(
          `[SEND_COPY_HOTKEY][ORCH_TIMEOUT_FALLBACK_LOCAL] source=${src}`,
        );
        setSendCopyHotkeyPhase('sending', 'orch-timeout-fallback', {
          pendingText: '本地执行中',
        });
        return runSendCopyHotkeyComposed(`${src}:orch-timeout-fallback`);
      } catch (err) {
        const errText = err && err.message ? err.message : String(err);
        console.error('[SEND_COPY_HOTKEY][ORCH_REQUEST_FAILED]', err);
        ToolboxShell.appendLog(
          `[SEND_COPY_HOTKEY][ORCH_REQUEST_FAILED] source=${src} error=${errText} fallback=local`,
        );
        setSendCopyHotkeyPhase('sending', 'orch-error-fallback', {
          pendingText: '本地执行中',
        });
        return runSendCopyHotkeyComposed(`${src}:orch-error-fallback`);
      }
    }

    function ensureSendCopyHotkeyTask() {
      if (!state.sendCopyHotkeyTask || typeof state.sendCopyHotkeyTask !== 'object') {
        state.sendCopyHotkeyTask = {
          phase: 'idle',
          runId: '',
          rootRunId: '',
          postRunId: '',
          cancelRequested: false,
          startedAt: 0,
          updatedAt: 0,
          lastError: null,
          source: '',
          nativeSendConfirmed: false,
          replyDone: false,
          copied: false,
          hotkeySent: false,
        };
      }
      if (!state.sendCopyHotkeyTask.rootRunId && state.sendCopyHotkeyTask.runId) {
        state.sendCopyHotkeyTask.rootRunId = state.sendCopyHotkeyTask.runId;
      }
      return state.sendCopyHotkeyTask;
    }

    function isSendCopyHotkeyActive() {
      const task = ensureSendCopyHotkeyTask();
      const phase = String(task.phase || 'idle').trim().toLowerCase();
      return SEND_COPY_HOTKEY_ACTIVE_PHASES.has(phase);
    }

    function isSendCopyHotkeyFlowStillRunning() {
      if (isSendCopyHotkeyActive()) {
        return true;
      }
      if (!sendMessageTaskState || sendMessageTaskState.running !== true) {
        return false;
      }
      const action = String(
        sendMessageTaskState.action
        || sendMessageTaskState.plan?.mode
        || '',
      ).trim();
      if (action !== 'send-copy-hotkey' && action !== 'send-copy-hotkey-continue') {
        return false;
      }
      if (
        sendMessageTaskState.nativeSendClicked === true
        || sendMessageTaskState.hasClickedNativeSend === true
        || Number(sendMessageTaskState.sentAt || 0) > 0
      ) {
        return false;
      }
      const sendPhase = String(sendMessageTaskState.phase || '').trim().toLowerCase();
      const preNativeSendPhases = new Set([
        SEND_MESSAGE_PHASES.WAITING_COMPOSER,
        SEND_MESSAGE_PHASES.WRITING_TEXT,
        SEND_MESSAGE_PHASES.WAITING_ATTACHMENT,
        SEND_MESSAGE_PHASES.READY_TO_CLICK,
        SEND_MESSAGE_PHASES.CLICKING_SEND,
        'auto_upload_before_send',
      ]);
      return preNativeSendPhases.has(sendPhase);
    }

    function buildSendCopyHotkeyButtonRenderDiagExtra(renderReason = '-') {
      const moduleTask = ensureSendCopyHotkeyTask();
      return {
        renderReason: String(renderReason || '-').trim() || '-',
        moduleTaskPhase: String(moduleTask.phase || 'idle').trim() || 'idle',
        moduleSendRunning: sendMessageTaskState.running === true,
        moduleSendAction: String(
          sendMessageTaskState.action
          || sendMessageTaskState.plan?.mode
          || '-',
        ).trim() || '-',
        moduleSendPhase: String(sendMessageTaskState.phase || '-').trim() || '-',
        flowStillRunning: isSendCopyHotkeyFlowStillRunning(),
      };
    }

    function setSendCopyHotkeyPhase(phase, reason = '', patch = {}) {
      const task = ensureSendCopyHotkeyTask();
      const nextPhase = String(phase || 'idle').trim().toLowerCase() || 'idle';
      const oldPhase = String(task.phase || 'idle').trim().toLowerCase();
      Object.assign(task, patch || {}, {
        phase: nextPhase,
        updatedAt: Date.now(),
      });
      if (nextPhase === 'idle' || nextPhase === 'success' || nextPhase === 'failed' || nextPhase === 'cancelled') {
        task.cancelRequested = false;
      }
      if (SEND_COPY_HOTKEY_ACTIVE_PHASES.has(nextPhase)) {
        reconcileSendCopyHotkeyOwnerRunningState(`phase:${nextPhase}:${reason || '-'}`);
      }
      ToolboxShell.appendLog(
        `[SEND_COPY_HOTKEY_TASK][PHASE] old=${oldPhase} new=${nextPhase} reason=${reason || '-'} `
        + `rootRunId=${task.rootRunId || task.runId || '-'} postRunId=${task.postRunId || '-'} runId=${task.runId || '-'}`,
      );
      safeRenderUploadButtonsOnly({
        immediate: true,
        force: true,
        buttonTasksReason: `send-copy-hotkey:${reason || nextPhase}`,
      });
    }

    function readSendCopyHotkeyPageSnapshot(source = 'send-copy-hotkey') {
      const preflight = getSendCopyHotkeyPreflightState(source);
      const responseState = preflight.responseState && typeof preflight.responseState === 'object'
        ? preflight.responseState
        : {};
      const composerState = preflight.composerState && typeof preflight.composerState === 'object'
        ? preflight.composerState
        : {};
      const responseStateText = String(
        responseState.response_state
          || responseState.responseState
          || responseState.state
          || '',
      ).trim().toLowerCase();
      const responseReason = String(
        responseState.response_state_reason
          || responseState.responseStateReason
          || responseState.reason
          || '',
      ).trim().toLowerCase();
      const sendable = responseState.sendable;
      const inputable = responseState.inputable;
      const composerTextLen = Number(
        responseState.textLength
          || responseState.composerTextLen
          || composerState.textLen
          || 0,
      ) || 0;
      const composerCount = Number(
        composerState.count
          || composerState.fileCount
          || composerState.ready
          || 0,
      ) || 0;
      const composerUploading = !!(
        Number(composerState.uploading || 0) > 0
        || Number(composerState.nativeUploading || 0) > 0
        || composerState.isUploading === true
      );
      const pageGenerating = responseStateText === 'generating'
        || responseReason === 'assistant_busy'
        || responseState.is_responding === true
        || responseState.responding === true
        || responseState.busy === true
        || isChatGptResponseBusyForSend();
      let localFileCount = 0;
      try {
        localFileCount = typeof getActiveGroupFiles === 'function'
          ? getActiveGroupFiles().filter(Boolean).length
          : 0;
      } catch (localCountErr) {
        console.error('[SEND_COPY_HOTKEY][SNAPSHOT_LOCAL_COUNT_FAILED]', localCountErr);
      }
      const hasRealComposerPayload = computeSendCopyHotkeyRealComposerPayload({
        composerTextLen,
        composerCount,
        composerUploading,
        localFileCount,
      });
      return {
        responseState: responseStateText,
        responseReason,
        sendable,
        inputable,
        composerTextLen,
        composerCount,
        composerUploading,
        localFileCount,
        pageGenerating,
        hasRealComposerPayload,
        hasComposerPayload: hasRealComposerPayload,
        preflight,
      };
    }

    function getSendCopyHotkeySendBlockReason(source = 'send-copy-hotkey') {
      let responseState = {};
      let composerState = {};
      try {
        responseState = typeof detectComposerResponseState === 'function'
          ? detectComposerResponseState()
          : {};
      } catch (err) {
        const errText = err && err.message ? err.message : String(err);
        console.error('[SEND_COPY_HOTKEY][PRECHECK_RESPONSE_STATE_FAILED]', err);
        ToolboxShell.appendLog(
          `[SEND_COPY_HOTKEY][PRECHECK_RESPONSE_STATE_FAILED] source=${source || '-'} error=${errText}`,
        );
        responseState = {};
      }
      try {
        composerState = typeof getComposerAttachmentState === 'function'
          ? getComposerAttachmentState(`send-copy-hotkey-block:${source}`)
          : {};
      } catch (composerErr) {
        console.error('[SEND_COPY_HOTKEY][BLOCK_COMPOSER_STATE_FAILED]', composerErr);
        composerState = {};
      }
      const responseStateText = String(
        responseState.response_state
          || responseState.state
          || '',
      ).trim().toLowerCase();
      const reasonText = String(
        responseState.response_state_reason
          || responseState.reason
          || '',
      ).trim().toLowerCase();
      const pageGenerating = responseStateText === 'generating'
        || reasonText === 'assistant_busy'
        || responseState.is_responding === true
        || responseState.responding === true
        || responseState.busy === true;
      const sendable = responseState.sendable;
      const inputable = responseState.inputable;
      const composerTextLen = Number(
        responseState.textLength
          || responseState.composerTextLen
          || composerState.textLen
          || 0,
      ) || 0;
      const composerCount = Number(
        composerState.count
          || composerState.fileCount
          || composerState.ready
          || 0,
      ) || 0;
      const composerUploading = !!(
        Number(composerState.uploading || 0) > 0
        || Number(composerState.nativeUploading || 0) > 0
        || composerState.isUploading === true
      );
      let localFileCount = 0;
      try {
        localFileCount = typeof getActiveGroupFiles === 'function'
          ? getActiveGroupFiles().filter(Boolean).length
          : 0;
      } catch (localCountErr) {
        console.error('[SEND_COPY_HOTKEY][BLOCK_LOCAL_COUNT_FAILED]', localCountErr);
      }

      let blockReason = '';
      let message = '';
      if (pageGenerating) {
        blockReason = 'assistant-busy';
        message = '当前正在回答，不能执行“发送+复制+快捷键”。请等待回复完成后再点击。';
      } else if (
        inputable === false
        && !canComposeSendDespiteInputableBlock(responseStateText, reasonText, sendable)
      ) {
        blockReason = 'input-not-ready';
        message = '当前输入框暂不可输入，需要等待输入框恢复。';
      } else if (sendable === false) {
        blockReason = 'send-not-ready';
        message = '当前输入框不可发送，请确认输入框里有文本或附件。';
      }

      ToolboxShell.appendLog(
        `[SEND_COPY_HOTKEY][BLOCK_REASON] responseState=${responseStateText || '-'} pageGenerating=${pageGenerating ? 1 : 0} `
        + `inputable=${inputable === false ? 0 : 1} sendable=${sendable === false ? 0 : 1} composerTextLen=${composerTextLen} `
        + `composerCount=${composerCount} localFileCount=${localFileCount} blockReason=${blockReason || '-'}`,
      );

      if (blockReason) {
        return {
          blocked: true,
          reason: blockReason,
          message,
          responseState,
        };
      }
      return {
        blocked: false,
        reason: '',
        message: '',
        responseState,
      };
    }

    async function ensureLocalFilesUploadedBeforeSendCopyHotkey(reason = '-', options = {}) {
      const reasonText = String(reason || '-').trim() || '-';
      const ownerButtonId = String(options.ownerButtonId || 'cgpt-send-copy-hotkey-once').trim()
        || 'cgpt-send-copy-hotkey-once';
      const runId = String(options.runId || '').trim();
      let localFileCount = 0;
      try {
        localFileCount = typeof getLocalUploadFileCount === 'function'
          ? Number(getLocalUploadFileCount() || 0)
          : 0;
      } catch (countErr) {
        const errText = countErr && countErr.message ? countErr.message : String(countErr);
        console.error('[SEND_COPY_HOTKEY][AUTO_UPLOAD_LOCAL_COUNT_FAILED]', countErr);
        ToolboxShell.appendLog(
          `[SEND_COPY_HOTKEY][AUTO_UPLOAD_LOCAL_COUNT_FAILED] reason=${reasonText} error_type=${countErr && countErr.name ? countErr.name : 'Error'} error=${errText}`,
        );
        localFileCount = 0;
      }

      if (localFileCount <= 0) {
        return {
          ok: true,
          uploaded: false,
          reason: 'no-local-files',
        };
      }

      let attachmentState = null;
      try {
        attachmentState = typeof getComposerAttachmentState === 'function'
          ? getComposerAttachmentState({ reason: `send-copy-hotkey-precheck:${reasonText}` })
          : null;
      } catch (stateErr) {
        const errText = stateErr && stateErr.message ? stateErr.message : String(stateErr);
        console.error('[SEND_COPY_HOTKEY][AUTO_UPLOAD_ATTACHMENT_STATE_FAILED]', stateErr);
        ToolboxShell.appendLog(
          `[SEND_COPY_HOTKEY][AUTO_UPLOAD_ATTACHMENT_STATE_FAILED] reason=${reasonText} error_type=${stateErr && stateErr.name ? stateErr.name : 'Error'} error=${errText}`,
        );
        attachmentState = null;
      }

      const composerReady = Number(
        attachmentState?.readyCount
          || attachmentState?.ready
          || 0,
      ) || 0;
      const composerUploading = Number(
        attachmentState?.uploadingCount
          || attachmentState?.uploading
          || attachmentState?.nativeUploading
          || 0,
      ) || (
        attachmentState?.isUploading === true
        || attachmentState?.stillUploading === true
          ? 1
          : 0
      );
      const composerCount = Number(
        attachmentState?.count
          || attachmentState?.fileCount
          || attachmentState?.uniqueCount
          || 0,
      ) || 0;

      if (composerReady > 0 && composerUploading <= 0) {
        return {
          ok: true,
          uploaded: false,
          reason: 'composer-attachment-ready',
        };
      }

      const copyHotkeyTask = ensureSendCopyHotkeyTask();
      if (runId) {
        copyHotkeyTask.runId = runId;
      }
      setSendCopyHotkeyPhase('auto_upload_before_send', reasonText, {
        runId: copyHotkeyTask.runId || runId || '',
      });

      if (!sendMessageTaskState.running) {
        startSendMessageTask(`send-copy-hotkey-auto-upload:${reasonText}`, 'send-copy-hotkey');
      }
      sendMessageTaskState.action = 'send-copy-hotkey';
      sendMessageTaskState.ownerButtonId = ownerButtonId;
      sendMessageTaskState.phase = 'auto_upload_before_send';
      if (typeof renderUploadButtonsOnly === 'function') {
        renderUploadButtonsOnly('send-copy-hotkey-auto-upload-before-send');
      } else {
        safeRenderUploadButtonsOnly({
          immediate: true,
          force: true,
          buttonTasksReason: 'send-copy-hotkey-auto-upload-before-send',
        });
      }

      ToolboxShell.appendLog(
        `[SEND_COPY_HOTKEY][AUTO_UPLOAD_BEFORE_SEND] reason=${reasonText} localFileCount=${localFileCount} composerReady=${composerReady} composerUploading=${composerUploading} composerCount=${composerCount}`,
      );
      setStatus('检测到本地队列有文件，正在先上传附件...', 'running');

      healStaleUploadRunningLockIfNeeded(`send-copy-hotkey-auto-upload:${reasonText}`);
      healStaleUploadActionLockIfNeeded(`send-copy-hotkey-auto-upload:${reasonText}`);

      const shouldStop = () => {
        const currentTask = ensureSendCopyHotkeyTask();
        return isSendCopyHotkeyRunCancelled(currentTask, runId || getSendCopyHotkeyRootRunId(currentTask));
      };

      if (composerUploading > 0 || composerCount > 0) {
        let waitExistingResult = null;
        try {
          waitExistingResult = await waitComposerAttachmentReady({
            source: 'send-copy-hotkey-wait-existing',
            timeoutMs: 120000,
            isCancelled: shouldStop,
          });
        } catch (waitExistingErr) {
          const errText = waitExistingErr && waitExistingErr.message ? waitExistingErr.message : String(waitExistingErr);
          console.error('[SEND_COPY_HOTKEY][WAIT_EXISTING_ATTACHMENT_FAILED]', waitExistingErr);
          ToolboxShell.appendLog(
            `[SEND_COPY_HOTKEY][WAIT_EXISTING_ATTACHMENT_FAILED] reason=${reasonText} error_type=${waitExistingErr && waitExistingErr.name ? waitExistingErr.name : 'Error'} error=${errText}`,
          );
          return {
            ok: false,
            uploaded: false,
            reason: 'attachment-not-ready',
            message: `附件未就绪：${errText}`,
          };
        }
        if (shouldStop()) {
          return {
            ok: false,
            uploaded: false,
            reason: 'cancelled',
          };
        }
        if (waitExistingResult && waitExistingResult.ok === true) {
          ToolboxShell.appendLog(
            `[SEND_COPY_HOTKEY][AUTO_UPLOAD_READY] localFileCount=${localFileCount} ready=${composerReady || composerCount || '-'} reason=existing-upload-finished`,
          );
          return {
            ok: true,
            uploaded: false,
            reason: 'attachment-ready-after-wait',
          };
        }
      }

      const runAutoUploadAttempt = async (attemptSource) => {
        try {
          return await runStartUploadButtonCore({
            source: attemptSource,
            preserveFiles: true,
          });
        } catch (uploadErr) {
          const errText = uploadErr && uploadErr.message ? uploadErr.message : String(uploadErr);
          console.error('[SEND_COPY_HOTKEY][AUTO_UPLOAD_FAILED]', uploadErr);
          ToolboxShell.appendLog(
            `[SEND_COPY_HOTKEY][AUTO_UPLOAD_FAILED] reason=${reasonText} source=${attemptSource} error_type=${uploadErr && uploadErr.name ? uploadErr.name : 'Error'} error=${errText}`,
          );
          return {
            ok: false,
            reason: 'upload-failed',
            message: `自动上传失败：${errText}`,
          };
        }
      };

      let uploadResult = await runAutoUploadAttempt('send-copy-hotkey-auto-upload');
      if (shouldStop()) {
        return {
          ok: false,
          uploaded: false,
          reason: 'cancelled',
        };
      }

      if (!uploadResult || uploadResult.ok !== true) {
        const firstFailReason = String(uploadResult?.reason || 'upload-failed').trim() || 'upload-failed';
        const retryableUploadBlock = firstFailReason === 'task-running'
          || firstFailReason === 'task-running-real'
          || firstFailReason.includes('task-running');
        if (retryableUploadBlock) {
          const healedRunning = healStaleUploadRunningLockIfNeeded(`send-copy-hotkey-auto-upload-retry:${reasonText}`);
          const healedAction = healStaleUploadActionLockIfNeeded(`send-copy-hotkey-auto-upload-retry:${reasonText}`);
          if (healedRunning || healedAction) {
            ToolboxShell.appendLog(
              `[SEND_COPY_HOTKEY][AUTO_UPLOAD_RETRY] reason=${firstFailReason} healedRunning=${healedRunning ? 1 : 0} healedAction=${healedAction ? 1 : 0}`,
            );
            uploadResult = await runAutoUploadAttempt('send-copy-hotkey-auto-upload-retry');
          }
        }
      }

      if (shouldStop()) {
        return {
          ok: false,
          uploaded: false,
          reason: 'cancelled',
        };
      }

      if (!uploadResult || uploadResult.ok !== true) {
        const reasonTextFail = uploadResult?.reason || 'upload-failed';
        const failMessage = uploadResult?.message || `自动上传失败：${reasonTextFail}`;
        ToolboxShell.appendLog(
          `[SEND_COPY_HOTKEY][AUTO_UPLOAD_FAILED] reason=${reasonTextFail}`,
        );
        return {
          ok: false,
          uploaded: false,
          reason: reasonTextFail,
          message: failMessage,
        };
      }

      let waitResult = null;
      try {
        waitResult = await waitComposerAttachmentReady({
          source: 'send-copy-hotkey',
          timeoutMs: 120000,
          isCancelled: shouldStop,
        });
      } catch (waitErr) {
        const errText = waitErr && waitErr.message ? waitErr.message : String(waitErr);
        console.error('[SEND_COPY_HOTKEY][WAIT_ATTACHMENT_READY_FAILED]', waitErr);
        ToolboxShell.appendLog(
          `[SEND_COPY_HOTKEY][WAIT_ATTACHMENT_READY_FAILED] reason=${reasonText} error_type=${waitErr && waitErr.name ? waitErr.name : 'Error'} error=${errText}`,
        );
        return {
          ok: false,
          uploaded: true,
          reason: 'attachment-not-ready',
          message: `附件未就绪：${errText}`,
        };
      }

      if (shouldStop()) {
        return {
          ok: false,
          uploaded: true,
          reason: 'cancelled',
        };
      }

      if (!waitResult || waitResult.ok !== true) {
        const waitReason = waitResult?.reason || 'attachment-not-ready';
        ToolboxShell.appendLog(
          `[SEND_COPY_HOTKEY][WAIT_ATTACHMENT_READY_FAILED] reason=${waitReason}`,
        );
        return {
          ok: false,
          uploaded: true,
          reason: waitReason,
          message: `附件未就绪：${waitReason}`,
        };
      }

      ToolboxShell.appendLog(
        `[SEND_COPY_HOTKEY][AUTO_UPLOAD_READY] localFileCount=${localFileCount} ready=${composerReady || localFileCount || '-'}`,
      );
      return {
        ok: true,
        uploaded: true,
        reason: 'auto-upload-ready',
      };
    }

    function resolveSendCopyHotkeyPreflightGate(src, preflight, runId = '') {
      if (!preflight || preflight.ok === true) {
        return { handled: false };
      }
      const code = String(preflight.code || 'preflight-failed').trim();
      const message = preflight.message || code;

      if ((code === 'assistant-busy' || code === 'input-not-ready' || code === 'send-not-ready') && preflight.canWait) {
        let pendingPhase = 'waiting_composer_ready';
        if (code === 'assistant-busy') {
          pendingPhase = (preflight.hasRealComposerPayload || preflight.hasComposerPayload)
            ? 'waiting_current_reply_done'
            : 'waiting_reply';
        } else if (code === 'input-not-ready') {
          pendingPhase = 'waiting_composer_ready';
        } else if (code === 'send-not-ready') {
          pendingPhase = 'waiting_composer_ready';
        }
        let taskPhase = 'waiting_input';
        if (pendingPhase === 'waiting_current_reply_done') {
          taskPhase = 'waiting_current_reply_done';
        } else if (pendingPhase === 'waiting_composer_ready') {
          taskPhase = 'waiting_composer_ready';
        } else if (pendingPhase === 'waiting_reply') {
          taskPhase = 'waiting_ready';
        }

        ToolboxShell.appendLog(
          `[SEND_COPY_HOTKEY][PREFLIGHT_WAIT] source=${src} code=${code} phase=${pendingPhase} hasComposerPayload=${preflight.hasComposerPayload ? 1 : 0} composerTextLen=${preflight.composerTextLen || 0} composerCount=${preflight.composerCount || 0}`,
        );

        setCurrentSendLikePendingTask({
          action: 'send-copy-hotkey',
          taskKey: 'send-copy-hotkey',
          phase: pendingPhase,
          text: resolveSendLikePendingText('send-copy-hotkey', pendingPhase),
          source: src,
          ownerButtonId: 'cgpt-send-copy-hotkey-once',
          fromSendCopyHotkey: true,
        });

        const phasePatch = {
          runId,
          pendingText: resolveSendLikePendingText('send-copy-hotkey', pendingPhase),
        };
        setSendCopyHotkeyPhase(taskPhase, `preflight-wait:${code}`, phasePatch);

        let statusMessage = '正在等待条件满足后再发送+复制+快捷键';
        if (code === 'assistant-busy') {
          statusMessage = preflight.hasComposerPayload
            ? '当前正在回答，等待当前回复完成后再发送+复制+快捷键'
            : '当前正在回答，等待回复完成后再发送+复制+快捷键';
        } else if (code === 'input-not-ready') {
          statusMessage = '正在等待输入框恢复后再发送+复制+快捷键';
        } else if (code === 'send-not-ready') {
          statusMessage = '正在等待输入框可发送后再发送+复制+快捷键';
        }
        setStatus(statusMessage, 'running');

        startSendLikePendingWatcher(`send-copy-hotkey-preflight-wait:${code}`);

        return {
          handled: true,
          result: {
            ok: true,
            reason: `queued:${code}`,
            queued: true,
          },
        };
      }

      if (code === 'empty-composer') {
        ToolboxShell.appendLog(
          `[SEND_COPY_HOTKEY][EMPTY_COMPOSER_BLOCK] source=${src} message=${message}`,
        );
        setStatus('当前输入框没有可发送内容。需要发送时请先输入内容；只复制回复请点“复制+快捷键”。', 'warn');
        setSendCopyHotkeyPhase('idle', 'empty-composer-soft-block', {
          runId: '',
          lastError: '',
        });
        return {
          handled: true,
          result: {
            ok: false,
            reason: 'empty-composer',
            message,
            softBlocked: true,
          },
        };
      }

      console.warn('[SEND_COPY_HOTKEY][PREFLIGHT_BLOCK]', preflight);
      ToolboxShell.appendLog(
        `[SEND_COPY_HOTKEY][PREFLIGHT_BLOCK] source=${src} code=${code} message=${message}`,
      );
      setStatus(message, 'warn');
      finishSendCopyHotkeyTask({
        ok: false,
        reason: code,
      });
      return {
        handled: true,
        result: {
          ok: false,
          reason: code,
          message,
        },
      };
    }

    function getSendCopyHotkeyPreflightState(source = 'send-copy-hotkey') {
      const src = String(source || 'send-copy-hotkey');
      let responseState = {};
      try {
        responseState = typeof detectComposerResponseState === 'function'
          ? detectComposerResponseState()
          : {};
      } catch (err) {
        const errText = err && err.message ? err.message : String(err);
        console.error('[SEND_COPY_HOTKEY][PREFLIGHT_RESPONSE_FAILED]', err);
        ToolboxShell.appendLog(
          `[SEND_COPY_HOTKEY][PREFLIGHT_RESPONSE_FAILED] source=${src} error=${errText}`,
        );
        responseState = {};
      }
      let composerState = {};
      try {
        composerState = typeof getComposerAttachmentState === 'function'
          ? getComposerAttachmentState(`send-copy-hotkey-preflight:${src}`)
          : {};
      } catch (err) {
        const errText = err && err.message ? err.message : String(err);
        console.error('[SEND_COPY_HOTKEY][PREFLIGHT_COMPOSER_FAILED]', err);
        ToolboxShell.appendLog(
          `[SEND_COPY_HOTKEY][PREFLIGHT_COMPOSER_FAILED] source=${src} error=${errText}`,
        );
        composerState = {};
      }
      const responseText = String(
        responseState.response_state
          || responseState.state
          || '',
      ).trim().toLowerCase();
      const responseReason = String(
        responseState.response_state_reason
          || responseState.reason
          || '',
      ).trim().toLowerCase();
      const sendable = responseState.sendable;
      const inputable = responseState.inputable;
      const assistantBusy = responseText === 'generating'
        || responseReason === 'assistant_busy'
        || responseState.is_responding === true
        || responseState.responding === true
        || responseState.busy === true;
      const sendButtonNotFound = responseReason === 'send_button_not_found';
      const composerCount = Number(
        composerState.count
          || composerState.fileCount
          || composerState.ready
          || 0,
      ) || 0;
      const composerUploading = !!(
        Number(composerState.uploading || 0) > 0
        || Number(composerState.nativeUploading || 0) > 0
        || composerState.isUploading === true
      );
      const composerTextLen = Number(
        responseState.textLength
          || responseState.composerTextLen
          || composerState.textLen
          || 0,
      ) || 0;
      const localFileCount = typeof getActiveGroupFiles === 'function'
        ? getActiveGroupFiles().filter(Boolean).length
        : 0;
      const hasComposerAttachment = composerCount > 0 || composerUploading;
      const hasRealComposerPayload = computeSendCopyHotkeyRealComposerPayload({
        composerTextLen,
        composerCount,
        composerUploading,
        localFileCount,
      });
      const hasComposerPayload = hasRealComposerPayload;
      ToolboxShell.appendLog(
        `[SEND_COPY_HOTKEY][PREFLIGHT] source=${src} response_state=${responseText || '-'} response_reason=${responseReason || '-'} sendable=${sendable === false ? 0 : 1} inputable=${inputable === false ? 0 : 1} composerCount=${composerCount} composerUploading=${composerUploading ? 1 : 0} composerTextLen=${composerTextLen} localFileCount=${localFileCount} hasRealComposerPayload=${hasRealComposerPayload ? 1 : 0} hasComposerAttachment=${hasComposerAttachment ? 1 : 0}`,
      );
      if (assistantBusy) {
        return {
          ok: false,
          code: 'assistant-busy',
          message: '当前 ChatGPT 正在回答，需要等待当前回复完成后再发送。',
          responseState,
          composerState,
          assistantBusy: true,
          canWait: true,
          hasComposerPayload: hasRealComposerPayload,
          hasRealComposerPayload,
          composerTextLen,
          composerCount,
          localFileCount,
        };
      }
      if (
        inputable === false
        && !canComposeSendDespiteInputableBlock(responseText, responseReason, sendable)
      ) {
        return {
          ok: false,
          code: 'input-not-ready',
          message: '当前输入框暂不可输入，需要等待输入框恢复。',
          responseState,
          composerState,
          assistantBusy: false,
          canWait: true,
          hasComposerPayload: hasRealComposerPayload,
          hasRealComposerPayload,
          composerTextLen,
          composerCount,
          localFileCount,
        };
      }
      if (
        sendButtonNotFound
        || (
          sendable === false
          && !canComposeSendDespiteInputableBlock(responseText, responseReason, sendable)
        )
      ) {
        return {
          ok: false,
          code: 'send-not-ready',
          message: '当前输入框不可发送，请确认输入框里有文本或附件，并且 ChatGPT 没有在回答。',
          responseState,
          composerState,
          canWait: hasRealComposerPayload,
          hasComposerPayload: hasRealComposerPayload,
          hasRealComposerPayload,
          composerTextLen,
          composerCount,
          localFileCount,
        };
      }
      if (!hasRealComposerPayload) {
        return {
          ok: false,
          code: 'empty-composer',
          message: '当前输入框没有可发送内容，请先输入文本或上传附件。',
          responseState,
          composerState,
          canWait: false,
          hasComposerPayload: false,
          hasRealComposerPayload: false,
          composerTextLen,
          composerCount,
          localFileCount,
        };
      }
      return {
        ok: true,
        code: 'ok',
        message: '',
        responseState,
        composerState,
      };
    }

    async function waitForComposerReadyForSendCopyHotkey(
      runId,
      source = 'send-copy-hotkey',
      timeoutMs = SEND_COPY_HOTKEY_COMPOSER_READY_TIMEOUT_MS,
    ) {
      const startedAt = Date.now();
      const intervalMs = 500;
      const maxWaitMs = Math.max(1000, Number(timeoutMs) || SEND_COPY_HOTKEY_COMPOSER_READY_TIMEOUT_MS);
      while (Date.now() - startedAt < maxWaitMs) {
        const task = ensureSendCopyHotkeyTask();
        if (isSendCopyHotkeyRunCancelled(task, runId)) {
          return {
            ok: false,
            reason: 'cancelled',
          };
        }
        if (isChatGptResponseBusyForSend()) {
          return {
            ok: false,
            reason: 'assistant-busy',
          };
        }
        if (isComposerActuallySendableForSendLike()) {
          return {
            ok: true,
            reason: 'sendable',
          };
        }
        await new Promise((resolve) => window.setTimeout(resolve, intervalMs));
      }
      return {
        ok: false,
        reason: 'composer-not-ready-timeout',
      };
    }

    async function waitUntilComposerSendableForSendCopyHotkey(runId, source = 'send-copy-hotkey') {
      const startedAt = Date.now();
      const timeoutMs = 120000;
      const intervalMs = 500;
      while (Date.now() - startedAt < timeoutMs) {
        const task = ensureSendCopyHotkeyTask();
        if (isSendCopyHotkeyRunCancelled(task, runId)) {
          return {
            ok: false,
            reason: 'cancelled',
          };
        }
        const block = getSendCopyHotkeySendBlockReason(source);
        if (!block.blocked) {
          return {
            ok: true,
            reason: 'sendable',
          };
        }
        await new Promise((resolve) => window.setTimeout(resolve, intervalMs));
      }
      return {
        ok: false,
        reason: 'timeout',
      };
    }

    function cancelSendCopyHotkey(source = 'user-click') {
      const task = ensureSendCopyHotkeyTask();
      const src = String(source || 'user-click').trim() || 'user-click';
      const phase = String(task.phase || 'idle').trim().toLowerCase();
      const sendPhase = String(sendMessageTaskState.phase || '').trim().toLowerCase();
      const waitingReply = isSendCopyHotkeyWaitingReplyPhase(phase)
        || isSendCopyHotkeyWaitingReplyPhase(sendPhase)
        || sendPhase === String(SEND_MESSAGE_PHASES.SENT_WAITING_RESPONSE || 'sent_waiting_response').trim().toLowerCase();
      const active = SEND_COPY_HOTKEY_ACTIVE_PHASES.has(phase) || waitingReply;

      if (!active) {
        ToolboxShell.appendLog(`[SEND_COPY_HOTKEY_TASK][CANCEL_IGNORE] source=${src} phase=${phase}`);
        return false;
      }

      const stopButton = document.querySelector(
        'button[data-testid="stop-button"], button[aria-label*="停止"], button[aria-label*="Stop"], button[aria-label*="stop"]',
      );
      if (stopButton instanceof HTMLButtonElement && !isToolboxDomNode(stopButton)) {
        stopButton.click();
        ToolboxShell.appendLog(
          `[SEND_COPY_HOTKEY][CANCEL_CLICK_NATIVE_STOP] reason=${src || '-'} phase=${phase || sendPhase || '-'}`,
        );
      } else if (typeof clickChatGptStopButtonForSendTask === 'function') {
        clickChatGptStopButtonForSendTask('cancel-send-copy-hotkey');
      }

      task.cancelRequested = true;
      if (typeof cancelCurrentUploadSend === 'function') {
        cancelCurrentUploadSend(`send-copy-hotkey:${src}`);
      }
      if (typeof cancelWaitingSend === 'function') {
        cancelWaitingSend(`send-copy-hotkey:${src}`);
      }
      if (typeof cancelCopyHotkeyOnce === 'function') {
        cancelCopyHotkeyOnce(`send-copy-hotkey:${src}`);
      }

      ToolboxShell.appendLog(
        `[SEND_COPY_HOTKEY][CANCEL] reason=${src} phase=${phase || sendPhase || '-'} runId=${task.runId || '-'}`,
      );
      finishSendCopyHotkeyTask({
        ok: false,
        reason: 'canceled',
        copied: false,
        hotkeySent: false,
      });
      return true;
    }

    async function maybeRunSendFamilyPlanPostSend(source = 'send-family-post') {
      const plan = sendMessageTaskState.plan || buildSendTaskPlanFromAction(sendMessageTaskState.action);
      if (!plan || plan.copyAfterReply !== true) {
        return { ok: true, skipped: true, reason: 'no-post-plan' };
      }
      const src = String(source || 'send-family-post').trim() || 'send-family-post';
      const task = ensureSendCopyHotkeyTask();
      const rootRunId = getSendCopyHotkeyRootRunId(task)
        || String(sendMessageTaskState.runId || '').trim()
        || createUploadTaskRunId('send_copy_hotkey');
      const postRunId = createUploadTaskRunId('send_family_post');
      Object.assign(task, {
        rootRunId,
        runId: rootRunId,
        postRunId,
        cancelRequested: false,
        startedAt: task.startedAt || Date.now(),
        updatedAt: Date.now(),
        lastError: null,
        source: src,
        ownerButtonId: sendMessageTaskState.ownerButtonId || 'cgpt-send-copy-hotkey-once',
      });
      if (!task.nativeSendConfirmed) {
        task.nativeSendConfirmed = !!(
          sendMessageTaskState.nativeSendClicked
          || sendMessageTaskState.hasClickedNativeSend
        );
      }
      reconcileSendCopyHotkeyOwnerRunningState(`post-plan-start:${src}`);
      setSendCopyHotkeyPhase('waiting_reply', 'send-ok-wait-copy-hotkey', {
        runId: rootRunId,
        rootRunId,
        postRunId,
        nativeSendConfirmed: task.nativeSendConfirmed,
        ownerButtonId: sendMessageTaskState.ownerButtonId || 'cgpt-send-copy-hotkey-once',
      });
      logSendCopyHotkeyTaskMilestone(task, 'waiting_reply', `post-plan-start:${src}`);
      const copyHotkeyTaskForWait = ensureSendCopyHotkeyTask();
      copyHotkeyTaskForWait.responseStartedAt = Date.now();
      sendMessageTaskState.responseStartedAt = sendMessageTaskState.responseStartedAt || copyHotkeyTaskForWait.responseStartedAt;
      resetSendCopyHotkeyReplyStableTracking();
      setStatus('正在等待回复并执行复制+快捷键', 'running');
      ToolboxShell.appendLog(
        `[SEND_TASK][POST_PLAN_START] source=${src} mode=${plan.mode || sendMessageTaskState.action || '-'} copyAfterReply=${plan.copyAfterReply ? 1 : 0} hotkeyAfterCopy=${plan.hotkeyAfterCopy ? 1 : 0} continueAfterHotkey=${plan.continueAfterHotkey ? 1 : 0}`,
      );

      if (reconcileSendCopyHotkeyBackgroundThrottle(`post-plan:${src}`)) {
        return { ok: true, reason: 'waiting-throttled' };
      }

      if (
        isAssistantReplyFinishedNow(`send-family-post:${src}`)
        && checkSendCopyHotkeyReplyStableDone(`send-family-post:${src}`)
      ) {
        ToolboxShell.appendLog(
          `[SEND_COPY_HOTKEY][POST_PLAN_REPLY_ALREADY_DONE] source=${src} action=continue-post-send`,
        );
        const directResult = await continueSendCopyHotkeyAfterReplyDone(`send-family-post:${src}`);
        if (plan.continueAfterHotkey === true && directResult && directResult.ok && typeof runCopyAction === 'function') {
          await runCopyAction('copy-and-continue', { source: `${src}:continue-after-hotkey` });
        }
        return directResult && directResult.ok
          ? { ok: true, reason: 'done' }
          : {
            ok: false,
            reason: directResult && directResult.reason ? directResult.reason : 'post-action-failed',
          };
      }

      ToolboxShell.appendLog(
        `[SEND_COPY_HOTKEY][POST_PLAN_WAIT_REPLY] source=${src} rootRunId=${rootRunId} responseState=${readLiveHotkeyGateSignals().responseState || '-'}`,
      );
      return { ok: true, reason: 'waiting-reply' };
    }

    function isCopyHotkeyContinueActive() {
      const task = ensureCopyHotkeyContinueTask();
      const fromPhase = isCopyHotkeyTaskPhaseActive(task.phase)
        || task.phase === 'cancelling';
      if (fromPhase !== !!copyHotkeyContinueTaskRunning) {
        copyHotkeyContinueTaskRunning = fromPhase;
      }
      return fromPhase;
    }

    function isCopyHotkeyLoopActive() {
      const task = ensureCopyHotkeyContinueLoopTask();
      const fromPhase = isCopyHotkeyLoopTaskPhaseActive(task.phase);
      if (fromPhase !== !!copyHotkeyContinueLoopRunning) {
        copyHotkeyContinueLoopRunning = fromPhase;
      }
      return fromPhase;
    }

    function isCopyHotkeyUploadVerifyLoopActive() {
      const fromClosedLoop = !!closedLoopContinueState.running;
      if (fromClosedLoop !== !!copyHotkeyUploadVerifyLoopRunning) {
        copyHotkeyUploadVerifyLoopRunning = fromClosedLoop;
      }
      return fromClosedLoop;
    }

    function isClosedLoopRunActive(runId) {
      if (shouldStopClosedLoopRun(runId)) {
        return false;
      }
      return closedLoopContinueState.running === true
        && closedLoopContinueState.runId === runId;
    }

    function clearUploadPendingTimersOnBatchDoneSignal(source = 'batch-done-signal') {
      const src = String(source || 'batch-done-signal').trim() || 'batch-done-signal';
      clearClosedLoopStepTimer(`batch-done:${src}`);
      clearClosedLoopRetryTimer(`batch-done:${src}`);
      ToolboxShell.appendLog(`[BATCH_FLOW][CLEAR_TIMERS_ON_DONE_SIGNAL] source=${src}`);
    }

    function clearClosedLoopRetryTimer(reason = 'unknown') {
      if (closedLoopContinueState.retryTimerId) {
        clearTimeout(closedLoopContinueState.retryTimerId);
        closedLoopContinueState.retryTimerId = null;
        ToolboxShell.appendLog(`[CLOSED_LOOP][RETRY_TIMER_CLEAR] reason=${reason || '-'}`);
      }
    }

    function appendClosedLoopTrace(event, fields = {}) {
      try {
        const e = String(event || '').trim() || 'unknown';
        const f = fields && typeof fields === 'object' ? fields : {};
        const runId = f.runId != null ? String(f.runId) : String(closedLoopContinueState.runId || '-');
        const round = f.round != null ? String(f.round) : String(closedLoopContinueState.round || '-');
        const source = String(f.source || closedLoopContinueState.mode || '-');
        const expectedLen = f.expectedLen != null ? String(f.expectedLen) : '-';
        const actualLen = f.actualLen != null ? String(f.actualLen) : '-';
        const deltaLen = f.deltaLen != null ? String(f.deltaLen) : '-';
        const normalizedMatch = f.normalizedMatch != null ? String(f.normalizedMatch ? 1 : 0) : '-';
        const sendable = f.sendable != null ? String(f.sendable ? 1 : 0) : '-';
        const inputable = f.inputable != null ? String(f.inputable ? 1 : 0) : '-';
        const responseState = f.responseState != null ? String(f.responseState) : '-';
        const sendPhase = f.sendPhase != null ? String(f.sendPhase) : '-';
        const decision = f.decision != null ? String(f.decision) : '-';
        const reason = f.reason != null ? String(f.reason) : '-';
        const cancelFlags = f.cancelFlags != null ? String(f.cancelFlags) : '-';
        ToolboxShell.appendLog(
          `[CLOSED_LOOP_TRACE] event=${e} runId=${runId} round=${round} source=${source} `
          + `expectedLen=${expectedLen} actualLen=${actualLen} deltaLen=${deltaLen} normalizedMatch=${normalizedMatch} `
          + `sendable=${sendable} inputable=${inputable} responseState=${responseState} sendPhase=${sendPhase} `
          + `cancelFlags=${cancelFlags} decision=${decision} reason=${reason}`,
        );
      } catch (err) {
        // best-effort trace only
      }
    }

    function appendClosedLoopSimple(event, fields = {}) {
      try {
        const e = String(event || '').trim() || 'unknown';
        const f = fields && typeof fields === 'object' ? fields : {};
        const round = f.round != null ? String(f.round) : String(closedLoopContinueState.round || '-');
        const matchedDone = f.matchedDone != null ? String(f.matchedDone ? 1 : 0) : '-';
        const replyLen = f.replyLen != null ? String(f.replyLen) : '-';
        const promptLen = f.promptLen != null ? String(f.promptLen) : '-';
        const composerLen = f.composerLen != null ? String(f.composerLen) : '-';
        const lenDiff = f.lenDiff != null ? String(f.lenDiff) : '-';
        const action = f.action != null ? String(f.action) : '-';
        const sendReady = f.sendReady != null ? String(f.sendReady ? 1 : 0) : '-';
        const buttonFound = f.buttonFound != null ? String(f.buttonFound ? 1 : 0) : '-';
        const reason = f.reason != null ? String(f.reason) : '-';
        ToolboxShell.appendLog(
          `[CLOSED_LOOP_SIMPLE] event=${e} round=${round} matchedDone=${matchedDone} replyLen=${replyLen} `
          + `promptLen=${promptLen} composerLen=${composerLen} lenDiff=${lenDiff} action=${action} `
          + `sendReady=${sendReady} buttonFound=${buttonFound} reason=${reason}`,
        );
      } catch (err) {
        // best-effort
      }
    }

    function isClosedLoopRetryablePauseReason(reason) {
      const text = String(reason || '').trim();

      if (!text) {
        return false;
      }

      return (
        text.includes('send_button_not_found')
        || text.includes('send_button_disabled')
        || text.includes('send_button_wait_timeout')
        || text.includes('send_button_not_ready')
        || text.includes('send_button_unavailable')
        || text.includes('no-real-submit-button')
        || text.includes('payload_ready_but_send_button_missing')
        || text.includes('attachment_ready_but_send_button_missing')
        || text.includes('continue-send-failed')
        || text.includes('send-message-button-core-failed')
        || text.includes('wait-next-reply-failed')
        || text.includes('assistant_busy')
        || text.includes('send_not_confirmed')
        || text.includes('stable_send_timeout')
      );
    }

    function isClosedLoopFatalSendPayloadInvalidReason(reason) {
      const text = String(reason || '').trim();
      if (!text) return false;
      return (
        // Only treat truly unrecoverable / programmer errors as fatal.
        // Closed-loop send uses a loose strategy and should never be blocked by payload diffs.
        text.includes('composer-api-missing')
        || text.includes('composer-api-missing')
        || text.includes('empty-payload')
        || text.includes('empty-content')
      );
    }

    function isClosedLoopLimitedRetrySendFailureReason(reason) {
      const text = String(reason || '').trim();
      if (!text) return false;
      return (
        text === 'payload_dropped'
        || text.includes('payload_dropped')
        || text === 'composer_empty'
        || text.includes('composer_empty')
        || text.includes('textLen=0')
        || text.includes('waiting_payload')
        || text.includes('cancelled-after-send')
        || text.includes('cancelled-after-claim')
        || text === 'cancelled'
        || text.includes('cancelled')
        || text.includes('continue-send-failed')
      );
    }

    function shouldClosedLoopPauseAfterSendFailed(reason) {
      const text = String(reason || '').trim();
      if (!text) return false;
      return (
        text === 'payload_dropped'
        || text === 'cancelled'
        || text === 'cancelled-after-send'
        || text === 'composer_empty'
        || text === 'waiting_payload'
        || text.includes('payload_dropped')
        || text.includes('composer_empty')
        || text.includes('waiting_payload')
      );
    }

    function scheduleClosedLoopRetry(runId, reason = 'unknown', options = {}) {
      if (!isClosedLoopRunActive(runId)) {
        ToolboxShell.appendLog(
          `[CLOSED_LOOP][RETRY_SKIP] reason=inactive runId=${runId} pauseReason=${reason || '-'}`,
        );
        return false;
      }

      clearClosedLoopRetryTimer(`reschedule:${reason || '-'}`);

      const reasonText = String(reason || 'unknown').trim() || 'unknown';
      const forceRetry = options.forceRetry === true
        || reasonText.includes('home-navigation')
        || reasonText.includes('home-recover');

      const retryable = isClosedLoopRetryablePauseReason(reasonText) || forceRetry;
      if (!retryable) {
        ToolboxShell.appendLog(
          `[CLOSED_LOOP][RETRY_SKIP] reason=not-retryable runId=${runId} pauseReason=${reasonText}`,
        );
        return false;
      }

      if (
        isClosedLoopRetryablePauseReason(reasonText)
        && !forceRetry
        && options.skipHomeRecover !== true
        && options.retryCurrentRound !== true
      ) {
        closedLoopContinueState.retryAttempts += 1;

        if (closedLoopContinueState.retryAttempts > 3) {
          const currentRound = closedLoopContinueState.round;
          if (!closedLoopContinueState.homeNavigationRunning) {
            closedLoopContinueState.homeNavigationRunning = true;
            const recoverMode = closedLoopContinueState.mode || CLOSED_LOOP_CONTINUE_MODES.WITH_HOTKEY;
            const recoverAction = getClosedLoopContinueActionDef(recoverMode).action;
            ToolboxShell.appendLog(
              `[CLOSED_LOOP][RETRY_RECOVER_ACTION] mode=${recoverMode} action=${recoverAction}`,
            );
            ToolboxShell.appendLog(
              `[CLOSED_LOOP][RETRY_HOME_RECOVER] runId=${runId} round=${currentRound} attempts=${closedLoopContinueState.retryAttempts} reason=${reasonText}`,
            );
            void runUnifiedContinueHomeNavigation(
              recoverAction,
              currentRound,
              'retry-recover',
            ).then((homeResult) => {
              closedLoopContinueState.homeNavigationRunning = false;
              if (!isClosedLoopRunActive(runId)) {
                return;
              }
              if (homeResult && homeResult.ok === true) {
                closedLoopContinueState.retryAttempts = 0;
                scheduleClosedLoopRetry(runId, 'home-recover-ok', {
                  delayMs: 1500,
                  retryCurrentRound: true,
                  skipHomeNavigation: true,
                  forceRetry: true,
                  skipHomeRecover: true,
                  maxAttempts: options.maxAttempts,
                });
                return;
              }
              const homeFailReason = homeResult && homeResult.reason
                ? homeResult.reason
                : 'unknown';
              ToolboxShell.appendLog(
                `[CLOSED_LOOP][RETRY_HOME_RECOVER_FAILED] runId=${runId} round=${currentRound} reason=${homeFailReason}`,
              );
              pauseClosedLoopContinue('home-recover-failed', {
                level: 'warn',
                message: `闭环第 ${currentRound} 轮回首页恢复失败，准备继续重试`,
              });
              scheduleClosedLoopRetry(runId, `home-recover-failed:${homeFailReason}`, {
                delayMs: 5000,
                retryCurrentRound: true,
                skipHomeNavigation: true,
                forceRetry: true,
                skipHomeRecover: true,
                maxAttempts: options.maxAttempts,
              });
            }).catch((error) => {
              closedLoopContinueState.homeNavigationRunning = false;
              const errText = formatToolboxError(error);
              console.error('[CLOSED_LOOP][RETRY_HOME_RECOVER_EXCEPTION]', error);
              ToolboxShell.appendLog(
                `[CLOSED_LOOP][RETRY_HOME_RECOVER_EXCEPTION] runId=${runId} error=${errText}`,
              );
              scheduleClosedLoopRetry(runId, `home-recover-exception:${errText}`, {
                delayMs: 5000,
                retryCurrentRound: true,
                skipHomeNavigation: true,
                forceRetry: true,
                skipHomeRecover: true,
                maxAttempts: options.maxAttempts,
              });
            });
            return true;
          }
        }
      }

      const maxAttempts = Number(options.maxAttempts || 120);
      if (
        isClosedLoopRetryablePauseReason(reasonText)
        && !forceRetry
        && closedLoopContinueState.retryAttempts > maxAttempts
      ) {
        ToolboxShell.appendLog(
          `[CLOSED_LOOP][RETRY_GIVE_UP] runId=${runId} attempts=${closedLoopContinueState.retryAttempts} reason=${reasonText}`,
        );
        finishClosedLoopContinue(`retry-give-up:${reasonText}`, {
          finalStatus: 'stopped',
        });
        setStatus(`闭环重试次数过多，已停止：${reasonText}`, 'warn');
        return false;
      }

      const delayMs = Number(options.delayMs || 3000);

      ToolboxShell.appendLog(
        `[CLOSED_LOOP][RETRY_SCHEDULE] runId=${runId} attempts=${closedLoopContinueState.retryAttempts} delayMs=${delayMs} reason=${reasonText} retryCurrentRound=${options.retryCurrentRound === true ? 1 : 0} skipHomeNavigation=${options.skipHomeNavigation === true ? 1 : 0}`,
      );

      setStatus(
        `闭环暂时无法推进，${Math.round(delayMs / 1000)} 秒后重试：${reasonText}`,
        'warn',
      );

      closedLoopContinueState.retryTimerId = setTimeout(() => {
        closedLoopContinueState.retryTimerId = null;

        if (!isClosedLoopRunActive(runId)) {
          ToolboxShell.appendLog(
            `[CLOSED_LOOP][RETRY_ABORT] reason=inactive runId=${runId}`,
          );
          return;
        }

        ToolboxShell.appendLog(
          `[CLOSED_LOOP][RETRY_FIRE] runId=${runId} attempts=${closedLoopContinueState.retryAttempts} reason=${reasonText}`,
        );

        scheduleClosedLoopContinueNextStep(runId, 0, `retry-fire:${reasonText}`, {
          retryCurrentRound: options.retryCurrentRound === true,
          skipHomeNavigation: options.skipHomeNavigation === true,
          retryReason: reasonText,
        });
      }, delayMs);

      return true;
    }

    function clearClosedLoopStepTimer(reason = 'unknown') {
      clearClosedLoopTimersAndLocks(reason || 'clear-step-timer');
      ToolboxShell.appendLog(`[CLOSED_LOOP][TIMER_ABORT] reason=${reason || '-'}`);
    }

    function scheduleClosedLoopContinueNextStep(runId, delayMs, reason = '', options = {}) {
      const scheduleReason = String(reason || 'unknown').trim() || 'unknown';
      if (!closedLoopContinueState.running || closedLoopContinueState.runId !== runId) {
        ToolboxShell.appendLog(
          [
            '[CLOSED_LOOP][SCHEDULE_SKIP_RUNID_MISMATCH]',
            `runId=${runId || '-'}`,
            `currentRunId=${closedLoopContinueState.runId || '-'}`,
            `running=${closedLoopContinueState.running ? 1 : 0}`,
            `reason=${scheduleReason}`,
          ].join(' '),
        );
        return false;
      }
      if (closedLoopContinueState.nextStepTimer) {
        clearTimeout(closedLoopContinueState.nextStepTimer);
        closedLoopContinueState.nextStepTimer = null;
        ToolboxShell.appendLog(
          `[CLOSED_LOOP][SCHEDULE_CLEAR_OLD_TIMER] runId=${runId} reason=${scheduleReason}`,
        );
      }
      if (closedLoopContinueState.timerId) {
        clearTimeout(closedLoopContinueState.timerId);
        closedLoopContinueState.timerId = null;
      }
      const safeDelayMs = Math.max(0, Math.min(600000, Math.round(Number(delayMs) || 0)));
      closedLoopContinueState.lastScheduleReason = scheduleReason;
      closedLoopContinueState.lastScheduleAtMs = Date.now();
      ToolboxShell.appendLog(
        [
          '[CLOSED_LOOP][SCHEDULE_NEXT_STEP]',
          `runId=${runId}`,
          `delayMs=${safeDelayMs}`,
          `delaySec=${Math.round(safeDelayMs / 1000)}`,
          `reason=${scheduleReason}`,
        ].join(' '),
      );
      const retryCurrentRound = options && options.retryCurrentRound === true;
      closedLoopContinueState.nextStepTimer = setTimeout(() => {
        closedLoopContinueState.nextStepTimer = null;
        closedLoopContinueState.timerId = null;
        if (!closedLoopContinueState.running || closedLoopContinueState.runId !== runId) {
          ToolboxShell.appendLog(
            [
              '[CLOSED_LOOP][SCHEDULED_STEP_SKIP_STOPPED]',
              `runId=${runId}`,
              `currentRunId=${closedLoopContinueState.runId || '-'}`,
              `reason=${scheduleReason}`,
            ].join(' '),
          );
          return;
        }
        void runClosedLoopContinueStep(runId, {
          source: `scheduled:${scheduleReason}`,
          retryCurrentRound,
          skipHomeNavigation: options.skipHomeNavigation === true,
          retryReason: options.retryReason || scheduleReason,
        }).catch((error) => {
          const errText = formatToolboxError(error);
          console.error('[CLOSED_LOOP][STEP_FAILED]', error);
          ToolboxShell.appendLog(
            `[CLOSED_LOOP][STEP_FAILED] runId=${runId} error=${errText}`,
          );
          if (isClosedLoopUserCancelledReason(errText)) {
            stopClosedLoopContinue(`step-failed:${errText}`);
            return;
          }
          recoverClosedLoopContinue(runId, `step-failed:${errText}`, {
            delayMs: 5000,
          });
        });
      }, safeDelayMs);
      closedLoopContinueState.timerId = closedLoopContinueState.nextStepTimer;
      return true;
    }

    function recoverClosedLoopContinue(runId, reason, options = {}) {
      const recoverReason = String(reason || 'unknown').trim() || 'unknown';
      const delayMs = Number(options.delayMs || 5000);
      const retryCurrentRound = options.retryCurrentRound !== false;

      if (!isClosedLoopRunActive(runId)) {
        ToolboxShell.appendLog(
          `[CLOSED_LOOP][RECOVER_SKIP] runId=${runId} reason=${recoverReason}`,
        );
        return false;
      }

      if (isClosedLoopFatalSendPayloadInvalidReason(recoverReason)) {
        const msg = '继续指令发送失败：输入框内容校验失败，已暂停，禁止空转';
        ToolboxShell.appendLog(
          `[CLOSED_LOOP][FATAL_SEND_PAYLOAD_INVALID] runId=${runId} reason=${recoverReason}`,
        );
        pauseClosedLoopContinue(`failed-paused:${recoverReason}`, {
          level: 'warn',
          message: msg,
        });
        setStatus(msg, 'warn');
        renderClosedLoopContinueButtons();
        return false;
      }

      // Prevent endless recover loop for common send-stage failures.
      if (isClosedLoopLimitedRetrySendFailureReason(recoverReason)) {
        const streak = Math.max(0, Number(closedLoopContinueState.sendFailedStreak || 0));
        if (streak >= 1) {
          const pauseMsg = '继续发送失败，已暂停，请手动检查输入框或点击重新发送继续指令。';
          ToolboxShell.appendLog(
            `[CLOSED_LOOP][PAUSE_AFTER_SEND_FAILED] runId=${runId} reason=${recoverReason} streak=${streak + 1}`,
          );
          pauseClosedLoopContinue(`send-failed-paused:${recoverReason}`, {
            level: 'warn',
            message: pauseMsg,
          });
          setStatus(pauseMsg, 'warn');
          renderClosedLoopContinueButtons();
          return false;
        }
        closedLoopContinueState.sendFailedStreak = streak + 1;
      } else {
        closedLoopContinueState.sendFailedStreak = 0;
      }

      closedLoopContinueState.stopping = false;
      closedLoopContinueState.lastReason = recoverReason;

      const loopTask = ensureCopyHotkeyUploadVerifyLoopTask();
      loopTask.stopRequested = false;
      loopTask.lastError = recoverReason;
      loopTask.currentSubtask = 'recovering';

      setCopyHotkeyUploadVerifyLoopPhase('running', `recovering:${recoverReason}`, {
        cycleIndex: closedLoopContinueState.round,
        currentSubtask: 'recovering',
      });

      ToolboxShell.appendLog(
        `[CLOSED_LOOP][RECOVER_SCHEDULE] runId=${runId} delayMs=${delayMs} reason=${recoverReason} retryCurrentRound=${retryCurrentRound ? 1 : 0}`,
      );

      renderClosedLoopContinueButtons();
      return scheduleClosedLoopContinueNextStep(runId, delayMs, recoverReason, {
        retryCurrentRound,
      });
    }

    function getClosedLoopContinueButtonElement(mode) {
      const actionDef = getClosedLoopContinueActionDef(mode);
      const selector = actionDef.selector;
      const candidates = [];

      if (rootElRef) {
        const scoped = qs(selector, rootElRef);
        if (scoped) {
          candidates.push(scoped);
        }
      }

      document.querySelectorAll(selector).forEach((btn) => {
        if (!candidates.includes(btn)) {
          candidates.push(btn);
        }
      });

      const visible = candidates.find((btn) => {
        if (!(btn instanceof HTMLElement)) {
          return false;
        }
        const rect = btn.getBoundingClientRect();
        return rect.width > 0 && rect.height > 0;
      });

      return visible || candidates[0] || null;
    }

    function forceResetClosedLoopStopButtonsWhenNotRunning(reason = 'unknown') {
      const root = rootElRef || document;
      if (!root) return;
      const running = !!(
        closedLoopContinueState
        && closedLoopContinueState.running === true
      );
      if (running) return;
      const closedLoopButtons = [
        {
          id: 'cgpt-closed-loop-upload-every5-hotkey-btn',
          action: 'closed-loop-with-hotkey',
          text: '闭环-快捷键模式+每5轮上传',
        },
        {
          id: 'cgpt-closed-loop-upload-every-round-hotkey-btn',
          action: 'closed-loop-with-hotkey-upload-every-round',
          text: '闭环-快捷键模式+每一轮上传',
        },
        {
          id: 'cgpt-closed-loop-upload-every5-btn',
          action: 'closed-loop-without-hotkey',
          text: '闭环-仅对话+每5轮上传',
        },
      ];
      closedLoopButtons.forEach((cfg) => {
        const btn = root.querySelector(`#${cfg.id}`);
        if (!btn) return;
        const text = String(btn.textContent || '').trim();
        if (text.includes('停止闭环继续') || text.includes('停止环继续')) {
          btn.textContent = cfg.text;
          btn.title = cfg.text;
          btn.disabled = false;
          btn.dataset.action = cfg.action;
          btn.dataset.cgptButtonAction = cfg.action;
          btn.dataset.cgptRuntimeAction = cfg.action;
          btn.classList.remove('cgpt-btn-busy', 'cgpt-btn-danger', 'cgpt-btn-failed');
          ToolboxShell.appendLog(
            `[CLOSED_LOOP][RESET_STALE_STOP_BUTTON] id=${cfg.id} action=${cfg.action} oldText=${text} newText=${cfg.text} reason=${String(reason || '-')}`,
          );
        }
      });
      const allStopButtons = Array.from(root.querySelectorAll('button')).filter((btn) => {
        const text = String(btn.textContent || '').trim();
        return text.includes('停止闭环继续') || text.includes('停止环继续');
      });
      if (allStopButtons.length > 0) {
        const detail = allStopButtons.map((btn) => {
          const action = btn.dataset.action
            || btn.dataset.cgptButtonAction
            || btn.dataset.cgptRuntimeAction
            || '-';
          return `${btn.id || '-'}:${action}:${String(btn.textContent || '').trim()}`;
        }).join(' | ');
        ToolboxShell.appendLog(
          `[CLOSED_LOOP][STALE_STOP_BUTTONS_REMAIN] count=${allStopButtons.length} reason=${String(reason || '-')} detail=${detail}`,
        );
      }
    }

    function removeOrResetOrphanClosedLoopStopButtons(reason = 'unknown') {
      const root = rootElRef || document;
      if (!root) return;
      const running = !!(
        closedLoopContinueState
        && closedLoopContinueState.running === true
      );
      if (running) return;
      const validClosedLoopIds = new Set([
        'cgpt-closed-loop-upload-every5-hotkey-btn',
        'cgpt-closed-loop-upload-every-round-hotkey-btn',
        'cgpt-closed-loop-upload-every5-btn',
      ]);
      const normalLabels = {
        'cgpt-upload-start': '开始上传',
        'cgpt-send-message-once': '发送消息',
        'cgpt-send-copy-hotkey-once': '发送+复制+快捷键',
        'cgpt-copy-hotkey-once': '复制+快捷键',
        'cgpt-upload-continue-once': '复制并继续',
        'cgpt-auto-continue-once': '无限继续',
        'cgpt-auto-continue-until-done': '无限继续直到完成',
        'cgpt-copy-last-message-scroll-bottom': '复制最后回复',
        'cgpt-copy-toolbox-log': '复制日志',
        'cgpt-open-chatgpt-home': '回到首页',
        'cgpt-copy-hotkey-continue-once': '复制+快捷键+继续',
        'cgpt-copy-hotkey-continue-loop': '无限连续复制+快捷键+继续',
      };
      Array.from(root.querySelectorAll('button')).forEach((btn) => {
        const text = String(btn.textContent || '').trim();
        if (!text.includes('停止闭环继续') && !text.includes('停止环继续')) return;
        const id = String(btn.id || '').trim();
        if (validClosedLoopIds.has(id)) return;
        const fixedText = normalLabels[id];
        if (fixedText) {
          btn.textContent = fixedText;
          btn.title = fixedText;
          btn.classList.remove('cgpt-btn-busy', 'cgpt-btn-danger', 'cgpt-btn-failed');
          ToolboxShell.appendLog(
            `[CLOSED_LOOP][RESET_POLLUTED_STOP_BUTTON] id=${id || '-'} oldText=${text} newText=${fixedText} reason=${String(reason || '-')}`,
          );
          return;
        }
        ToolboxShell.appendLog(
          `[CLOSED_LOOP][REMOVE_ORPHAN_STOP_BUTTON] id=${id || '-'} oldText=${text} reason=${String(reason || '-')}`,
        );
        btn.remove();
      });
    }

    function diagnoseDuplicateClosedLoopStopButtons(reason = 'unknown') {
      diagnoseButtonTextPollution(reason);
    }

    function diagnoseButtonTextPollution(reason = 'unknown') {
      const root = rootElRef || document;
      if (!root) {
        return;
      }
      const closedLoopButtonActions = typeof UploadButtonVm !== 'undefined'
        && UploadButtonVm.CLOSED_LOOP_BUTTON_ACTIONS
        ? UploadButtonVm.CLOSED_LOOP_BUTTON_ACTIONS
        : new Set([
          'closed-loop-with-hotkey',
          'closed-loop-with-hotkey-upload-every-round',
          'closed-loop-without-hotkey',
        ]);
      const closedLoopButtonIds = typeof UploadButtonVm !== 'undefined'
        && UploadButtonVm.CLOSED_LOOP_BUTTON_IDS
        ? UploadButtonVm.CLOSED_LOOP_BUTTON_IDS
        : new Set([
          'cgpt-closed-loop-upload-every5-hotkey-btn',
          'cgpt-closed-loop-upload-every-round-hotkey-btn',
          'cgpt-closed-loop-upload-every5-btn',
        ]);
      const isClosedLoopLikeText = typeof UploadButtonVm !== 'undefined'
        && typeof UploadButtonVm.isClosedLoopLikeText === 'function'
        ? UploadButtonVm.isClosedLoopLikeText.bind(UploadButtonVm)
        : (text) => {
          const t = String(text || '').trim();
          return t.includes('闭环') || t.includes('停止环继续') || t.startsWith('环-');
        };

      const buttons = Array.from(root.querySelectorAll('button'));
      const stopButtons = [];
      const pollutedButtons = [];
      buttons.forEach((btn) => {
        const text = String(btn.textContent || '').trim();
        const action = String(
          btn.dataset?.action
          || btn.dataset?.cgptButtonAction
          || btn.dataset?.cgptRuntimeAction
          || '',
        ).trim();
        const id = String(btn.id || '').trim();
        if (text.includes('停止闭环继续') || text.includes('停止环继续')) {
          stopButtons.push(`${id || '-'}:${action || '-'}:${text}`);
        }
        const isClosedLoopBtn = closedLoopButtonIds.has(id)
          || closedLoopButtonActions.has(action);
        if (!isClosedLoopBtn && isClosedLoopLikeText(text)) {
          pollutedButtons.push(`${id || '-'}:${action || '-'}:${text}`);
        }
      });
      if (stopButtons.length > 1) {
        ToolboxShell.appendLog(
          `[BUTTON_TEXT][DUP_STOP] count=${stopButtons.length} reason=${String(reason || '-')} buttons=${stopButtons.join(' | ')}`,
        );
      }
      if (pollutedButtons.length > 0) {
        ToolboxShell.appendLog(
          `[BUTTON_TEXT][POLLUTED] count=${pollutedButtons.length} reason=${String(reason || '-')} buttons=${pollutedButtons.join(' | ')}`,
        );
      }
    }

    function renderClosedLoopContinueButtons(snapshot = null) {
      const hotkeyBtn = getClosedLoopContinueButtonElement(CLOSED_LOOP_CONTINUE_MODES.WITH_HOTKEY);
      const everyRoundBtn = getClosedLoopContinueButtonElement(CLOSED_LOOP_CONTINUE_MODES.WITH_HOTKEY_EVERY_ROUND);
      const plainBtn = getClosedLoopContinueButtonElement(CLOSED_LOOP_CONTINUE_MODES.WITHOUT_HOTKEY);
      let changed = 0;

      const vmAvailable = typeof UploadButtonVm !== 'undefined'
        && typeof UploadButtonVm.getClosedLoopContinueButtonViewState === 'function'
        && typeof UploadButtonVm.applyUploadButtonViewState === 'function';

      const renderOne = (btn, mode) => {
        if (!btn) {
          return false;
        }

        if (!vmAvailable) {
          return false;
        }

        const actionDef = getClosedLoopContinueActionDef(mode);
        const closedLoopCfg = getClosedLoopAutomationConfig();
        const localSnapshot = snapshot && typeof snapshot === 'object'
          ? snapshot
          : buildUploadButtonRenderSnapshot();
        localSnapshot.closedLoopLabel = getClosedLoopButtonLabel(mode);
        localSnapshot.closedLoopUploadInterval = getClosedLoopEffectiveUploadInterval(mode, closedLoopCfg);
        localSnapshot.closedLoopTitle = actionDef.title;

        const view = UploadButtonVm.getClosedLoopContinueButtonViewState(localSnapshot, mode);
        const ownerAction = typeof UploadButtonVm.getClosedLoopOwnerActionFromSnapshot === 'function'
          ? UploadButtonVm.getClosedLoopOwnerActionFromSnapshot(localSnapshot)
          : '';
        const buttonAction = typeof UploadButtonVm.resolveActionForClosedLoopMode === 'function'
          ? UploadButtonVm.resolveActionForClosedLoopMode(mode)
          : (actionDef.action || '');
        const isRunning = localSnapshot.closedLoopContinueRunning === true;
        const isOwner = typeof UploadButtonVm.isClosedLoopOwnerAction === 'function'
          ? UploadButtonVm.isClosedLoopOwnerAction(buttonAction, localSnapshot)
          : (isRunning && closedLoopContinueState.mode === mode);
        const pageGenerating = isPageGeneratingForClosedLoopStart(localSnapshot) ? 1 : 0;
        const currentOwner = typeof UploadButtonVm.resolveWaitingReplyOwner === 'function'
          ? UploadButtonVm.resolveWaitingReplyOwner(localSnapshot, localSnapshot.capability)
          : '';
        const ownerInfo = (
          typeof ClosedLoopButtonVm !== 'undefined'
          && typeof ClosedLoopButtonVm.resolveCurrentToolboxOwnerInfo === 'function'
        )
          ? ClosedLoopButtonVm.resolveCurrentToolboxOwnerInfo(localSnapshot)
          : null;
        const ownerSource = ownerInfo && ownerInfo.source ? String(ownerInfo.source).trim() : '-';
        const pendingStart = localSnapshot.closedLoopStartPending
          && typeof localSnapshot.closedLoopStartPending === 'object'
          ? localSnapshot.closedLoopStartPending
          : null;
        const pendingAction = pendingStart
          ? String(
            pendingStart.action
            || (
              typeof UploadButtonVm.resolveActionForClosedLoopMode === 'function'
                ? UploadButtonVm.resolveActionForClosedLoopMode(pendingStart.mode)
                : ''
            )
            || '',
          ).trim()
          : '';
        const isThisPending = !!pendingAction && pendingAction === buttonAction;
        const pageBusyButNotClosedLoop = pageGenerating && !isRunning && !isThisPending ? 1 : 0;
        const layoutHidden = isClosedLoopButtonsHiddenByExtraNarrowLayout();
        const visible = layoutHidden ? 0 : (isClosedLoopButtonDomVisible(btn) ? 1 : 0);
        const hitTestEnabled = layoutHidden ? 0 : visible;
        if (typeof ToolboxShell !== 'undefined' && typeof ToolboxShell.appendLog === 'function') {
          ToolboxShell.appendLog(
            `[CLOSED_LOOP_BUTTON][VIEW_DECIDE] id=${btn.id || actionDef.id || '-'} action=${buttonAction || '-'} visible=${visible} hitTestEnabled=${hitTestEnabled} running=${isRunning ? 1 : 0} owner=${ownerAction || '-'} isOwner=${isOwner ? 1 : 0} pageGenerating=${pageGenerating} currentOwner=${currentOwner || '-'} source=${ownerSource} pageBusyButNotClosedLoop=${pageBusyButNotClosedLoop} text=${view.text || '-'}`,
          );
        }
        const applied = UploadButtonVm.applyUploadButtonViewState(
          btn,
          view,
          'render-closed-loop',
          { snapshot: localSnapshot, buttonName: actionDef.action },
        );

        const isActiveMode = isOwner;
        btn.setAttribute('aria-disabled', isRunning && !isActiveMode ? 'true' : 'false');
        return applied;
      };

      if (renderOne(hotkeyBtn, CLOSED_LOOP_CONTINUE_MODES.WITH_HOTKEY)) {
        changed += 1;
      }
      if (renderOne(everyRoundBtn, CLOSED_LOOP_CONTINUE_MODES.WITH_HOTKEY_EVERY_ROUND)) {
        changed += 1;
      }
      if (renderOne(plainBtn, CLOSED_LOOP_CONTINUE_MODES.WITHOUT_HOTKEY)) {
        changed += 1;
      }
      scheduleClosedLoopButtonHitTest('after-render-closed-loop-buttons');
      forceResetClosedLoopStopButtonsWhenNotRunning('renderClosedLoopContinueButtons');
      diagnoseButtonTextPollution('renderClosedLoopContinueButtons');
      if (
        typeof AutoQueueModule !== 'undefined'
        && AutoQueueModule
        && typeof AutoQueueModule.refreshClosedLoopControlPanel === 'function'
      ) {
        AutoQueueModule.refreshClosedLoopControlPanel('upload-closed-loop-render');
      }
      return changed > 0;
    }

    function renderClosedLoopContinueButton(snapshot = null) {
      return renderClosedLoopContinueButtons(snapshot);
    }

    function pauseClosedLoopContinue(reason = 'unknown', options = {}) {
      const src = String(reason || 'unknown').trim() || 'unknown';
      const level = String(options.level || 'warn').trim() || 'warn';
      const message = String(options.message || `闭环继续暂时无法推进：${src}`);

      if (!closedLoopContinueState.running) {
        ToolboxShell.appendLog(`[CLOSED_LOOP][PAUSE_SKIP] reason=${src} cause=not-running`);
        return false;
      }

      closedLoopContinueState.stopping = false;
      closedLoopContinueState.lastReason = src;

      const loopTask = ensureCopyHotkeyUploadVerifyLoopTask();
      loopTask.stopRequested = false;
      loopTask.lastError = src;
      loopTask.currentSubtask = 'paused';

      setCopyHotkeyUploadVerifyLoopPhase('paused', `paused:${src}`, {
        cycleIndex: closedLoopContinueState.round,
        currentSubtask: 'paused',
      });

      ToolboxShell.appendLog(
        `[CLOSED_LOOP][PAUSED] reason=${src} round=${closedLoopContinueState.round} retryTimer=${closedLoopContinueState.retryTimerId ? 1 : 0} retryable=${isClosedLoopRetryablePauseReason(src) ? 1 : 0}`,
      );

      setStatus(message, level);
      renderClosedLoopContinueButtons();
      return true;
    }

    function isClosedLoopSuccessfulFinishCleanup(reason = '') {
      const src = String(reason || '').trim();
      if (!src.includes('closed-loop-finish')) {
        return false;
      }
      const finishFinalStatus = String(closedLoopContinueState.finishFinalStatus || '').trim().toLowerCase();
      if (finishFinalStatus === 'completed') {
        return true;
      }
      const task = ensureCopyHotkeyUploadVerifyLoopTask();
      const taskPhase = String(task && task.phase ? task.phase : '').trim().toLowerCase();
      return (
        taskPhase === 'success'
        || src.includes('assistant-terminal-signal-verified')
      );
    }

    function finishClosedLoopContinue(reason = 'unknown', options = {}) {
      const src = String(reason || 'unknown').trim() || 'unknown';
      const finalStatus = String(options.finalStatus || 'finished');
      closedLoopContinueState.finishFinalStatus = finalStatus;

      if (!closedLoopContinueState.running && !closedLoopContinueState.stopping) {
        ToolboxShell.appendLog(`[CLOSED_LOOP][FINISH_SKIP] reason=${src} state=idle`);
        return false;
      }

      clearClosedLoopStepTimer(`finish:${src}`);

      clearClosedLoopRetryTimer(src);
      closedLoopContinueState.retryAttempts = 0;
      clearClosedLoopButtonWaitState(`finish:${src}`);

      ToolboxShell.appendLog(
        `[CLOSED_LOOP][FINISH_REQUEST] reason=${src} finalStatus=${finalStatus} runId=${closedLoopContinueState.runId}`,
      );

      copyHotkeyUploadVerifyLoopStopRequested = true;
      state.cancelWaitingSend = true;
      state.messageSendCancelRequested = true;
      cancelCurrentUploadSend(`closed-loop-finish:${src}`);
      cancelWaitingSend(`closed-loop-finish:${src}`);

      const loopTask = ensureCopyHotkeyUploadVerifyLoopTask();
      loopTask.stopRequested = true;

      closedLoopContinueState.running = false;
      closedLoopContinueState.stopping = false;
      closedLoopContinueState.doneVerificationRunning = false;
      closedLoopContinueState.doneVerificationSent = false;
      closedLoopContinueState.doneVerificationRound = 0;
      closedLoopContinueState.homeNavigationRunning = false;
      closedLoopContinueState.lastHomeNavigationRound = 0;

      copyHotkeyUploadVerifyLoopRunning = false;
      copyHotkeyUploadVerifyLoopStopRequested = false;
      loopTask.stopRequested = false;
      syncToolboxRunningOwner(`closed-loop-finish:${src}`);

      setCopyHotkeyUploadVerifyLoopPhase(
        finalStatus === 'completed' ? 'success' : 'stopped',
        src,
        {
          cycleIndex: closedLoopContinueState.round,
        },
      );

      renderClosedLoopContinueButtons();
      releaseUploadActionLock('copy-hotkey-upload-verify-loop');

      window.setTimeout(() => {
        if (!closedLoopContinueState.running) {
          setCopyHotkeyUploadVerifyLoopPhase('idle', 'closed-loop-finish-reset');
        }
      }, 1200);

      ToolboxShell.appendLog(`[CLOSED_LOOP][FINISH_DONE] reason=${src} finalStatus=${finalStatus}`);
      ToolboxShell.appendLog(
        `[COPY_HOTKEY_UPLOAD_VERIFY_LOOP][done] reason=${src} cycles=${closedLoopContinueState.round}`,
      );

      return true;
    }

    function stopClosedLoopContinue(reason = 'manual-stop') {
      const src = String(reason || 'manual-stop').trim() || 'manual-stop';
      const oldRunId = closedLoopContinueState.runId || 0;

      ToolboxShell.appendLog(
        `[CLOSED_LOOP][STOP_REQUEST] reason=${src} runningBefore=${closedLoopContinueState.running ? 1 : 0} runId=${oldRunId} mode=${closedLoopContinueState.mode || '-'}`,
      );

      closedLoopContinueState.running = false;
      closedLoopContinueState.stopping = false;
      closedLoopContinueState.cancelRequested = true;
      closedLoopContinueState.cancelReason = src;
      closedLoopContinueState.runId = oldRunId + 1;
      closedLoopContinueState.mode = '';
      closedLoopContinueState.retryingCurrentRound = false;
      closedLoopContinueState.doneVerificationRunning = false;
      closedLoopContinueState.homeNavigationRunning = false;

      clearClosedLoopTimersAndLocks(`stop:${src}`);
      setClosedLoopPhase(CLOSED_LOOP_PHASES.IDLE, {
        reason: `stop:${src}`,
      });
      clearClosedLoopRetryTimer(`stop:${src}`);
      clearClosedLoopButtonWaitState(`stop:${src}`);

      if (closedLoopContinueState.countdownTickTimer) {
        clearInterval(closedLoopContinueState.countdownTickTimer);
        closedLoopContinueState.countdownTickTimer = 0;
      }
      closedLoopContinueState.waitKind = 'idle';
      closedLoopContinueState.waitStartedAt = 0;
      closedLoopContinueState.nextStepDelayMs = 0;
      closedLoopContinueState.nextStepCountdownEndAt = 0;

      copyHotkeyUploadVerifyLoopRunning = false;
      copyHotkeyUploadVerifyLoopStopRequested = true;
      const loopTask = ensureCopyHotkeyUploadVerifyLoopTask();
      loopTask.stopRequested = true;
      loopTask.currentSubtask = 'manual-stopped';

      setCopyHotkeyUploadVerifyLoopPhase('idle', `manual-stopped:${src}`, {
        cycleIndex: closedLoopContinueState.round || 0,
        currentSubtask: 'manual-stopped',
      });
      copyHotkeyUploadVerifyLoopStopRequested = false;
      loopTask.stopRequested = false;

      syncToolboxRunningOwner(`stop:${src}`);
      releaseUploadActionLock('copy-hotkey-upload-verify-loop');
      setStatus('闭环已停止', 'idle');
      renderClosedLoopContinueButtons();
      if (typeof renderUploadButtonsOnly === 'function') {
        renderUploadButtonsOnly(`closed-loop-stop:${src}`);
      }

      ToolboxShell.appendLog(
        `[CLOSED_LOOP][STOP_DONE] reason=${src} runningAfter=${closedLoopContinueState.running ? 1 : 0} oldRunId=${oldRunId} newRunId=${closedLoopContinueState.runId || '-'}`,
      );
      ToolboxShell.appendLog(`[CLOSED_LOOP][USER_STOP] reason=${src}`);

      return true;
    }

    function readComposerTextFallback() {
      const selectors = [
        'textarea[data-testid="composer-text-input"]',
        'textarea#prompt-textarea',
        '#prompt-textarea',
        'div.ProseMirror[contenteditable="true"]',
        'form [contenteditable="true"]',
        '[role="textbox"][contenteditable="true"]',
        '[contenteditable="true"][id="prompt-textarea"]',
      ];
      for (const selector of selectors) {
        const nodes = Array.from(document.querySelectorAll(selector));
        for (const node of nodes) {
          if (!(node instanceof HTMLElement)) {
            continue;
          }
          if (rootElRef && rootElRef.contains(node)) {
            continue;
          }
          const rect = node.getBoundingClientRect();
          if (rect.width <= 0 || rect.height <= 0) {
            continue;
          }
          const value = typeof node.value === 'string' ? node.value : '';
          const text = String(value || node.innerText || node.textContent || '').trim();
          if (text) {
            return text;
          }
        }
      }
      return '';
    }

    function getComposerPayloadStateForInitialSend() {
      let composerText = '';
      if (
        typeof ComposerApi !== 'undefined'
        && ComposerApi
        && typeof ComposerApi.getComposerText === 'function'
      ) {
        composerText = String(ComposerApi.getComposerText() || '').trim();
      }
      if (!composerText) {
        composerText = readComposerTextFallback();
      }

      const hasAttachment = (
        typeof ComposerApi !== 'undefined'
        && ComposerApi
        && typeof ComposerApi.hasComposerAttachmentUnified === 'function'
      )
        ? !!ComposerApi.hasComposerAttachmentUnified()
        : false;

      let hasVisiblePayloadText = false;
      if (
        typeof ComposerApi !== 'undefined'
        && ComposerApi
        && typeof ComposerApi.hasVisibleComposerAttachmentPayload === 'function'
      ) {
        hasVisiblePayloadText = !!ComposerApi.hasVisibleComposerAttachmentPayload();
      } else if (
        typeof ComposerApi !== 'undefined'
        && ComposerApi
        && typeof ComposerApi.hasComposerDraftPayload === 'function'
      ) {
        hasVisiblePayloadText = !!ComposerApi.hasComposerDraftPayload();
      }

      if (!hasVisiblePayloadText && composerText) {
        hasVisiblePayloadText = true;
      }

      ToolboxShell.appendLog(
        `[CLOSED_LOOP][INITIAL_PAYLOAD_STATE] textLen=${composerText.length} hasAttachment=${hasAttachment ? 1 : 0} hasVisiblePayloadText=${hasVisiblePayloadText ? 1 : 0}`,
      );

      return {
        composerText,
        hasAttachment,
        hasVisiblePayloadText,
      };
    }

    function hasPendingUploadQueueItems(options = {}) {
      if (typeof getPendingUploadItems !== 'function') {
        return false;
      }
      const groupId = getActiveUploadScopeGroupId(options);
      try {
        return (getPendingUploadItems({ groupId }) || []).length > 0;
      } catch (error) {
        console.error('[COPY_HOTKEY_UPLOAD_VERIFY_LOOP][pending-queue-check-failed]', {
          groupId,
          error_type: error && error.name,
          error: error && error.message,
          stack: error && error.stack,
        });
        return false;
      }
    }

    function isManualSendMessageSource(source) {
      const src = String(source || '').trim();
      return /^(button|shortcut|send-message|manual-send-message|enter-hotkey)/i.test(src);
    }

    function normalizeSendMessageSource(source, normalizedAction = 'send-message') {
      const rawSource = String(source || '').trim() || 'unknown';
      if (normalizedAction === 'send-message') {
        if (
          rawSource === 'delegated-click'
          || rawSource === 'root-delegated-click'
          || rawSource === 'button'
          || rawSource === 'unknown'
          || /^document:/i.test(rawSource)
        ) {
          return 'manual-send-message-button';
        }
      }
      return rawSource;
    }

    function resolveSendLogSource(source, options = {}) {
      const src = String(source || '').trim() || 'unknown';
      const parent = options && (options.parentAction || options.compositeAction)
        ? String(options.parentAction || options.compositeAction).trim()
        : '';
      return parent ? `${src}/${parent}` : src;
    }

    function isManualSendTimeoutDisabled() {
      const value = Number(MANUAL_SEND_TIMEOUT_MS);
      return !Number.isFinite(value) || value <= 0;
    }

    function getManualSendTimeoutSeconds() {
      if (isManualSendTimeoutDisabled()) {
        return 0;
      }
      return Math.ceil(Number(MANUAL_SEND_TIMEOUT_MS || 0) / 1000);
    }

    function getManualSendTimeoutText() {
      if (isManualSendTimeoutDisabled()) {
        return '不自动超时';
      }
      return `${getManualSendTimeoutSeconds()} 秒`;
    }

    function resolveManualSendActionLockTimeoutMs() {
      if (isManualSendTimeoutDisabled()) {
        return Number.POSITIVE_INFINITY;
      }
      return Math.max(1000, Number(MANUAL_SEND_TIMEOUT_MS) || 30000);
    }

    function resolveManualSendDeadlineMs() {
      if (isManualSendTimeoutDisabled()) {
        return Number.POSITIVE_INFINITY;
      }
      return Date.now() + Math.max(1000, Number(MANUAL_SEND_TIMEOUT_MS) || 30000);
    }

    function resolveSendDeadlineMs(rawDeadlineMs, isManualSend) {
      const value = Number(rawDeadlineMs);
      if (value === Number.POSITIVE_INFINITY) {
        return Number.POSITIVE_INFINITY;
      }
      if (Number.isFinite(value) && value > 0) {
        return value;
      }
      if (isManualSend) {
        return resolveManualSendDeadlineMs();
      }
      return Date.now() + Math.max(1000, Number(SEND_WAIT_TIMEOUT_MS) || 120000);
    }

    function isSendDeadlineReached(deadlineMs) {
      const value = Number(deadlineMs);
      return Number.isFinite(value) && value > 0 && Date.now() >= value;
    }

    function resolveManualSendAttachmentWaitMs() {
      const value = Number(MANUAL_SEND_ATTACHMENT_WAIT_MS);
      if (Number.isFinite(value) && value > 0) {
        return value;
      }
      if (isManualSendTimeoutDisabled()) {
        return Number.POSITIVE_INFINITY;
      }
      return Math.max(1000, Number(MANUAL_SEND_TIMEOUT_MS) || 30000);
    }

    function getUnreadableLocalQueueItems() {
      return (state.queue || []).filter((q) => q && isUploadItemLocallyUnreadable(q));
    }

    function hasUnreadableLocalQueueForSend() {
      return getUnreadableLocalQueueItems().length > 0;
    }

    function hasLocalQueueFilesWithoutComposerAttachment() {
      const queueHasFiles = (state.queue || []).length > 0;
      if (!queueHasFiles) {
        return false;
      }

      const unifiedHas = typeof ComposerApi.hasComposerAttachmentUnified === 'function'
        && ComposerApi.hasComposerAttachmentUnified();
      const chipCount = typeof ComposerApi.countAttachmentChips === 'function'
        ? ComposerApi.countAttachmentChips()
        : 0;

      return !unifiedHas && chipCount <= 0;
    }

    function probeSendMessageNativeReady() {
      const sendButton = typeof findUploadComposerSendButton === 'function'
        ? findUploadComposerSendButton()
        : null;
      return !!(
        sendButton instanceof HTMLButtonElement
        && typeof ComposerApi.isSendButtonReady === 'function'
        && ComposerApi.isSendButtonReady(sendButton)
      );
    }

    function getUploadNativeSendButtonReadyState() {
      let ready = false;
      let source = 'none';
      let error = null;

      try {
        if (typeof getComposerSendButtonSnapshot === 'function') {
          const sendSnap = getComposerSendButtonSnapshot({ silent: true });
          if (
            sendSnap
            && sendSnap.ready === true
            && assertNativeButtonIsSendButton(sendSnap.button, 'native-ready-probe-snapshot')
          ) {
            ready = true;
            source = 'snapshot.ready';
            return { ready, source, error };
          }
        }
      } catch (err) {
        error = err;
        console.error('[ChatGPT toolbox] getUploadNativeSendButtonReadyState snapshot failed', err);
        if (typeof ToolboxShell !== 'undefined' && typeof ToolboxShell.appendLog === 'function') {
          ToolboxShell.appendLog(
            `[SEND][NATIVE_READY_PROBE_ERROR] stage=snapshot error=${err && err.message ? err.message : String(err)}`,
          );
        }
      }

      try {
        if (typeof evaluateComposerSendability === 'function') {
          const sendability = evaluateComposerSendability(findUploadComposerSendButton());
          if (sendability && sendability.realSendButtonEnabled) {
            ready = true;
            source = 'sendability.realSendButtonEnabled';
            return { ready, source, error };
          }
        }
      } catch (err) {
        error = err;
        console.error('[ChatGPT toolbox] getUploadNativeSendButtonReadyState sendability failed', err);
        if (typeof ToolboxShell !== 'undefined' && typeof ToolboxShell.appendLog === 'function') {
          ToolboxShell.appendLog(
            `[SEND][NATIVE_READY_PROBE_ERROR] stage=sendability error=${err && err.message ? err.message : String(err)}`,
          );
        }
      }

      try {
        const sendButton = typeof findUploadComposerSendButton === 'function'
          ? findUploadComposerSendButton()
          : null;
        if (
          sendButton instanceof HTMLButtonElement
          && typeof ComposerApi !== 'undefined'
          && ComposerApi
          && typeof ComposerApi.isSendButtonReady === 'function'
          && ComposerApi.isSendButtonReady(sendButton)
        ) {
          ready = true;
          source = 'fallback.buttonReady';
          return { ready, source, error };
        }
      } catch (err) {
        error = err;
        console.error('[ChatGPT toolbox] getUploadNativeSendButtonReadyState fallback failed', err);
        if (typeof ToolboxShell !== 'undefined' && typeof ToolboxShell.appendLog === 'function') {
          ToolboxShell.appendLog(
            `[SEND][NATIVE_READY_PROBE_ERROR] stage=fallback error=${err && err.message ? err.message : String(err)}`,
          );
        }
      }

      return { ready: false, source, error };
    }

    function logSendMessageComposerState(source, extraSuffix = '') {
      const textLen = typeof ComposerApi.getComposerText === 'function'
        ? String(ComposerApi.getComposerText() || '').trim().length
        : 0;
      const attachmentCount = typeof getComposerUploadPayloadCount === 'function'
        ? getComposerUploadPayloadCount(`send-composer-state:${source}`)
        : (
          typeof ComposerApi.countAttachmentChips === 'function'
            ? ComposerApi.countAttachmentChips()
            : 0
        );
      const uploading = typeof ComposerApi.isAttachmentStillUploading === 'function'
        && ComposerApi.isAttachmentStillUploading();
      const nativeReady = getUploadNativeSendButtonReadyState().ready ? 1 : 0;
      const suffix = extraSuffix ? ` ${extraSuffix}` : '';

      ToolboxShell.appendLog(
        `[SEND_MESSAGE][COMPOSER_STATE] source=${source} textLen=${textLen} attachmentCount=${attachmentCount} uploading=${uploading ? 1 : 0} nativeReady=${nativeReady}${suffix}`,
      );

      return {
        textLen,
        attachmentCount,
        uploading,
        nativeReady: nativeReady === 1,
      };
    }

    function scheduleManualSendFailureHintClear(runId) {
      window.setTimeout(() => {
        if (state.autoSendRunId !== runId) {
          return;
        }
        if (!state.uploadSendFailureHint) {
          return;
        }
        state.uploadSendFailureHint = '';
        state.uploadSendFailureHintAt = 0;
        scheduleRenderUpload('send-message:manual-fail-hint-clear');
      }, MANUAL_SEND_FAILURE_HINT_CLEAR_MS);
    }

    function failManualSendEarly(runId, source, reason, failMessage) {
      lastUploadSendPanelFailReason = reason;
      const composerSnap = logSendMessageComposerState(source, `reason=${reason}`);
      ToolboxShell.appendLog(
        `[SEND_MESSAGE][FAILED] reason=${reason} source=${source} textLen=${composerSnap.textLen} attachmentCount=${composerSnap.attachmentCount} nativeReady=${composerSnap.nativeReady ? 1 : 0}`,
      );
      resetUploadSendUiState(`send-message:manual-fail:${reason}`, runId);
      const statusType = isIdleComposerEmptySendButtonNotFound(reason) ? 'info' : 'warn';
      if (statusType === 'info') {
        ToolboxShell.appendLog(
          `[SEND_UI][IDLE_SEND_BUTTON_NOT_FOUND] reason=${reason} source=${source} downgraded=info`,
        );
      }
      setStatus(failMessage, statusType);
      state.uploadSendFailureHint = failMessage;
      state.uploadSendFailureHintAt = Date.now();
      scheduleRenderUpload('send-message:manual-fail');
      scheduleManualSendFailureHintClear(runId);
      logUploadSendUiState('not-sent', reason, runId);
      return false;
    }

    function isAutoQueueInternalSendSource(source) {
      const text = String(source || '');
      return (
        text.startsWith('autoq:')
        || text.startsWith('autoq-task-')
        || text.includes('autoq:send-existing')
        || text.includes('cadence-upload-failed')
        || text.includes('continue-send')
      );
    }

    function resolveSendLockOwnerContext(source) {
      const src = String(source || '').trim();
      let currentRunId = '';
      let currentTaskId = '';
      if (
        typeof AutoQueueModule !== 'undefined'
        && AutoQueueModule
        && typeof AutoQueueModule.getState === 'function'
      ) {
        const autoState = AutoQueueModule.getState() || {};
        const run = autoState.taskRun || {};
        currentRunId = String(run.runId || autoState.currentRunId || '').trim();
        currentTaskId = String(
          run.currentTaskId
          || run.taskId
          || autoState.currentTaskId
          || (autoState.currentTask && autoState.currentTask.id)
          || '',
        ).trim();
      }
      return {
        source: src,
        currentRunId,
        currentTaskId,
      };
    }

    function getSendActionLockOwnerSnapshot() {
      if (
        typeof ActionRuntime !== 'undefined'
        && ActionRuntime
        && typeof ActionRuntime.getActionLockOwner === 'function'
      ) {
        return ActionRuntime.getActionLockOwner('send-message');
      }
      return { taskId: '', runId: '', source: '' };
    }

    function logSendLockCheck(decision, reason, ownerCtx, lockOwner) {
      const owner = ownerCtx || resolveSendLockOwnerContext('');
      const lock = lockOwner || getSendActionLockOwnerSnapshot();
      ToolboxShell.appendLog(
        `[SEND_LOCK][CHECK] decision=${decision} reason=${reason || '-'} `
        + `currentRunId=${owner.currentRunId || '-'} lockRunId=${lock.runId || '-'} `
        + `currentTaskId=${owner.currentTaskId || '-'} lockTaskId=${lock.taskId || '-'} `
        + `source=${owner.source || '-'} lockSource=${lock.source || '-'}`,
      );
    }

    function shouldForceReleaseSendLockForAutoQueue(source) {
      if (!isAutoQueueInternalSendSource(source)) {
        return false;
      }
      const sendPhaseNow = typeof getSendTaskPhase === 'function' ? String(getSendTaskPhase() || '') : 'idle';
      const sendPhaseIdle = (
        sendPhaseNow === 'idle'
        || sendPhaseNow === 'failed'
        || sendPhaseNow === 'cancelled'
        || sendPhaseNow === 'completed'
        || sendPhaseNow === 'success'
      );
      const composerCount = getComposerUploadPayloadCount();
      return sendPhaseIdle && composerCount > 0;
    }

    function shouldForceReleaseStaleSendLockForDifferentAutoQueueTask(source, lockOwner) {
      if (!isAutoQueueInternalSendSource(source)) {
        return false;
      }
      const ownerCtx = resolveSendLockOwnerContext(source);
      const lock = lockOwner || getSendActionLockOwnerSnapshot();
      if (!ownerCtx.currentTaskId || !lock.taskId || ownerCtx.currentTaskId === lock.taskId) {
        return false;
      }
      const sendPhaseNow = typeof getSendTaskPhase === 'function' ? String(getSendTaskPhase() || '') : 'idle';
      const sendPhaseIdle = (
        sendPhaseNow === 'idle'
        || sendPhaseNow === 'failed'
        || sendPhaseNow === 'cancelled'
        || sendPhaseNow === 'completed'
        || sendPhaseNow === 'success'
      );
      const flowRunActive = !!(currentUploadSendFlowRun && !currentUploadSendFlowRun.cancelled);
      const stateActive = !!(
        state.waitingSend
        || state.autoSendWaiting
        || state.messageSending
      );
      return sendPhaseIdle && !flowRunActive && !stateActive;
    }

    async function sendExistingComposerBySendMessageButtonCore(options = {}) {
      const source = String(options.source || 'shared-send-message').trim() || 'shared-send-message';
      const logSource = String(options.logSource || source).trim() || source;
      const shouldStop = typeof options.shouldStop === 'function'
        ? options.shouldStop
        : () => false;
      const unifiedText = options.text != null ? String(options.text) : '';
      const isManualSend = options.manualSend === true || isManualSendMessageSource(source);
      const timeoutMs = isManualSend
        ? resolveManualSendActionLockTimeoutMs()
        : Math.max(1000, Number(options.timeoutMs || SEND_WAIT_TIMEOUT_MS || 120000));

      ToolboxShell.appendLog(`[SEND_MESSAGE_SHARED][ENTER] source=${logSource}`);

      const duplicateSnapshotBeforeSend = getComposerUploadPayloadSnapshot(`send-before:${source || 'unknown'}`);
      if (
        duplicateSnapshotBeforeSend.rawCount > 1
        && duplicateSnapshotBeforeSend.normalizedCount === 1
      ) {
        ToolboxShell.appendLog(
          `[SEND_MESSAGE_SHARED][DUPLICATE_RAW_IGNORED] source=${logSource || '-'} raw=${duplicateSnapshotBeforeSend.rawCount} normalized=${duplicateSnapshotBeforeSend.normalizedCount} ready=${duplicateSnapshotBeforeSend.readyCount} action=continue-send`,
        );
      } else if (duplicateSnapshotBeforeSend.normalizedCount > 1) {
        ToolboxShell.appendLog(
          `[SEND_MESSAGE_SHARED][MULTI_ATTACHMENTS_KEEP] source=${logSource || '-'} raw=${duplicateSnapshotBeforeSend.rawCount} normalized=${duplicateSnapshotBeforeSend.normalizedCount} ready=${duplicateSnapshotBeforeSend.readyCount} visibleRemoveButtons=${duplicateSnapshotBeforeSend.visibleRemoveButtonCount || 0} action=continue-send reason=multi-file-is-valid`,
        );
      }

      const activeGroupIdForSendCheck = typeof getActiveUploadScopeGroupId === 'function'
        ? getActiveUploadScopeGroupId({})
        : '';
      const activeFilesForSendCheck = typeof getActiveGroupFiles === 'function'
        ? getActiveGroupFiles()
        : [];
      const activeFileCountForSendCheck = Array.isArray(activeFilesForSendCheck)
        ? activeFilesForSendCheck.length
        : 0;
      if (
        activeFileCountForSendCheck > 0
        && duplicateSnapshotBeforeSend.normalizedCount > activeFileCountForSendCheck
      ) {
        ToolboxShell.appendLog(
          `[SEND_MESSAGE_SHARED][WARN_COMPOSER_MORE_THAN_QUEUE] source=${logSource || '-'} groupId=${activeGroupIdForSendCheck || '-'} composer=${duplicateSnapshotBeforeSend.normalizedCount} queue=${activeFileCountForSendCheck} action=warn-only reason=possible-stale-composer-attachment`,
        );
      }

      const uploadPhaseForSendCheck = typeof getUploadTaskState === 'function'
        ? String((getUploadTaskState() || {}).phase || 'idle').trim().toLowerCase()
        : String(state && state.uploadPhase ? state.uploadPhase : 'idle').trim().toLowerCase();
      if (
        activeFileCountForSendCheck > 0
        && uploadPhaseForSendCheck === 'idle'
        && duplicateSnapshotBeforeSend.normalizedCount > 0
      ) {
        ToolboxShell.appendLog(
          `[SEND_MESSAGE][LOCAL_QUEUE_EXISTS] activeFiles=${activeFileCountForSendCheck} composerAttachmentCount=${duplicateSnapshotBeforeSend.normalizedCount} action=send-current-composer-only`,
        );
      }

      if (shouldStop()) {
        ToolboxShell.appendLog(`[SEND_MESSAGE_SHARED][FAILED] source=${logSource} reason=cancelled-before-start`);
        return {
          ok: false,
          reason: 'cancelled',
        };
      }

      const composerAttachmentCountForPrepare = Math.max(
        0,
        Number(duplicateSnapshotBeforeSend.normalizedCount || 0),
      );
      try {
        await prepareBeforeManualSend({
          isManualSend,
          attachmentCount: composerAttachmentCountForPrepare,
          source: logSource,
        });
      } catch (prepareErr) {
        const prepareErrStack = prepareErr && prepareErr.stack
          ? prepareErr.stack
          : (prepareErr && prepareErr.message ? prepareErr.message : String(prepareErr));
        console.error('[ChatGPT toolbox] prepareBeforeManualSend failed', prepareErr);
        ToolboxShell.appendLog(
          `[SEND_PREPARE][FAILED] source=${logSource} error=${prepareErrStack}`,
        );
        if (isManualSend && composerAttachmentCountForPrepare === 0) {
          ToolboxShell.appendLog(
            `[SEND_PREPARE][PLAIN_TEXT_CONTINUE] source=${logSource} reason=queue-restore-failed-but-plain-text`,
          );
        } else {
          return {
            ok: false,
            reason: 'send-prepare-failed',
          };
        }
      }

      const sendLockOwnerCtx = resolveSendLockOwnerContext(source);
      const sendLockClaimOptions = {
        timeoutMs,
        taskId: sendLockOwnerCtx.currentTaskId,
        runId: sendLockOwnerCtx.currentRunId,
        source,
      };

      let sendLock = claimUploadActionLock('send-message', sendLockClaimOptions);

      if (sendLock && sendLock.ok && sendLock.reason === 'same-owner-reuse') {
        logSendLockCheck('allow', 'same-owner-reuse', sendLockOwnerCtx, sendLock.lockOwner);
      } else if (sendLock && sendLock.ok) {
        logSendLockCheck('allow', 'claimed', sendLockOwnerCtx, sendLock.lockOwner);
      }

      if (
        !sendLock.ok
        && sendLock.reason === 'task-running'
        && shouldForceReleaseSendLockForAutoQueue(source)
      ) {
        logSendLockCheck('allow', 'autoq-force-release-ready-attachment', sendLockOwnerCtx, sendLock.lockOwner);
        ToolboxShell.appendLog(
          `[SEND_LOCK][AUTOQ_FORCE_RELEASE] key=send-message source=${logSource} reason=autoq-internal-send-with-ready-attachment`,
        );
        releaseUploadActionLock('send-message');
        sendLock = claimUploadActionLock('send-message', Object.assign({}, sendLockClaimOptions, {
          forceRelease: true,
        }));
      }

      if (!sendLock.ok && sendLock.reason === 'task-running') {
        // 检查是否是 stale lock：锁认为在运行，但所有状态都表明任务已结束
        const sendPhaseNow = typeof getSendTaskPhase === 'function' ? getSendTaskPhase() : 'idle';
        const sendPhaseIdle = sendPhaseNow === 'idle'
          || sendPhaseNow === 'failed'
          || sendPhaseNow === 'cancelled'
          || sendPhaseNow === 'completed'
          || sendPhaseNow === 'success';
        const flowRunActive = !!(currentUploadSendFlowRun && !currentUploadSendFlowRun.cancelled);
        const stateActive = !!(
          state.waitingSend
          || state.autoSendWaiting
          || state.waitingReply
          || state.messageSending
        );
        const isStale = sendPhaseIdle && !flowRunActive && !stateActive;
        const isDifferentTaskStale = shouldForceReleaseStaleSendLockForDifferentAutoQueueTask(
          source,
          sendLock.lockOwner,
        );

        if (isStale || isDifferentTaskStale) {
          logSendLockCheck(
            'allow',
            isDifferentTaskStale ? 'stale-release-different-task' : 'stale-release-idle',
            sendLockOwnerCtx,
            sendLock.lockOwner,
          );
          ToolboxShell.appendLog(
            `[SEND_LOCK][STALE_RELEASE] key=send-message reason=${isDifferentTaskStale ? 'different-task-stale-lock' : 'task-running-but-send-task-idle'} source=${logSource} sendPhase=${sendPhaseNow}`,
          );
          releaseUploadActionLock('send-message');
          sendLock = claimUploadActionLock('send-message', sendLockClaimOptions);
        }
      }

      if (!sendLock.ok) {
        logSendLockCheck('reject', sendLock.reason || 'task-running', sendLockOwnerCtx, sendLock.lockOwner);
        ToolboxShell.appendLog(
          `[SEND_MESSAGE_SHARED][FAILED] source=${logSource} reason=send-action-lock detail=${sendLock.reason || '-'}`,
        );
        logSendHotkeyBlocked('send-action-lock', source, `detail=${sendLock.reason || '-'}`);
        const failMsg = '发送失败：发送任务锁未释放';
        setStatus(failMsg, 'warn');
        state.uploadSendFailureHint = failMsg;
        state.uploadSendFailureHintAt = Date.now();
        scheduleRenderUpload('send-message:lock-blocked');
        const lockReason = sendLock.reason || 'locked';
        return {
          ok: false,
          reason: `send-action-lock:${lockReason}`,
          retryable: lockReason === 'task-running' || String(lockReason).includes('task-running'),
          wait: true,
          wait_send: true,
        };
      }

      const flowRun = createUploadSendRun(source);
      if (!flowRun) {
        releaseUploadActionLock('send-message');
        ToolboxShell.appendLog(`[SEND_MESSAGE_SHARED][FAILED] source=${logSource} reason=upload-send-flow-locked`);
        logSendHotkeyBlocked('upload-send-flow-locked', source);
        return {
          ok: false,
          reason: 'upload-send-flow-locked',
        };
      }

      const useSendMessageTask = shouldUseSendMessageTaskState(source);
      let sendMessageTaskCtx = null;
      if (useSendMessageTask) {
        if (sendMessageTaskState.running && sendMessageTaskState.runId) {
          sendMessageTaskCtx = {
            runId: sendMessageTaskState.runId,
            signal: sendMessageTaskState.abortController
              ? sendMessageTaskState.abortController.signal
              : null,
          };
          ToolboxShell.appendLog(
            `[SEND_TASK][REUSE_RUNNING] runId=${sendMessageTaskCtx.runId} source=${logSource}`,
          );
        } else {
          sendMessageTaskCtx = startSendMessageTask(logSource, resolveSendTaskActionFromOptions(options));
          if (!sendMessageTaskCtx) {
            releaseUploadActionLock('send-message');
            finishUploadSendRun(flowRun, `shared-send-message-blocked-already-running:${source}`);
            return {
              ok: false,
              reason: 'send-task-already-running',
              wait: true,
              retryable: false,
            };
          }
        }
      }

      const runId = claimWaitingSendRun(
        source,
        typeof options.runId !== 'undefined' ? options.runId : Date.now(),
      );

      let sharedSendOutcome = noteSharedSendOutcome({
        ok: false,
        sent: false,
        verified: false,
        cancelled: false,
        cancelledAfterSend: false,
        reason: '',
        verifyReason: '',
        source,
      });

      try {
        if (shouldStop()) {
          cancelCurrentUploadSend(`shared-send-cancelled:${source}`);
          const sendPhase = typeof getSendTaskPhase === 'function' ? String(getSendTaskPhase() || '') : '';
          const uploadPhase = typeof getUploadTaskState === 'function'
            ? String((getUploadTaskState() || {}).phase || '')
            : String(state && state.uploadPhase ? state.uploadPhase : '');
          ToolboxShell.appendLog(
            `[SEND_MESSAGE_SHARED][CANCEL_AFTER_CLAIM_DETAIL] source=${logSource} runId=${runId} autoSendRunId=${state.autoSendRunId || 0} `
            + `cancelWaitingSend=${state.cancelWaitingSend ? 1 : 0} messageSendCancelRequested=${state.messageSendCancelRequested ? 1 : 0} `
            + `waitingSend=${state.waitingSend ? 1 : 0} waitingReply=${state.waitingReply ? 1 : 0} messageSending=${state.messageSending ? 1 : 0} `
            + `sendPhase=${sendPhase || '-'} uploadPhase=${uploadPhase || '-'} flowCancelled=${currentUploadSendFlowRun && currentUploadSendFlowRun.cancelled ? 1 : 0} `
            + `flowReason=${currentUploadSendFlowRun && currentUploadSendFlowRun.cancelReason ? String(currentUploadSendFlowRun.cancelReason) : '-'}`,
          );
          if (String(source || '') === 'quick-prompt-click' || String(source || '').startsWith('quick-prompt')) {
            ToolboxShell.appendLog(
              `[SEND_MESSAGE_SHARED][UNEXPECTED_CANCEL_AFTER_CLAIM] source=${logSource} runId=${runId} `
              + `hint=quick-prompt-shouldStop-true check_cancel_flags_above`,
            );
          }
          ToolboxShell.appendLog(`[SEND_MESSAGE_SHARED][FAILED] source=${logSource} reason=cancelled-after-claim`);
          return {
            ok: false,
            reason: 'cancelled',
          };
        }

        const ok = await sendCurrentMessageFromUploadPanel(source, runId, flowRun, {
          text: unifiedText,
          rawSource: options.rawSource || source,
          manualSend: isManualSend,
          singleShot: options.singleShot === true,
          maxStableAttempts: options.maxStableAttempts,
          sendDeadlineMs: isManualSend ? resolveManualSendDeadlineMs() : Date.now() + timeoutMs,
          allowReplaceDraft: options.allowReplaceDraft !== false,
          payloadVerify: options.payloadVerify || null,
        });

        if (ok === true) {
          const sendPhaseAfterOk = typeof getSendTaskPhase === 'function'
            ? String(getSendTaskPhase() || '')
            : '';
          let responseStateAfterOk = '';
          if (typeof detectComposerResponseState === 'function') {
            const responseSnap = detectComposerResponseState();
            responseStateAfterOk = responseSnap && responseSnap.state
              ? String(responseSnap.state)
              : '';
          }
          sharedSendOutcome = noteSharedSendOutcome({
            ok: true,
            sent: true,
            verified: true,
            reason: 'send-message-button-core',
            verifyReason: String(lastUploadSendPanelFailReason || '').includes('turn_count')
              ? lastUploadSendPanelFailReason
              : (sendPhaseAfterOk === 'waiting_reply' ? 'turn_count_increased' : ''),
            responseState: responseStateAfterOk,
            sendPhase: sendPhaseAfterOk,
          });
        }

        if (shouldStop()) {
          const sendPhase = typeof getSendTaskPhase === 'function' ? String(getSendTaskPhase() || '') : '';
          const uploadPhase = typeof getUploadTaskState === 'function'
            ? String((getUploadTaskState() || {}).phase || '')
            : String(state && state.uploadPhase ? state.uploadPhase : '');
          const alreadySent = ok === true || isRealSendConfirmed(sharedSendOutcome) || isRealSendConfirmed(lastSharedSendOutcome);
          if (alreadySent) {
            ToolboxShell.appendLog(
              `[SEND_MESSAGE_SHARED][CANCEL_AFTER_SEND_IGNORED] source=${logSource || '-'} reason=already-sent `
              + `verifyReason=${sharedSendOutcome.verifyReason || lastSharedSendOutcome && lastSharedSendOutcome.verifyReason ? lastSharedSendOutcome.verifyReason : '-'} `
              + `sent=${sharedSendOutcome.sent ? 1 : 0} verified=${sharedSendOutcome.verified ? 1 : 0} `
              + `composerCleared=${sharedSendOutcome.composerCleared ? 1 : 0} `
              + `stopButtonVisible=${sharedSendOutcome.stopButtonVisible ? 1 : 0} `
              + `responseState=${sharedSendOutcome.responseState || '-'} sendPhase=${sendPhase || '-'}`,
            );
            return {
              ok: true,
              sent: true,
              verified: true,
              cancelledAfterSend: true,
              reason: 'sent-before-cancelled',
              verifyReason: sharedSendOutcome.verifyReason || 'already-sent',
            };
          }
          ToolboxShell.appendLog(
            `[SEND_MESSAGE_SHARED][CANCEL_AFTER_SEND_DETAIL] source=${logSource} runId=${runId} `
            + `cancelWaitingSend=${state.cancelWaitingSend ? 1 : 0} messageSendCancelRequested=${state.messageSendCancelRequested ? 1 : 0} `
            + `currentFlowCancelled=${currentUploadSendFlowRun && currentUploadSendFlowRun.cancelled ? 1 : 0} `
            + `currentFlowReason=${currentUploadSendFlowRun && currentUploadSendFlowRun.cancelReason ? String(currentUploadSendFlowRun.cancelReason) : '-'} `
            + `sendPhase=${sendPhase || '-'} uploadPhase=${uploadPhase || '-'}`,
          );
          ToolboxShell.appendLog(`[SEND_MESSAGE_SHARED][FAILED] source=${logSource} reason=cancelled-before-send`);
          return {
            ok: false,
            sent: false,
            verified: false,
            cancelled: true,
            reason: 'cancelled-before-send',
          };
        }

        ToolboxShell.appendLog(
          `[SEND_MESSAGE_SHARED][DONE] source=${logSource} ok=${ok ? 1 : 0}`,
        );

        if (ok === true) {
          // 当发送按钮已经点击且消息进入发送流，上传流程的“忙碌态”不应继续悬挂。
          clearUploadBusyAfterMessageSent('send-message-shared-ok');
        }

        if (ok !== true) {
          const panelReason = String(lastUploadSendPanelFailReason || 'send-message-button-core-failed').trim()
            || 'send-message-button-core-failed';
          const softWaitReasons = new Set([
            'send_not_confirmed_composer_still_has_payload',
            'duplicate_prompt_text_detected',
            'waiting_payload',
            'composer_empty_wait_payload',
            'attachment_still_uploading',
            'attachment_uploading',
            'waiting_attachment_upload',
            'waiting_attachment_upload_done',
            'waiting_real_send_button',
          ]);
          const isSendNotConfirmed = panelReason.startsWith('send_not_confirmed:');
          const wait = softWaitReasons.has(panelReason) || isSendNotConfirmed;
          const retryable = panelReason === 'send_not_confirmed_composer_still_has_payload'
            || panelReason === 'waiting_payload'
            || panelReason === 'composer_empty_wait_payload'
            || panelReason === 'attachment_still_uploading'
            || panelReason === 'attachment_uploading'
            || panelReason === 'waiting_attachment_upload'
            || panelReason === 'waiting_attachment_upload_done'
            || panelReason === 'waiting_real_send_button'
            || isSendNotConfirmed;
          logSendHotkeyBlocked(panelReason, source);
          ToolboxShell.appendLog(
            `[SEND_MESSAGE_SHARED][FAILED] source=${logSource} reason=${panelReason} detail=sendCurrentMessageFromUploadPanel-returned-false`,
          );
          return {
            ok: false,
            reason: panelReason,
            wait,
            retryable,
            wait_send: wait,
            wait_reply: false,
          };
        }

        return Object.assign({}, sharedSendOutcome, {
          ok: true,
          sent: true,
          verified: true,
          reason: 'send-message-button-core',
        });
      } catch (err) {
        const errText = err && err.message ? err.message : String(err);
        console.error('[SEND_MESSAGE_SHARED][ERROR]', err);
        ToolboxShell.appendLog(
          `[SEND_MESSAGE_SHARED][ERROR] source=${logSource} error=${err && err.stack ? err.stack : errText}`,
        );
        setStatus(`发送消息失败：${errText}`, 'error');
        return {
          ok: false,
          reason: errText,
        };
      } finally {
        if (
          useSendMessageTask
          && sendMessageTaskCtx
          && sendMessageTaskState.runId === sendMessageTaskCtx.runId
        ) {
          const sendTaskAction = String(
            sendMessageTaskState.action || sendMessageTaskState.plan?.mode || 'send-message',
          ).trim();
          const keepForCompositeFlow = (
            sendTaskAction === 'send-copy-hotkey'
            || sendTaskAction === 'send-copy-hotkey-continue'
          ) && (
            isSendCopyHotkeyActive()
            || sendMessageTaskState.hasClickedNativeSend
            || sendMessageTaskState.nativeSendClicked
          );
          const keepForStopButton = keepForCompositeFlow
            || (
              sendMessageTaskState.hasClickedNativeSend
              && (
                state.waitingReply
                || getSendTaskPhase() === 'waiting_reply'
                || sendMessageTaskState.phase === SEND_MESSAGE_PHASES.SENT_WAITING_RESPONSE
                || sendMessageTaskState.phase === SEND_MESSAGE_PHASES.STOPPING_RESPONSE
              )
            );
          if (!keepForStopButton && sendMessageTaskState.phase !== SEND_MESSAGE_PHASES.CANCELLED) {
            const doneOk = !!(sharedSendOutcome && (sharedSendOutcome.ok || sharedSendOutcome.sent));
            finishSendMessageTask({
              ok: doneOk,
              reason: sharedSendOutcome && sharedSendOutcome.reason
                ? String(sharedSendOutcome.reason)
                : 'done',
            });
          }
        }
        finishUploadSendRun(flowRun, `shared-send-message-finally:${source}`);
        releaseUploadActionLock('send-message');
        scheduleRenderUpload(`shared-send-message-finally:${source}`);
      }
    }

    function getSharedComposerTextTrimmed() {
      if (
        typeof ComposerApi === 'undefined'
        || !ComposerApi
        || typeof ComposerApi.getComposerText !== 'function'
      ) {
        return '';
      }
      return String(ComposerApi.getComposerText() || '').trim();
    }

    function inspectSharedComposerPromptState(text) {
      const expectedText = String(text || '').trim();
      const existingText = getSharedComposerTextTrimmed();
      const exactMatch = !!(expectedText && existingText && existingText === expectedText);
      const duplicateLongerMatch = !!(
        expectedText
        && existingText
        && existingText.length > expectedText.length
        && existingText.includes(expectedText)
      );

      return {
        expectedText,
        existingText,
        exactMatch,
        duplicateLongerMatch,
      };
    }

    async function sendTextBySendMessageButtonCore(text, options = {}) {
      const source = String(options.source || 'shared-send-text').trim() || 'shared-send-text';
      const content = String(text || '');
      const shouldStop = typeof options.shouldStop === 'function'
        ? options.shouldStop
        : () => false;
      const allowReplaceDraft = options.allowReplaceDraft !== false;

      ToolboxShell.appendLog(
        `[SEND_MESSAGE_SHARED][TEXT_ENTER] source=${source} chars=${content.length}`,
      );

      if (blockComposerWriteIfOriginalAfterInitial(content, source)) {
        return {
          ok: false,
          reason: 'original_prompt_after_initial_blocked',
          blocked: true,
        };
      }

      if (shouldStop()) {
        return {
          ok: false,
          reason: 'cancelled',
        };
      }

      if (!content.trim()) {
        ToolboxShell.appendLog(`[SEND_MESSAGE_SHARED][TEXT_FAILED] source=${source} reason=empty-content`);
        return {
          ok: false,
          reason: 'empty-content',
        };
      }

      if (
        typeof ComposerApi === 'undefined'
        || !ComposerApi
        || typeof ComposerApi.getComposerText !== 'function'
        || typeof ComposerApi.setComposerValue !== 'function'
      ) {
        ToolboxShell.appendLog(`[SEND_MESSAGE_SHARED][TEXT_FAILED] source=${source} reason=composer-api-missing`);
        return {
          ok: false,
          reason: 'composer-api-missing',
        };
      }

      const promptState = inspectSharedComposerPromptState(content);
      const existingText = promptState.existingText;
      const cfg = typeof getCompactUiConfig === 'function'
        ? getCompactUiConfig()
        : {};

      if (promptState.exactMatch) {
        ToolboxShell.appendLog(
          `[SEND_MESSAGE_SHARED][TEXT_ALREADY_PRESENT] source=${source} chars=${existingText.length} action=send-existing`,
        );
        return sendExistingComposerBySendMessageButtonCore({
          source,
          rawSource: options.rawSource || source,
          shouldStop,
          manualSend: options.manualSend === true,
          singleShot: options.singleShot === true,
          maxStableAttempts: options.maxStableAttempts,
          timeoutMs: Number(options.timeoutMs || SEND_WAIT_TIMEOUT_MS || 120000),
          text: '',
          allowReplaceDraft: false,
          payloadVerify: options.payloadVerify || null,
        });
      }

      if (promptState.duplicateLongerMatch) {
        ToolboxShell.appendLog(
          `[SEND_MESSAGE_SHARED][DUPLICATE_TEXT_GUARD] source=${source} expectedLen=${promptState.expectedText.length} `
          + `existingLen=${existingText.length} action=block-rewrite`,
        );
        return {
          ok: false,
          reason: 'duplicate_prompt_text_detected',
          wait: true,
          retryable: false,
        };
      }

      if (existingText && existingText !== content.trim()) {
        if (!allowReplaceDraft) {
          ToolboxShell.appendLog(
            `[SEND_MESSAGE_SHARED][TEXT_FAILED] source=${source} reason=composer-has-existing-text existingChars=${existingText.length}`,
          );
          return {
            ok: false,
            reason: 'composer-has-existing-text',
          };
        }

        if (cfg.confirmPromptDraftOverwrite === true) {
          const okReplace = window.confirm(
            `ChatGPT 输入框已有 ${existingText.length} 个字符，是否覆盖并继续发送？`,
          );

          if (!okReplace) {
            ToolboxShell.appendLog(
              `[SEND_MESSAGE_SHARED][TEXT_FAILED] source=${source} reason=user-refused-overwrite existingChars=${existingText.length}`,
            );
            return {
              ok: false,
              reason: 'user-refused-overwrite',
            };
          }
        }

        ToolboxShell.appendLog(
          `[SEND_MESSAGE_SHARED][TEXT_OVERWRITE] source=${source} existingChars=${existingText.length} newChars=${content.length}`,
        );
      }

      if (shouldStop()) {
        return {
          ok: false,
          reason: 'cancelled',
        };
      }

      return sendExistingComposerBySendMessageButtonCore({
        source,
        rawSource: options.rawSource || source,
        shouldStop,
        manualSend: options.manualSend === true,
        singleShot: options.singleShot === true,
        maxStableAttempts: options.maxStableAttempts,
        timeoutMs: Number(options.timeoutMs || SEND_WAIT_TIMEOUT_MS || 120000),
        text: content,
        allowReplaceDraft,
        payloadVerify: options.payloadVerify || null,
      });
    }

    async function sendCurrentComposerMessage(options = {}) {
      const source = String(options.source || 'send-current-composer');
      const shouldStop = typeof options.shouldStop === 'function'
        ? options.shouldStop
        : () => false;

      if (shouldStop()) {
        return { ok: false, reason: 'cancelled' };
      }
      if (state && (state.cancelWaitingSend || state.messageSendCancelRequested)) {
        ToolboxShell.appendLog(
          `[COMPOSER_SEND_CURRENT][REAL_CANCEL_DETECTED] source=${source} cancelWaitingSend=${state.cancelWaitingSend ? 1 : 0} messageSendCancelRequested=${state.messageSendCancelRequested ? 1 : 0}`,
        );
        return { ok: false, reason: 'cancelled' };
      }

      resetSendCancelStateForNewRun('sendCurrentComposerMessage', { source });
      ToolboxShell.appendLog(`[COMPOSER_SEND_CURRENT][DELEGATE_TO_SEND_BUTTON_CORE] source=${source}`);

      const result = await sendExistingComposerBySendMessageButtonCore({
        source,
        shouldStop,
        timeoutMs: Number(options.timeoutMs || SEND_WAIT_TIMEOUT_MS || 120000),
      });

      ToolboxShell.appendLog(
        `[COMPOSER_SEND_CURRENT][DONE] source=${source} ok=${result && result.ok ? 1 : 0} reason=${result && result.reason ? result.reason : '-'}`,
      );

      return result;
    }

    async function runUploadVerifyLoopInitialSend(options = {}) {
      const source = String(options.source || 'upload-verify-loop-initial');
      const shouldStop = typeof options.shouldStop === 'function'
        ? options.shouldStop
        : () => false;
      const cycleIndex = Number(options.cycleIndex) || 1;

      ToolboxShell.appendLog(`[COPY_HOTKEY_UPLOAD_VERIFY_LOOP][initial-send-enter] source=${source} cycle=${cycleIndex}`);

      if (shouldStop()) {
        return {
          ok: false,
          reason: 'cancelled',
          assistantDoneSignal: false,
          copied: false,
          hotkeySent: false,
          continueSent: false,
          initialSent: false,
          assistantMessageKey: '',
        };
      }

      const payloadState = getComposerPayloadStateForInitialSend();
      const {
        composerText,
        hasAttachment,
        hasVisiblePayloadText,
      } = payloadState;

      ToolboxShell.appendLog(
        `[COPY_HOTKEY_UPLOAD_VERIFY_LOOP][initial-send-state] source=${source} textLen=${composerText.length} hasAttachment=${hasAttachment ? 1 : 0} hasVisiblePayloadText=${hasVisiblePayloadText ? 1 : 0}`,
      );

      if (!composerText && !hasAttachment && !hasVisiblePayloadText) {
        ToolboxShell.appendLog(`[COPY_HOTKEY_UPLOAD_VERIFY_LOOP][initial-send-skip] reason=no-composer-payload source=${source}`);
        return {
          ok: false,
          reason: 'no-composer-payload',
          assistantDoneSignal: false,
          copied: false,
          hotkeySent: false,
          continueSent: false,
          initialSent: false,
          assistantMessageKey: '',
        };
      }

      if (shouldStop()) {
        return {
          ok: false,
          reason: 'cancelled',
          assistantDoneSignal: false,
          copied: false,
          hotkeySent: false,
          continueSent: false,
          initialSent: false,
          assistantMessageKey: '',
        };
      }

      setCopyHotkeyUploadVerifyLoopPhase('sending_initial', source, {
        cycleIndex,
        currentSubtask: 'send-initial',
      });

      const sendResult = await sendCurrentComposerMessage({
        source,
        waitUntilSendable: true,
        timeoutMs: SEND_WAIT_TIMEOUT_MS,
        shouldStop,
      });

      if (shouldStop()) {
        return {
          ok: false,
          reason: 'cancelled',
          assistantDoneSignal: false,
          copied: false,
          hotkeySent: false,
          continueSent: false,
          initialSent: false,
          assistantMessageKey: '',
        };
      }

      if (!sendResult || !sendResult.ok) {
        const reason = sendResult && sendResult.reason ? sendResult.reason : 'initial-send-failed';
        ToolboxShell.appendLog(`[COPY_HOTKEY_UPLOAD_VERIFY_LOOP][initial-send-failed] source=${source} reason=${reason}`);
        setStatus(`闭环首轮发送失败：${reason}`, 'error');

        return {
          ok: false,
          reason,
          assistantDoneSignal: false,
          copied: false,
          hotkeySent: false,
          continueSent: false,
          initialSent: false,
          assistantMessageKey: '',
        };
      }

      ToolboxShell.appendLog(`[COPY_HOTKEY_UPLOAD_VERIFY_LOOP][initial-send-ok] source=${source} reason=${sendResult.reason || '-'}`);
      setStatus('闭环首轮消息已发送，正在等待回答完成', 'running');

      return {
        ok: true,
        reason: 'initial-send-ok',
        assistantDoneSignal: false,
        copied: false,
        hotkeySent: false,
        continueSent: false,
        initialSent: true,
        assistantMessageKey: getLastAssistantMessageKeySafe(),
      };
    }

    function repairStaleClosedLoopRunningBeforeClick(reason = 'closed-loop-click') {
      const src = String(reason || 'closed-loop-click').trim() || 'closed-loop-click';
      if (!closedLoopContinueState.running) {
        return false;
      }
      const task = ensureCopyHotkeyUploadVerifyLoopTask();
      const taskPhase = String(task && task.phase ? task.phase : 'idle').trim().toLowerCase();
      const activeTaskPhases = new Set([
        'running',
        'copying',
        'sending_hotkey',
        'sending_continue',
        'waiting_next_reply',
        'auto_uploading',
        'home_navigation',
        'paused',
        'stopping',
        'cancelling',
      ]);
      const hasTimer = !!closedLoopContinueState.timerId || !!closedLoopContinueState.retryTimerId;
      const hasBusyRuntime = !!(
        state.running
        || state.waitingReply
        || state.messageSending
        || state.pendingSendAfterReply
        || closedLoopContinueState.doneVerificationRunning
        || closedLoopContinueState.homeNavigationRunning
      );
      if (activeTaskPhases.has(taskPhase) || hasTimer || hasBusyRuntime) {
        return false;
      }
      ToolboxShell.appendLog(
        `[CLOSED_LOOP][STALE_RUNNING_REPAIR] reason=${src} `
        + `taskPhase=${taskPhase || '-'} hasTimer=${hasTimer ? 1 : 0} hasBusyRuntime=${hasBusyRuntime ? 1 : 0}`,
      );
      closedLoopContinueState.running = false;
      closedLoopContinueState.stopping = false;
      copyHotkeyUploadVerifyLoopRunning = false;
      copyHotkeyUploadVerifyLoopStopRequested = false;
      task.stopRequested = false;
      task.currentSubtask = '';
      task.lastError = null;
      setCopyHotkeyUploadVerifyLoopPhase('idle', `stale-running-repair:${src}`, {
        cycleIndex: closedLoopContinueState.round || 0,
        currentSubtask: '',
      });
      renderClosedLoopContinueButtons();
      return true;
    }

    async function handleClosedLoopContinueModeClick(mode, source = 'button') {
      let normalizedMode = CLOSED_LOOP_CONTINUE_MODES.WITH_HOTKEY;
      if (mode === CLOSED_LOOP_CONTINUE_MODES.WITHOUT_HOTKEY) {
        normalizedMode = CLOSED_LOOP_CONTINUE_MODES.WITHOUT_HOTKEY;
      } else if (mode === CLOSED_LOOP_CONTINUE_MODES.WITH_HOTKEY_EVERY_ROUND) {
        normalizedMode = CLOSED_LOOP_CONTINUE_MODES.WITH_HOTKEY_EVERY_ROUND;
      }

      repairStaleClosedLoopRunningBeforeClick(`mode-click:${normalizedMode}`);

      const useHotkey = normalizedMode !== CLOSED_LOOP_CONTINUE_MODES.WITHOUT_HOTKEY;
      ToolboxShell.appendLog(
        `[CLOSED_LOOP][MODE_EXPLAIN] mode=${normalizedMode} useHotkey=${useHotkey ? 1 : 0} sharedState=closedLoopContinueState`,
      );
      ToolboxShell.appendLog(
        `[CLOSED_LOOP][MODE_CLICK] mode=${normalizedMode} running=${closedLoopContinueState.running ? 1 : 0} activeMode=${closedLoopContinueState.mode || '-'}`,
      );
      ToolboxShell.appendLog('[COPY_HOTKEY_UPLOAD_VERIFY_LOOP][click]');

      if (closedLoopContinueState.running) {
        const currentMode = closedLoopContinueState.mode;
        if (currentMode && currentMode !== normalizedMode) {
          ToolboxShell.appendLog(
            `[CLOSED_LOOP][MODE_SWITCH_CLICK_AS_STOP] currentMode=${currentMode} clickedMode=${normalizedMode} action=stop-current-loop`,
          );
        }
        const loopTask = ensureCopyHotkeyUploadVerifyLoopTask();
        const phase = String(loopTask && loopTask.phase ? loopTask.phase : '').trim().toLowerCase();
        const sourceText = String(source || '').trim();
        const isExplicitResume = sourceText.includes('resume-by-button');
        if (
          !isExplicitResume
          && (phase === 'paused' || loopTask.currentSubtask === 'paused')
        ) {
          ToolboxShell.appendLog(
            `[CLOSED_LOOP][USER_STOP_WHILE_PAUSED] reason=button-toggle:${normalizedMode} runId=${closedLoopContinueState.runId} round=${closedLoopContinueState.round}`,
          );
          stopClosedLoopContinue(`button-stop-while-paused:${normalizedMode}`);
          return;
        }
        if (isExplicitResume && (phase === 'paused' || loopTask.currentSubtask === 'paused')) {
          const runId = closedLoopContinueState.runId;
          closedLoopContinueState.cancelRequested = false;
          closedLoopContinueState.cancelReason = '';
          ToolboxShell.appendLog(
            `[CLOSED_LOOP][RESUME_BY_BUTTON] reason=button-toggle:${normalizedMode} runId=${runId} round=${closedLoopContinueState.round}`,
          );
          loopTask.stopRequested = false;
          loopTask.lastError = null;
          loopTask.currentSubtask = 'resume';
          closedLoopContinueState.stopping = false;
          closedLoopContinueState.lastReason = `resume-by-button:${normalizedMode}`;
          setCopyHotkeyUploadVerifyLoopPhase('running', `resume-by-button:${normalizedMode}`, {
            cycleIndex: closedLoopContinueState.round,
            currentSubtask: 'resume',
          });
          setStatus('闭环继续已恢复运行', 'running');
          renderClosedLoopContinueButtons();
          scheduleClosedLoopContinueNextStep(runId, 0, `resume-by-button:${normalizedMode}`, {
            retryCurrentRound: true,
          });
          return;
        }

        ToolboxShell.appendLog(`[CLOSED_LOOP][USER_STOP_BY_BUTTON] reason=button-toggle:${normalizedMode}`);
        stopClosedLoopContinue(`button-toggle:${normalizedMode}`);
        return;
      }

      const pendingStart = getClosedLoopStartPending();
      if (pendingStart) {
        if (pendingStart.mode === normalizedMode) {
          clearClosedLoopStartPending('user-cancel-pending');
          setStatus('已取消等待启动闭环', 'info');
          return;
        }
        clearClosedLoopStartPending('switch-pending-mode');
      }

      if (isPageGeneratingForClosedLoopStart()) {
        setClosedLoopStartPending(normalizedMode, source);
        return;
      }

      await startClosedLoopContinue({
        reason: source,
        mode: normalizedMode,
      });
    }

    function resetClosedLoopStartCancelFlags(reason = 'closed-loop-start') {
      const src = String(reason || 'closed-loop-start').trim() || 'closed-loop-start';
      const oldCancelWaitingSend = !!state.cancelWaitingSend;
      const oldMessageSendCancelRequested = !!state.messageSendCancelRequested;
      const oldUploadCancelRequested = !!state.uploadCancelRequested;
      state.cancelWaitingSend = false;
      state.messageSendCancelRequested = false;
      state.uploadCancelRequested = false;
      if (state.sendTask && typeof state.sendTask === 'object' && state.sendTask.phase === 'idle') {
        state.sendTask.cancelRequested = false;
      }
      if (
        state.uploadTask
        && typeof state.uploadTask === 'object'
        && state.uploadTask.phase !== 'uploading'
        && state.uploadTask.phase !== 'cancelling'
      ) {
        state.uploadTask.cancelRequested = false;
        state.uploadTask.abortController = null;
      }
      ToolboxShell.appendLog(
        `[CLOSED_LOOP][START_CANCEL_FLAGS_RESET] reason=${src} `
        + `oldCancelWaitingSend=${oldCancelWaitingSend ? 1 : 0} `
        + `oldMessageSendCancelRequested=${oldMessageSendCancelRequested ? 1 : 0} `
        + `oldUploadCancelRequested=${oldUploadCancelRequested ? 1 : 0}`,
      );
    }

    async function startClosedLoopContinue(options = {}) {
      const reason = typeof options === 'string'
        ? options
        : String(options.reason || 'unknown');
      const src = String(reason || 'unknown').trim() || 'unknown';
      const mode = typeof options === 'object' && options.mode
        ? options.mode
        : CLOSED_LOOP_CONTINUE_MODES.WITH_HOTKEY;

      if (closedLoopContinueState.running) {
        ToolboxShell.appendLog(`[CLOSED_LOOP][START_SKIP] reason=${src} alreadyRunning=1`);
        return;
      }

      clearClosedLoopStartPending('start-immediate');

      const loopLock = claimUploadActionLock('copy-hotkey-upload-verify-loop', {
        timeoutMs: 600000,
      });
      if (!loopLock.ok) {
        ToolboxShell.appendLog(
          `[CLOSED_LOOP][START_SKIP] reason=${src} lock=${loopLock.reason || '-'}`,
        );
        return;
      }

      resetClosedLoopStartCancelFlags(`closed-loop-start:${src}`);

      closedLoopContinueState.running = true;
      closedLoopContinueState.stopping = false;
      closedLoopContinueState.cancelRequested = false;
      closedLoopContinueState.cancelReason = '';
      closedLoopContinueState.phase = 'running';
      closedLoopContinueState.runId += 1;
      closedLoopContinueState.round = 0;
      clearClosedLoopRetryTimer(`start:${src}`);
      closedLoopContinueState.retryAttempts = 0;
      closedLoopContinueState.lastReason = src;
      closedLoopContinueState.mode = mode;
      closedLoopContinueState.doneVerificationRunning = false;
      closedLoopContinueState.doneVerificationSent = false;
      closedLoopContinueState.doneVerificationRound = 0;
      closedLoopContinueState.homeNavigationRunning = false;
      closedLoopContinueState.lastHomeNavigationRound = 0;
      closedLoopContinueState.sendFailedStreak = 0;
      closedLoopContinueState.hotkeyContinueSendFailCount = 0;
      closedLoopContinueState.lastProcessedReplyKey = '';
      closedLoopContinueState.lastProcessedRound = 0;
      clearClosedLoopButtonWaitState(`start:${src}`);
      copyHotkeyUploadVerifyLoopStopRequested = false;

      const runId = closedLoopContinueState.runId;
      const loopTask = ensureCopyHotkeyUploadVerifyLoopTask();
      loopTask.stopRequested = false;
      loopTask.runId = createUploadTaskRunId('closed_loop_continue');
      loopTask.lastError = null;

      setCopyHotkeyUploadVerifyLoopPhase('running', src, { cycleIndex: 0 });
      syncToolboxRunningOwner(`closed-loop-start:${src}`);
      const modeLabel = getClosedLoopModeLabel(mode) || mode;
      const uploadPolicyText = getClosedLoopUploadPolicyText(mode);
      setStatus(`${modeLabel}已启动：第 1 轮与${uploadPolicyText}自动上传代码`, 'running');
      ToolboxShell.appendLog('[COPY_HOTKEY_UPLOAD_VERIFY_LOOP][start]');
      ToolboxShell.appendLog(`[CLOSED_LOOP][START] reason=${src} mode=${mode} runId=${runId}`);
      renderClosedLoopContinueButtons();

      try {
        await runClosedLoopContinueStep(runId);
      } catch (error) {
        const errText = formatToolboxError(error);
        console.error('[CLOSED_LOOP][START_FAILED]', error);
        ToolboxShell.appendLog(`[CLOSED_LOOP][START_FAILED] runId=${runId} error=${errText}`);
        setStatus(`闭环继续失败：${errText}`, 'error');
        if (isClosedLoopUserCancelledReason(errText)) {
          stopClosedLoopContinue(`exception:${errText}`);
        } else {
          recoverClosedLoopContinue(runId, `exception:${errText}`, {
            delayMs: 5000,
          });
        }
      }
    }

    function buildClosedLoopDoneVerificationPrompt() {
      const doneSignal = resolveDefaultDoneSignal();
      ToolboxShell.appendLog(
        `[CLOSED_LOOP][DONE_VERIFY_PROMPT_CONTRACT] mode=single-stop stopSignal=${doneSignal}`,
      );
      return [
        '请根据刚才重新上传的代码文件、当前任务要求和上一轮回复，判断闭环任务是否已经可以停止。',
        '',
        '重点：这不是让你重新回答任务，而是验证“最开始那个 Prompt 的任务目标”是否已经完整完成。',
        '',
        '只允许两种结果：',
        '',
        '1. 如果你非常确定最开始那个 Prompt 的任务目标已经完整完成，并且没有任何剩余内容、遗漏内容、未输出完的代码、未覆盖的文件、未完成的检查项或未完成的修改指令，只输出下面这一行，不能有任何其他文字：',
        doneSignal,
        '',
        '2. 如果最开始那个 Prompt 的任务目标还没有完成，或者你无法确认它已经完整完成，不要输出任何终止符号，直接继续补充尚未完成、尚未输出、尚未覆盖的内容。',
        '',
        '如果还缺少源码、日志、构建结果、测试结果、用户确认等外部材料，说明任务尚未进入可停止状态。此时不要输出终止符号，应继续说明缺少什么材料，或者继续补充当前能够完成的部分。',
        '',
        '禁止输出其他停止符、阻塞符、无更多内容符。',
        '不要重复之前已经输出过的内容。',
        '不要重新开始整个任务。',
        '不要扩展到新任务。',
      ].join('\n');
    }

    async function runClosedLoopDoneVerification(runId, round, triggerReason = 'done-signal', expectedStatus = 'done') {
      if (!isClosedLoopRunActive(runId)) {
        ToolboxShell.appendLog(`[CLOSED_LOOP][DONE_VERIFY_SKIP] reason=inactive runId=${runId} round=${round}`);
        return {
          ok: false,
          reason: 'inactive',
        };
      }

      if (closedLoopContinueState.doneVerificationRunning) {
        ToolboxShell.appendLog(`[CLOSED_LOOP][DONE_VERIFY_SKIP] reason=already-running runId=${runId} round=${round}`);
        return {
          ok: false,
          reason: 'already-running',
        };
      }

      if (closedLoopContinueState.doneVerificationSent) {
        ToolboxShell.appendLog(`[CLOSED_LOOP][DONE_VERIFY_SKIP] reason=already-sent runId=${runId} round=${round}`);
        return {
          ok: false,
          reason: 'already-sent',
        };
      }

      closedLoopContinueState.doneVerificationRunning = true;
      closedLoopContinueState.doneVerificationRound = round;
      let verifySucceeded = false;

      const shouldStop = () => !isClosedLoopRunActive(runId);

      ToolboxShell.appendLog(
        `[CLOSED_LOOP][DONE_VERIFY_START] runId=${runId} round=${round} trigger=${triggerReason} expectedStatus=${expectedStatus || '-'}`,
      );

      try {
        setCopyHotkeyUploadVerifyLoopPhase('auto_uploading', `done-verify-upload-${round}`, {
          cycleIndex: round,
          currentSubtask: 'done_verify_upload',
        });
        renderClosedLoopContinueButton();

        ToolboxShell.appendLog(
          `[CLOSED_LOOP][DONE_VERIFY_UPLOAD_START] runId=${runId} round=${round}`,
        );

        const useHotkeyForVerify = closedLoopContinueState.mode !== CLOSED_LOOP_CONTINUE_MODES.WITHOUT_HOTKEY;
        const verifyUploadSource = useHotkeyForVerify
          ? 'closed-loop-hotkey-final-verify-upload'
          : 'closed-loop-final-verify-upload';

        const uploadResult = await runStartUploadButtonCore({
          source: verifyUploadSource,
          reason: 'closed-loop-done-verification',
          parentTask: 'closedLoopDoneVerification',
          cycleIndex: round,
          shouldStop,
        });

        ToolboxShell.appendLog(
          `[CLOSED_LOOP][DONE_VERIFY_UPLOAD_DONE] runId=${runId} round=${round} ok=${uploadResult && uploadResult.ok ? 1 : 0} uploaded=${uploadResult && uploadResult.uploadedCount != null ? uploadResult.uploadedCount : '-'} failed=${uploadResult && uploadResult.failedCount != null ? uploadResult.failedCount : '-'} skipped=${uploadResult && uploadResult.skippedCount != null ? uploadResult.skippedCount : '-'} reason=${uploadResult && uploadResult.reason ? uploadResult.reason : '-'}`,
        );

        if (!uploadResult || uploadResult.ok !== true) {
          const reason = uploadResult && uploadResult.reason ? uploadResult.reason : 'unknown';
          ToolboxShell.appendLog(
            `[CLOSED_LOOP][UPLOAD_FAILED] source=${verifyUploadSource} runId=${runId} round=${round} reason=${reason}`,
          );
          setStatus(`闭环上传失败：${reason}`, 'error');
          return {
            ok: false,
            reason: `upload-failed:${reason}`,
          };
        }

        if (!isClosedLoopRunActive(runId)) {
          return {
            ok: false,
            reason: 'inactive-after-upload',
          };
        }

        setCopyHotkeyUploadVerifyLoopPhase('sending_continue', `done-verify-send-${round}`, {
          cycleIndex: round,
          currentSubtask: 'done_verify_send',
        });
        renderClosedLoopContinueButton();

        const previousKey = getLastAssistantMessageKeySafe();
        const verifyPrompt = buildClosedLoopDoneVerificationPrompt();
        const doneSignal = resolveDefaultDoneSignal();

        ToolboxShell.appendLog(
          `[CLOSED_LOOP][DONE_VERIFY_SEND_START] runId=${runId} round=${round} promptLen=${verifyPrompt.length}`,
        );

        const sendResult = await sendContinuePromptFromUnifiedPipeline(
          `closed-loop-final-verify-${round}`,
          {
            continuePrompt: verifyPrompt,
            shouldStop,
            doneSignal,
            strictDoneSignal: true,
            disableBatchTextTerminalStop: true,
            skipDoneSignalBeforeSendCheck: true,
            allowSendAfterDoneSignal: true,
            payloadVerify: {
              allowLenDelta: 20,
              allowCoreContains: true,
              requiredIncludes: [
                '判断闭环任务是否已经可以停止',
                '最开始那个 Prompt 的任务目标',
                doneSignal,
              ],
            },
          },
        );

        if (!sendResult || !sendResult.ok) {
          const reason = sendResult && sendResult.reason ? sendResult.reason : 'verify-send-failed';
          ToolboxShell.appendLog(
            `[CLOSED_LOOP][DONE_VERIFY_SEND_FAILED] runId=${runId} round=${round} reason=${reason}`,
          );
          if (reason === 'payload_dropped' || reason === 'composer_empty') {
            ToolboxShell.appendLog(
              `[CLOSED_LOOP][DONE_VERIFY_SEND_PAYLOAD_FAILED_PAUSE] runId=${runId} round=${round} reason=${reason}`,
            );
            pauseClosedLoopContinue(`done-verify-send-failed:${reason}`, {
              level: 'warn',
              message: '终止符已出现，但二次确认 Prompt 未成功发送，闭环已暂停，请手动检查输入框。',
            });
            return {
              ok: false,
              reason: `verify-send-failed-paused:${reason}`,
              terminalVerifySendFailed: true,
            };
          }
          return {
            ok: false,
            reason,
          };
        }

        closedLoopContinueState.doneVerificationSent = true;

        ToolboxShell.appendLog(
          `[CLOSED_LOOP][DONE_VERIFY_SEND_DONE] runId=${runId} round=${round}`,
        );

        beginClosedLoopReplyWait(`done-verify-wait-${round}`);
        setCopyHotkeyUploadVerifyLoopPhase('waiting_next_reply', `done-verify-wait-${round}`, {
          cycleIndex: round,
          currentSubtask: 'done_verify_wait',
        });

        const waited = await waitAssistantCycleAfterContinue(
          `closed-loop-final-verify-${round}`,
          previousKey,
          { shouldStop },
        );

        if (!waited) {
          ToolboxShell.appendLog(
            `[CLOSED_LOOP][DONE_VERIFY_WAIT_FAILED] runId=${runId} round=${round}`,
          );
          return {
            ok: false,
            reason: 'verify-wait-failed',
          };
        }

        if (!isClosedLoopRunActive(runId)) {
          return {
            ok: false,
            reason: 'inactive-after-verify-wait',
          };
        }

        const verifyStopSignal = detectCopyHotkeyLoopStopSignal(round);
        const matched = !!(verifyStopSignal && verifyStopSignal.matched);
        const verifyStatus = verifyStopSignal && verifyStopSignal.status
          ? String(verifyStopSignal.status)
          : 'continue';

        ToolboxShell.appendLog(
          `[CLOSED_LOOP][DONE_VERIFY_REPLY_CHECK] runId=${runId} round=${round} `
          + `matched=${matched ? 1 : 0} status=${verifyStatus} `
          + `expectedStatus=${expectedStatus || '-'} `
          + `reason=${verifyStopSignal && verifyStopSignal.reason ? verifyStopSignal.reason : '-'}`,
        );

        if (matched) {
          verifySucceeded = true;
          return {
            ok: true,
            reason: `verified-${verifyStatus}`,
            status: verifyStatus,
          };
        }

        return {
          ok: false,
          reason: 'verify-reply-not-terminal',
          status: verifyStatus,
        };
      } catch (error) {
        const errText = formatToolboxError(error);
        console.error('[CLOSED_LOOP][DONE_VERIFY_FAILED]', error);
        ToolboxShell.appendLog(
          `[CLOSED_LOOP][DONE_VERIFY_FAILED] runId=${runId} round=${round} error=${errText}`,
        );
        return {
          ok: false,
          reason: errText,
        };
      } finally {
        closedLoopContinueState.doneVerificationRunning = false;
        if (!verifySucceeded && closedLoopContinueState.doneVerificationSent) {
          closedLoopContinueState.doneVerificationSent = false;
          ToolboxShell.appendLog(
            `[CLOSED_LOOP][DONE_VERIFY_SENT_RESET] runId=${runId} round=${round}`,
          );
        }
      }
    }

    async function runClosedLoopSharedUpload(round, runId, options = {}) {
      const useHotkey = options.useHotkey === true;
      const scopeGroupId = getActiveUploadScopeGroupId(options);
      const scopeGroupName = getActiveGroupName ? getActiveGroupName() : '';
      const shouldStop = typeof options.shouldStop === 'function'
        ? options.shouldStop
        : () => false;

      const uploadEveryRound = options.uploadEveryRound === true
        || isClosedLoopEveryRoundUploadMode(options.mode || closedLoopContinueState.mode);
      const source = useHotkey
        ? (
          round === 1
            ? 'closed-loop-hotkey-initial-upload'
            : (uploadEveryRound ? 'closed-loop-hotkey-every-round-upload' : 'closed-loop-hotkey-every-n-upload')
        )
        : (
          round === 1
            ? 'closed-loop-initial-upload'
            : (uploadEveryRound ? 'closed-loop-every-round-upload' : 'closed-loop-every-n-upload')
        );

      if (!uploadEveryRound && typeof globalThis.__cgptShouldSkipBatchUpload === 'function' && round > 1) {
        try {
          const batchUploadSkip = globalThis.__cgptShouldSkipBatchUpload(source);
          if (batchUploadSkip && batchUploadSkip.skip === true && batchUploadSkip.reason === 'not-upload-round') {
            ToolboxShell.appendLog(
              `[CLOSED_LOOP][SHARED_UPLOAD_SKIP] runId=${runId || '-'} round=${round} reason=${batchUploadSkip.reason}`,
            );
            return {
              ok: true,
              skipped: true,
              reason: batchUploadSkip.reason,
              uploadedCount: 0,
              failedCount: 0,
              skippedCount: 0,
            };
          }
        } catch (closedLoopUploadGuardErr) {
          console.error('[CLOSED_LOOP][SHARED_UPLOAD_GUARD_FAILED]', closedLoopUploadGuardErr);
        }
      }

      ToolboxShell.appendLog(
        `[CLOSED_LOOP][SHARED_UPLOAD_ENTER] runId=${runId || '-'} round=${round} source=${source} groupId=${scopeGroupId || '-'} groupName=${scopeGroupName || '-'}`,
      );

      const result = await runStartUploadButtonCore({
        source,
        reason: round === 1
          ? 'closed-loop-initial'
          : (uploadEveryRound ? 'closed-loop-every-round' : 'closed-loop-every-n'),
        parentTask: 'closedLoopContinue',
        cycleIndex: round,
        groupId: scopeGroupId,
        shouldStop,
      });

      ToolboxShell.appendLog(
        `[CLOSED_LOOP][SHARED_UPLOAD_DONE] runId=${runId || '-'} round=${round} source=${source} groupId=${scopeGroupId || '-'} ok=${result && result.ok ? 1 : 0} reason=${result && result.reason ? result.reason : '-'}`,
      );

      return result;
    }

    function shouldUploadBeforeClosedLoopSend(round, interval = 5) {
      const n = Number(round || 0);
      if (!Number.isFinite(n) || n <= 1) {
        return false;
      }
      const completedReplyCount = n - 1;
      return completedReplyCount > 0 && completedReplyCount % interval === 0;
    }

    const closedLoopUploadDedupState = {
      runId: null,
      lastUploadRound: 0,
      lastUploadReason: '',
    };

    function shouldSkipDuplicateClosedLoopUpload(runId, round) {
      return (
        closedLoopUploadDedupState.runId === runId
        && closedLoopUploadDedupState.lastUploadRound === round
      );
    }

    function isClosedLoopSendCoreFalseNegativeReason(reason) {
      const text = String(reason || '').trim();
      if (!text) {
        return false;
      }
      return (
        text === 'send-message-button-core-failed'
        || text.includes('send-message-button-core-failed')
      );
    }

    async function confirmClosedLoopSendActuallyStartedAfterFailure(sourceText, promptText, context = {}) {
      const source = String(sourceText || 'closed-loop-confirm-after-fail').trim() || 'closed-loop-confirm-after-fail';
      const prompt = String(promptText || '').trim();
      const ctx = context && typeof context === 'object' ? context : {};
      const runId = ctx.runId != null ? ctx.runId : '-';
      const round = ctx.round != null ? ctx.round : '-';

      if (typeof ctx.shouldStop === 'function' && ctx.shouldStop()) {
        return { ok: false, reason: 'cancelled' };
      }

      const signals = [];
      let cap = null;

      try {
        cap = typeof getUploadPageCapabilityLight === 'function'
          ? getUploadPageCapabilityLight()
          : (typeof getUploadPageCapability === 'function' ? getUploadPageCapability({ heavy: false }) : null);
      } catch (err) {
        console.error('[CLOSED_LOOP][SEND_FALSE_NEGATIVE_CHECK] getUploadPageCapability failed', err);
        ToolboxShell.appendLog(
          `[CLOSED_LOOP][SEND_FALSE_NEGATIVE_CHECK][CAPABILITY_ERROR] runId=${runId} round=${round} error=${formatToolboxError(err)}`,
        );
      }

      const responseState = String(cap && cap.response_state ? cap.response_state : '').trim().toLowerCase();
      const responseReason = String(cap && cap.response_state_reason ? cap.response_state_reason : '').trim().toLowerCase();
      const isResponding = !!(cap && (cap.isResponding || cap.is_responding));
      const assistantGenerating = isResponding
        || responseState === 'generating'
        || responseState === 'responding'
        || responseState === 'waiting_reply'
        || responseState === 'answering'
        || responseReason === 'assistant_busy'
        || responseReason === 'response_in_progress';

      if (assistantGenerating) {
        signals.push('assistant-generating');
      }

      let stopButtonPresent = false;
      try {
        const stopButton = typeof document !== 'undefined'
          ? document.querySelector('[data-testid="stop-button"], button[aria-label*="停止"], button[aria-label*="Stop"]')
          : null;
        stopButtonPresent = !!(stopButton && stopButton instanceof HTMLElement);
      } catch (err) {
        console.error('[CLOSED_LOOP][SEND_FALSE_NEGATIVE_CHECK] stop button query failed', err);
        ToolboxShell.appendLog(
          `[CLOSED_LOOP][SEND_FALSE_NEGATIVE_CHECK][STOP_BTN_ERROR] runId=${runId} round=${round} error=${formatToolboxError(err)}`,
        );
      }

      if (stopButtonPresent) {
        signals.push('stop-button-present');
      }

      let composerTextLen = 0;
      try {
        composerTextLen = typeof getSharedComposerTextTrimmed === 'function'
          ? getSharedComposerTextTrimmed().length
          : (
            typeof ComposerApi !== 'undefined'
            && ComposerApi
            && typeof ComposerApi.getComposerText === 'function'
              ? String(ComposerApi.getComposerText() || '').trim().length
              : 0
          );
      } catch (err) {
        console.error('[CLOSED_LOOP][SEND_FALSE_NEGATIVE_CHECK] composer text read failed', err);
        ToolboxShell.appendLog(
          `[CLOSED_LOOP][SEND_FALSE_NEGATIVE_CHECK][COMPOSER_TEXT_ERROR] runId=${runId} round=${round} error=${formatToolboxError(err)}`,
        );
      }

      if (composerTextLen === 0) {
        signals.push('composer-cleared');
      }

      const turnCountAfter = typeof getCurrentPageTurnCountSafe === 'function'
        ? getCurrentPageTurnCountSafe()
        : null;
      const turnCountBefore = Number.isFinite(Number(ctx.turnCountBefore))
        ? Number(ctx.turnCountBefore)
        : null;
      const turnCountIncreased = turnCountBefore != null
        && turnCountAfter != null
        && Number(turnCountAfter) > Number(turnCountBefore);

      if (turnCountIncreased) {
        signals.push('turn-count-increased');
      }

      if (
        assistantGenerating
        || stopButtonPresent
        || (composerTextLen === 0 && (turnCountIncreased || assistantGenerating || stopButtonPresent))
      ) {
        ToolboxShell.appendLog(
          `[CLOSED_LOOP][SEND_FALSE_NEGATIVE_CHECK] runId=${runId} round=${round} accepted=1 reason=assistant-generating-after-send `
          + `signals=${signals.join(',') || '-'} responseState=${responseState || '-'} composerTextLen=${composerTextLen} `
          + `turnBefore=${turnCountBefore == null ? '-' : turnCountBefore} turnAfter=${turnCountAfter == null ? '-' : turnCountAfter}`,
        );
        return {
          ok: true,
          reason: 'assistant-generating-after-send',
          signals,
          responseState,
          composerTextLen,
          turnCountBefore,
          turnCountAfter,
        };
      }

      if (typeof confirmSharedMessageSubmitted === 'function') {
        try {
          const submitted = await confirmSharedMessageSubmitted(source, prompt, {
            timeoutMs: 1500,
            turnCountBefore,
            beforeTurnCount: turnCountBefore,
            beforeLatestKey: ctx.beforeLatestKey || '',
            beforeConversationId: ctx.beforeConversationId || '',
          });
          if (submitted && submitted.ok === true) {
            ToolboxShell.appendLog(
              `[CLOSED_LOOP][SEND_FALSE_NEGATIVE_CHECK] runId=${runId} round=${round} accepted=1 reason=confirm-shared-submitted `
              + `detail=${submitted.detailReason || submitted.reason || '-'}`,
            );
            return {
              ok: true,
              reason: submitted.detailReason || submitted.reason || 'message-submitted-composer-cleared',
              signals: signals.concat(['confirm-shared-submitted']),
            };
          }
        } catch (err) {
          console.error('[CLOSED_LOOP][SEND_FALSE_NEGATIVE_CHECK] confirmSharedMessageSubmitted failed', err);
          ToolboxShell.appendLog(
            `[CLOSED_LOOP][SEND_FALSE_NEGATIVE_CHECK][CONFIRM_ERROR] runId=${runId} round=${round} error=${formatToolboxError(err)}`,
          );
        }
      }

      ToolboxShell.appendLog(
        `[CLOSED_LOOP][SEND_FALSE_NEGATIVE_CHECK] runId=${runId} round=${round} accepted=0 signals=${signals.join(',') || '-'} `
        + `responseState=${responseState || '-'} composerTextLen=${composerTextLen} `
        + `turnBefore=${turnCountBefore == null ? '-' : turnCountBefore} turnAfter=${turnCountAfter == null ? '-' : turnCountAfter}`,
      );
      return {
        ok: false,
        reason: 'send-not-confirmed-after-failure',
        signals,
      };
    }

    async function runClosedLoopContinueStep(runId, options = {}) {
      if (shouldStopClosedLoopRun(runId)) {
        ToolboxShell.appendLog(
          `[CLOSED_LOOP][ABORT_BY_STOP] runId=${runId} currentRunId=${closedLoopContinueState.runId || '-'} reason=${closedLoopContinueState.cancelReason || '-'} stage=before-step`,
        );
        return;
      }
      if (!isClosedLoopRunActive(runId)) {
        ToolboxShell.appendLog(
          `[CLOSED_LOOP][STEP_ABORT] reason=inactive-before-step runId=${runId}`,
        );
        return;
      }
      if (!closedLoopContinueState.running || closedLoopContinueState.runId !== runId) {
        ToolboxShell.appendLog(
          [
            '[CLOSED_LOOP][STEP_SKIP_RUNID_MISMATCH]',
            `runId=${runId || '-'}`,
            `currentRunId=${closedLoopContinueState.runId || '-'}`,
            `running=${closedLoopContinueState.running ? 1 : 0}`,
            `source=${options.source || '-'}`,
          ].join(' '),
        );
        return;
      }
      if (closedLoopContinueState.currentStepRunning) {
        ToolboxShell.appendLog(
          [
            '[CLOSED_LOOP][STEP_REENTRY_BLOCKED]',
            `runId=${runId}`,
            `phase=${closedLoopContinueState.phase || '-'}`,
            `token=${closedLoopContinueState.currentStepToken || '-'}`,
            `source=${options.source || '-'}`,
          ].join(' '),
        );
        return;
      }
      const stepToken = `${runId}:${Date.now()}:${Math.random().toString(36).slice(2)}`;
      closedLoopContinueState.currentStepRunning = true;
      closedLoopContinueState.currentStepToken = stepToken;
      ToolboxShell.appendLog(
        [
          '[CLOSED_LOOP][STEP_ENTER]',
          `runId=${runId}`,
          `token=${stepToken}`,
          `phase=${closedLoopContinueState.phase || '-'}`,
          `source=${options.source || '-'}`,
        ].join(' '),
      );

      if (closedLoopContinueState.waitKind === 'reply') {
        endClosedLoopReplyWait('step-active');
      } else if (closedLoopContinueState.waitKind !== 'next-step') {
        clearClosedLoopButtonWaitState('step-active');
      }
      renderClosedLoopContinueButtons();

      try {
      const retryCurrentRound = options && options.retryCurrentRound === true;
      closedLoopContinueState.retryingCurrentRound = retryCurrentRound;
      let round = 0;

      if (retryCurrentRound && closedLoopContinueState.round > 0) {
        round = closedLoopContinueState.round;
        ToolboxShell.appendLog(
          `[CLOSED_LOOP][STEP_RETRY_CURRENT_ROUND] runId=${runId} round=${round} reason=${options.retryReason || '-'}`,
        );
      } else {
        round = closedLoopContinueState.round + 1;
        closedLoopContinueState.retryAttempts = 0;
      }
      syncClosedLoopRound(round, retryCurrentRound ? 'retry-current-round' : 'step-advance');
      setClosedLoopPhase(CLOSED_LOOP_PHASES.SENDING, {
        reason: `round-${round}-send-start`,
      });

      ToolboxShell.appendLog(`[COPY_HOTKEY_UPLOAD_VERIFY_LOOP][cycle-start] round=${round}`);
      ToolboxShell.appendLog(
        `[CLOSED_LOOP][ROUND_SEND_START] runId=${runId} round=${round} source=${options.source || '-'}`,
      );
      ToolboxShell.appendLog(`[CLOSED_LOOP][STEP_START] runId=${runId} round=${round}`);

      const closedLoopCfg = getClosedLoopAutomationConfig();
      const closedLoopHomeSource = getClosedLoopContinueActionDef(
        closedLoopContinueState.mode || CLOSED_LOOP_CONTINUE_MODES.WITH_HOTKEY,
      ).action;

      const skipHomeNavigation = options && options.skipHomeNavigation === true;
      const homeCheck = shouldRunUnifiedContinueHomeNavigation(
        round,
        closedLoopHomeSource,
      );
      if (
        homeCheck.ok
        && !skipHomeNavigation
        && !retryCurrentRound
      ) {
        if (closedLoopContinueState.lastHomeNavigationRound === round) {
          ToolboxShell.appendLog(
            `[CLOSED_LOOP][HOME_NAV_SKIP] reason=already-ran-this-round runId=${runId} round=${round}`,
          );
        } else if (closedLoopContinueState.homeNavigationRunning) {
          ToolboxShell.appendLog(
            `[CLOSED_LOOP][HOME_NAV_SKIP] reason=home-navigation-running runId=${runId} round=${round}`,
          );
        } else {
          closedLoopContinueState.lastHomeNavigationRound = round;
          closedLoopContinueState.homeNavigationRunning = true;
          const homeResult = await runUnifiedContinueHomeNavigation(
            closedLoopHomeSource,
            round,
            'interval',
          );
          closedLoopContinueState.homeNavigationRunning = false;
          if (!homeResult || homeResult.ok !== true) {
            ToolboxShell.appendLog(
              `[CLOSED_LOOP][HOME_NAV_FAILED] runId=${runId} round=${round} reason=${homeResult && homeResult.reason ? homeResult.reason : 'unknown'}`,
            );
            pauseClosedLoopContinue('home-navigation-failed', {
              level: 'warn',
              message: `闭环第 ${round} 轮回首页失败，准备自动重试`,
            });
            scheduleClosedLoopRetry(runId, 'home-navigation-failed', {
              delayMs: 5000,
              retryCurrentRound: true,
              skipHomeNavigation: true,
              forceRetry: true,
            });
            return;
          }
          ToolboxShell.appendLog(
            `[CLOSED_LOOP][HOME_NAV_OK] runId=${runId} round=${round} next=retry-current-round`,
          );
          scheduleClosedLoopRetry(runId, 'home-navigation-ok', {
            delayMs: 1500,
            retryCurrentRound: true,
            skipHomeNavigation: true,
            forceRetry: true,
          });
          return;
        }
      }

      const shouldStop = () => !isClosedLoopRunActive(runId);
      const composerPayload = getComposerPayloadStateForInitialSend();
      const closedLoopMode = closedLoopContinueState.mode || CLOSED_LOOP_CONTINUE_MODES.WITH_HOTKEY;
      const useHotkey = closedLoopMode !== CLOSED_LOOP_CONTINUE_MODES.WITHOUT_HOTKEY;
      const stepSourceTag = getClosedLoopStepSourceTag(closedLoopMode, round);
      const activeUploadGroupId = getActiveUploadScopeGroupId();
      const activeGroupHasUploadableFiles = hasActiveScopeUploadableFiles({
        groupId: activeUploadGroupId,
      });

      const safeInterval = getClosedLoopEffectiveUploadInterval(closedLoopContinueState.mode, closedLoopCfg);
      const policyReason = safeInterval <= 1 ? 'every-round' : `after-${safeInterval}-replies`;

      let needUpload = false;
      if (round === 1) {
        if (activeGroupHasUploadableFiles) {
          needUpload = true;
          ToolboxShell.appendLog(
            `[COPY_HOTKEY_UPLOAD_VERIFY_LOOP][initial-upload] round=${round} reason=active-group-has-files groupId=${activeUploadGroupId || '-'}`,
          );
        } else if (!composerPayload.hasAttachment && hasPendingUploadQueueItems({ groupId: activeUploadGroupId })) {
          needUpload = true;
          ToolboxShell.appendLog(
            `[COPY_HOTKEY_UPLOAD_VERIFY_LOOP][initial-upload] round=${round} reason=no-composer-attachment-active-group-pending groupId=${activeUploadGroupId || '-'}`,
          );
        }
      } else {
        const enabled = closedLoopCfg.autoUploadEnabled === true;
        const completedReplyCount = Math.max(0, Number(round || 0) - 1);
        const shouldUpload = enabled && shouldUploadBeforeClosedLoopSend(round, safeInterval);
        ToolboxShell.appendLog(
          `[CLOSED_LOOP][UPLOAD_POLICY_CHECK] runId=${runId} round=${round} completedReplyCount=${completedReplyCount} `
          + `shouldUpload=${shouldUpload ? 1 : 0} interval=${safeInterval} reason=${shouldUpload ? policyReason : 'not-due'}`,
        );
        if (shouldUpload) {
          needUpload = true;
        }
      }

      if (needUpload) {
        if (shouldSkipDuplicateClosedLoopUpload(runId, round)) {
          ToolboxShell.appendLog(
            `[CLOSED_LOOP][UPLOAD_SKIP_DUPLICATE] runId=${runId} round=${round} reason=same-round-already-uploaded note=this-is-retry-not-new-round`,
          );
        } else if (round > 1) {
          ToolboxShell.appendLog(
            `[CLOSED_LOOP][UPLOAD_POLICY_HIT] runId=${runId} round=${round} interval=${safeInterval} reason=${policyReason}`,
          );
        }

        if (!shouldSkipDuplicateClosedLoopUpload(runId, round)) {
          ToolboxShell.appendLog(`[CLOSED_LOOP][UPLOAD_BEFORE_STEP] runId=${runId} round=${round}`);

          setCopyHotkeyUploadVerifyLoopPhase('auto_uploading', `round-${round}-upload`, {
            cycleIndex: round,
            currentSubtask: 'auto_upload',
          });
          renderClosedLoopContinueButton();

          const uploadResult = await runClosedLoopSharedUpload(round, runId, {
            useHotkey,
            shouldStop,
            groupId: activeUploadGroupId,
            mode: closedLoopContinueState.mode,
            uploadEveryRound: isClosedLoopEveryRoundUploadMode(closedLoopContinueState.mode),
          });

          if (!uploadResult || uploadResult.ok !== true) {
            const reason = uploadResult && uploadResult.reason ? uploadResult.reason : 'unknown';
            const uploadSharedSource = getClosedLoopUploadFailedSource(useHotkey, round, closedLoopMode);
            ToolboxShell.appendLog(
              `[CLOSED_LOOP][UPLOAD_FAILED] source=${uploadSharedSource} runId=${runId} round=${round} reason=${reason}`,
            );
            if (isClosedLoopUserCancelledReason(reason)) {
              stopClosedLoopContinue(`upload-failed:${reason}`);
            } else {
              setStatus(`闭环上传失败，准备恢复：${reason}`, 'error');
              recoverClosedLoopContinue(runId, `upload-failed:${reason}`, {
                delayMs: 5000,
              });
            }
            return;
          }

          if (!isClosedLoopRunActive(runId)) {
            ToolboxShell.appendLog(
              `[CLOSED_LOOP][STEP_ABORT] reason=inactive-after-upload runId=${runId}`,
            );
            return;
          }

          setCopyHotkeyUploadVerifyLoopPhase('running', `round-${round}-upload-done`, {
            cycleIndex: round,
          });
          renderClosedLoopContinueButton();

          closedLoopUploadDedupState.runId = runId;
          closedLoopUploadDedupState.lastUploadRound = round;
          closedLoopUploadDedupState.lastUploadReason = round === 1
            ? 'closed-loop-initial'
            : (isClosedLoopEveryRoundUploadMode(closedLoopContinueState.mode) ? 'closed-loop-every-round' : 'closed-loop-every-n');
        }
      }

      const previousKeyBeforeStep = getLastAssistantMessageKeySafe();
      const turnCountBeforeStep = typeof getCurrentPageTurnCountSafe === 'function'
        ? getCurrentPageTurnCountSafe()
        : null;
      const conversationIdBeforeStep = typeof getCurrentPageConversationIdSafe === 'function'
        ? getCurrentPageConversationIdSafe()
        : '';
      const closedLoopFlowOptions = {
        isolated: true,
        shouldStop,
        doneSignal: resolveDefaultDoneSignal(),
        strictDoneSignal: true,
        disableBatchTextTerminalStop: true,
        useHotkey,
        sourceMode: closedLoopContinueState.mode,
      };

      let result = null;

      if (!guardClosedLoopBeforeSend(runId, round, stepSourceTag)) {
        return;
      }

      if (round === 1) {
        result = await runUploadVerifyLoopInitialSend({
          source: `upload-verify-loop-initial-${round}`,
          shouldStop,
          cycleIndex: round,
        });

        if (!isClosedLoopRunActive(runId)) {
          ToolboxShell.appendLog(
            `[CLOSED_LOOP][STEP_ABORT] reason=inactive-after-initial-send runId=${runId}`,
          );
          return;
        }

        if (result && result.reason === 'no-composer-payload') {
          ToolboxShell.appendLog(
            `[COPY_HOTKEY_UPLOAD_VERIFY_LOOP][initial-send-fallback] reason=no-composer-payload action=copy-continue`,
          );
          setCopyHotkeyUploadVerifyLoopPhase('copying', `round-${round}-copy-fallback`, {
            cycleIndex: round,
            currentSubtask: useHotkey ? 'copy_hotkey_continue' : 'copy_continue',
          });
          result = await runClosedLoopContinueOnce(stepSourceTag, closedLoopFlowOptions);
        }
      } else {
        setCopyHotkeyUploadVerifyLoopPhase('copying', `round-${round}-copy`, {
          cycleIndex: round,
          currentSubtask: useHotkey ? 'copy_hotkey_continue' : 'copy_continue',
        });
        if (useHotkey) {
          const sourceText = stepSourceTag;
          const context = buildCopyHotkeyContinueContext(sourceText, closedLoopFlowOptions);
          const copyStage = await copyLastAssistantReplyForContinue(
            sourceText,
            closedLoopFlowOptions,
            context,
          );
          if (!copyStage || copyStage.ok === false) {
            result = copyStage || {
              ok: false,
              reason: 'copy-failed',
              source: sourceText,
              loopMode: true,
              copied: false,
              hotkeySent: false,
              continueSent: false,
              assistantMessageKey: '',
            };
          } else if (copyStage.assistantDoneSignal === true || copyStage.assistantBatchTerminalStop === true) {
            result = copyStage;
          } else {
            const hotkeyStage = await triggerContinueHotkeyForContinue(
              sourceText,
              closedLoopFlowOptions,
              context,
              copyStage,
            );
            if (!hotkeyStage || hotkeyStage.ok === false) {
              result = {
                ok: false,
                reason: hotkeyStage && hotkeyStage.reason ? hotkeyStage.reason : 'hotkey-failed',
                detail: hotkeyStage && hotkeyStage.detail ? hotkeyStage.detail : '',
                source: sourceText,
                loopMode: true,
                copied: true,
                hotkeySent: false,
                continueSent: false,
                assistantMessageKey: copyStage.assistantMessageKey || '',
              };
            } else {
              await focusComposerForClosedLoop(sourceText);
              // 聚焦后短暂停顿；附件稳定由 sendClosedLoopContinuePrompt → runSharedComposerSendFlow 等待。
              await sleep(300);
              const continuePromptText = getCopyHotkeyContinuePromptText({
                ...closedLoopFlowOptions,
                logContinuePrompt: false,
              });
              appendClosedLoopTrace('CONTINUE_PAYLOAD_PREPARED', {
                runId,
                round,
                source: sourceText,
                expectedLen: continuePromptText.length,
              });
              ToolboxShell.appendLog(
                `[CLOSED_LOOP][HOTKEY_THEN_DIRECT_CONTINUE] runId=${runId} round=${round} source=${sourceText} promptLen=${continuePromptText.length}`,
              );
              ToolboxShell.appendLog(
                `[CLOSED_LOOP][WAIT_ATTACHMENT_BEFORE_CONTINUE_SEND] runId=${runId} round=${round} source=${sourceText} uploadEveryRound=${isClosedLoopEveryRoundUploadMode(closedLoopContinueState.mode) ? 1 : 0}`,
              );
              let sendResult = await sendClosedLoopContinuePrompt(continuePromptText, {
                ...closedLoopFlowOptions,
                source: sourceText,
                shouldStop,
              });
              if (!sendResult || sendResult.ok !== true) {
                const failReason = sendResult && sendResult.reason
                  ? sendResult.reason
                  : 'continue-send-failed';
                if (isHotkeyContinueDirectSendRetryReason(failReason)) {
                  ToolboxShell.appendLog(
                    `[CLOSED_LOOP][HOTKEY_CONTINUE_FALLBACK_DIRECT] runId=${runId} round=${round} reason=${failReason}`,
                  );
                  resetClosedLoopOwnWaitingSendState(sourceText);
                  await focusComposerForClosedLoop(`${sourceText}:retry-after-${failReason}`);
                  await sleep(300);
                  ToolboxShell.appendLog(
                    `[CLOSED_LOOP][WAIT_ATTACHMENT_BEFORE_CONTINUE_SEND] runId=${runId} round=${round} source=${sourceText}:retry-direct uploadEveryRound=${isClosedLoopEveryRoundUploadMode(closedLoopContinueState.mode) ? 1 : 0}`,
                  );
                  sendResult = await sendClosedLoopContinuePrompt(continuePromptText, {
                    ...closedLoopFlowOptions,
                    source: `${sourceText}:retry-direct`,
                    shouldStop,
                  });
                }
              }
              appendClosedLoopTrace(sendResult && sendResult.ok ? 'CONTINUE_SENT' : 'SEND_FAILED', {
                runId,
                round,
                source: sourceText,
                expectedLen: continuePromptText.length,
                decision: sendResult && sendResult.ok ? 'sent' : 'failed',
                reason: sendResult && sendResult.reason
                  ? sendResult.reason
                  : (sendResult && sendResult.ok ? 'ok' : 'send-failed'),
              });
              result = {
                ok: !!(sendResult && sendResult.ok),
                reason: sendResult && sendResult.ok
                  ? (sendResult.reason || 'hotkey-direct-continue-sent')
                  : (sendResult && sendResult.reason ? sendResult.reason : 'continue-send-failed'),
                assistantDoneSignal: false,
                assistantBatchTerminalStop: false,
                source: sourceText,
                loopMode: true,
                copied: true,
                hotkeySent: true,
                continueSent: !!(sendResult && sendResult.ok),
                assistantMessageKey: copyStage.assistantMessageKey || '',
                copied_text: copyStage.waitCopyResult && copyStage.waitCopyResult.text
                  ? String(copyStage.waitCopyResult.text)
                  : '',
              };
            }
          }
        } else {
          const continuePromptText = getCopyHotkeyContinuePromptText({
            ...closedLoopFlowOptions,
            logContinuePrompt: false,
          });
          appendClosedLoopTrace('CONTINUE_PAYLOAD_PREPARED', {
            runId,
            round,
            source: stepSourceTag,
            expectedLen: continuePromptText.length,
          });
          appendClosedLoopSimple('LAST_REPLY_CHECK', {
            round,
            matchedDone: false,
          });
          appendClosedLoopSimple('CONTINUE_PREPARE', {
            round,
            promptLen: continuePromptText.length,
          });

          ToolboxShell.appendLog(
            `[CLOSED_LOOP][AFTER_UPLOAD_BEFORE_CONTINUE_SEND] runId=${runId} round=${round} source=${stepSourceTag}`,
          );
          ToolboxShell.appendLog(
            `[CLOSED_LOOP][WAIT_ATTACHMENT_BEFORE_CONTINUE_SEND] runId=${runId} round=${round} source=${stepSourceTag} uploadEveryRound=${isClosedLoopEveryRoundUploadMode(closedLoopContinueState.mode) ? 1 : 0}`,
          );

          const sendResult = await sendClosedLoopContinuePrompt(continuePromptText, {
            ...closedLoopFlowOptions,
            source: stepSourceTag,
            shouldStop,
          });
          appendClosedLoopTrace(sendResult && sendResult.ok ? 'CONTINUE_SENT' : 'SEND_FAILED', {
            runId,
            round,
            source: stepSourceTag,
            expectedLen: continuePromptText.length,
            decision: sendResult && sendResult.ok ? 'sent' : 'failed',
            reason: sendResult && sendResult.reason ? sendResult.reason : (sendResult && sendResult.ok ? 'ok' : 'send-failed'),
          });
          result = sendResult && typeof sendResult === 'object'
            ? {
              ok: !!sendResult.ok,
              reason: sendResult.ok ? (sendResult.reason || 'closed-loop-continue-sent') : (sendResult.reason || 'continue-send-failed'),
              assistantDoneSignal: false,
              assistantBatchTerminalStop: false,
              source: stepSourceTag,
              loopMode: true,
              copied: false,
              hotkeySent: false,
              continueSent: !!sendResult.ok,
              assistantMessageKey: '',
            }
            : {
              ok: false,
              reason: 'continue-send-failed',
              assistantDoneSignal: false,
              assistantBatchTerminalStop: false,
              source: stepSourceTag,
              loopMode: true,
              copied: false,
              hotkeySent: false,
              continueSent: false,
              assistantMessageKey: '',
            };
        }
      }

      if (!isClosedLoopRunActive(runId)) {
        ToolboxShell.appendLog(
          `[CLOSED_LOOP][STEP_ABORT] reason=inactive-after-continue runId=${runId}`,
        );
        return;
      }

      const isInitialSendRound = !!(result && result.initialSent === true);

      const terminalBeforeSend = !!(
        !isInitialSendRound
        && result
        && (
          result.assistantDoneSignal === true
          || result.assistantBatchTerminalStop === true
          || result.reason === 'task-done-signal'
          || result.reason === 'assistant-done-signal'
          || result.reason === 'assistant-done-signal-before-send'
          || result.reason === 'task-done-signal-before-send'
          || String(result.reason || '').startsWith('batch-reply-')
        )
      );

      if (terminalBeforeSend) {
        const terminalStatus = String(
          result.batchReplyClassifyStatus
          || (result.assistantDoneSignal === true ? 'done' : 'blocked'),
        );

        ToolboxShell.appendLog(
          `[CLOSED_LOOP][STEP_TERMINAL_SIGNAL] source=before-send-check runId=${runId} round=${round} status=${terminalStatus} reason=${result.reason || 'assistant-terminal-signal'}`,
        );
        ToolboxShell.appendLog(
          `[COPY_HOTKEY_UPLOAD_VERIFY_LOOP][terminal-signal] round=${round} status=${terminalStatus} reason=${result.reason || 'assistant-terminal-signal'}`,
        );

        const verifyResult = await runClosedLoopDoneVerification(
          runId,
          round,
          result.reason || 'assistant-terminal-signal',
          terminalStatus,
        );

        if (verifyResult && verifyResult.ok) {
          const finalStatus = verifyResult.status || terminalStatus || 'done';
          finishClosedLoopContinue(`assistant-terminal-signal-verified:${finalStatus}`, {
            finalStatus: 'completed',
          });
          setStatus(
            buildClosedLoopTerminalStopMessage(finalStatus, round),
            getClosedLoopTerminalStopStatusLevel(finalStatus),
          );
          return;
        }
        if (verifyResult && verifyResult.terminalVerifySendFailed) {
          ToolboxShell.appendLog(
            `[CLOSED_LOOP][TERMINAL_VERIFY_SEND_PAYLOAD_FAILED_PAUSE] source=before-send-check runId=${runId} round=${round} reason=${verifyResult.reason || '-'}`,
          );
          return;
        }
        const verifyFailReason = `terminal-verification-failed:${verifyResult && verifyResult.reason ? verifyResult.reason : 'unknown'}`;
        ToolboxShell.appendLog(
          `[CLOSED_LOOP][TERMINAL_VERIFY_FAILED_CONTINUE] source=before-send-check runId=${runId} round=${round} reason=${verifyResult && verifyResult.reason ? verifyResult.reason : 'unknown'}`,
        );
        setStatus('终止信号二次确认失败，闭环继续下一轮', 'warn');
        recoverClosedLoopContinue(runId, verifyFailReason, {
          delayMs: 5000,
        });
        return;
      }

      if (!result || result.ok === false) {
        const failReason = result && result.reason ? result.reason : 'once-failed';

        if (failReason === 'cancelled') {
          stopClosedLoopContinue('button-toggle');
          return;
        }

        if (isClosedLoopSendCoreFalseNegativeReason(failReason)) {
          const confirmAfterFail = await confirmClosedLoopSendActuallyStartedAfterFailure(
            stepSourceTag,
            getCopyHotkeyContinuePromptText(closedLoopFlowOptions),
            {
              runId,
              round,
              shouldStop,
              turnCountBefore: turnCountBeforeStep,
              beforeLatestKey: previousKeyBeforeStep,
              beforeConversationId: conversationIdBeforeStep,
            },
          );
          if (confirmAfterFail && confirmAfterFail.ok === true) {
            ToolboxShell.appendLog(
              `[CLOSED_LOOP][STEP_SEND_TEMP_FAILED] reason=${failReason} runId=${runId} round=${round}`,
            );
            ToolboxShell.appendLog(
              `[CLOSED_LOOP][SEND_FALSE_NEGATIVE_ACCEPTED] runId=${runId} round=${round} reason=${confirmAfterFail.reason || '-'}`,
            );
            result = {
              ok: true,
              reason: 'send-false-negative-accepted',
              assistantDoneSignal: false,
              assistantBatchTerminalStop: false,
              source: stepSourceTag,
              loopMode: true,
              copied: !!(result && result.copied),
              hotkeySent: !!(result && result.hotkeySent),
              continueSent: true,
              assistantMessageKey: result && result.assistantMessageKey ? result.assistantMessageKey : '',
              copied_text: result && result.copied_text ? result.copied_text : '',
            };
          }
        }

        if (result && result.ok === true) {
          ToolboxShell.appendLog(
            `[CLOSED_LOOP][STEP_SEND_RECOVERED] runId=${runId} round=${round} reason=send-false-negative-accepted`,
          );
        } else {
          ToolboxShell.appendLog(
            `[CLOSED_LOOP][STEP_PAUSED] reason=${failReason} runId=${runId} round=${round}`,
          );
        if (
          useHotkey
          && (
            isHotkeyContinueDirectSendRetryReason(failReason)
            || failReason === 'hotkey-failed'
            || failReason === 'copy-failed'
          )
        ) {
          closedLoopContinueState.hotkeyContinueSendFailCount += 1;
          const failCount = closedLoopContinueState.hotkeyContinueSendFailCount;
          const failDetail = result && result.detail ? String(result.detail) : '';
          ToolboxShell.appendLog(
            `[CLOSED_LOOP][HOTKEY_CONTINUE_SEND_FAIL] runId=${runId} round=${round} count=${failCount} reason=${failReason} detail=${failDetail || '-'}`,
          );
          if (failCount === 1) {
            const recoverReason = `hotkey-continue-send-failed:${failReason}`;
            setStatus(
              `闭环第 ${round} 轮继续发送失败（${failCount}/3），准备重试：${failReason}`,
              'warn',
            );
            recoverClosedLoopContinue(runId, recoverReason, {
              delayMs: 3000,
              retryCurrentRound: true,
            });
            return;
          }
          if (failCount >= 2) {
            ToolboxShell.appendLog(
              `[CLOSED_LOOP][HOTKEY_CONTINUE_PAUSE_AFTER_RETRY_LIMIT] runId=${runId} round=${round} reason=${failReason}`,
            );
            const pauseMsg = '继续发送失败，已暂停，请手动检查输入框或点击重新发送继续指令。';
            pauseClosedLoopContinue(`hotkey-continue-pause:${failReason}`, {
              level: 'warn',
              message: pauseMsg,
            });
            setStatus(pauseMsg, 'warn');
            renderClosedLoopContinueButtons();
            return;
          }
        }

        if (shouldClosedLoopPauseAfterSendFailed(failReason)) {
          const msg = '继续发送失败，已暂停，请手动检查输入框或点击重新发送继续指令。';
          ToolboxShell.appendLog(
            `[CLOSED_LOOP][PAUSE_AFTER_SEND_FAILED] runId=${runId} round=${round} reason=${failReason}`,
          );
          appendClosedLoopSimple('SEND_FAILED', { round, reason: failReason });
          pauseClosedLoopContinue(`paused-after-send-failed:${failReason}`, {
            level: 'warn',
            message: msg,
          });
          setStatus(msg, 'warn');
          renderClosedLoopContinueButtons();
          return;
        }

        if (isClosedLoopFatalSendPayloadInvalidReason(failReason)) {
          const msg = '继续指令发送失败：输入框内容校验失败，已暂停，禁止空转';
          ToolboxShell.appendLog(
            `[CLOSED_LOOP][FATAL_SEND_PAYLOAD_INVALID] runId=${runId} round=${round} reason=${failReason}`,
          );
          appendClosedLoopTrace('RECOVER_DECIDE', {
            runId,
            round,
            source: stepSourceTag,
            decision: 'fatal-pause',
            reason: failReason,
          });
          pauseClosedLoopContinue(`failed-paused:${failReason}`, {
            level: 'warn',
            message: msg,
          });
          setStatus(msg, 'warn');
          renderClosedLoopContinueButtons();
          return;
        }

        const recoverReason = `cycle-failed:${failReason}`;
        appendClosedLoopTrace('RECOVER_DECIDE', {
          runId,
          round,
          source: stepSourceTag,
          decision: 'recover-schedule',
          reason: recoverReason,
        });
        setStatus(`闭环第 ${round} 轮暂时失败，准备恢复：${failReason}`, 'warn');
        recoverClosedLoopContinue(runId, recoverReason, {
          delayMs: 3000,
        });
        return;
        }
      }

      closedLoopContinueState.retryingCurrentRound = false;
      closedLoopContinueState.hotkeyContinueSendFailCount = 0;
      closedLoopContinueState.sendFailedStreak = 0;
      closedLoopContinueState.lastSentAtMs = Date.now();
      closedLoopContinueState.lastSendRound = round;

      setCopyHotkeyUploadVerifyLoopPhase('waiting_next_reply', `round-${round}-wait`, {
        cycleIndex: round,
        currentSubtask: 'wait-next-reply',
      });
      setClosedLoopPhase(CLOSED_LOOP_PHASES.WAITING_REPLY, {
        reason: `round-${round}-sent`,
      });
      ToolboxShell.appendLog(
        `[CLOSED_LOOP][ROUND_SENT_WAIT_REPLY] runId=${runId} round=${round}`,
      );
      setStatus(`第 ${round} 轮已发送，正在等待回复完成`, 'running', {
        persist: true,
        shortText: '等回复',
      });

      const stableResult = await waitClosedLoopReplyDoneStable(runId, round, {
        requiredStableCount: closedLoopContinueState.replyDoneRequiredStableCount || 3,
        pollMs: 1500,
        timeoutMs: 30 * 60 * 1000,
      });

      if (!isClosedLoopRunActive(runId)) {
        ToolboxShell.appendLog(
          `[CLOSED_LOOP][STEP_ABORT] reason=inactive-after-wait runId=${runId}`,
        );
        return;
      }

      if (!stableResult.ok) {
        ToolboxShell.appendLog(
          `[CLOSED_LOOP][ROUND_WAIT_REPLY_NOT_OK] runId=${runId} round=${round} reason=${stableResult.reason} stableCount=${stableResult.stableCount || 0}`,
        );
        if (closedLoopContinueState.running && closedLoopContinueState.runId === runId) {
          recoverClosedLoopContinue(runId, `wait-reply-${stableResult.reason}`, {
            delayMs: 5000,
          });
        }
        return;
      }

      endClosedLoopReplyWait(`round-${round}-reply-done`);

      const stopSignalResult = detectCopyHotkeyLoopStopSignal(round);
      const terminalStop = !!(stopSignalResult && stopSignalResult.matched);
      ToolboxShell.appendLog(
        `[CLOSED_LOOP][TERMINAL_STOP_CHECK] runId=${runId} round=${round} stop=${terminalStop ? 1 : 0} `
        + `reason=${stopSignalResult && stopSignalResult.reason ? stopSignalResult.reason : '-'}`,
      );

      if (terminalStop) {
        const terminalStatus = stopSignalResult.status || 'done';
        ToolboxShell.appendLog(
          `[CLOSED_LOOP][STOP_BY_TERMINAL] runId=${runId} round=${round} status=${terminalStatus} reason=${stopSignalResult.reason || 'terminal-signal'}`,
        );
        ToolboxShell.appendLog(
          `[CLOSED_LOOP][STEP_TERMINAL_SIGNAL] source=after-wait-check runId=${runId} round=${round} status=${terminalStatus} reason=${stopSignalResult.reason || 'terminal-signal'}`,
        );
        const verifyResult = await runClosedLoopDoneVerification(
          runId,
          round,
          stopSignalResult.reason || 'terminal-signal',
          terminalStatus,
        );
        if (verifyResult && verifyResult.ok) {
          const finalStatus = verifyResult.status || terminalStatus || 'done';
          finishClosedLoopContinue(`assistant-terminal-signal-verified:${finalStatus}`, {
            finalStatus: 'completed',
          });
          setStatus(
            buildClosedLoopTerminalStopMessage(finalStatus, round),
            getClosedLoopTerminalStopStatusLevel(finalStatus),
          );
          return;
        }
        if (verifyResult && verifyResult.terminalVerifySendFailed) {
          ToolboxShell.appendLog(
            `[CLOSED_LOOP][TERMINAL_VERIFY_SEND_PAYLOAD_FAILED_PAUSE] source=after-wait-check runId=${runId} round=${round} reason=${verifyResult.reason || '-'}`,
          );
          return;
        }
        const verifyFailReasonAfterWait = `terminal-verification-failed:${verifyResult && verifyResult.reason ? verifyResult.reason : 'unknown'}`;
        ToolboxShell.appendLog(
          `[CLOSED_LOOP][TERMINAL_VERIFY_FAILED_CONTINUE] source=after-wait-check runId=${runId} round=${round} reason=${verifyResult && verifyResult.reason ? verifyResult.reason : 'unknown'}`,
        );
        setStatus('终止信号二次确认失败，闭环继续下一轮', 'warn');
        recoverClosedLoopContinue(runId, verifyFailReasonAfterWait, {
          delayMs: 5000,
        });
        return;
      }

      if (!isClosedLoopRunActive(runId)) {
        ToolboxShell.appendLog(
          `[CLOSED_LOOP][STEP_ABORT] reason=inactive-before-timer runId=${runId}`,
        );
        return;
      }

      const delayMs = getClosedLoopNextStepDelayMs({
        runId,
        round,
        reason: 'reply-stable-before-next-round',
      });
      const delayResult = await waitClosedLoopPostReplyDelay(runId, round, delayMs);
      if (!delayResult.ok) {
        ToolboxShell.appendLog(
          `[CLOSED_LOOP][ROUND_POST_DELAY_NOT_OK] runId=${runId} round=${round} reason=${delayResult.reason}`,
        );
        return;
      }

      const finalCheck = checkClosedLoopReadyForNextSend(
        runId,
        round,
        'post-reply-delay-done',
      );
      if (!finalCheck.ok) {
        if (finalCheck.reason === 'busy') {
          setClosedLoopPhase(CLOSED_LOOP_PHASES.WAITING_REPLY, {
            reason: 'final-check-busy',
          });
          beginClosedLoopReplyWait('final-check-busy');
          recoverClosedLoopContinue(runId, 'busy-after-post-delay', {
            delayMs: 5000,
          });
        } else {
          recoverClosedLoopContinue(runId, `final-check-${finalCheck.reason}`, {
            delayMs: 5000,
          });
        }
        return;
      }

      setClosedLoopPhase(CLOSED_LOOP_PHASES.READY_NEXT_ROUND, {
        reason: `round-${round}-ready-next`,
      });
      ToolboxShell.appendLog(
        `[CLOSED_LOOP][REPLY_DONE] runId=${runId} round=${round} action=schedule-next-round`,
      );
      scheduleClosedLoopContinueNextStep(
        runId,
        0,
        `round-${round}-reply-stable-delay-done`,
      );
      } catch (error) {
        console.error('[CLOSED_LOOP][STEP_ERROR]', error);
        ToolboxShell.appendLog(
          [
            '[CLOSED_LOOP][STEP_ERROR]',
            `runId=${runId}`,
            `message=${error && error.message ? error.message : String(error)}`,
            `stack=${error && error.stack ? String(error.stack).split('\n').slice(0, 3).join(' | ') : '-'}`,
          ].join(' '),
        );
        recoverClosedLoopContinue(runId, 'step-error', {
          delayMs: 5000,
        });
      } finally {
        if (closedLoopContinueState.currentStepToken === stepToken) {
          closedLoopContinueState.currentStepRunning = false;
          closedLoopContinueState.currentStepToken = '';
          ToolboxShell.appendLog(
            [
              '[CLOSED_LOOP][STEP_EXIT]',
              `runId=${runId}`,
              `token=${stepToken}`,
              `phase=${closedLoopContinueState.phase || '-'}`,
            ].join(' '),
          );
        } else {
          ToolboxShell.appendLog(
            [
              '[CLOSED_LOOP][STEP_EXIT_SKIP_TOKEN_CHANGED]',
              `runId=${runId}`,
              `token=${stepToken}`,
              `currentToken=${closedLoopContinueState.currentStepToken || '-'}`,
            ].join(' '),
          );
        }
      }
    }

    function migrateLegacyClosedLoopHotkeyButton(scope) {
      if (!(scope instanceof HTMLElement || scope === document)) {
        return;
      }

      if (scope.querySelector(`#${CLOSED_LOOP_CONTINUE_ACTIONS.WITH_HOTKEY.id}`)) {
        return;
      }

      const legacyBtn = scope.querySelector(`#${CLOSED_LOOP_CONTINUE_ACTIONS.WITHOUT_HOTKEY.id}:not([data-closed-loop-mode])`);
      if (!legacyBtn) {
        return;
      }

      legacyBtn.id = CLOSED_LOOP_CONTINUE_ACTIONS.WITH_HOTKEY.id;
      legacyBtn.dataset.action = CLOSED_LOOP_CONTINUE_ACTIONS.WITH_HOTKEY.action;
      legacyBtn.textContent = getClosedLoopModeLabel(CLOSED_LOOP_CONTINUE_MODES.WITH_HOTKEY);
      ToolboxShell.appendLog('[CLOSED_LOOP][MIGRATE] legacy closed-loop button id -> hotkey btn');
    }

    function isClosedLoopButtonsHiddenByExtraNarrowLayout() {
      const panel = document.getElementById(typeof APP !== 'undefined' && APP && APP.panelId ? APP.panelId : 'cgpt-toolbox-panel');
      if (!(panel instanceof HTMLElement)) {
        return false;
      }
      if (!panel.classList.contains('cgpt-toolbox-extra-narrow')) {
        return false;
      }
      const row = rootElRef
        ? rootElRef.querySelector('.cgpt-upload-closed-loop-action-row')
        : document.querySelector('#cgpt-upload-module .cgpt-upload-closed-loop-action-row');
      if (!row) {
        return false;
      }
      const style = window.getComputedStyle(row);
      return style.display === 'none' || style.visibility === 'hidden';
    }

    function isClosedLoopPanelVisible() {
      const panel = document.getElementById('cgpt-autoq-closed-loop-panel');
      if (!(panel instanceof HTMLElement)) {
        return false;
      }
      const style = window.getComputedStyle(panel);
      if (style.display === 'none' || style.visibility === 'hidden') {
        return false;
      }
      const rect = panel.getBoundingClientRect();
      return rect.width > 0 && rect.height > 0;
    }

    function isUploadToolboxPanelVisible() {
      const panelId = typeof APP !== 'undefined' && APP && APP.panelId ? APP.panelId : 'cgpt-toolbox-panel';
      const panel = document.getElementById(panelId);
      if (!(panel instanceof HTMLElement)) {
        return false;
      }
      const style = window.getComputedStyle(panel);
      if (style.display === 'none' || style.visibility === 'hidden') {
        return false;
      }
      const rect = panel.getBoundingClientRect();
      return rect.width > 0 && rect.height > 0;
    }

    function scheduleClosedLoopButtonHitTest(reason = '') {
      const run = () => {
        logClosedLoopButtonHitTest(reason);
      };
      if (typeof requestAnimationFrame === 'function') {
        requestAnimationFrame(() => {
          requestAnimationFrame(run);
        });
        return;
      }
      window.setTimeout(run, 32);
    }

    function logClosedLoopButtonHitTest(reason = '') {
      const ids = [
        CLOSED_LOOP_CONTINUE_ACTIONS.WITH_HOTKEY.id,
        CLOSED_LOOP_CONTINUE_ACTIONS.WITH_HOTKEY_EVERY_ROUND.id,
        CLOSED_LOOP_CONTINUE_ACTIONS.WITHOUT_HOTKEY.id,
      ];
      const hiddenByExtraNarrow = isClosedLoopButtonsHiddenByExtraNarrowLayout();
      if (!isUploadToolboxPanelVisible()) {
        ids.forEach((id) => {
          ToolboxShell.appendLog(
            `[CLOSED_LOOP][HIT_TEST_SKIP] id=${id} reason=panel-hidden source=${reason || '-'}`,
          );
        });
        return;
      }
      ids.forEach((id) => {
        const btn = document.getElementById(id);
        if (!btn) {
          if (hiddenByExtraNarrow) {
            ToolboxShell.appendLog(
              `[CLOSED_LOOP][HIT_TEST_SKIP] id=${id} reason=hidden-by-extra-narrow source=${reason || '-'}`,
            );
          } else {
            ToolboxShell.appendLog(`[CLOSED_LOOP][HIT_TEST] id=${id} found=0 reason=${reason || '-'}`);
          }
          return;
        }
        if (hiddenByExtraNarrow) {
          ToolboxShell.appendLog(
            `[CLOSED_LOOP][HIT_TEST_SKIP] id=${id} reason=hidden-by-extra-narrow source=${reason || '-'}`,
          );
          return;
        }
        const rect = btn.getBoundingClientRect();
        const rectWidth = Math.round(rect.width);
        const rectHeight = Math.round(rect.height);
        const visible = rectWidth > 0 && rectHeight > 0 ? 1 : 0;
        const offsetParent = btn.offsetParent ? 1 : 0;
        if (rectWidth <= 0 || rectHeight <= 0) {
          ToolboxShell.appendLog(
            `[CLOSED_LOOP][HIT_TEST] id=${id} found=1 disabled=${btn.disabled ? 1 : 0} visible=${visible} offsetParent=${offsetParent} rectWidth=${rectWidth} rectHeight=${rectHeight} skipped=1 blocked=0 reason=zero-rect-not-layouted source=${reason || '-'}`,
          );
          return;
        }
        const x = rect.left + rect.width / 2;
        const y = rect.top + rect.height / 2;
        const topEl = document.elementFromPoint(x, y);
        const blocked = topEl && topEl !== btn && !btn.contains(topEl);
        ToolboxShell.appendLog(
          `[CLOSED_LOOP][HIT_TEST] id=${id} found=1 disabled=${btn.disabled ? 1 : 0} visible=${visible} offsetParent=${offsetParent} rectWidth=${rectWidth} rectHeight=${rectHeight} skipped=0 pointerEvents=${getComputedStyle(btn).pointerEvents} rect=${Math.round(rect.left)}/${Math.round(rect.top)}/${rectWidth}/${rectHeight} blocked=${blocked ? 1 : 0} topId=${topEl && topEl.id ? topEl.id : '-'} topTag=${topEl && topEl.tagName ? topEl.tagName : '-'} topClass=${topEl && topEl.className ? String(topEl.className).slice(0, 120) : '-'} reason=${reason || '-'}`,
        );
      });
    }

    function bindClosedLoopButtonDirect(btn, actionDef, reason = '') {
      if (!(btn instanceof HTMLElement) || !actionDef) {
        return false;
      }
      const action = String(actionDef.action || '').trim();
      const mode = actionDef.mode;
      if (!action || !mode) {
        ToolboxShell.appendLog(
          `[CLOSED_LOOP][DIRECT_BIND_SKIP] reason=missing-action-or-mode id=${btn.id || '-'} action=${action || '-'} mode=${mode || '-'}`,
        );
        return false;
      }
      // 每次绑定/重绑都先修复按钮动作字段，避免 render 后 data-action/runtime/baseAction 不一致。
      applyClosedLoopContinueButtonDef(btn, actionDef);

      const invokeClosedLoop = (event) => {
        ToolboxShell.appendLog(
          `[CLOSED_LOOP][DIRECT_CLICK_DIAG] id=${btn.id || '-'} action=${action} mode=${mode} disabled=${btn.disabled ? 1 : 0} reason=${reason || '-'} note=delegated-dispatch-only`,
        );
        if (event && event.cgptUploadUiActionHandled) {
          ToolboxShell.appendLog(
            `[CLOSED_LOOP][DIRECT_CLICK_DIAG] reason=already-handled id=${btn.id || '-'} action=${action}`,
          );
        }
      };

      if (btn.dataset.closedLoopDirectClickBound !== '1') {
        btn.dataset.closedLoopDirectClickBound = '1';
        btn.addEventListener('click', (event) => {
          invokeClosedLoop(event);
        });
      }

      return true;
    }

    function bindClosedLoopContinueButtons(rootEl, reason = '') {
      ToolboxShell.appendLog(
        `[CLOSED_LOOP][BIND_ENTER] reason=${reason || '-'} root=${rootEl && rootEl.id ? rootEl.id : '-'}`,
      );

      const scope = rootEl instanceof HTMLElement ? rootEl : document;
      migrateLegacyClosedLoopHotkeyButton(scope);

      let hotkeyBtn = scope.querySelector(`#${CLOSED_LOOP_CONTINUE_ACTIONS.WITH_HOTKEY.id}`);
      if (!hotkeyBtn) {
        hotkeyBtn = scope.querySelector('#cgpt-copy-hotkey-continue-loop-upload-verify');
        if (hotkeyBtn) {
          hotkeyBtn.id = CLOSED_LOOP_CONTINUE_ACTIONS.WITH_HOTKEY.id;
          hotkeyBtn.dataset.action = CLOSED_LOOP_CONTINUE_ACTIONS.WITH_HOTKEY.action;
        }
      }

      const everyRoundBtn = scope.querySelector(`#${CLOSED_LOOP_CONTINUE_ACTIONS.WITH_HOTKEY_EVERY_ROUND.id}`);
      const plainBtn = scope.querySelector(`#${CLOSED_LOOP_CONTINUE_ACTIONS.WITHOUT_HOTKEY.id}`);

      ToolboxShell.appendLog(
        `[CLOSED_LOOP][BIND_STATE] reason=${reason || '-'} hotkey=${hotkeyBtn ? 1 : 0} everyRound=${everyRoundBtn ? 1 : 0} plain=${plainBtn ? 1 : 0}`,
      );

      const bindOne = (btn, mode) => {
        if (!btn) {
          return;
        }
        const bindKey = `closedLoopModeBound_${mode}`;
        if (btn.dataset[bindKey] === '1') {
          const actionDef = getClosedLoopContinueActionDef(mode);
          applyClosedLoopContinueButtonDef(btn, actionDef);
          bindClosedLoopButtonDirect(btn, actionDef, reason);
          ToolboxShell.appendLog(
            `[CLOSED_LOOP][BIND_HEAL] mode=${mode} id=${btn.id || '-'} action=${btn.dataset.action || '-'} reason=already-bound-heal`,
          );
          return;
        }

        btn.dataset[bindKey] = '1';
        const actionDef = getClosedLoopContinueActionDef(mode);
        applyClosedLoopContinueButtonDef(btn, actionDef);

        const directBound = bindClosedLoopButtonDirect(btn, actionDef, reason);
        ToolboxShell.appendLog(
          `[CLOSED_LOOP][BIND_ONE] mode=${mode} id=${btn.id || '-'} action=${btn.dataset.action || '-'} directClick=${directBound ? 1 : 0}`,
        );
      };

      bindOne(hotkeyBtn, CLOSED_LOOP_CONTINUE_MODES.WITH_HOTKEY);
      bindOne(everyRoundBtn, CLOSED_LOOP_CONTINUE_MODES.WITH_HOTKEY_EVERY_ROUND);
      bindOne(plainBtn, CLOSED_LOOP_CONTINUE_MODES.WITHOUT_HOTKEY);
    }

    function bindClosedLoopDocumentClickFallback(reason = '') {
      if (document.documentElement.dataset.closedLoopDocumentFallbackBound === '1') {
        return;
      }
      document.documentElement.dataset.closedLoopDocumentFallbackBound = '1';
      document.addEventListener('click', (event) => {
        const target = event.target instanceof Element ? event.target : null;
        if (!target) {
          return;
        }
        const hotkeyDef = CLOSED_LOOP_CONTINUE_ACTIONS.WITH_HOTKEY;
        const everyRoundDef = CLOSED_LOOP_CONTINUE_ACTIONS.WITH_HOTKEY_EVERY_ROUND;
        const plainDef = CLOSED_LOOP_CONTINUE_ACTIONS.WITHOUT_HOTKEY;
        const btn = target.closest(
          `#${hotkeyDef.id}, #${everyRoundDef.id}, #${plainDef.id}, [data-action="${hotkeyDef.action}"], [data-action="${everyRoundDef.action}"], [data-action="${plainDef.action}"]`,
        );
        if (!(btn instanceof HTMLElement)) {
          return;
        }
        const action = normalizeClosedLoopAction(btn.dataset.action || '');
        if (
          !isClosedLoopCanonicalAction(action)
          && btn.id !== hotkeyDef.id
          && btn.id !== everyRoundDef.id
          && btn.id !== plainDef.id
        ) {
          return;
        }
        if (event && event.cgptUploadUiActionHandled) {
          ToolboxShell.appendLog(
            `[CLOSED_LOOP][DOCUMENT_CLICK_SKIP] reason=already-handled id=${btn.id || '-'} action=${action || '-'}`,
          );
          return;
        }
        const resolvedAction = isClosedLoopCanonicalAction(action)
          ? action
          : (btn.id === plainDef.id
            ? plainDef.action
            : (btn.id === everyRoundDef.id ? everyRoundDef.action : hotkeyDef.action));
        ToolboxShell.appendLog(
          `[CLOSED_LOOP][DOCUMENT_CLICK] id=${btn.id || '-'} action=${resolvedAction} disabled=${btn.disabled ? 1 : 0} reason=${reason || '-'}`,
        );
        dispatchToolboxActionSafe(resolvedAction, {
          button: btn,
          source: `document:${reason || resolvedAction || btn.id}`,
          event,
        });
      }, true);
      ToolboxShell.appendLog(`[CLOSED_LOOP][DOCUMENT_FALLBACK_BOUND] reason=${reason || '-'}`);
    }

    function shouldRunClosedLoopDiagnostics(reason = '-') {
      const reasonText = String(reason || '-');
      if (typeof isAdvancedDebugEnabled === 'function' && isAdvancedDebugEnabled()) {
        return true;
      }
      return reasonText === 'initial-render'
        || reasonText === 'manual-debug'
        || reasonText.includes('mount-upload-module');
    }

    function rebindClosedLoopContinueUi(rootEl, reason = 'after-render') {
      bindClosedLoopContinueButtons(rootEl || rootElRef || document, reason);
      bindClosedLoopDocumentClickFallback(reason);
      renderClosedLoopContinueButtons();
      if (shouldRunClosedLoopDiagnostics(reason)) {
        scheduleClosedLoopButtonHitTest(`rebind:${reason || '-'}`);
      }
    }

    function ensureCopyHotkeyContinueTask() {
      if (!state.copyHotkeyContinueTask || typeof state.copyHotkeyContinueTask !== 'object') {
        state.copyHotkeyContinueTask = {
          phase: 'idle',
          runId: '',
          cancelRequested: false,
          abortController: null,
          startedAt: 0,
          lastError: null,
        };
      }
      return state.copyHotkeyContinueTask;
    }

    function isCopyHotkeyContinueCancelled(runId = '') {
      const task = ensureCopyHotkeyContinueTask();
      const expectedRunId = String(runId || '').trim();
      if (expectedRunId && task.runId && task.runId !== expectedRunId) {
        return true;
      }
      return !!(
        task.cancelRequested
        || task.phase === 'cancelling'
        || task.phase === 'cancelled'
      );
    }

    function setCopyHotkeyContinuePhase(phase, reason = '') {
      const task = ensureCopyHotkeyContinueTask();
      const normalized = String(phase || 'idle').trim().toLowerCase();
      task.phase = normalized;

      const activePhases = new Set([
        'waiting_reply',
        'copying',
        'sending_hotkey',
        'sending_continue',
        'cancelling',
      ]);
      copyHotkeyContinueTaskRunning = activePhases.has(normalized);
      if (copyHotkeyContinueTaskRunning && !task.startedAt) {
        task.startedAt = Date.now();
        copyHotkeyContinueTaskStartedAt = task.startedAt;
      }
      if (!copyHotkeyContinueTaskRunning) {
        task.startedAt = 0;
        copyHotkeyContinueTaskStartedAt = 0;
      }

      if (reason) {
        task.lastReason = String(reason);
      }
      if (typeof ButtonTasks !== 'undefined' && typeof ButtonTasks.setTaskPhase === 'function') {
        ButtonTasks.setTaskPhase('copyHotkeyContinue', normalized, reason || 'phase-sync', {
          cancelRequested: !!task.cancelRequested,
          runId: task.runId || '',
        });
      }
      logButtonTasksMigration('copyHotkeyContinueTaskRunning', 'copyHotkeyContinue', normalized);

      logTaskSourceConsistency(
        'copyHotkeyContinue',
        normalized,
        copyHotkeyContinueTaskRunning,
        isCopyHotkeyContinueActive(),
        reason,
      );
      scheduleRenderUpload(`copyHotkeyContinue:${normalized}:${reason || '-'}`);
    }

    function cancelCopyHotkeyContinue(source = 'unknown') {
      const task = ensureCopyHotkeyContinueTask();
      const src = String(source || 'unknown').trim() || 'unknown';

      if (task.phase === 'idle' || task.phase === 'cancelling') {
        ToolboxShell.appendLog(`[COPY_HOTKEY_CONTINUE][cancel-ignore] source=${src} phase=${task.phase}`);
        return false;
      }

      if (!COPY_HOTKEY_CONTINUE_CANCELLABLE_PHASES.has(task.phase)) {
        ToolboxShell.appendLog(`[COPY_HOTKEY_CONTINUE][cancel-ignore] source=${src} phase=${task.phase}`);
        return false;
      }

      task.cancelRequested = true;
      if (task.abortController && typeof task.abortController.abort === 'function') {
        task.abortController.abort();
      }
      setCopyHotkeyContinuePhase('cancelling', src);
      ToolboxShell.appendLog(`[COPY_HOTKEY_CONTINUE][cancel] source=${src} runId=${task.runId || '-'}`);
      return true;
    }

    function finishCopyHotkeyContinueTask(outcome, runId, source = '') {
      const task = ensureCopyHotkeyContinueTask();
      if (runId && task.runId && task.runId !== runId) {
        return;
      }

      task.abortController = null;
      task.cancelRequested = false;

      const normalized = String(outcome || 'idle').trim().toLowerCase();
      setCopyHotkeyContinuePhase(normalized, source || outcome);

      releaseUploadActionLock('copy-hotkey-continue');

      const resetMs = normalized === 'cancelled'
        ? 400
        : (normalized === 'success' ? 1200 : 1500);
      window.setTimeout(() => {
        if (!runId || (state.copyHotkeyContinueTask && state.copyHotkeyContinueTask.runId === runId)) {
          if (state.copyHotkeyContinueTask) {
            state.copyHotkeyContinueTask.runId = '';
          }
          setCopyHotkeyContinuePhase('idle', 'auto-reset');
        }
      }, resetMs);
    }

    async function runCopyHotkeyContinueOnce(source = 'button') {
      const src = String(source || 'button').trim() || 'button';

      if (isCopyHotkeyLoopActive() || isCopyHotkeyUploadVerifyLoopActive()) {
        ToolboxShell.appendLog(`[COPY_HOTKEY_CONTINUE][skip] source=${src} reason=loop-running`);
        return {
          ok: false,
          reason: 'loop-running',
        };
      }

      const task = ensureCopyHotkeyContinueTask();
      if (COPY_HOTKEY_CONTINUE_CANCELLABLE_PHASES.has(task.phase) || task.phase === 'cancelling') {
        ToolboxShell.appendLog(`[COPY_HOTKEY_CONTINUE][skip] source=${src} reason=task-running phase=${task.phase}`);
        return {
          ok: false,
          reason: 'task-running',
        };
      }

      const runId = createUploadTaskRunId('copy_hotkey_continue');
      task.runId = runId;
      task.cancelRequested = false;
      task.lastError = null;
      task.abortController = typeof AbortController !== 'undefined' ? new AbortController() : null;
      task.startedAt = Date.now();
      copyHotkeyContinueTaskStartedAt = task.startedAt;

      const shouldStop = () => isCopyHotkeyContinueCancelled(runId);

      setCopyHotkeyContinuePhase('waiting_reply', src);

      try {
        const result = await copyHotkeyAndContinueOnce(src, {
          shouldStop,
          runId,
          managedPhase: true,
        });

        if (task.runId !== runId) {
          return result;
        }

        if (isCopyHotkeyContinueCancelled(runId) || (result && result.reason === 'cancelled')) {
          finishCopyHotkeyContinueTask('cancelled', runId, src);
          return result || { ok: false, reason: 'cancelled' };
        }

        if (result && result.ok) {
          finishCopyHotkeyContinueTask('success', runId, src);
        } else {
          task.lastError = result && (result.detail || result.reason)
            ? String(result.detail || result.reason)
            : 'failed';
          finishCopyHotkeyContinueTask('failed', runId, src);
        }

        return result;
      } catch (error) {
        const errText = formatToolboxError(error);
        if (task.runId === runId) {
          task.lastError = errText;
          finishCopyHotkeyContinueTask('failed', runId, src);
        }
        throw error;
      }
    }

    function ensureCopyHotkeyContinueLoopTask() {
      if (!state.copyHotkeyContinueLoopTask || typeof state.copyHotkeyContinueLoopTask !== 'object') {
        state.copyHotkeyContinueLoopTask = {
          phase: 'idle',
          runId: '',
          stopRequested: false,
          cycleIndex: 0,
          startedAt: 0,
          lastError: null,
          currentSubtask: '',
        };
      }
      return state.copyHotkeyContinueLoopTask;
    }

    function setCopyHotkeyContinueLoopPhase(phase, reason = '', options = {}) {
      const task = ensureCopyHotkeyContinueLoopTask();
      const normalized = String(phase || 'idle').trim().toLowerCase();
      task.phase = normalized;

      if (options.cycleIndex != null) {
        task.cycleIndex = Number(options.cycleIndex) || 0;
        copyHotkeyContinueLoopCount = task.cycleIndex;
      }

      if (options.currentSubtask != null) {
        task.currentSubtask = String(options.currentSubtask || '');
      }

      const loopActive = !['idle', 'success', 'failed', 'stopped'].includes(normalized);
      copyHotkeyContinueLoopRunning = loopActive;
      copyHotkeyContinueLoopStopRequested = !!(
        task.stopRequested
        || normalized === 'stopping'
      );

      if (reason) {
        task.lastReason = String(reason);
      }
      if (typeof ButtonTasks !== 'undefined' && typeof ButtonTasks.setTaskPhase === 'function') {
        ButtonTasks.setTaskPhase('copyHotkeyContinueLoop', normalized, reason || 'phase-sync', {
          stopRequested: !!task.stopRequested,
          currentSubtask: task.currentSubtask || '',
          cycleIndex: task.cycleIndex || 0,
        });
      }
      logButtonTasksMigration('copyHotkeyContinueLoopRunning', 'copyHotkeyContinueLoop', normalized);

      logTaskSourceConsistency(
        'copyHotkeyContinueLoop',
        normalized,
        copyHotkeyContinueLoopRunning,
        isCopyHotkeyLoopActive(),
        reason,
      );
      scheduleRenderUpload(`copyHotkeyLoop:${normalized}:${reason || '-'}`);
    }

    function requestCopyHotkeyContinueLoopStop(source = 'unknown') {
      const task = ensureCopyHotkeyContinueLoopTask();
      const src = String(source || 'unknown').trim() || 'unknown';

      if (!COPY_HOTKEY_LOOP_STOP_PHASES.has(task.phase) && !copyHotkeyContinueLoopRunning) {
        return false;
      }

      invalidateCopyHotkeyContinueLoopRun(src);
      haltClosedLoopCompanionAutomation(src);
      setCopyHotkeyContinueLoopPhase('stopping', src);
      setStatus('停止请求已提交，等待任务退出...', 'warn');
      ToolboxShell.appendLog(`[COPY_HOTKEY_CONTINUE_LOOP][STOP] user requested stop source=${src}`);
      scheduleRenderUpload(`copyHotkeyLoop:stopping:${src}`);
      return true;
    }

    async function runCopyHotkeyContinueLoop(source = 'button') {
      const src = String(source || 'button').trim() || 'button';
      const loopTask = ensureCopyHotkeyContinueLoopTask();

      if (COPY_HOTKEY_LOOP_STOP_PHASES.has(loopTask.phase) || copyHotkeyContinueLoopRunning) {
        return requestCopyHotkeyContinueLoopStop(src);
      }

      if (loopTask.phase === 'stopping') {
        ToolboxShell.appendLog(`[COPY_HOTKEY_CONTINUE_LOOP][click-ignore] source=${src} phase=stopping`);
        return false;
      }

      const actionLock = claimUploadActionLock('copy-hotkey-continue-loop', { timeoutMs: 600000 });
      if (!actionLock.ok) {
        ToolboxShell.appendLog(
          `[COPY_HOTKEY_CONTINUE_LOOP][skip] source=${src} reason=${actionLock.reason} runningMs=${actionLock.runningMs || 0}`,
        );
        return false;
      }

      try {
        return await toggleCopyHotkeyContinueLoop(src);
      } catch (err) {
        const errText = formatToolboxError(err);
        console.error('[ChatGPT toolbox] copy hotkey continue loop failed', err);
        setStatus(`连续复制+快捷键+继续失败：${errText}`, 'error');
        ToolboxShell.appendLog(`[COPY_HOTKEY_CONTINUE_LOOP][FAILED] source=${src} error=${errText}`);
        return false;
      } finally {
        releaseUploadActionLock('copy-hotkey-continue-loop');
      }
    }

    async function handleCopyHotkeyContinueLoopClick(source = 'unknown') {
      return runCopyHotkeyContinueLoop(source);
    }

    function ensureCopyHotkeyUploadVerifyLoopTask() {
      if (!state.copyHotkeyUploadVerifyLoopTask || typeof state.copyHotkeyUploadVerifyLoopTask !== 'object') {
        state.copyHotkeyUploadVerifyLoopTask = {
          phase: 'idle',
          runId: '',
          stopRequested: false,
          cycleIndex: 0,
          startedAt: 0,
          lastError: null,
          currentSubtask: '',
        };
      }
      return state.copyHotkeyUploadVerifyLoopTask;
    }

    function setCopyHotkeyUploadVerifyLoopPhase(phase, reason = '', options = {}) {
      const task = ensureCopyHotkeyUploadVerifyLoopTask();
      const normalized = String(phase || 'idle').trim().toLowerCase();
      task.phase = normalized;

      if (options.cycleIndex != null) {
        task.cycleIndex = Number(options.cycleIndex) || 0;
        copyHotkeyUploadVerifyLoopCount = task.cycleIndex;
      }

      if (options.currentSubtask != null) {
        task.currentSubtask = String(options.currentSubtask || '');
      }

      copyHotkeyUploadVerifyLoopRunning = !!closedLoopContinueState.running;
      copyHotkeyUploadVerifyLoopStopRequested = !!(
        closedLoopContinueState.stopping
        || task.stopRequested
        || normalized === 'stopping'
      );

      if (reason) {
        task.lastReason = String(reason);
      }
      if (typeof ButtonTasks !== 'undefined' && typeof ButtonTasks.setTaskPhase === 'function') {
        ButtonTasks.setTaskPhase('copyHotkeyUploadVerifyLoop', normalized, reason || 'phase-sync', {
          stopRequested: !!task.stopRequested,
          currentSubtask: task.currentSubtask || '',
          cycleIndex: task.cycleIndex || 0,
        });
      }
      logButtonTasksMigration('copyHotkeyUploadVerifyLoopRunning', 'copyHotkeyUploadVerifyLoop', normalized);

      logTaskSourceConsistency(
        'copyHotkeyUploadVerifyLoop',
        normalized,
        copyHotkeyUploadVerifyLoopRunning,
        isCopyHotkeyUploadVerifyLoopActive(),
        reason,
      );
      if (closedLoopContinueState.running || closedLoopContinueState.stopping) {
        renderClosedLoopContinueButton();
      } else {
        scheduleRenderUpload(`copyHotkeyUploadVerifyLoop:${normalized}:${reason || '-'}`);
      }
    }

    function shouldSkipAction(actionName, windowMs = 300) {
      return !!(
        typeof ActionRuntime !== 'undefined'
        && ActionRuntime
        && typeof ActionRuntime.shouldSkipAction === 'function'
        && ActionRuntime.shouldSkipAction(actionName, windowMs)
      );
    }

    function resolveUploadActionDebounceKey(action, source) {
      const normalized = String(action || '').trim();
      const src = String(source || '').trim();

      if (normalized === 'send-message' && src === 'enter-hotkey') {
        return 'enter-send';
      }

      if (normalized === 'loop-copy-hotkey-continue') {
        return 'copy-hotkey-loop';
      }

      if (isClosedLoopCanonicalAction(normalized)) {
        return 'copy-hotkey-upload-verify-loop';
      }

      if (normalized === 'copy-hotkey-continue') {
        return 'copy-hotkey-continue-once';
      }

      if (
        normalized === 'start-upload'
        || normalized === 'send-message'
        || normalized === 'auto-continue'
        || normalized === 'auto-continue-until-done'
      ) {
        return normalized;
      }

      return '';
    }

    function claimUploadActionLock(key, options = {}) {
      const lockKey = String(key || '').trim();
      const result = (
        typeof ActionRuntime !== 'undefined'
        && ActionRuntime
        && typeof ActionRuntime.claimActionLock === 'function'
      )
        ? ActionRuntime.claimActionLock(lockKey, options)
        : { ok: false, reason: 'action-runtime-missing' };

      if (result && result.ok && lockKey === 'copy-hotkey-once') {
        setCopyHotkeyOncePhase('waiting_reply', 'action-lock-claim');
      } else if (result && result.ok && lockKey === 'copy-hotkey-continue') {
        copyHotkeyContinueTaskRunning = true;
        copyHotkeyContinueTaskStartedAt = Number(result.startedAt || Date.now());
      }

      return result;
    }

    function releaseUploadActionLock(key) {
      const lockKey = String(key || '').trim();
      if (!lockKey) {
        return;
      }

      if (
        typeof ActionRuntime !== 'undefined'
        && ActionRuntime
        && typeof ActionRuntime.releaseActionLock === 'function'
      ) {
        ActionRuntime.releaseActionLock(lockKey);
      }

      if (lockKey === 'copy-hotkey-once') {
        setCopyHotkeyOncePhase('idle', 'action-lock-release');
      } else if (lockKey === 'copy-hotkey-continue') {
        copyHotkeyContinueTaskRunning = false;
        copyHotkeyContinueTaskStartedAt = 0;
      }
    }

    function getDefaultCopyHotkeyContinuePromptText() {
      let text = '';
      if (typeof getDefaultBatchContinuePromptText === 'function') {
        text = getDefaultBatchContinuePromptText();
      } else if (typeof getDefaultTaskContinuePromptText === 'function') {
        text = getDefaultTaskContinuePromptText();
      } else if (typeof getDefaultContinuePromptText === 'function') {
        text = getDefaultContinuePromptText();
      } else {
        text = '请继续完成当前任务。';
      }
      if (typeof appendDetailedCursorInstructionBlock === 'function') {
        return appendDetailedCursorInstructionBlock(text);
      }
      if (!String(text || '').includes('Cursor / Claude Code 修改指令')) {
        return [
          String(text || '').trim(),
          '',
          '如果当前任务涉及代码修改、修复、重构、Bug 定位、UI 行为、状态同步、上传逻辑、闭环控制或日志排查，必须输出详细的 Cursor / Claude Code 修改指令。必须列出涉及文件、函数名、修改前问题、修改后目标行为、关键代码片段、日志要求、验证步骤和边界条件。不要只给笼统建议。',
        ].join('\n');
      }
      return text;
    }

    function readUserConfiguredContinuePromptText() {
      const cfg = typeof getCompactUiConfig === 'function'
        ? getCompactUiConfig()
        : {};
      return String(cfg.copyHotkeyContinuePromptText || '').trim();
    }

    const CANONICAL_CONTINUE_STOP_TOKEN = '<<<XZ_TOOLBOX_BATCH_TASK_STOP_7F3B9C>>>';

    function logContinuePromptBuild(promptText, options = {}) {
      const source = String(options.source || options.logSource || '-').trim() || '-';
      const text = String(promptText || '');
      const hasDetailedCursor = typeof hasDetailedCursorInstructionBlock === 'function'
        ? hasDetailedCursorInstructionBlock(text)
        : (
          text.includes('Cursor / Claude Code 修改指令')
          || text.includes('函数名')
          || text.includes('验证步骤')
        );
      ToolboxShell.appendLog(
        `[CLOSED_LOOP][CONTINUE_PROMPT_BUILD] source=${source} len=${text.length} `
        + `hasStopToken=${text.includes(CANONICAL_CONTINUE_STOP_TOKEN) ? 1 : 0} `
        + `hasDetailedCursor=${hasDetailedCursor ? 1 : 0} `
        + `hasFunctionRequirement=${text.includes('函数名') ? 1 : 0} `
        + `hasVerifyRequirement=${text.includes('验证步骤') ? 1 : 0}`,
      );
    }

    function buildContinuePromptPayloadVerify(promptText, doneSignal) {
      const text = String(promptText || '');
      const signal = String(doneSignal || CANONICAL_CONTINUE_STOP_TOKEN).trim();
      const defaultMarkers = [
        '请继续完成当前任务',
        '最开始那个 Prompt',
        'Cursor',
        'Claude Code',
        '函数名',
        '验证步骤',
        '日志要求',
        signal,
      ].filter((item) => item && text.includes(item));
      if (defaultMarkers.length >= 4) {
        return {
          allowLenDelta: 120,
          allowCoreContains: true,
          requiredIncludes: defaultMarkers.slice(0, 6),
        };
      }
      const userCore = text.slice(0, Math.min(48, text.length)).trim();
      return {
        allowLenDelta: 120,
        allowCoreContains: true,
        requiredIncludes: userCore ? [userCore] : [],
      };
    }

    function formatContinuePromptPreview(text, maxLen = 160) {
      const normalized = String(text || '').replace(/\r\n/g, '\n').trim();
      if (normalized.length <= maxLen) {
        return normalized;
      }
      return `${normalized.slice(0, maxLen)}...`;
    }

    function getCopyHotkeyContinueStopSignal(options = {}) {
      const override = String(options.doneSignal || '').trim();
      if (override) {
        return override;
      }

      const cfg = typeof getCompactUiConfig === 'function'
        ? getCompactUiConfig()
        : {};

      let signal = String(
        cfg.copyHotkeyContinueStopSignal || resolveDefaultDoneSignal(),
      ).trim();

      return signal || resolveDefaultDoneSignal();
    }

    function getCopyHotkeyContinuePromptText(options = {}) {
      const overridePrompt = String(options.continuePrompt || '').trim();
      if (overridePrompt) {
        if (options.logContinuePrompt !== false) {
          logContinuePromptBuild(overridePrompt, options);
        }
        return overridePrompt;
      }

      const userText = readUserConfiguredContinuePromptText();
      let text = userText;
      if (!text) {
        text = getDefaultCopyHotkeyContinuePromptText();
      }

      const signal = getCopyHotkeyContinueStopSignal(options);

      let rendered = text;
      if (typeof renderContinuePromptTemplate === 'function') {
        rendered = renderContinuePromptTemplate(text, signal);
      } else if (!text.includes(signal)) {
        rendered = [
          text,
          '',
          '如果任务已经完整完成，只能回复下面这一行，不能有任何其他文字：',
          '',
          signal,
        ].join('\n');
      }

      if (options.logContinuePrompt !== false) {
        logContinuePromptBuild(rendered, options);
      }
      return rendered;
    }

    function uploadAnalyzeAssistantDoneSignalText(text, options = {}) {
      const configuredStopSignal = getCopyHotkeyContinueStopSignal(options);
      if (typeof analyzeAssistantDoneSignalText === 'function') {
        return analyzeAssistantDoneSignalText(text, {
          ...options,
          doneSignal: configuredStopSignal,
        });
      }
      console.error('[UPLOAD][done-signal] analyzeAssistantDoneSignalText missing');
      return {
        matched: false,
        corrupted: false,
        lineCount: 0,
        configuredStopSignal,
        allowedSignals: configuredStopSignal ? [configuredStopSignal] : [],
        reason: 'analyzeAssistantDoneSignalText-missing',
      };
    }

    function analyzeClosedLoopTerminalSignalText(text, options = {}) {
      const configuredDoneSignal = getCopyHotkeyContinueStopSignal(options);
      const defaultDoneSignal = resolveDefaultDoneSignal();
      const checked = (
        typeof cleanAssistantTextForDoneSignal === 'function'
          ? cleanAssistantTextForDoneSignal(text)
          : String(text || '')
      )
        .replace(/\r\n/g, '\n')
        .trim();
      const lines = checked
        .split('\n')
        .map((line) => String(line || '').trim())
        .filter(Boolean);
      if (lines.length !== 1) {
        return {
          matched: false,
          status: lines.length === 0 ? 'empty' : 'continue',
          reason: lines.length === 0 ? 'empty' : 'not-single-line-terminal-signal',
          lineCount: lines.length,
          line: '',
        };
      }
      const line = lines[0];
      const allowedStopSignals = new Set(
        [configuredDoneSignal, defaultDoneSignal, '<<<XZ_TOOLBOX_BATCH_TASK_STOP_7F3B9C>>>']
          .map((item) => String(item || '').trim())
          .filter(Boolean),
      );
      if (allowedStopSignals.has(line)) {
        ToolboxShell.appendLog(
          `[CLOSED_LOOP][CANONICAL_STOP_SIGNAL_HIT] status=done signal=${line}`,
        );
        return {
          matched: true,
          status: 'done',
          reason: 'single-canonical-stop-signal',
          lineCount: 1,
          line,
        };
      }
      if (
        line === '<<<XZ_TOOLBOX_BATCH_TASK_DONE_7F3B9C>>>'
        || line === '<<<XZ_TOOLBOX_BATCH_TASK_BLOCKED_NEED_INPUT_7F3B9C>>>'
        || line === '<<<XZ_TOOLBOX_BATCH_TASK_NO_MORE_CONTENT_7F3B9C>>>'
      ) {
        ToolboxShell.appendLog(
          `[CLOSED_LOOP][LEGACY_TERMINAL_SIGNAL_IGNORED] signal=${line} action=continue reason=only-canonical-stop-allowed`,
        );
        return {
          matched: false,
          status: 'continue',
          reason: 'legacy-terminal-signal-ignored',
          lineCount: 1,
          line,
        };
      }
      return {
        matched: false,
        status: 'continue',
        reason: 'not-canonical-stop-signal',
        lineCount: 1,
        line,
      };
    }

    function checkClosedLoopTerminalSignalWithLog(text, logPrefix, phase, extraFields = '', options = {}) {
      const result = analyzeClosedLoopTerminalSignalText(text, options);
      const preview = formatDoneSignalPreview(
        String(text || '').replace(/\r\n/g, '\n').trim(),
      );
      ToolboxShell.appendLog(
        `[${logPrefix}][TERMINAL_SIGNAL_CHECK] matched=${result.matched ? 1 : 0} `
        + `status=${result.status || '-'} phase=${phase || '-'} `
        + `reason=${result.reason || '-'} lineCount=${result.lineCount || 0} `
        + `${extraFields || ''} preview=${preview}`,
      );
      return result;
    }

    function getClosedLoopTerminalStopStatusLevel(status) {
      return 'success';
    }

    function buildClosedLoopTerminalStopMessage(status, round) {
      return `闭环任务已确认完成，已停止，共执行 ${round} 轮`;
    }

    function formatDoneSignalPreview(text) {
      const preview = String(text || '').replace(/\r\n/g, '\n').trim();
      if (preview.length <= 120) {
        return preview;
      }
      return `${preview.slice(0, 120)}...`;
    }

    function logAssistantDoneSignalCheck(logPrefix, text, phase, extraFields, options = {}) {
      const analysis = uploadAnalyzeAssistantDoneSignalText(text, options);
      const rawPreview = formatDoneSignalPreview(
        String(text || '').replace(/\r\n/g, '\n').trim(),
      );
      const checkedPreview = formatDoneSignalPreview(
        cleanAssistantTextForDoneSignal(text).replace(/\r\n/g, '\n').trim(),
      );
      const extra = extraFields
        ? ` ${String(extraFields).trim()}`
        : '';
      const allowedSignalsText = (analysis.allowedSignals || []).join('|');
      const line = `[${logPrefix}][done-signal-check] phase=${phase || '-'} matched=${analysis.matched ? '1' : '0'} rawPreview=${rawPreview} checkedPreview=${checkedPreview} lineCount=${analysis.lineCount} configuredStopSignal=${analysis.configuredStopSignal} allowedSignals=${allowedSignalsText} reason=${analysis.reason}${extra}`;
      safeAppendLog(line);
      if (typeof ToolboxShell !== 'undefined' && typeof ToolboxShell.appendLog === 'function') {
        ToolboxShell.appendLog(line);
      }
      console.warn(`[${logPrefix}][done-signal-check]`, {
        phase: phase || '-',
        matched: analysis.matched,
        rawPreview,
        checkedPreview,
        lineCount: analysis.lineCount,
        configuredStopSignal: analysis.configuredStopSignal,
        allowedSignals: analysis.allowedSignals,
        reason: analysis.reason,
      });
    }

    function checkUploadDoneSignalWithLog(text, logPrefix, phase, extraFields, options = {}) {
      const matched = uploadAnalyzeAssistantDoneSignalText(text, options).matched;
      logAssistantDoneSignalCheck(logPrefix, text, phase, extraFields, options);
      return matched;
    }


