    function syncActiveGroupCountInCache() {
      if (!state.groupCounts) {
        state.groupCounts = new Map();
      }

      state.groups.forEach((group) => {
        if (!state.groupCounts.has(group.id)) {
          state.groupCounts.set(group.id, 0);
        }
      });

      if (state.activeGroupId) {
        const memoryCount = getActiveGroupFiles().length;
        const restorePhase = getQueueRestorePhase();
        const currentDbCount = Number(state.groupCounts.get(state.activeGroupId) || 0);
        if (memoryCount === 0 && currentDbCount > 0) {
          const mismatchLine = `[UPLOAD_GROUP][COUNT_MISMATCH] dbCount=${currentDbCount} memoryCount=${memoryCount} activeGroupId=${state.activeGroupId || '-'}`;
          console.warn(mismatchLine);
          if (typeof ToolboxShell !== 'undefined' && typeof ToolboxShell.appendLog === 'function') {
            ToolboxShell.appendLog(mismatchLine);
          }
          if (
            restorePhase === 'ready'
            && typeof ToolboxShell !== 'undefined'
            && typeof ToolboxShell.appendLog === 'function'
          ) {
            ToolboxShell.appendLog(
              `[UPLOAD_GROUP][COUNT_KEEP_DB] activeGroupId=${state.activeGroupId || '-'} queueRestorePhase=${restorePhase} dbCount=${currentDbCount} memoryCount=${memoryCount}`,
            );
          }
          return;
        }
        state.groupCounts.set(state.activeGroupId, memoryCount);
      }
    }

    function getUploadGroupFileCount(groupId) {
      if (state.groupCounts && state.groupCounts.has(groupId)) {
        return state.groupCounts.get(groupId) || 0;
      }

      if (groupId === state.activeGroupId) {
        return getActiveGroupFiles().length;
      }

      return 0;
    }

    async function refreshUploadGroupCounts() {
      const refreshStartedAt = (typeof performance !== 'undefined' && performance.now)
        ? performance.now()
        : Date.now();
      const counts = new Map();

      state.groups.forEach((group) => {
        counts.set(group.id, 0);
      });

      if (!state.groups.length) {
        state.groupCounts = counts;
        return true;
      }

      try {
        const db = await openDb();

        const rows = await new Promise((resolve, reject) => {
          const tx = db.transaction(APP.uploadStore, 'readonly');
          const store = tx.objectStore(APP.uploadStore);
          const req = store.getAll();

          req.onsuccess = () => resolve(Array.isArray(req.result) ? req.result : []);
          req.onerror = () => reject(req.error || new Error('refreshUploadGroupCounts getAll failed'));
        });

        rows.forEach((row) => {
          const groupId = String(row.groupId || '').trim();
          if (!groupId) {
            return;
          }
          if (!counts.has(groupId)) {
            return;
          }
          counts.set(groupId, (counts.get(groupId) || 0) + 1);
        });

        state.groupCounts = counts;
        if (state.activeGroupId) {
          const dbCount = Number(counts.get(state.activeGroupId) || 0);
          const memoryCount = getActiveGroupFiles().length;
          if (dbCount > 0 && memoryCount === 0) {
            const mismatchLine = `[UPLOAD_GROUP][COUNT_MISMATCH] dbCount=${dbCount} memoryCount=${memoryCount} activeGroupId=${state.activeGroupId || '-'}`;
            console.warn(mismatchLine);
            if (typeof ToolboxShell !== 'undefined' && typeof ToolboxShell.appendLog === 'function') {
              ToolboxShell.appendLog(mismatchLine);
            }
          }
        }
        logSlowOperation('refreshUploadGroupCounts', refreshStartedAt, `groups=${state.groups.length}`);
        return true;
      } catch (e) {
        const errName = e && e.name ? e.name : 'Error';
        const errText = e && e.message ? e.message : String(e);
        console.error('[ChatGPT toolbox] refreshUploadGroupCounts failed', e);
        syncActiveGroupCountInCache();
        ToolboxShell.appendLog(
          `[UPLOAD_GROUP][refresh-counts:failed] activeGroupId=${state.activeGroupId || '-'} groups=${state.groups.length} type=${errName} error=${errText}`,
        );
        setStatus(`上传分组数量刷新失败：${errText}`, 'error');
        return false;
      }
    }


