    function getUnifiedRuntimeStatus(reason = '') {
      // 权威来源：module state.uploadTask / state.sendTask；ButtonTasks 仅为镜像，不可反写 UI 快照。
      const uploadTaskFromModule = syncUploadTaskFromLegacyState()
        || (state.uploadTask && typeof state.uploadTask === 'object'
          ? state.uploadTask
          : { phase: 'idle', runId: '', cancelRequested: false });
      const sendTaskFromModule = state.sendTask && typeof state.sendTask === 'object'
        ? state.sendTask
        : { phase: 'idle', runId: '', cancelRequested: false };
      const copyTaskFromModule = state.copyTask && typeof state.copyTask === 'object'
        ? state.copyTask
        : { phase: 'idle', runId: '', cancelRequested: false };

      const uploadTask = Object.assign(
        { phase: 'idle', runId: '', cancelRequested: false },
        uploadTaskFromModule,
      );
      const sendTask = Object.assign(
        { phase: 'idle', runId: '', cancelRequested: false },
        sendTaskFromModule,
      );
      const copyTask = Object.assign(
        { phase: 'idle', runId: '', cancelRequested: false },
        copyTaskFromModule,
      );
      const batchTask = (
        typeof ButtonTasks !== 'undefined'
        && typeof ButtonTasks.getButtonTask === 'function'
      )
        ? ButtonTasks.getButtonTask('batch')
        : null;

      let capability = {};
      try {
        capability = getUploadPageCapabilityLight();
      } catch (error) {
        const errText = error && error.message ? error.message : String(error);
        console.error('[ChatGPT toolbox] getUnifiedRuntimeStatus capability failed', error);
        capability = {
          hasComposer: false,
          canSendNow: false,
          can_send_now: false,
          isResponding: false,
          is_responding: false,
          response_state: 'not_ready',
          response_state_reason: `capability_error:${errText}`,
          sendable: false,
        };
      }

      let uploadQueue = {};
      try {
        uploadQueue = getUploadStatus();
      } catch (error) {
        const errText = error && error.message ? error.message : String(error);
        console.error('[ChatGPT toolbox] getUnifiedRuntimeStatus upload status failed', error);
        uploadQueue = {
          total: 0,
          attached: 0,
          failed: 0,
          missing: 0,
          running: false,
          error: errText,
        };
      }

      const uploadQuota = getUploadQuotaState();
      const messageQuota = getMessageQuotaState();

      const legacyFlags = {
        running: !!state.running,
        waitingSend: !!state.waitingSend,
        waitingReply: !!state.waitingReply,
        autoSendWaiting: !!state.autoSendWaiting,
        messageSending: !!state.messageSending,
        cancelled: !!state.cancelled,
        copyLastReplyTaskRunning: !!copyLastReplyTaskRunning,
        copyHotkeyContinueLoopRunning: !!copyHotkeyContinueLoopRunning,
      };
      const normalizedSendPhaseForFlags = normalizeSendTaskPhaseForModule(sendTask || {});
      const taskDerivedFlags = {
        uploadRunning: String(uploadTask && uploadTask.phase ? uploadTask.phase : 'idle').trim().toLowerCase() !== 'idle',
        waitingSend: (
          normalizedSendPhaseForFlags === 'waiting_send'
          || normalizedSendPhaseForFlags === 'waiting_page_reply_to_send'
        ),
        waitingReply: normalizedSendPhaseForFlags === 'waiting_reply',
        messageSending: normalizedSendPhaseForFlags === 'sending',
      };

      // Diagnostic only: do NOT use legacy flags to override task-driven UI.
      try {
        const uploadPhase = String(uploadTask && uploadTask.phase ? uploadTask.phase : 'idle').trim().toLowerCase();
        const sendPhase = String(sendTask && sendTask.phase ? sendTask.phase : 'idle').trim().toLowerCase();

        const taskFlags = {
          running: taskDerivedFlags.uploadRunning,
          waitingSend: taskDerivedFlags.waitingSend,
          waitingReply: taskDerivedFlags.waitingReply,
          messageSending: taskDerivedFlags.messageSending,
        };

        const mismatch = (
          taskFlags.running !== legacyFlags.running
          || taskFlags.waitingSend !== legacyFlags.waitingSend
          || taskFlags.waitingReply !== legacyFlags.waitingReply
          || taskFlags.messageSending !== legacyFlags.messageSending
        );

        if (mismatch) {
          const now = Date.now();
          const lastAt = getUnifiedRuntimeStatus._lastConflictAt || 0;
          if (now - lastAt >= 5000) {
            getUnifiedRuntimeStatus._lastConflictAt = now;
            const line = `[STATE_CONFLICT][LEGACY_TASK_MISMATCH] legacy=${JSON.stringify(legacyFlags)} task={uploadPhase:${uploadPhase},sendPhase:${sendPhase}}`;
            if (typeof ToolboxShell !== 'undefined' && typeof ToolboxShell.appendLog === 'function') {
              ToolboxShell.appendLog(line);
            } else {
              console.warn(line);
            }
          }
        }
      } catch (err) {
        console.error('[ChatGPT toolbox] getUnifiedRuntimeStatus conflict check failed', err);
      }

      const pageStatus = {
        pageDisplayId: getBridgePageDisplayIdText(),
        reason: String(reason || ''),
        at: Date.now(),
      };

      return {
        reason: String(reason || ''),
        at: Date.now(),
        pageStatus,
        capability,
        uploadQueue,
        uploadQuota,
        messageQuota,
        legacyFlags,
        taskDerivedFlags,
        uploadTask: uploadTask || { phase: 'idle', runId: '', cancelRequested: false },
        sendTask: sendTask || { phase: 'idle', runId: '', cancelRequested: false },
        copyTask: copyTask || { phase: 'idle', runId: '', cancelRequested: false },
        batchTask,
      };
    }

    let lastToolboxTopStatusSignature = '';
    let lastToolboxTopStatusHeavyAt = 0;
    let lastTopStatusSlotsLogAt = 0;

    const TOP_STATUS_SLOT_ORDER = [
      'reply-state',
      'page-id',
      'turn-count',
      'upload-usage',
      'message-usage',
      'top-status-spacer',
      'task-state',
      'attachment-state',
      'alert-state',
      'compact-mode',
    ];

    const TOP_STATUS_SLOT_EXTRA_CLASSES = {
      'reply-state': 'cgpt-status-pill cgpt-toolbox-status-primary-badge',
      'page-id': 'cgpt-toolbox-page-id-badge',
      'turn-count': 'cgpt-toolbox-turn-count-badge cgpt-toolbox-page-turn-badge cgpt-toolbox-must-show-badge cgpt-page-count-badge',
      'upload-usage': 'cgpt-toolbox-upload-quota-badge cgpt-toolbox-low-priority-badge cgpt-top-stat-secondary cgpt-local-upload-badge',
      'message-usage': 'cgpt-toolbox-message-quota-badge cgpt-toolbox-low-priority-badge cgpt-top-stat-secondary cgpt-local-message-badge',
      'task-state': 'cgpt-top-badge cgpt-top-badge-task',
      'attachment-state': 'cgpt-top-badge-attachment',
      'alert-state': 'cgpt-top-status-alert',
      'compact-mode': 'cgpt-top-status-compact-mode',
    };

    function applyTopStatusSlotVariant(el, variant) {
      if (!el) {
        return;
      }
      const nextVariant = variant || 'muted';
      el.dataset.variant = nextVariant;
      el.classList.remove(
        'cgpt-top-status-variant-ok',
        'cgpt-top-status-variant-danger',
        'cgpt-top-status-variant-warning',
        'cgpt-top-status-variant-info',
        'cgpt-top-status-variant-muted',
      );
      el.classList.add(`cgpt-top-status-variant-${nextVariant}`);
    }

    function reorderTopStatusSlots(statusRoot) {
      if (!statusRoot) {
        return;
      }
      TOP_STATUS_SLOT_ORDER.forEach((slotName) => {
        const el = statusRoot.querySelector(`[data-top-status-slot="${slotName}"]`);
        if (el) {
          statusRoot.appendChild(el);
        }
      });
    }

    function ensureTopStatusSlot(statusRoot, slotName, className = '') {
      if (!statusRoot || !slotName) {
        return null;
      }

      if (slotName === 'top-status-spacer') {
        let spacerEl = statusRoot.querySelector('[data-top-status-slot="top-status-spacer"]');
        if (!spacerEl) {
          spacerEl = document.createElement('div');
          spacerEl.dataset.topStatusSlot = 'top-status-spacer';
          spacerEl.className = 'cgpt-top-status-spacer';
          statusRoot.appendChild(spacerEl);
        }
        reorderTopStatusSlots(statusRoot);
        return spacerEl;
      }

      let el = statusRoot.querySelector(`[data-top-status-slot="${slotName}"]`);

      if (slotName === 'alert-state' && !el) {
        const legacyReminderEl = statusRoot.querySelector('[data-top-status-slot="reminder"]');
        if (legacyReminderEl) {
          el = legacyReminderEl;
        }
      }

      if (slotName === 'reply-state' && !el) {
        el = statusRoot.querySelector('#cgpt-page-input-state');
      }

      if (!el) {
        el = document.createElement('span');
        if (slotName === 'reply-state') {
          el.id = 'cgpt-page-input-state';
        }
        statusRoot.appendChild(el);
      }

      el.dataset.topStatusSlot = slotName;
      const extraClasses = TOP_STATUS_SLOT_EXTRA_CLASSES[slotName] || '';
      el.className = `cgpt-top-status-badge cgpt-toolbox-top-status-badge ${extraClasses} ${className}`.trim();
      el.hidden = false;
      el.style.display = '';
      reorderTopStatusSlots(statusRoot);
      return el;
    }

    function ensureAllTopStatusSlots(statusRoot) {
      TOP_STATUS_SLOT_ORDER.forEach((slotName) => {
        ensureTopStatusSlot(statusRoot, slotName);
      });
      reorderTopStatusSlots(statusRoot);
      statusRoot.classList.add('cgpt-top-status-row');
    }

    function updateTopStatusSlot(statusRoot, slotName, options = {}) {
      const {
        text = '',
        title = '',
        variant = 'muted',
        hidden = false,
        extraClass = '',
        stateClass = '',
      } = options;
      const el = ensureTopStatusSlot(statusRoot, slotName, extraClass);
      if (!el) {
        return null;
      }
      el.textContent = text;
      el.title = title || text;
      applyTopStatusSlotVariant(el, variant);
      const isHidden = Boolean(hidden);
      el.classList.toggle('is-hidden-placeholder', isHidden);
      if (slotName === 'alert-state') {
        el.style.display = isHidden ? 'none' : '';
      }
      if (stateClass) {
        [
          'cgpt-state-ready',
          'cgpt-state-waiting',
          'cgpt-state-sending',
          'cgpt-state-answering',
          'cgpt-state-generating',
          'cgpt-state-blocked',
          'cgpt-state-offline',
          'cgpt-state-unknown',
          'cgpt-state-blocked',
          'cgpt-state-waiting',
        ].forEach((cls) => el.classList.remove(cls));
        el.classList.add(stateClass);
      }
      return el;
    }

    function getTopStatusPanelWidth() {
      const panelEl = document.getElementById(APP.panelId);
      if (!panelEl) {
        return 0;
      }
      const rect = panelEl.getBoundingClientRect();
      return Math.round(rect.width || panelEl.offsetWidth || 0);
    }

    function resolveReplyStateSlot(runtimeSnapshot) {
      const capability = runtimeSnapshot.capability && typeof runtimeSnapshot.capability === 'object'
        ? runtimeSnapshot.capability
        : {};
      const bridgePollConnected = !!(
        typeof BridgePollRuntime !== 'undefined'
        && BridgePollRuntime
        && BridgePollRuntime.bridge_connected === true
      );
      const bridgeConnected = !!(
        capability.bridge_connected
        || capability.bridgeConnected
        || bridgePollConnected
      );
      const online = capability.online !== false;

      if (!bridgeConnected || !online) {
        return {
          text: '离线',
          variant: 'muted',
          title: 'Bridge / 页面不可用或未连接',
          stateClass: 'cgpt-state-offline',
        };
      }

      const responseState = String(
        capability.response_state || capability.responseState || '',
      ).trim().toLowerCase();
      const responseReason = String(
        capability.response_state_reason || capability.responseStateReason || '',
      ).trim().toLowerCase();
      const bridgePollState = (
        typeof BridgePollRuntime !== 'undefined'
        && BridgePollRuntime
        && typeof BridgePollRuntime === 'object'
      )
        ? BridgePollRuntime
        : {};
      const effectiveResponseState = responseState || String(
        bridgePollState.response_state || bridgePollState.responseState || '',
      ).trim().toLowerCase();
      const effectiveResponseReason = responseReason || String(
        bridgePollState.response_state_reason || bridgePollState.responseStateReason || '',
      ).trim().toLowerCase();

      if (effectiveResponseState === 'generating' || effectiveResponseState === 'responding') {
        return {
          text: '回答中',
          variant: 'danger',
          title: 'ChatGPT 正在生成回复',
          stateClass: 'cgpt-state-answering',
        };
      }

      if (
        effectiveResponseState === 'attachment_processing'
        || effectiveResponseReason === 'attachment_processing'
      ) {
        return {
          text: '附件中',
          variant: 'warning',
          title: '附件正在处理，等待完成后可发送',
          stateClass: 'cgpt-state-waiting',
        };
      }

      if (
        effectiveResponseState === 'not_ready'
        && (
          effectiveResponseReason === 'home_new_chat_payload_but_send_button_missing'
          || effectiveResponseReason === 'send_button_not_found'
        )
      ) {
        return {
          text: '待发送',
          variant: 'warning',
          title: '输入框有内容，等待 ChatGPT 发送按钮可用',
          stateClass: 'cgpt-state-waiting',
        };
      }

      const inputable = !!(
        capability.can_accept_input
        || capability.canAcceptInput
        || capability.inputable === true
        || capability.inputable === 1
        || (
          typeof BridgePollRuntime !== 'undefined'
          && BridgePollRuntime
          && (BridgePollRuntime.inputable === true || BridgePollRuntime.inputable === 1)
        )
      );
      const sendable = !!(
        capability.can_send_now
        || capability.canSendNow
        || capability.sendable === true
        || capability.sendable === 1
        || (
          typeof BridgePollRuntime !== 'undefined'
          && BridgePollRuntime
          && (BridgePollRuntime.sendable === true || BridgePollRuntime.sendable === 1)
        )
      );
      const canSendNow = !!(
        capability.can_send_now
        || capability.canSendNow
      );
      const readyOverride =
        effectiveResponseState === 'ready'
        && effectiveResponseReason === 'home_new_chat_composer_ready_override';

      if (effectiveResponseState === 'ready' || sendable || canSendNow || readyOverride) {
        return {
          text: inputable || sendable ? '可输入' : '就绪',
          variant: 'ok',
          title: effectiveResponseState === 'ready'
            ? '当前页面已就绪，可以发送'
            : '当前页面可以发送',
          stateClass: 'cgpt-state-ready',
        };
      }

      if (inputable) {
        return {
          text: '可输入',
          variant: 'ok',
          title: '当前页面可以输入',
          stateClass: 'cgpt-state-ready',
        };
      }

      if (
        effectiveResponseState === 'idle'
        && (
          effectiveResponseReason === 'empty_composer'
          || effectiveResponseReason === 'composer_empty'
        )
      ) {
        return {
          text: '可输入',
          variant: 'ok',
          title: '输入框为空，可以输入新消息',
          stateClass: 'cgpt-state-ready',
        };
      }

      if (effectiveResponseState === 'idle' || effectiveResponseState === 'ready') {
        return {
          text: '可输入',
          variant: 'ok',
          title: '当前页面已就绪',
          stateClass: 'cgpt-state-ready',
        };
      }

      if (!inputable && !sendable && effectiveResponseState !== 'idle' && effectiveResponseState !== 'ready') {
        return {
          text: '不可用',
          variant: 'warning',
          title: '当前页面无法输入或发送',
          stateClass: 'cgpt-state-blocked',
        };
      }

      return {
        text: '可输入',
        variant: 'ok',
        title: '当前页面可以输入',
        stateClass: 'cgpt-state-ready',
      };
    }

    function resolveTaskStateSlot(runtimeSnapshot, useCompactText = false) {
      const sendTask = runtimeSnapshot.sendTask && typeof runtimeSnapshot.sendTask === 'object'
        ? runtimeSnapshot.sendTask
        : {};
      const uploadTask = runtimeSnapshot.uploadTask && typeof runtimeSnapshot.uploadTask === 'object'
        ? runtimeSnapshot.uploadTask
        : {};
      const copyTask = runtimeSnapshot.copyTask && typeof runtimeSnapshot.copyTask === 'object'
        ? runtimeSnapshot.copyTask
        : {};
      const taskFlags = runtimeSnapshot.taskDerivedFlags && typeof runtimeSnapshot.taskDerivedFlags === 'object'
        ? runtimeSnapshot.taskDerivedFlags
        : {};
      const legacyFlags = runtimeSnapshot.legacyFlags && typeof runtimeSnapshot.legacyFlags === 'object'
        ? runtimeSnapshot.legacyFlags
        : {};

      const sendPhase = String(sendTask.phase || '').trim().toLowerCase();
      const uploadPhase = String(uploadTask.phase || '').trim().toLowerCase();
      const copyPhase = String(copyTask.phase || '').trim().toLowerCase();

      if (
        sendPhase === 'waiting_reply'
        || taskFlags.waitingReply
        || legacyFlags.waitingReply
      ) {
        return {
          text: useCompactText ? '等回复' : '等待回复',
          variant: 'danger',
          title: '已发送，等待 ChatGPT 回复',
        };
      }

      if (
        sendPhase === 'sending'
        || sendPhase === 'running'
        || taskFlags.messageSending
        || legacyFlags.messageSending
      ) {
        return {
          text: '发送中',
          variant: 'danger',
          title: '消息正在发送中',
        };
      }

      if (
        uploadPhase === 'running'
        || uploadPhase === 'uploading'
        || taskFlags.uploadRunning
        || legacyFlags.running
      ) {
        return {
          text: '上传中',
          variant: 'warning',
          title: '文件正在上传中',
        };
      }

      if (
        copyPhase === 'running'
        || legacyFlags.copyLastReplyTaskRunning
        || legacyFlags.copyHotkeyContinueLoopRunning
      ) {
        return {
          text: '处理中',
          variant: 'info',
          title: '复制/热键任务处理中',
        };
      }

      if (
        typeof AutoQueueModule !== 'undefined'
        && AutoQueueModule
        && typeof AutoQueueModule.getCurrentTaskBadgeText === 'function'
      ) {
        const batchText = String(AutoQueueModule.getCurrentTaskBadgeText() || '').trim();
        if (batchText) {
          return {
            text: '处理中',
            variant: 'info',
            title: batchText,
          };
        }
      }

      return {
        text: '空闲',
        variant: 'muted',
        title: '当前无运行中任务',
      };
    }

    function resolveAttachmentStateSlot(runtimeSnapshot, useCompactText = false) {
      let composerCount = 0;
      let composerUploading = false;
      let composerReady = 0;

      try {
        const snap = getComposerAttachmentState({ reason: 'top-status-attachment-slot' });
        const summarized = summarizeComposerStateForUploadHeal(snap);
        composerCount = summarized.composerCount;
        composerUploading = summarized.composerUploading;
        composerReady = summarized.composerReady ? 1 : 0;
      } catch (err) {
        console.error('[ChatGPT toolbox] resolveAttachmentStateSlot failed', err);
      }

      const capability = runtimeSnapshot.capability && typeof runtimeSnapshot.capability === 'object'
        ? runtimeSnapshot.capability
        : {};
      const responseState = String(
        capability.response_state || capability.responseState || '',
      ).trim().toLowerCase();
      const responseReason = String(
        capability.response_state_reason || capability.responseStateReason || '',
      ).trim().toLowerCase();
      const isAttachmentProcessing = responseState === 'attachment_processing'
        || responseReason.includes('attachment');

      if (composerUploading) {
        return {
          text: '上传中',
          variant: 'warning',
          title: '附件正在上传到 Composer',
        };
      }

      if (composerCount > 0 || composerReady > 0 || isAttachmentProcessing) {
        return {
          text: '附件中',
          variant: 'warning',
          title: 'Composer 中有附件',
        };
      }

      return {
        text: useCompactText ? '附件' : '无附件',
        variant: 'muted',
        title: '当前无附件',
      };
    }

    function resolveAlertStateSlot() {
      let alertEntry = {
        visible: false,
        text: '',
        title: '',
        variant: 'muted',
      };
      if (
        typeof ToolboxShell !== 'undefined'
        && typeof ToolboxShell.getCurrentTopAlertEntry === 'function'
      ) {
        alertEntry = ToolboxShell.getCurrentTopAlertEntry();
      }
      return {
        text: alertEntry.visible ? alertEntry.text : '',
        title: alertEntry.title || '',
        variant: alertEntry.variant || 'muted',
        hidden: !alertEntry.visible,
        level: alertEntry.level || '',
      };
    }

    function resolveCompactModeStateSlot() {
      const compact = (
        typeof ToolboxShell !== 'undefined'
        && typeof ToolboxShell.isCompactMode === 'function'
        && ToolboxShell.isCompactMode()
      );
      return {
        text: compact ? '完整' : '简洁',
        variant: compact ? 'info' : 'muted',
        title: compact ? '当前为简洁模式，可切换到完整模式' : '当前为完整模式，可切换到简洁模式',
      };
    }

    function logTopStatusSlots(slotTexts, reason) {
      const now = Date.now();
      if (now - lastTopStatusSlotsLogAt < 3000) {
        return;
      }
      lastTopStatusSlotsLogAt = now;

      const order = TOP_STATUS_SLOT_ORDER.join(',');
      ToolboxShell.appendLog(
        `[TOOLBOX_TOP_STATUS][SLOTS]\n`
        + `reply=${slotTexts['reply-state'] || '-'}\n`
        + `page=${slotTexts['page-id'] || '-'}\n`
        + `turn=${slotTexts['turn-count'] || '-'}\n`
        + `upload=${slotTexts['upload-usage'] || '-'}\n`
        + `message=${slotTexts['message-usage'] || '-'}\n`
        + `task=${slotTexts['task-state'] || '-'}\n`
        + `attachment=${slotTexts['attachment-state'] || '-'}\n`
        + `alert=${slotTexts['alert-state'] || '-'}\n`
        + `compact=${slotTexts['compact-mode'] || '-'}\n`
        + `order=${order}\n`
        + `reason=${reason || '-'}`,
      );
    }

    function syncToolboxHeaderLayoutFromUpload(reason = 'renderToolboxTopStatus') {
      if (
        typeof ToolboxShell !== 'undefined'
        && typeof ToolboxShell.syncToolboxHeaderLayout === 'function'
      ) {
        ToolboxShell.syncToolboxHeaderLayout(reason);
      }
    }

    function renderToolboxPageStatusRow(options = {}) {
      let pageStatusRowEl = document.getElementById('cgpt-toolbox-page-status-row');

      if (!pageStatusRowEl) {
        if (
          typeof ToolboxShell !== 'undefined'
          && typeof ToolboxShell.ensureToolboxHeaderPageStatusRow === 'function'
        ) {
          pageStatusRowEl = ToolboxShell.ensureToolboxHeaderPageStatusRow();
        }
      }

      if (!pageStatusRowEl) {
        return;
      }

      ensureAllTopStatusSlots(pageStatusRowEl);

      const pageDisplayId = getBridgePageDisplayIdText();
      const stats = getCurrentConversationSnapshotStatsForHeader();

      const statsRound = stats
        ? Math.max(Number(stats.round_count || 0), Number(stats.dom_estimated_round_count || 0))
        : 0;
      const domEstimatedRound = stats
        ? Number(stats.dom_estimated_round_count || 0)
        : 0;

      logConversationTurnCountIfChanged(domEstimatedRound, 'renderToolboxPageStatusRow');

      let roundCount = statsRound;
      if (roundCount <= 0 && typeof getCurrentPageTurnCount === 'function') {
        const fallbackRound = Number(getCurrentPageTurnCount()) || 0;
        if (fallbackRound > 0) {
          ToolboxShell.appendLog(
            `[TOOLBOX_TOP_STATUS][TURN_FALLBACK] statsRound=${statsRound} fallbackRound=${fallbackRound} reason=renderToolboxPageStatusRow`,
          );
          roundCount = fallbackRound;
        }
      }

      const pageIdText = `页ID:${pageDisplayId}`;
      const pageIdTitle = `页面ID:${pageDisplayId}`;
      const roundText = `轮数:${roundCount}`;
      const roundTitle = `页面轮数:${roundCount}（当前对话已完成轮数）`;

      const runtimeSnapshot = (
        typeof getUnifiedRuntimeStatus === 'function'
      )
        ? getUnifiedRuntimeStatus('renderToolboxPageStatusRow')
        : {
            uploadQuota: getUploadQuotaState(),
            messageQuota: getMessageQuotaState(),
            capability: {},
            uploadQueue: {},
            legacyFlags: {},
            taskDerivedFlags: {},
            sendTask: { phase: 'idle' },
            uploadTask: { phase: 'idle' },
            copyTask: { phase: 'idle' },
          };
      const uploadQuota = runtimeSnapshot.uploadQuota && typeof runtimeSnapshot.uploadQuota === 'object'
        ? runtimeSnapshot.uploadQuota
        : getUploadQuotaState();
      const messageQuota = runtimeSnapshot.messageQuota && typeof runtimeSnapshot.messageQuota === 'object'
        ? runtimeSnapshot.messageQuota
        : getMessageQuotaState();
      const responseState = String(
        (runtimeSnapshot.capability && (runtimeSnapshot.capability.response_state || runtimeSnapshot.capability.responseState))
        || '-',
      );
      const QUOTA_WARN_UPLOAD_REMAINING = 5;
      const QUOTA_WARN_MESSAGE_REMAINING = 10;

      const uploadQuotaRemaining = Math.max(0, Number(uploadQuota.remaining) || 0);
      const messageQuotaRemaining = Math.max(0, Number(messageQuota.remaining) || 0);

      const uploadIsFullWait = uploadQuotaRemaining <= 0;
      const messageIsFullWait = messageQuotaRemaining <= 0;

      const uploadIsWarn = !uploadIsFullWait && uploadQuotaRemaining <= QUOTA_WARN_UPLOAD_REMAINING;
      const messageIsWarn = !messageIsFullWait && messageQuotaRemaining <= QUOTA_WARN_MESSAGE_REMAINING;

      const uploadStatusLabel = uploadIsFullWait
        ? '已满等待'
        : (uploadIsWarn ? '即将满额' : '可上传');

      const messageStatusLabel = messageIsFullWait
        ? '已满等待'
        : (messageIsWarn ? '即将满额' : '可上传');

      const uploadBadgeStateClass = uploadIsFullWait
        ? 'cgpt-state-blocked'
        : (uploadIsWarn ? 'cgpt-state-waiting' : '');

      const messageBadgeStateClass = messageIsFullWait
        ? 'cgpt-state-blocked'
        : (messageIsWarn ? 'cgpt-state-waiting' : '');

      const panelWidthForQuotaText = getTopStatusPanelWidth();
      const useCompactQuotaText = panelWidthForQuotaText > 0 && panelWidthForQuotaText < 520;
      pageStatusRowEl.classList.toggle('cgpt-top-status-compact', useCompactQuotaText);

      const uploadQuotaText = useCompactQuotaText
        ? `上传:${uploadQuota.used}/${uploadQuota.maxFiles}`
        : `本地上传:${uploadQuota.used}/${uploadQuota.maxFiles}`;

      const messageQuotaText = useCompactQuotaText
        ? `消息:${messageQuota.used}/${messageQuota.maxMessages}`
        : `本地消息:${messageQuota.used}/${messageQuota.maxMessages}`;

      const uploadReleaseText = uploadQuota.remaining <= 0
        ? formatQuotaReleaseCountdown(uploadQuota.nextReleaseAt)
        : '可立即使用';
      const messageReleaseText = messageQuota.remaining <= 0
        ? formatQuotaReleaseCountdown(messageQuota.nextReleaseAt)
        : '可立即使用';

      const uploadNextReleaseTitle = uploadIsFullWait
        ? (uploadReleaseText === '即将释放' ? '即将释放' : `${uploadReleaseText} 后`)
        : '可立即使用';

      const messageNextReleaseTitle = messageIsFullWait
        ? (messageReleaseText === '即将释放' ? '即将释放' : `${messageReleaseText} 后`)
        : '可立即使用';

      const uploadQuotaTitle = `全局上传统计（今日所有标签页共享）：已用：${uploadQuota.used}/${uploadQuota.maxFiles}；剩余：${uploadQuotaRemaining}；重置：今日 24:00；下一条释放：${uploadNextReleaseTitle}；状态：${uploadStatusLabel}。该额度是工具箱全局统计，不代表 ChatGPT 官方真实额度。`;
      const messageQuotaTitle = `全局消息统计（今日所有标签页共享）：已用：${messageQuota.used}/${messageQuota.maxMessages}；剩余：${messageQuotaRemaining}；重置：今日 24:00；下一条释放：${messageNextReleaseTitle}；状态：${messageStatusLabel}。该额度是工具箱全局统计，不代表 ChatGPT 官方真实额度。`;

      const replyState = resolveReplyStateSlot(runtimeSnapshot);
      const taskState = resolveTaskStateSlot(runtimeSnapshot, useCompactQuotaText);
      const attachmentState = resolveAttachmentStateSlot(runtimeSnapshot, useCompactQuotaText);
      const alertState = resolveAlertStateSlot();
      const compactState = resolveCompactModeStateSlot();

      const signature = [
        replyState.text,
        pageIdText,
        roundText,
        uploadQuotaText,
        messageQuotaText,
        taskState.text,
        attachmentState.text,
        alertState.hidden ? '-' : alertState.text,
        compactState.text,
        replyState.variant,
        taskState.variant,
        attachmentState.variant,
        alertState.variant,
        alertState.hidden ? 'hidden' : 'visible',
        uploadBadgeStateClass,
        messageBadgeStateClass,
      ].join('|');

      const forceRender = !!(options && options.force === true);
      if (!forceRender && signature === lastToolboxTopStatusSignature) {
        if (typeof renderToolboxHeaderStatus === 'function') {
          renderToolboxHeaderStatus('renderToolboxPageStatusRow-skip');
        }
        syncToolboxHeaderLayoutFromUpload('renderToolboxPageStatusRow-skip');
        return;
      }
      lastToolboxTopStatusSignature = signature;

      // 清理旧版动态任务 badge，避免与固定 task-state 槽位重复。
      const legacyTaskBadge = pageStatusRowEl.querySelector('#cgpt-top-current-task-badge');
      if (legacyTaskBadge) {
        legacyTaskBadge.remove();
      }

      updateTopStatusSlot(pageStatusRowEl, 'reply-state', {
        text: replyState.text,
        title: replyState.title,
        variant: replyState.variant,
        stateClass: replyState.stateClass || '',
      });

      updateTopStatusSlot(pageStatusRowEl, 'page-id', {
        text: pageIdText,
        title: pageIdTitle,
        variant: 'ok',
      });

      updateTopStatusSlot(pageStatusRowEl, 'turn-count', {
        text: roundText,
        title: roundTitle,
        variant: 'info',
      });

      updateTopStatusSlot(pageStatusRowEl, 'upload-usage', {
        text: uploadQuotaText,
        title: uploadQuotaTitle,
        variant: uploadIsFullWait ? 'danger' : (uploadIsWarn ? 'warning' : 'muted'),
        extraClass: uploadBadgeStateClass,
      });

      updateTopStatusSlot(pageStatusRowEl, 'message-usage', {
        text: messageQuotaText,
        title: messageQuotaTitle,
        variant: messageIsFullWait ? 'danger' : (messageIsWarn ? 'warning' : 'muted'),
        extraClass: messageBadgeStateClass,
      });

      updateTopStatusSlot(pageStatusRowEl, 'task-state', {
        text: taskState.text,
        title: taskState.title,
        variant: taskState.variant,
      });

      updateTopStatusSlot(pageStatusRowEl, 'attachment-state', {
        text: attachmentState.text,
        title: attachmentState.title,
        variant: attachmentState.variant,
      });

      updateTopStatusSlot(pageStatusRowEl, 'alert-state', {
        text: alertState.text,
        title: alertState.title,
        variant: alertState.variant,
        hidden: alertState.hidden,
      });

      if (
        typeof ToolboxShell !== 'undefined'
        && typeof ToolboxShell.logTopAlertEntry === 'function'
      ) {
        ToolboxShell.logTopAlertEntry(
          {
            visible: !alertState.hidden,
            text: alertState.text,
            title: alertState.title,
            variant: alertState.variant,
            level: alertState.level,
          },
          options && options.reason ? String(options.reason) : 'render',
        );
      }

      updateTopStatusSlot(pageStatusRowEl, 'compact-mode', {
        text: compactState.text,
        title: compactState.title,
        variant: compactState.variant,
      });

      reorderTopStatusSlots(pageStatusRowEl);

      if (typeof ChatInputStateRuntime !== 'undefined' && ChatInputStateRuntime) {
        ChatInputStateRuntime.lastTopStatusText = replyState.text;
        ChatInputStateRuntime.lastTopStatusType = replyState.variant;
      }

      if (typeof renderToolboxHeaderStatus === 'function') {
        renderToolboxHeaderStatus('renderToolboxPageStatusRow');
      }
      syncToolboxHeaderLayoutFromUpload('renderToolboxPageStatusRow');

      const slotTexts = {
        'reply-state': replyState.text,
        'page-id': pageIdText,
        'turn-count': roundText,
        'upload-usage': uploadQuotaText,
        'message-usage': messageQuotaText,
        'task-state': taskState.text,
        'attachment-state': attachmentState.text,
        'alert-state': alertState.hidden ? '-' : alertState.text,
        'compact-mode': compactState.text,
      };
      logTopStatusSlots(
        slotTexts,
        options && options.reason ? String(options.reason) : 'render',
      );

      logToolboxPageAndGlobalUsageStatus({
        reason: options && options.reason ? String(options.reason) : 'render-slots',
        pageDisplayId,
        roundCount,
        responseState,
        uploadQuota,
        messageQuota,
      });
    }

    let lastGlobalUsageTopRenderLogAt = 0;

    function logToolboxPageAndGlobalUsageStatus(payload = {}) {
      const now = Date.now();
      if (now - lastGlobalUsageTopRenderLogAt < 3000) {
        return;
      }
      lastGlobalUsageTopRenderLogAt = now;

      const pageDisplayId = payload.pageDisplayId != null ? payload.pageDisplayId : '-';
      const roundCount = payload.roundCount != null ? payload.roundCount : '-';
      const responseState = payload.responseState != null ? payload.responseState : '-';
      const uploadQuota = payload.uploadQuota || getUploadQuotaState();
      const messageQuota = payload.messageQuota || getMessageQuotaState();
      const reason = payload.reason || '-';
      const dayKey = uploadQuota.dayKey
        || messageQuota.dayKey
        || (typeof GlobalUsageStore !== 'undefined' && typeof GlobalUsageStore.getTodayUsageDayKey === 'function'
          ? GlobalUsageStore.getTodayUsageDayKey()
          : '-');

      ToolboxShell.appendLog(
        `[PAGE_STATUS][RENDER] pageDisplayId=${pageDisplayId} pageTurn=${roundCount} `
        + `responseState=${responseState} reason=${reason}`,
      );
      ToolboxShell.appendLog(
        `[GLOBAL_USAGE][TOP_RENDER] reason=${reason} messageUsed=${messageQuota.used} `
        + `messageLimit=${messageQuota.maxMessages} uploadUsed=${uploadQuota.used} uploadLimit=${uploadQuota.maxFiles} `
        + `dayKey=${dayKey}`,
      );
    }

    function renderToolboxTopStatus(options = {}) {
      const heavy = options && options.heavy === true;
      const force = options && options.force === true;
      const reason = options && options.reason ? String(options.reason) : '-';
      if (heavy && shouldSkipHeavyUploadRenderDuringAutoQueueWaitingReply(reason)) {
        renderToolboxPageStatusRow({ heavy: false, force, reason });
        syncToolboxHeaderLayoutFromUpload(`renderToolboxTopStatus-skip-heavy:${reason}`);
        return;
      }
      const now = Date.now();
      if (heavy && !force && now - lastToolboxTopStatusHeavyAt < 3000) {
        renderToolboxPageStatusRow({ heavy: false, force, reason });
        syncToolboxHeaderLayoutFromUpload(`renderToolboxTopStatus-throttle:${reason}`);
        return;
      }
      renderToolboxPageStatusRow({ heavy, force, reason });
      if (heavy) {
        lastToolboxTopStatusHeavyAt = now;
        renderProjectCategoryChips();
      }
      if (typeof renderToolboxHeaderStatus === 'function') {
        renderToolboxHeaderStatus(`renderToolboxTopStatus:${reason || '-'}`);
      }
      syncToolboxHeaderLayoutFromUpload(`renderToolboxTopStatus:${reason}`);
    }

    function setStatus(text, type, options) {
      const opts = options || {};
      ToolboxShell.setStatus(text, type, {
        ...opts,
        owner: opts.owner || 'upload',
        source: opts.source || (opts.owner === 'upload' || !opts.owner ? 'real-upload' : ''),
      });
    }

    function updateItem(id, patch) {
      const q = state.queue.find((x) => x.id === id);
      if (!q) return;
      const inputPatch = patch && typeof patch === 'object' ? patch : {};

      if (
        q.state === UploadState.CANCELLED &&
        state.cancelled &&
        inputPatch.state &&
        inputPatch.state !== UploadState.CANCELLED
      ) {
        return;
      }

      const normalizedPatch = normalizeUploadItem({
        ...q,
        ...inputPatch,
      }, {
        groupId: q.groupId || state.activeGroupId,
      });

      Object.assign(q, normalizedPatch);

      if (normalizedPatch.state === UploadState.ATTACHED) {
        q.attachedInSession = true;

        if (Object.prototype.hasOwnProperty.call(normalizedPatch, 'persistedAttached')) {
          q.persistedAttached = !!normalizedPatch.persistedAttached;
        } else {
          q.persistedAttached = true;
        }
      }

      if (
        normalizedPatch.state &&
        UploadStateUtils &&
        typeof UploadStateUtils.isFinal === 'function' &&
        UploadStateUtils.isFinal(normalizedPatch.state)
      ) {
        window.setTimeout(() => {
          const healed = healStaleUploadRunningLockIfNeeded(`updateItem-final-state:${normalizedPatch.state}`);

          if (healed) {
            render();
            if (!(typeof isToolboxPageNavigating === 'function' && isToolboxPageNavigating())) {
              persistQueueInBackground(`updateItem-final-state:${normalizedPatch.state}`);
            }
          }
        }, 300);
      }

      const skipPersistWhileNavigating = typeof isToolboxPageNavigating === 'function'
        && isToolboxPageNavigating();

      const itemDomUpdated = updateUploadListItemDom(q.id, 'updateItem');

      if (state.running) {
        scheduleRenderUpload('updateItem');
        if (!itemDomUpdated) {
          scheduleRenderUploadListOnly('updateItem:fallback-list', 1000);
        }
        if (!skipPersistWhileNavigating) {
          schedulePersistQueueItem(q, 'updateItem');
        }
      } else {
        if (itemDomUpdated) {
          renderUploadButtonsOnly({
            heavy: false,
            buttonTasksReason: 'updateItem:item-only',
          });
        } else {
          render();
        }
        if (!skipPersistWhileNavigating) {
          schedulePersistQueueItem(q, 'updateItem');
        }
      }
    }

    function isUploadCancelled(runId, signal) {
      return state.cancelled ||
        runId !== state.runId ||
        (signal && signal.aborted);
    }

    const NATIVE_UPLOAD_ERROR_SELECTORS = [
      // 仅扫描可能的 toast/alert/upload-error 区域
      '[role="alert"]',
      '[data-testid*="toast"]',
      '[data-testid*="upload-error"]',
      '[aria-label*="上传失败"]',
      '[aria-label*="Upload failed"]',
    ].join(', ');

    const NATIVE_UPLOAD_ERROR_PATTERNS = [
      // 强匹配：只认文件服务器域名或明确的英文/失败描述
      /files\.oaiusercontent\.com/i,
      /上传到\s*files\.oaiusercontent\.com\s*失败/i,
      /upload\s+failed/i,
      /couldn'?t\s+upload/i,
      /failed\s+to\s+upload/i,
    ];

    function detectChatGPTNativeUploadError() {
      try {
        if (
          typeof ComposerAttachments !== 'undefined'
          && ComposerAttachments
          && typeof ComposerAttachments.detectNativeUploadError === 'function'
        ) {
          const pick = ComposerAttachments.detectNativeUploadError();
          if (pick && pick.hasError) {
            return {
              ok: false,
              reason: 'native-upload-failed',
              message: String(pick.errorText || '').slice(0, 500),
            };
          }
          return null;
        }

        if (typeof UploadCriticalRuntime !== 'undefined'
          && UploadCriticalRuntime
          && typeof UploadCriticalRuntime.detectChatGptUploadErrorToast === 'function') {
          const toastPick = UploadCriticalRuntime.detectChatGptUploadErrorToast({ minIntervalMs: 800 });
          if (toastPick && toastPick.ok) {
            return {
              ok: false,
              reason: 'native-upload-failed',
              message: String(toastPick.message || '').slice(0, 500),
            };
          }
        }

        return null;
      } catch (error) {
        const errText = error && error.message ? error.message : String(error);
        console.error('[ChatGPT toolbox] detectChatGPTNativeUploadError failed', error);
        if (typeof ToolboxShell !== 'undefined' && typeof ToolboxShell.appendLog === 'function') {
          ToolboxShell.appendLog(`[UPLOAD_NATIVE][DETECT_ERROR] error=${errText}`);
        }
        return null;
      }
    }

    function isNativeSendReadyForUpload() {
      return !!(
        typeof ComposerCapability !== 'undefined'
        && ComposerCapability
        && typeof ComposerCapability.isNativeSendReadyForUpload === 'function'
        && ComposerCapability.isNativeSendReadyForUpload({ source: 'unified/native-send-ready' })
      );
    }

    async function waitChatGPTNativeUploadSettled(files, options = {}) {
      if (
        typeof UploadNativeRuntime !== 'undefined'
        && UploadNativeRuntime
        && typeof UploadNativeRuntime.waitChatGPTNativeUploadSettled === 'function'
      ) {
        return UploadNativeRuntime.waitChatGPTNativeUploadSettled(files, {
          ...options,
          detectNativeUploadError: detectChatGPTNativeUploadError,
        });
      }
      return { ok: false, reason: 'native-upload-settle-timeout' };
    }

    async function waitComposerAttachmentReady(options = {}) {
      const timeoutMs = Number(options.timeoutMs || 120000);
      const pollMs = 500;
      const stableMs = 1300;
      const startedAt = Date.now();
      let loggedWaitSnapshot = false;
      let loggedAttachmentWaitingDetail = false;

      const initialStillUploading = !!(
        typeof ComposerApi !== 'undefined'
        && typeof ComposerApi.isAttachmentStillUploading === 'function'
        && ComposerApi.isAttachmentStillUploading()
      );
      const initialHasAttachment = !!(
        (typeof ComposerApi !== 'undefined'
          && typeof ComposerApi.countAttachmentChipsFast === 'function'
          && ComposerApi.countAttachmentChipsFast() > 0)
        || (typeof ComposerApi !== 'undefined'
          && typeof ComposerApi.hasVisibleComposerAttachmentPayload === 'function'
          && ComposerApi.hasVisibleComposerAttachmentPayload())
        || (typeof ComposerApi !== 'undefined'
          && typeof ComposerApi.hasComposerAttachmentUnified === 'function'
          && ComposerApi.hasComposerAttachmentUnified())
      );
      if (!initialStillUploading && !initialHasAttachment) {
        ToolboxShell.appendLog('[SEND][SKIP_ATTACHMENT_WAIT] reason=text-only-payload');
        return { ok: true, reason: 'no-attachment-payload' };
      }

      const pickNativeUploadError = () => {
        if (
          typeof ComposerApi !== 'undefined'
          && typeof ComposerApi.detectChatGPTNativeUploadError === 'function'
        ) {
          return ComposerApi.detectChatGPTNativeUploadError();
        }
        return detectChatGPTNativeUploadError();
      };

      const expectedNames = [
        options.originalName,
        options.displayName,
        options.canonicalName,
        options.fileName,
        options.name,
      ].filter(Boolean);

      const pickStillUploading = () => !!(
        typeof ComposerApi !== 'undefined'
        && typeof ComposerApi.isAttachmentStillUploading === 'function'
        && ComposerApi.isAttachmentStillUploading({ expectedNames })
      );

      const pickAttachmentReady = () => {
        if (isUploadActuallyReadyInComposer(`wait-composer-attachment:${String(options.source || '-')}`)) {
          return true;
        }
        return !!(
          typeof ComposerApi !== 'undefined'
          && typeof ComposerApi.isAttachmentReadyInComposer === 'function'
          && ComposerApi.isAttachmentReadyInComposer({
            expectedNames,
            requireSendReady: false,
          })
        );
      };

      const pickHasAttachment = () => !!(
        (typeof ComposerApi !== 'undefined'
          && typeof ComposerApi.countAttachmentChipsFast === 'function'
          && ComposerApi.countAttachmentChipsFast() > 0)
        || (typeof ComposerApi !== 'undefined'
          && typeof ComposerApi.hasVisibleComposerAttachmentPayload === 'function'
          && ComposerApi.hasVisibleComposerAttachmentPayload())
        || (typeof ComposerApi !== 'undefined'
          && typeof ComposerApi.hasComposerAttachmentUnified === 'function'
          && ComposerApi.hasComposerAttachmentUnified())
      );

      while (Date.now() - startedAt < timeoutMs) {
        if (options.signal && options.signal.aborted) {
          return { ok: false, reason: 'cancelled' };
        }
        if (typeof options.isCancelled === 'function' && options.isCancelled()) {
          return { ok: false, reason: 'cancelled' };
        }
        if (isSendMessageTaskAborted()) {
          return { ok: false, reason: 'cancelled' };
        }

        try {
          if (
            typeof UploadCriticalRuntime !== 'undefined'
            && UploadCriticalRuntime
            && typeof UploadCriticalRuntime.detectChatGptUploadErrorToast === 'function'
          ) {
            const toastPick = UploadCriticalRuntime.detectChatGptUploadErrorToast({ minIntervalMs: 800 });
            if (toastPick && toastPick.ok) {
              ToolboxShell.appendLog(
                `[UPLOAD_PLATFORM_ERROR][DETECTED] domain=files.oaiusercontent.com message=${toastPick.message || '-'} phase=waitComposerAttachmentReady`,
              );
              return {
                ok: false,
                reason: 'files-oaiusercontent-upload-failed',
                detail: toastPick.message || '',
              };
            }
          }
        } catch (err) {
          console.error('[ChatGPT toolbox] platform toast detect failed in waitComposerAttachmentReady', err);
        }

        const nativeErr = pickNativeUploadError();
        if (nativeErr && nativeErr.ok === false) {
          ToolboxShell.appendLog(
            `[UPLOAD_NATIVE][FAILED] message=${nativeErr.message || '-'} phase=waitComposerAttachmentReady`,
          );
          return {
            ok: false,
            reason: 'native-upload-failed',
            detail: nativeErr.message || '',
          };
        }

        const stillUploading = pickStillUploading();
        const attachmentReady = pickAttachmentReady();
        const hasAttachment = pickHasAttachment() || attachmentReady;
        const sendReady = isNativeSendReadyForUpload();
        const elapsed = Date.now() - startedAt;

        if (!loggedWaitSnapshot && elapsed > 2500) {
          loggedWaitSnapshot = true;
          ToolboxShell.appendLog(
            `[UPLOAD][WAIT] uploading=${stillUploading ? 1 : 0} ready=${attachmentReady ? 1 : 0} sendReady=${sendReady ? 1 : 0} elapsed=${elapsed}`,
          );
        }

        if (hasAttachment && sendReady) {
          ToolboxShell.appendLog(
            `[SEND][NATIVE_READY_BYPASS_ATTACHMENT_WAIT] uploading=${stillUploading ? 1 : 0} attachmentReady=${attachmentReady ? 1 : 0} hasAttachment=${hasAttachment ? 1 : 0} sendReady=${sendReady ? 1 : 0} elapsed=${elapsed}`,
          );
          return {
            ok: true,
            reason: 'native-send-ready-bypass-attachment-wait',
          };
        }

        if (stillUploading) {
          if (!loggedAttachmentWaitingDetail && elapsed > 3000) {
            loggedAttachmentWaitingDetail = true;
            let textPreview = '';
            if (typeof ComposerApi !== 'undefined' && typeof ComposerApi.collectAttachmentChipText === 'function') {
              textPreview = ComposerApi.collectAttachmentChipText().slice(0, 500);
            }
            ToolboxShell.appendLog(
              `[UPLOAD][ATTACHMENT_WAITING] reason=still-uploading textPreview=${textPreview}`,
            );
          }
          ToolboxShell.appendLog(
            `[SEND][WAIT_ATTACHMENT_UPLOAD] reason=still-uploading sendReady=${sendReady ? 1 : 0} source=${String(options.source || '-')}`,
          );
          if (sendReady) {
            ToolboxShell.appendLog(
              `[SEND][NATIVE_READY_BYPASS_ATTACHMENT_WAIT] uploading=${stillUploading ? 1 : 0} attachmentReady=${attachmentReady ? 1 : 0} hasAttachment=${hasAttachment ? 1 : 0} sendReady=${sendReady ? 1 : 0} elapsed=${elapsed}`,
            );
            return {
              ok: true,
              reason: 'native-send-ready-bypass-attachment-wait',
            };
          }
          await sleep(pollMs);
          continue;
        }

        await sleep(pollMs);
      }

      if (pickAttachmentReady()) {
        ToolboxShell.appendLog(
          `[UPLOAD][ATTACHMENT_READY] reason=attachment-ready-at-timeout elapsed=${Date.now() - startedAt}`,
        );
        return {
          ok: true,
          reason: 'attachment-ready-at-timeout',
        };
      }

      ToolboxShell.appendLog(
        `[UPLOAD][TIMEOUT] file=${expectedNames.join('|') || '-'} elapsed=${Date.now() - startedAt}`,
      );
      return {
        ok: false,
        reason: 'attachment-ready-timeout',
      };
    }

    function getBridgeCapabilitySnapshot(source) {
      if (typeof getPageCapability === 'function') {
        return getPageCapability(`upload-heal:${source || '-'}`);
      }
      if (typeof getUploadPageCapabilityLight === 'function') {
        return getUploadPageCapabilityLight();
      }
      return null;
    }

    function clearStaleUploadReadyCachesForHeal(source) {
      if (typeof clearComposerAttachmentEvidenceCache === 'function') {
        clearComposerAttachmentEvidenceCache(`upload-heal:${source || '-'}`);
      }
      if (typeof clearUploadInputCache === 'function') {
        clearUploadInputCache(`upload-heal:${source || '-'}`);
      }
      if (typeof resetComposerDetectionReentryGuard === 'function') {
        resetComposerDetectionReentryGuard(`upload-heal:${source || '-'}`);
      }
      if (typeof invalidateComposerResponseStateCache === 'function') {
        invalidateComposerResponseStateCache(`upload-heal:${source || '-'}`);
      }
      ToolboxShell.appendLog(
        `[UPLOAD_HEAL][CLEAR_READY_CACHE] source=${source || '-'}`,
      );
    }

    function safeSetExistingProperty(target, key, value, source) {
      if (!target || typeof target !== 'object') {
        return false;
      }
      if (!Object.prototype.hasOwnProperty.call(target, key)) {
        ToolboxShell.appendLog(
          `[UPLOAD_HEAL][SAFE_SET_SKIP_MISSING] source=${source || '-'} key=${key}`,
        );
        return false;
      }
      if (!Object.isExtensible(target) && !Object.prototype.hasOwnProperty.call(target, key)) {
        ToolboxShell.appendLog(
          `[UPLOAD_HEAL][SAFE_SET_SKIP_NON_EXTENSIBLE] source=${source || '-'} key=${key}`,
        );
        return false;
      }
      try {
        target[key] = value;
        return true;
      } catch (err) {
        const msg = err && err.message ? err.message : String(err);
        ToolboxShell.appendLog(
          `[UPLOAD_HEAL][SAFE_SET_ERROR] source=${source || '-'} key=${key} error=${msg}`,
        );
        return false;
      }
    }

    function clearStaleUploadRunningFlagsForHeal(source) {
      const safeSource = String(source || '-');
      if (typeof setUploadButtonState === 'function') {
        setUploadButtonState('idle', `upload-heal-clear-stale:${safeSource}`);
      }
      if (typeof UploadState !== 'undefined' && UploadState && typeof UploadState === 'object') {
        safeSetExistingProperty(UploadState, 'running', false, safeSource);
        safeSetExistingProperty(UploadState, 'manualUploadRunning', false, safeSource);
        safeSetExistingProperty(UploadState, 'uploadingFromAutoQueue', false, safeSource);
      }
      safeSetExistingProperty(state, 'manualUploadImmediateBusy', false, safeSource);
      safeSetExistingProperty(state, 'manualUploadImmediateBusySource', '', safeSource);
      safeSetExistingProperty(state, 'uploadingFromAutoQueue', false, safeSource);
      safeSetExistingProperty(state, 'running', false, safeSource);
      ToolboxShell.appendLog(
        `[UPLOAD_HEAL][CLEAR_STALE_UPLOAD_FLAGS] source=${safeSource}`,
      );
    }

    function findCurrentComposerRootForUploadHeal(source) {
      const roots = Array.from(document.querySelectorAll(
        'form, [data-testid="composer"], [contenteditable="true"], textarea',
      ));
      let best = null;
      for (const el of roots) {
        const rect = el.getBoundingClientRect ? el.getBoundingClientRect() : null;
        if (!rect || rect.width <= 0 || rect.height <= 0) {
          continue;
        }
        const root = el.closest('form') || el.closest('[data-testid="composer"]') || el.parentElement;
        if (root) {
          best = root;
        }
      }
      ToolboxShell.appendLog(
        `[UPLOAD_HEAL][COMPOSER_ROOT] source=${source || '-'} found=${best ? 1 : 0}`,
      );
      return best;
    }

    function findUploadFilesInputForComposerHeal(composerRoot, source) {
      const selectors = [
        'input#upload-files[type="file"]',
        'input[type="file"][multiple]',
        'input[type="file"]',
      ];
      const scopes = [];
      if (composerRoot) {
        scopes.push(composerRoot);
      }
      scopes.push(document);
      for (const scope of scopes) {
        for (const selector of selectors) {
          const candidates = Array.from(scope.querySelectorAll(selector));
          for (const input of candidates) {
            const accept = String(input.getAttribute('accept') || '');
            const id = String(input.id || '');
            const html = String(input.outerHTML || '').slice(0, 180);
            const isFileInput = input && input.type === 'file';
            const isGenericFileInput = !accept || accept.includes('*') || id === 'upload-files';
            if (isFileInput && isGenericFileInput) {
              ToolboxShell.appendLog(
                `[UPLOAD_HEAL][INPUT_CANDIDATE_OK] source=${source || '-'} id=${id || '-'} accept=${accept || '-'} html=${html}`,
              );
              return input;
            }
            ToolboxShell.appendLog(
              `[UPLOAD_HEAL][INPUT_CANDIDATE_SKIP] source=${source || '-'} id=${id || '-'} accept=${accept || '-'}`,
            );
          }
        }
      }
      return null;
    }

    function clickAttachButtonForUploadHeal(source) {
      const buttons = Array.from(document.querySelectorAll('button, [role="button"]'));
      for (const btn of buttons) {
        const text = String(btn.innerText || btn.getAttribute('aria-label') || btn.getAttribute('title') || '');
        const lower = text.toLowerCase();
        const looksLikeAttach = text.includes('添加文件')
          || text.includes('上传文件')
          || text.includes('附件')
          || lower.includes('attach')
          || lower.includes('upload file');
        if (!looksLikeAttach) {
          continue;
        }
        const rect = btn.getBoundingClientRect ? btn.getBoundingClientRect() : null;
        if (!rect || rect.width <= 0 || rect.height <= 0) {
          continue;
        }
        btn.click();
        ToolboxShell.appendLog(
          `[UPLOAD_HEAL][CLICK_ATTACH_BUTTON] source=${source || '-'} text=${text}`,
        );
        return true;
      }
      ToolboxShell.appendLog(
        `[UPLOAD_HEAL][CLICK_ATTACH_BUTTON_NOT_FOUND] source=${source || '-'}`,
      );
      return false;
    }

    async function healUploadComposerReadyBeforeAttach(source) {
      const sourceText = String(source || '-');
      ToolboxShell.appendLog(
        `[UPLOAD_HEAL][BEFORE_ATTACH_ENTER] source=${sourceText}`,
      );
      const evidenceBefore = typeof ComposerAttachments !== 'undefined'
        && ComposerAttachments
        && typeof ComposerAttachments.getSharedComposerAttachmentEvidence === 'function'
        ? ComposerAttachments.getSharedComposerAttachmentEvidence(`upload-heal-before:${sourceText}`)
        : null;
      const bridgeState = getBridgeCapabilitySnapshot(`upload-heal-before:${sourceText}`);
      ToolboxShell.appendLog(
        `[UPLOAD_HEAL][SNAPSHOT_BEFORE] source=${sourceText} `
        + `hasAttachment=${evidenceBefore && evidenceBefore.hasAttachment ? 1 : 0} `
        + `uploading=${evidenceBefore && evidenceBefore.uploading ? 1 : 0} `
        + `nativeUploading=${evidenceBefore && evidenceBefore.nativeUploading ? 1 : 0} `
        + `bridgeResponseState=${bridgeState && bridgeState.response_state ? bridgeState.response_state : '-'} `
        + `bridgeReason=${bridgeState && bridgeState.response_state_reason ? bridgeState.response_state_reason : '-'}`,
      );
      clearStaleUploadReadyCachesForHeal(sourceText);
      clearStaleUploadRunningFlagsForHeal(sourceText);
      const composerRoot = findCurrentComposerRootForUploadHeal(sourceText);
      const input = findUploadFilesInputForComposerHeal(composerRoot, sourceText);
      if (input) {
        ToolboxShell.appendLog(
          `[UPLOAD_HEAL][INPUT_FOUND] source=${sourceText} id=${input.id || '-'} multiple=${input.multiple ? 1 : 0}`,
        );
        return {
          ok: true,
          reason: 'input-found',
          composerRootFound: !!composerRoot,
          inputFound: true,
        };
      }
      const attachClicked = clickAttachButtonForUploadHeal(sourceText);
      if (attachClicked) {
        await new Promise((resolve) => setTimeout(resolve, 300));
      }
      const inputAfterClick = findUploadFilesInputForComposerHeal(composerRoot, `${sourceText}:after-click`);
      if (inputAfterClick) {
        ToolboxShell.appendLog(
          `[UPLOAD_HEAL][INPUT_FOUND_AFTER_CLICK] source=${sourceText} id=${inputAfterClick.id || '-'}`,
        );
        return {
          ok: true,
          reason: 'input-found-after-click',
          composerRootFound: !!composerRoot,
          inputFound: true,
        };
      }
      ToolboxShell.appendLog(
        `[UPLOAD_HEAL][INPUT_NOT_READY] source=${sourceText} composerRootFound=${composerRoot ? 1 : 0}`,
      );
      return {
        ok: false,
        reason: 'upload_input_not_ready',
        composerRootFound: !!composerRoot,
        inputFound: false,
      };
    }

    function resetUploadStateAfterReadyTimeout(reason, source) {
      const safeReason = String(reason || 'timeout-wait-ready');
      const safeSource = String(source || '-');
      ToolboxShell.appendLog(
        `[UPLOAD_HEAL][RESET_AFTER_READY_TIMEOUT] reason=${safeReason} source=${safeSource}`,
      );
      clearStaleUploadRunningFlagsForHeal(`timeout:${safeSource}`);
      if (!isChildUploadContextForHeal()) {
        resetMainUploadRuntime(`upload-ready-timeout:${safeSource}`);
        reconcileUploadPhase(`upload-ready-timeout:${safeSource}`);
      }
      if (
        typeof AutoQueueModule !== 'undefined'
        && AutoQueueModule
        && typeof AutoQueueModule.resetUploadReadyTimeoutState === 'function'
      ) {
        AutoQueueModule.resetUploadReadyTimeoutState(safeReason, safeSource);
      } else {
        ToolboxShell.appendLog(
          `[UPLOAD_HEAL][AUTOQ_RESET_API_MISSING] reason=${safeReason} source=${safeSource}`,
        );
      }
      if (typeof setWaitingSendActive === 'function') {
        setWaitingSendActive(false);
      }
      if (typeof markTaskBatchStepRunning === 'function') {
        markTaskBatchStepRunning(false);
      }
    }

    function isChildUploadContextForHeal() {
      const task = state.uploadTask;
      return !!(task && String(task.parentTask || '').trim());
    }

    function normalizeComposerBlockedUploadReason(reason) {
      const text = String(reason || '').trim().toLowerCase();
      if (!text) {
        return 'composer_not_ready';
      }
      if (
        text === 'upload_input_not_ready'
        || text.includes('file_input')
        || text.includes('attach_entry')
        || text === 'composer_not_found'
        || text === 'composer_scope_not_found'
      ) {
        return 'upload_input_not_ready';
      }
      if (
        text === 'timeout-wait-ready'
        || text === 'composer_not_ready'
        || text.includes('composer')
        || text.includes('unstable')
        || text.includes('final-upload-blocked')
      ) {
        return 'composer_not_ready';
      }
      return reason;
    }

    function formatManualUploadFailureUserMessage(reason) {
      const normalized = String(reason || '').trim();
      if (normalized === 'timeout-wait-ready') {
        return '页面上传入口未就绪，已清理上传状态，请重试';
      }
      if (normalized === 'upload_input_not_ready') {
        return '未找到当前输入框的文件上传入口，请刷新页面或重新打开会话';
      }
      if (normalized === 'composer_not_ready' || normalized === 'final-upload-blocked-composer-not-ready') {
        return '页面上传入口未就绪，已清理上传状态，请重试';
      }
      if (normalized === 'no-files') {
        return '本地队列没有可上传文件';
      }
      return '';
    }

    async function waitChatGPTComposerReadyForUpload(options = {}) {
      const timeoutMs = Number(options.timeoutMs) || 120000;
      const pollMs = Number(options.pollMs) || 500;
      const stableMs = Number(options.stableMs) || 1500;
      const mode = String(options.mode || '');
      const source = String(options.source || '-');
      const uploadOnly = options.uploadOnly === true || mode === 'upload_only';
      const allowUploadOnlyDuringNativeUploading = options.allowUploadOnlyDuringNativeUploading === true || uploadOnly;
      const startedAt = Date.now();
      const deadline = startedAt + timeoutMs;
      const debugEnabled = isUploadDebugEnabled();
      if (debugEnabled) {
        ToolboxShell.appendLog(
          `[FINAL_UPLOAD][WAIT_COMPOSER_READY] timeoutMs=${timeoutMs} stableMs=${stableMs} pollMs=${pollMs} uploadOnly=${uploadOnly ? 1 : 0} allowUploadOnlyDuringNativeUploading=${allowUploadOnlyDuringNativeUploading ? 1 : 0}`,
        );
      }
      let lastBusyLogAt = 0;
      let lastNotReadyDetail = null;
      let lastBlockedLogAt = 0;
      let bypassLogged = false;
      let detectReenterSkipCount = 0;
      const getSnapshot = () => {
        const cap = typeof getUploadPageCapabilityLight === 'function'
          ? getUploadPageCapabilityLight()
          : null;
        return cap && typeof cap === 'object' ? cap : null;
      };
      const isElementUsable = (el) => {
        if (!el) return false;
        if (el.disabled) return false;
        if (typeof el.getAttribute === 'function') {
          const ariaDisabled = el.getAttribute('aria-disabled');
          if (String(ariaDisabled || '').trim().toLowerCase() === 'true') return false;
        }
        try {
          const rect = el.getBoundingClientRect();
          return rect.width > 0 && rect.height > 0;
        } catch (err) {
          const errText = err && err.message ? err.message : String(err);
          console.error('[ChatGPT toolbox] isElementUsable rect failed', err);
          ToolboxShell.appendLog(`[FINAL_UPLOAD][COMPOSER_READY_CHECK_ERROR] isElementUsable error=${errText}`);
          return false;
        }
      };
      const collectReadyContext = (cap) => {
        const hasComposerInput = !!(cap && cap.hasComposer);
        const nativeUploading = typeof ComposerApi !== 'undefined'
          && typeof ComposerApi.isAttachmentStillUploading === 'function'
          ? !!ComposerApi.isAttachmentStillUploading()
          : false;
        const composerRoot = typeof ComposerApi !== 'undefined'
          && typeof ComposerApi.getComposerRoot === 'function'
          ? ComposerApi.getComposerRoot()
          : null;
        const composer = typeof ComposerApi !== 'undefined'
          && typeof ComposerApi.getComposer === 'function'
          ? ComposerApi.getComposer()
          : null;
        const composerForm = composer instanceof HTMLElement ? composer.closest('form') : null;
        const composerScope = composerForm instanceof HTMLElement
          ? composerForm
          : (composerRoot instanceof HTMLElement ? composerRoot : null);
        const fileInputs = composerScope instanceof HTMLElement
          ? Array.from(composerScope.querySelectorAll('input[type="file"]'))
          : [];
        const fileInputUsable = fileInputs.some((input) => {
          if (!(input instanceof HTMLInputElement)) return false;
          if (input.disabled) return false;
          const ariaDisabled = input.getAttribute('aria-disabled');
          if (String(ariaDisabled || '').trim().toLowerCase() === 'true') return false;
          if (typeof isInToolbox === 'function' && isInToolbox(input)) return false;
          if (typeof isInsideConversationHistory === 'function' && isInsideConversationHistory(input)) return false;
          return true;
        });

        let attachmentEntryUsable = false;
        let uploadEntryReason = '';
        if (typeof resolveChatGPTUploadEntryReadyState === 'function') {
          const entryState = resolveChatGPTUploadEntryReadyState({
            source: `wait-composer-ready:${source}`,
            scope: composerScope instanceof HTMLElement ? composerScope : null,
          });
          uploadEntryReason = entryState && entryState.reason ? String(entryState.reason) : '';
          attachmentEntryUsable = !!(
            entryState
            && entryState.ok === true
            && entryState.reason !== 'file-input-ready'
          );
          if (entryState && entryState.ok === true && entryState.reason === 'file-input-ready') {
            // Hidden file inputs are injectable even when rect is zero.
          }
        } else if (composerScope instanceof HTMLElement && !fileInputUsable) {
          const candidates = Array.from(composerScope.querySelectorAll('button, [role="button"]'));
          attachmentEntryUsable = candidates.some((el) => {
            if (!isElementUsable(el)) return false;
            const text = (el.innerText || el.textContent || '').trim();
            const aria = (el.getAttribute && el.getAttribute('aria-label') ? el.getAttribute('aria-label') : '').trim();
            const title = (el.getAttribute && el.getAttribute('title') ? el.getAttribute('title') : '').trim();
            return (
              text.includes('添加')
              || text.includes('上传')
              || text.includes('Attach')
              || text.includes('Upload')
              || aria.includes('Attach')
              || aria.includes('Upload')
              || aria.includes('附件')
              || title.includes('Attach')
              || title.includes('Upload')
              || title.includes('附件')
            );
          });
        }

        const usable = uploadOnly
          ? (fileInputUsable || attachmentEntryUsable || composerScope instanceof HTMLElement)
          : (hasComposerInput && !nativeUploading && (fileInputUsable || attachmentEntryUsable));
        return {
          hasComposerInput,
          nativeUploading,
          composerScope,
          fileInputs,
          fileInputUsable,
          attachmentEntryUsable,
          uploadEntryReason,
          usable,
        };
      };
      const pickComposerBusy = (cap) => {
        const response_state = String(cap && cap.response_state ? cap.response_state : '');
        const response_state_reason = String(cap && cap.response_state_reason ? cap.response_state_reason : '');
        const stopBtnPresent = (
          typeof hasRealChatGPTStopGeneratingButton === 'function'
          && hasRealChatGPTStopGeneratingButton()
        );
        const assistantGenerating = (
          response_state === 'generating'
          || response_state === 'streaming'
          || response_state_reason === 'assistant_busy'
          || (typeof ComposerApi !== 'undefined'
            && typeof ComposerApi.isAssistantLikelyBusy === 'function'
            && ComposerApi.isAssistantLikelyBusy())
        );
        return { response_state, response_state_reason, stopBtnPresent, assistantGenerating };
      };
      while (Date.now() < deadline) {
        if (typeof options.shouldStop === 'function' && options.shouldStop()) {
          ToolboxShell.appendLog(
            `[FINAL_UPLOAD][COMPOSER_READY_ABORTED] reason=shouldStop source=${source}`,
          );
          return {
            ok: false,
            reason: 'cancelled',
            detail: {
              source,
              stage: 'wait-composer-ready',
            },
          };
        }
        if (options.signal && options.signal.aborted) {
          ToolboxShell.appendLog(
            `[FINAL_UPLOAD][COMPOSER_READY_ABORTED] reason=signal-aborted source=${source}`,
          );
          return {
            ok: false,
            reason: 'cancelled',
            detail: {
              source,
              stage: 'wait-composer-ready',
            },
          };
        }
        try {
          const cap = getSnapshot();
          if (cap && cap.response_state_reason === 'detect-reenter-skip') {
            detectReenterSkipCount += 1;
            ToolboxShell.appendLog(
              `[UPLOAD_HEAL][DETECT_REENTER_SKIP_COUNT] source=${source || '-'} count=${detectReenterSkipCount}`,
            );
            if (detectReenterSkipCount >= 3) {
              const healed = await healUploadComposerReadyBeforeAttach(`detect-reenter-skip:${source || '-'}`);
              ToolboxShell.appendLog(
                `[UPLOAD_HEAL][DETECT_REENTER_SKIP_HEAL_RESULT] source=${source || '-'} ok=${healed.ok ? 1 : 0} reason=${healed.reason || '-'}`,
              );
              detectReenterSkipCount = 0;
            }
          }
          const busy = pickComposerBusy(cap || {});
          const ctx = collectReadyContext(cap);
          const composerReadyNow = !busy.assistantGenerating && !busy.stopBtnPresent && ctx.usable;
          if (!composerReadyNow) {
            const now = Date.now();
            if (!lastBusyLogAt || now - lastBusyLogAt >= 2500) {
              lastBusyLogAt = now;
              const hasComposerFlag = !!ctx.hasComposerInput;
              const composerScopeOk = ctx.composerScope instanceof HTMLElement ? 1 : 0;
              const fileInputCount = ctx.fileInputs.length;
              const fileInputOk = ctx.fileInputUsable ? 1 : 0;
              const attachEntryOk = ctx.attachmentEntryUsable ? 1 : 0;
              let detailReason = 'composer_unstable_timeout';
              if (busy.assistantGenerating) {
                detailReason = 'assistant_generating';
              } else if (busy.stopBtnPresent) {
                detailReason = 'stop_button_present';
              } else if (ctx.nativeUploading && !(uploadOnly && allowUploadOnlyDuringNativeUploading)) {
                detailReason = 'native_attachment_uploading';
              } else if (!hasComposerFlag) {
                detailReason = 'composer_not_found';
              } else if (!composerScopeOk) {
                detailReason = 'composer_scope_not_found';
              } else if (fileInputCount <= 0 && attachEntryOk) {
                detailReason = 'file_input_not_found';
              } else if (fileInputCount > 0 && !fileInputOk) {
                detailReason = 'file_input_not_found';
              } else if (!attachEntryOk) {
                detailReason = 'attach_entry_not_found';
              }
              lastNotReadyDetail = {
                reason: detailReason,
                hasComposer: hasComposerFlag,
                composerScopeFound: !!composerScopeOk,
                fileInputFound: fileInputCount > 0,
                fileInputUsable: ctx.fileInputUsable,
                attachmentEntryFound: attachEntryOk ? true : false,
                attachmentEntryUsable: ctx.attachmentEntryUsable,
                assistantGenerating: !!busy.assistantGenerating,
                nativeUploading: !!ctx.nativeUploading,
                stopButtonPresent: !!busy.stopBtnPresent,
                url: location.href,
              };
              ToolboxShell.appendLog(
                `[FINAL_UPLOAD][COMPOSER_NOT_READY_DETAIL] uploadOnly=${uploadOnly ? 1 : 0} hasComposer=${hasComposerFlag ? 1 : 0} scope=${composerScopeOk} fileInputs=${fileInputCount} fileInputOk=${fileInputOk} attachEntry=${attachEntryOk} response_state=${busy.response_state || '-'} response_state_reason=${busy.response_state_reason || '-'} stopBtn=${busy.stopBtnPresent ? 1 : 0} assistantBusy=${busy.assistantGenerating ? 1 : 0} nativeUploading=${ctx.nativeUploading ? 1 : 0}`,
              );
              if (!lastBlockedLogAt || now - lastBlockedLogAt >= 1000) {
                lastBlockedLogAt = now;
                ToolboxShell.appendLog(
                  `[UPLOAD_TIMING][COMPOSER_READY_BLOCKED] cost=${now - startedAt}ms reason=${detailReason} nativeUploading=${ctx.nativeUploading ? 1 : 0} uploadOnly=${uploadOnly ? 1 : 0} source=${source}`,
                );
              }
            }
            await sleep(pollMs);
            continue;
          }
          if (uploadOnly && allowUploadOnlyDuringNativeUploading && ctx.nativeUploading && !bypassLogged) {
            bypassLogged = true;
            ToolboxShell.appendLog(
              `[FINAL_UPLOAD][UPLOAD_ONLY_BYPASS_NATIVE_UPLOADING] nativeUploading=1 fileInputOk=${ctx.fileInputUsable ? 1 : 0} attachEntry=${ctx.attachmentEntryUsable ? 1 : 0} hasComposer=${ctx.hasComposerInput ? 1 : 0} source=${source}`,
            );
          }
          if (typeof options.shouldStop === 'function' && options.shouldStop()) {
            ToolboxShell.appendLog(
              `[FINAL_UPLOAD][COMPOSER_READY_ABORTED] reason=shouldStop-before-stable source=${source}`,
            );
            return {
              ok: false,
              reason: 'cancelled',
              detail: {
                source,
                stage: 'wait-composer-ready-stable',
              },
            };
          }
          await sleep(stableMs);
          if (typeof options.shouldStop === 'function' && options.shouldStop()) {
            ToolboxShell.appendLog(
              `[FINAL_UPLOAD][COMPOSER_READY_ABORTED] reason=shouldStop-after-stable source=${source}`,
            );
            return {
              ok: false,
              reason: 'cancelled',
              detail: {
                source,
                stage: 'wait-composer-ready-stable',
              },
            };
          }
          const cap2 = getSnapshot();
          const busy2 = pickComposerBusy(cap2 || {});
          const ctx2 = collectReadyContext(cap2);
          const composerReadyAfterStable = !busy2.assistantGenerating && !busy2.stopBtnPresent && ctx2.usable;
          if (composerReadyAfterStable) {
            const nativeUploading2 = !!ctx2.nativeUploading;
            if (debugEnabled) {
              ToolboxShell.appendLog(
                `[FINAL_UPLOAD][COMPOSER_READY] response_state=${busy2.response_state || '-'} response_state_reason=${busy2.response_state_reason || '-'} stopBtn=${busy2.stopBtnPresent ? 1 : 0} nativeUploading=${nativeUploading2 ? 1 : 0} reason=composer-ready-for-upload`,
              );
            }
            ToolboxShell.appendLog(
              `[UPLOAD_TIMING][COMPOSER_READY_WAIT_DONE] cost=${Date.now() - startedAt}ms ok=1 reason=composer-ready-for-upload nativeUploading=${nativeUploading2 ? 1 : 0} uploadOnly=${uploadOnly ? 1 : 0}`,
            );
            return { ok: true, reason: 'composer-ready-for-upload' };
          }
        } catch (err) {
          const errText = err && err.message ? err.message : String(err);
          console.error('[ChatGPT toolbox] waitChatGPTComposerReadyForUpload failed', err);
          ToolboxShell.appendLog(`[FINAL_UPLOAD][COMPOSER_READY_CHECK_ERROR] error=${errText}`);
        }
        await sleep(pollMs);
      }
      if (debugEnabled) {
        ToolboxShell.appendLog(
          `[FINAL_UPLOAD][COMPOSER_READY_TIMEOUT] timeoutMs=${timeoutMs} reason=final-upload-blocked-composer-not-ready`,
        );
      }
      const finalReason = (lastNotReadyDetail && lastNotReadyDetail.reason)
        ? lastNotReadyDetail.reason
        : 'composer_unstable_timeout';
      ToolboxShell.appendLog(
        `[UPLOAD_TIMING][COMPOSER_READY_WAIT_DONE] cost=${Date.now() - startedAt}ms ok=0 reason=${finalReason} nativeUploading=${lastNotReadyDetail && lastNotReadyDetail.nativeUploading ? 1 : 0} uploadOnly=${uploadOnly ? 1 : 0}`,
      );
      return {
        ok: false,
        reason: finalReason,
        detail: lastNotReadyDetail,
      };
    }

    async function waitUntilComposerUploadIdle(options = {}) {
      const timeoutMs = Number(options.timeoutMs) || 30000;
      const runId = options.runId;
      const signal = options.signal;
      const deadline = Date.now() + timeoutMs;

      while (Date.now() < deadline) {
        if (isUploadCancelled(runId, signal)) {
          return false;
        }

        if (!ComposerApi.isAttachmentStillUploading()) {
          await sleep(800);

          if (!ComposerApi.isAttachmentStillUploading()) {
            return true;
          }
        }

        await sleep(500);
      }

      ToolboxShell.appendLog('[UPLOAD_DIAG][wait-upload-idle-timeout] 附件空闲检测超时，但文件状态已写入，继续结束上传流程');
      return false;
    }

    function areAllUploadTargetsSettled(targets) {
      const list = Array.isArray(targets) ? targets : [];
      if (!list.length) {
        return false;
      }
      return UploadStateUtils.allSettled(list);
    }

    function countUploadResult(targets) {
      const stats = UploadStateUtils.count(targets);
      return {
        success: stats.success,
        failed: stats.failed,
      };
    }

    function resolveUploadTargets(targets) {
      return (targets || [])
        .map((old) => state.queue.find((item) => item && old && item.id === old.id))
        .filter(Boolean);
    }

    function isCompactUploadView() {
      const panelEl = document.getElementById(APP.panelId);
      return !!(panelEl && panelEl.classList.contains('cgpt-toolbox-compact'));
    }

    function getCompactUiConfig() {
      if (typeof CompactUiConfigStore !== 'undefined' && typeof CompactUiConfigStore.get === 'function') {
        return CompactUiConfigStore.get();
      }
      if (typeof SettingsModule !== 'undefined' && typeof SettingsModule.getConfig === 'function') {
        return SettingsModule.getConfig();
      }
      const saved = MemoryManager.get(MemoryManager.KEYS.compactUiConfig, null) || {};
      return normalizeCompactUiConfig(saved);
    }

    function saveCompactUiConfigPatch(patch) {
      if (typeof CompactUiConfigStore !== 'undefined' && typeof CompactUiConfigStore.patch === 'function') {
        return CompactUiConfigStore.patch(patch || {});
      }
      const next = Object.assign({}, getCompactUiConfig(), patch || {});
      if (typeof SettingsModule !== 'undefined' && typeof SettingsModule.saveConfig === 'function') {
        SettingsModule.saveConfig(next);
        return next;
      }
      const normalized = normalizeCompactUiConfig(next);
      MemoryManager.set(MemoryManager.KEYS.compactUiConfig, normalized);
      return normalized;
    }

    function getUploadLoopMode() {
      const cfg = getCompactUiConfig();
      const value = String(cfg && cfg.uploadLoopMode ? cfg.uploadLoopMode : 'closed').trim();
      return value === 'open' ? 'open' : 'closed';
    }

    function isOpenLoopUploadMode() {
      return getUploadLoopMode() === 'open';
    }

    function isClosedLoopUploadMode() {
      return getUploadLoopMode() === 'closed';
    }

    function normalizeQuotaRecords(records, windowMs) {
      const now = Date.now();
      const windowValue = Math.max(1000, Number(windowMs) || 0);
      const list = Array.isArray(records) ? records : [];

      return list
        .filter((item) => {
          const ts = Number(item && (item.ts != null ? item.ts : item.at));
          return Number.isFinite(ts) && ts > 0 && now - ts < windowValue;
        })
        .sort((a, b) => {
          const tsA = Number(a && (a.ts != null ? a.ts : a.at)) || 0;
          const tsB = Number(b && (b.ts != null ? b.ts : b.at)) || 0;
          return tsA - tsB;
        });
    }

    function getUploadQuotaState(options = {}) {
      const snapshot = typeof GlobalUsageStore !== 'undefined'
        && typeof GlobalUsageStore.getGlobalUsageQuotaSnapshot === 'function'
        ? GlobalUsageStore.getGlobalUsageQuotaSnapshot('upload')
        : null;

      if (!snapshot) {
        const cfg = getCompactUiConfig();
        const maxFiles = typeof getUploadQuotaLimit === 'function'
          ? getUploadQuotaLimit()
          : Number(cfg.uploadQuotaMaxFiles || 80);
        return {
          windowMs: 0,
          maxFiles,
          limit: maxFiles,
          used: 0,
          remaining: maxFiles,
          canUpload: true,
          records: [],
          nextReleaseAt: 0,
          source: 'global-usage-unavailable',
        };
      }

      if (options.logSnapshot) {
        ToolboxShell.appendLog(
          `[GLOBAL_USAGE][UPLOAD][SNAPSHOT] used=${snapshot.used} limit=${snapshot.maxFiles} remaining=${snapshot.remaining} `
          + `records=${Array.isArray(snapshot.records) ? snapshot.records.length : 0} dayKey=${snapshot.dayKey || '-'} source=${snapshot.source}`,
        );
      }

      return snapshot;
    }

    function getMessageQuotaState(options = {}) {
      const snapshot = typeof GlobalUsageStore !== 'undefined'
        && typeof GlobalUsageStore.getGlobalUsageQuotaSnapshot === 'function'
        ? GlobalUsageStore.getGlobalUsageQuotaSnapshot('message')
        : null;

      if (!snapshot) {
        const cfg = getCompactUiConfig();
        const maxMessages = typeof getMessageQuotaLimit === 'function'
          ? getMessageQuotaLimit()
          : Number(cfg.messageQuotaMaxMessages || 150);
        return {
          windowMs: 0,
          maxMessages,
          limit: maxMessages,
          used: 0,
          remaining: maxMessages,
          canSend: true,
          records: [],
          nextReleaseAt: 0,
          source: 'global-usage-unavailable',
        };
      }

      if (options.logSnapshot) {
        ToolboxShell.appendLog(
          `[GLOBAL_USAGE][MESSAGE][SNAPSHOT] used=${snapshot.used} limit=${snapshot.maxMessages} remaining=${snapshot.remaining} `
          + `records=${Array.isArray(snapshot.records) ? snapshot.records.length : 0} dayKey=${snapshot.dayKey || '-'} source=${snapshot.source}`,
        );
      }

      return snapshot;
    }

    function clearUploadQuotaRecords(reason = 'manual') {
      const quota = getUploadQuotaState();
      if (typeof GlobalUsageStore !== 'undefined' && typeof GlobalUsageStore.clearGlobalUsageKind === 'function') {
        GlobalUsageStore.clearGlobalUsageKind('upload', String(reason || 'manual'));
      }
      ToolboxShell.appendLog(
        `[GLOBAL_USAGE][UPLOAD_CLEAR] reason=${String(reason || 'manual')} used_before=${quota.used}`,
      );
      renderToolboxTopStatus({ reason: `global-usage-upload-clear:${reason || 'manual'}` });
    }

    function clearMessageQuotaRecords(reason = 'manual') {
      const quotaBefore = getMessageQuotaState();
      if (typeof GlobalUsageStore !== 'undefined' && typeof GlobalUsageStore.clearGlobalUsageKind === 'function') {
        GlobalUsageStore.clearGlobalUsageKind('message', String(reason || 'manual'));
      }
      ToolboxShell.appendLog(
        `[GLOBAL_USAGE][MESSAGE_CLEAR] reason=${String(reason || 'manual')} used_before=${quotaBefore.used}`,
      );
      renderToolboxTopStatus({ reason: `global-usage-message-clear:${reason || 'manual'}` });
    }

    function formatQuotaReleaseCountdown(nextReleaseAt) {
      const target = Number(nextReleaseAt || 0);
      if (!Number.isFinite(target) || target <= 0) {
        return '可立即使用';
      }

      const waitMs = Math.max(0, target - Date.now());
      if (waitMs <= 0) {
        return '即将释放';
      }

      const totalSeconds = Math.ceil(waitMs / 1000);
      const hours = Math.floor(totalSeconds / 3600);
      const minutes = Math.floor((totalSeconds % 3600) / 60);
      const seconds = totalSeconds % 60;

      if (hours > 0) {
        return `${hours}小时${minutes}分`;
      }

      if (minutes > 0) {
        return `${minutes}分${seconds}秒`;
      }

      return `${seconds}秒`;
    }

    function formatDurationMsForButton(ms) {
      const value = Number(ms || 0);

      if (!Number.isFinite(value) || value <= 0) {
        return '0秒';
      }

      const totalSeconds = Math.ceil(value / 1000);
      const hours = Math.floor(totalSeconds / 3600);
      const minutes = Math.floor((totalSeconds % 3600) / 60);
      const seconds = totalSeconds % 60;

      if (hours > 0) {
        return `${hours}小时${minutes}分`;
      }

      if (minutes > 0) {
        return `${minutes}分${seconds}秒`;
      }

      return `${seconds}秒`;
    }

    function recordUploadSuccess(fileCountOrFiles, source = '', runId = '') {
      const src = String(source || 'unknown');
      const rid = String(runId || '');

      const afterInitialUploadBlock = blockUploadAfterInitialIfNeeded(src);
      if (afterInitialUploadBlock.blocked) {
        ToolboxShell.appendLog(
          `[GLOBAL_USAGE][UPLOAD_SKIP_BLOCKED_AFTER_INITIAL] source=${src || '-'} runId=${rid || '-'}`,
        );
        return;
      }

      const files = Array.isArray(fileCountOrFiles)
        ? fileCountOrFiles.filter(Boolean)
        : [];
      const count = files.length > 0
        ? files.length
        : Number(fileCountOrFiles || 0);

      if (!Number.isFinite(count) || count <= 0) {
        return;
      }

      if (typeof GlobalUsageStore === 'undefined' || typeof GlobalUsageStore.recordGlobalUploadUsage !== 'function') {
        ToolboxShell.appendLog('[GLOBAL_USAGE][UPLOAD_SKIP] reason=store-unavailable');
        return;
      }

      const recordOne = (file, index) => {
        const fileObj = file && typeof file === 'object' ? file : {
          name: `file-${index + 1}`,
          size: 0,
          lastModified: 0,
        };
        const fileFingerprint = GlobalUsageStore.buildFileFingerprint(fileObj);
        const eventId = GlobalUsageStore.buildUploadUsageEventId(fileObj, {
          runId: rid,
          fileFingerprint,
        });
        return GlobalUsageStore.recordGlobalUploadUsage({
          eventId,
          runId: rid,
          fileName: fileObj.name || '',
          fileSize: Number(fileObj.size || 0),
          fileFingerprint,
        });
      };

      if (files.length > 0) {
        let recorded = 0;
        files.forEach((file, index) => {
          const result = recordOne(file, index);
          if (result && result.ok && !result.dedup) {
            recorded += 1;
          }
        });
        ToolboxShell.appendLog(
          `[GLOBAL_USAGE][UPLOAD_RECORD_BATCH] source=${src} runId=${rid || '-'} requested=${files.length} recorded=${recorded}`,
        );
      } else {
        for (let i = 0; i < count; i += 1) {
          recordOne({ name: `batch-${rid || 'unknown'}-${i + 1}`, size: 0, lastModified: 0 }, i);
        }
        ToolboxShell.appendLog(
          `[GLOBAL_USAGE][UPLOAD_RECORD_COUNT] source=${src} runId=${rid || '-'} count=${count}`,
        );
      }

      const after = getUploadQuotaState({ logSnapshot: true });
      ToolboxShell.appendLog(
        `[GLOBAL_USAGE][UPLOAD_RECORD] source=${src} runId=${rid || '-'} used=${after.used} max=${after.maxFiles} remaining=${after.remaining}`,
      );
      renderToolboxTopStatus({ reason: `global-usage-upload-record:${src}` });
      scheduleRenderUpload('quota-record-upload-success');
    }

    function recordUploadSuccessOnce(fileCountOrFiles, source, runId) {
      recordUploadSuccess(fileCountOrFiles, source, runId);
    }

    function buildMessageUsageContext(context = {}) {
      const ctx = context && typeof context === 'object' ? context : {};
      const runId = String(
        ctx.runId
        || sendMessageTaskState.runId
        || (state.sendTask && state.sendTask.runId)
        || '',
      );
      let text = String(ctx.text || ctx.originalText || '');
      if (!text && typeof getSharedComposerTextTrimmed === 'function') {
        text = getSharedComposerTextTrimmed();
      }
      let attachmentCount = Number(ctx.attachmentCount);
      if (!Number.isFinite(attachmentCount)) {
        const attachmentEvidence = typeof ComposerAttachments !== 'undefined'
          && ComposerAttachments
          && typeof ComposerAttachments.getSharedComposerAttachmentEvidence === 'function'
          ? ComposerAttachments.getSharedComposerAttachmentEvidence('global-usage-message-context', { heavy: false })
          : null;
        attachmentCount = Math.max(0, Number(attachmentEvidence && attachmentEvidence.count) || 0);
      }

      const textHash = String(ctx.textHash || hashStringTiny(text));
      return {
        runId,
        text,
        textHash,
        attachmentCount,
        conversationId: String(ctx.conversationId || (typeof getCurrentPageConversationIdSafe === 'function' ? getCurrentPageConversationIdSafe() : '') || ''),
        pageInstanceId: String(
          ctx.pageInstanceId
          || (typeof getToolboxPageInstanceId === 'function' ? getToolboxPageInstanceId() : '')
          || '',
        ),
      };
    }

    function recordMessageSent(context = {}) {
      if (typeof GlobalUsageStore === 'undefined' || typeof GlobalUsageStore.recordGlobalMessageUsage !== 'function') {
        ToolboxShell.appendLog('[GLOBAL_USAGE][MESSAGE_SKIP] reason=store-unavailable');
        return { ok: false, reason: 'store-unavailable' };
      }

      const usageContext = buildMessageUsageContext(context);
      const eventId = GlobalUsageStore.buildMessageUsageEventId(usageContext);
      const result = GlobalUsageStore.recordGlobalMessageUsage(Object.assign({}, usageContext, { eventId }));

      const after = getMessageQuotaState({ logSnapshot: true });
      ToolboxShell.appendLog(
        `[GLOBAL_USAGE][MESSAGE_RECORD] eventId=${eventId} dedup=${result && result.dedup ? 1 : 0} `
        + `used=${after.used} max=${after.maxMessages} remaining=${after.remaining}`,
      );
      renderToolboxTopStatus({ reason: 'global-usage-message-record' });
      scheduleRenderUpload('quota-record-message-sent');
      return result;
    }

    // SINGLE SOURCE OF TRUTH: 3 小时消息额度（发送前统一走 waitChatRateLimitBeforeSend）
    const ChatRateLimiter = {
      get windowMs() {
        return getMessageQuotaState().windowMs;
      },
      get maxMessages() {
        return getMessageQuotaState().maxMessages;
      },
      get sentAtList() {
        return getMessageQuotaState().records;
      },
      cleanup(now = Date.now()) {
        void now;
        return getMessageQuotaState();
      },
      getUsedCount() {
        return getMessageQuotaState().used;
      },
      canSend() {
        return getMessageQuotaState().canSend;
      },
      getNextAvailableDelayMs() {
        const quota = getMessageQuotaState();
        if (quota.remaining > 0) {
          return 0;
        }
        const nextReleaseAt = Number(quota.nextReleaseAt) || 0;
        if (nextReleaseAt > Date.now()) {
          return Math.max(0, nextReleaseAt - Date.now());
        }
        const normalized = normalizeQuotaRecords(quota.records, quota.windowMs);
        const oldest = normalized.length
          ? Number(normalized[0].ts != null ? normalized[0].ts : normalized[0].at) || 0
          : 0;
        return oldest > 0 ? Math.max(0, oldest + quota.windowMs - Date.now()) : 0;
      },
      recordSend() {
        recordMessageSent();
      },
      toViewModel(now = Date.now()) {
        const quota = getMessageQuotaState();
        const used = quota.used;
        const remaining = quota.remaining;
        const delayMs = this.getNextAvailableDelayMs(now);
        return {
          used,
          remaining,
          maxMessages: quota.maxMessages,
          delayMs,
          delayText: formatDurationMsForButton(delayMs),
        };
      },
    };

    async function waitChatRateLimitBeforeSend() {
      const vm = ChatRateLimiter.toViewModel();

      if (vm.remaining > 0) {
        return { ok: true, reason: 'rate_limit_ok' };
      }

      ToolboxShell.appendLog(
        `[RATE_LIMIT][BLOCK] used=${vm.used}/${vm.maxMessages} remaining=${vm.remaining} wait=${vm.delayText}`,
      );

      return {
        ok: false,
        reason: 'rate_limit_reached',
        delayMs: vm.delayMs,
      };
    }

    function recordMessageSentAfterConfirmed(source = '', context = {}) {
      const sourceText = String(source || '').trim();
      recordMessageSent(context);
      if (
        isClosedLoopSource(sourceText)
        || (closedLoopContinueState && closedLoopContinueState.running)
        || copyHotkeyUploadVerifyLoopRunning
      ) {
        ToolboxShell.appendLog(
          `[UPLOAD_CADENCE][COUNT_SKIP] reason=closed-loop-message source=${sourceText || '-'}`,
        );
      } else {
        UploadCadencePolicy.recordMessageSent();
      }
      const vm = ChatRateLimiter.toViewModel();
      ToolboxShell.appendLog(
        `[GLOBAL_USAGE][MESSAGE_CONFIRMED] source=${sourceText || '-'} used=${vm.used}/${vm.maxMessages} remaining=${vm.remaining}`,
      );
    }

    const UploadCadencePolicy = {
      get enabled() {
        const cfg = getCompactUiConfig();
        return cfg.continueAutomation?.autoUploadEnabled !== false;
      },
      get uploadEveryMessages() {
        const cfg = getCompactUiConfig();
        const n = Number(cfg.continueAutomation?.autoUploadInterval || 5);
        return Number.isFinite(n) && n > 0 ? Math.floor(n) : 5;
      },
      messageCountSinceLastUpload: 0,
      recordMessageSent() {
        this.messageCountSinceLastUpload += 1;
      },
      recordUploadDone() {
        this.messageCountSinceLastUpload = 0;
      },
      shouldUploadBeforeNextSend() {
        if (!this.enabled) {
          return false;
        }
        return this.messageCountSinceLastUpload >= this.uploadEveryMessages;
      },
      toViewModel() {
        return {
          enabled: this.enabled,
          uploadEveryMessages: this.uploadEveryMessages,
          messageCountSinceLastUpload: this.messageCountSinceLastUpload,
          remainingBeforeUpload: Math.max(
            0,
            this.uploadEveryMessages - this.messageCountSinceLastUpload,
          ),
        };
      },
    };

    function isClosedLoopSource(source) {
      const text = String(source || '');
      return (
        text.includes('closed-loop')
        || text.includes('closedLoopContinue')
        || /^closed-loop-every5-\d+$/.test(text)
        || /^closed-loop-every-n-\d+$/.test(text)
        || /^closed-loop-every-round-\d+$/.test(text)
      );
    }

    function isCadenceContinueUploadSource(source) {
      const sourceText = String(source || '');
      return sourceText.includes('upload-cadence-policy')
        || sourceText.includes('cadence-upload')
        || sourceText.includes('auto-upload-cadence')
        || sourceText.includes('continue_with_upload')
        || sourceText.includes('send_continue_with_upload')
        || sourceText.includes('continue-with-upload')
        || sourceText.includes('auto-upload-every-n')
        || sourceText.includes('closed-loop-every5-upload')
        || sourceText.includes('closed-loop-hotkey-every5-upload')
        || sourceText.includes('closed-loop-every-n-upload')
        || sourceText.includes('closed-loop-hotkey-every-n-upload')
        || sourceText.includes('closed-loop-every-round-upload')
        || sourceText.includes('closed-loop-hotkey-every-round-upload');
    }

    async function prepareUploadByCadenceIfNeeded(context = {}) {
      const source = context && typeof context === 'object' ? context.source : '';
      const round = context && typeof context === 'object' ? context.round : 0;
      const closedLoopContinueRunning = !!(closedLoopContinueState && closedLoopContinueState.running);

      if (
        isClosedLoopSource(source)
        || closedLoopContinueRunning
        || copyHotkeyUploadVerifyLoopRunning
      ) {
        ToolboxShell.appendLog(
          `[UPLOAD_CADENCE][SKIP] reason=closed-loop-owns-upload source=${source || '-'} round=${round || '-'}`,
        );
        return {
          ok: true,
          skipped: true,
          reason: 'closed-loop-owns-upload',
        };
      }

      if (!UploadCadencePolicy.shouldUploadBeforeNextSend()) {
        return { ok: true, skipped: true, reason: 'cadence_not_reached' };
      }

      ToolboxShell.appendLog(
        `[UPLOAD_CADENCE][TRIGGER] count=${UploadCadencePolicy.messageCountSinceLastUpload} every=${UploadCadencePolicy.uploadEveryMessages}`,
      );

      const cadenceSource = 'upload-cadence-policy';
      const result = await startUploadOnlyFlow({ source: cadenceSource });

      if (result) {
        UploadCadencePolicy.recordUploadDone();
        return {
          ok: true,
          skipped: false,
          reason: 'cadence-upload-ok',
          source: cadenceSource,
        };
      }

      ToolboxShell.appendLog(
        `[UPLOAD_CADENCE][FAILED] source=${cadenceSource} reason=cadence-upload-failed`,
      );

      return {
        ok: false,
        skipped: false,
        blocked: true,
        reason: 'cadence-upload-failed',
        source: cadenceSource,
      };
    }

    function canStartNextTaskByQuota(task) {
      const uploadQuota = getUploadQuotaState();
      const messageQuota = getMessageQuotaState();
      const fileCount = getTaskUploadFileCountForQuota(task);
      const needMessageCount = 1;

      if (fileCount > uploadQuota.remaining) {
        return {
          ok: false,
          reason: 'upload-quota-exceeded',
          uploadRemaining: uploadQuota.remaining,
          messageRemaining: messageQuota.remaining,
          fileCount,
        };
      }

      if (needMessageCount > messageQuota.remaining) {
        return {
          ok: false,
          reason: 'message-quota-exceeded',
          uploadRemaining: uploadQuota.remaining,
          messageRemaining: messageQuota.remaining,
          fileCount,
        };
      }

      return {
        ok: true,
        uploadRemaining: uploadQuota.remaining,
        messageRemaining: messageQuota.remaining,
      };
    }

    function getTaskUploadFileCountForQuota(task) {
      void task;
      const pending = typeof getPendingUploadItems === 'function' ? getPendingUploadItems() : [];
      return Array.isArray(pending) ? pending.length : 0;
    }

    function normalizeQuickPromptCategoryName(value) {
      const text = String(value || '').trim();
      if (!text || text === '鍏ㄩ儴') {
        if (text === '鍏ㄩ儴') {
          console.info('[QUICK_PROMPT][CATEGORY][NORMALIZE_MOJIBAKE]', {
            from: text,
            to: '全部',
          });
        }
        return '全部';
      }
      return text;
    }

    function getQuickPromptActiveCategory() {
      if (typeof PromptCategoryState !== 'undefined'
        && typeof PromptCategoryState.getActiveCategory === 'function') {
        quickPromptActiveCategory = PromptCategoryState.getActiveCategory();
      }
      return normalizeQuickPromptCategoryName(quickPromptActiveCategory);
    }

    function saveQuickPromptActiveCategory(category, options = {}) {
      const nextCategory = normalizeQuickPromptCategoryName(category);
      quickPromptActiveCategory = nextCategory;

      if (typeof PromptCategoryState !== 'undefined'
        && typeof PromptCategoryState.setActiveCategory === 'function') {
        PromptCategoryState.setActiveCategory(nextCategory, {
          syncCompactUi: options.syncCompactUi !== false,
        });
      } else if (typeof MemoryManager !== 'undefined') {
        MemoryManager.set(
          MemoryManager.KEYS.promptManagerActiveCategory,
          nextCategory,
        );
        writeDataStorage("promptManagerActiveCategory", nextCategory);

        const cfg = getCompactUiConfig();
        const next = Object.assign({}, cfg, {
          quickPromptActiveCategory: nextCategory,
        });

        if (typeof SettingsModule !== 'undefined' && typeof SettingsModule.saveConfig === 'function') {
          SettingsModule.saveConfig(next);
        } else {
          MemoryManager.set(
            MemoryManager.KEYS.compactUiConfig,
            normalizeCompactUiConfig(next),
          );
        }
      }

      if (options.savePageState !== false) {
        saveCurrentToolboxBaseState(options.reason || 'quick-category-change');
      }
    }

    function getPromptCategoryName(prompt) {
      return normalizePromptCategoryName(prompt, '默认');
    }

    function getQuickPromptGroups(promptList) {
      if (typeof PromptManagerModule !== 'undefined'
        && typeof PromptManagerModule.getPromptCategoriesFromList === 'function') {
        return PromptManagerModule.getPromptCategoriesFromList(promptList);
      }

      const names = [];

      (promptList || []).forEach((p) => {
        const name = getPromptCategoryName(p);
        if (!names.includes(name)) {
          names.push(name);
        }
      });

      return ['全部', ...names];
    }

    function applyCompactUiVisibility() {
      if (!rootElRef) return;

      const cfg = getCompactUiConfig();
      const isCompact = isCompactUploadView();

      // Compact mode always keeps the group bar visible (product rule); full mode respects cfg.
      if (isCompact) {
        rootElRef.classList.remove('compact-hide-upload-groups');
      } else {
        rootElRef.classList.toggle('compact-hide-upload-groups', cfg.showUploadGroups === false);
      }

      rootElRef.classList.toggle('compact-hide-upload-start', isCompact && !cfg.showUploadStartButton);
      rootElRef.classList.toggle('compact-hide-file-list', isCompact && !cfg.showUploadFileList);
      const shouldShowQuick = isCompact
        ? cfg.showCompactQuickPrompts !== false
        : cfg.showUploadQuickPrompts !== false;

      rootElRef.classList.toggle('compact-hide-quick-prompts', !shouldShowQuick);
    }

    function shouldQuickPromptAutoSend(cfg) {
      if (QUICK_PROMPT_CLICK_AUTO_SEND !== true) {
        return false;
      }
      return cfg.quickPromptClickAction !== 'fill';
    }

    function normalizePromptPayload(prompt) {
      const rawText = String(prompt && prompt.content != null ? prompt.content : '');

      return {
        rawText,
        isEmpty: rawText.trim().length === 0,
      };
    }

    async function writeComposerDraftCore(text, options = {}) {
      const source = String(options.source || 'write-composer-draft').trim() || 'write-composer-draft';
      const content = String(text ?? '');
      const shouldStop = typeof options.shouldStop === 'function'
        ? options.shouldStop
        : () => false;

      if (blockComposerWriteIfOriginalAfterInitial(content, source)) {
        return { ok: false, reason: 'original_prompt_after_initial_blocked', blocked: true };
      }

      if (shouldStop()) {
        return { ok: false, reason: 'cancelled' };
      }

      if (
        typeof ComposerApi === 'undefined'
        || !ComposerApi
        || typeof ComposerApi.setComposerValue !== 'function'
      ) {
        return { ok: false, reason: 'composer-api-missing' };
      }

      const ok = ComposerApi.setComposerValue(content);
      if (!ok) {
        ToolboxShell.appendLog(`[COMPOSER_DRAFT][WRITE_FAILED] source=${source} reason=composer_set_failed`);
        return { ok: false, reason: 'composer-set-failed' };
      }

      if (typeof ComposerApi.waitForComposerTextSynced === 'function') {
        const synced = await ComposerApi.waitForComposerTextSynced(
          content,
          typeof SEND_TEXT_SYNC_TIMEOUT_MS === 'number' ? SEND_TEXT_SYNC_TIMEOUT_MS : 10000,
          { shouldStop },
        );
        if (!synced || !synced.ok) {
          const syncReason = synced && synced.reason ? synced.reason : 'composer-text-not-synced';
          const actualText = typeof ComposerApi.getComposerText === 'function'
            ? String(ComposerApi.getComposerText() || '').trim()
            : '';
          if (actualText.length > 0) {
            ToolboxShell.appendLog(
              `[COMPOSER_DRAFT][SYNC_MISMATCH_ALLOWED] source=${source} reason=${syncReason} actualLen=${actualText.length} expectedLen=${content.length}`,
            );
            return { ok: true, reason: 'composer-sync-mismatch-allowed' };
          }
          ToolboxShell.appendLog(
            `[COMPOSER_DRAFT][SYNC_FAILED_EMPTY] source=${source} reason=${syncReason}`,
          );
          return { ok: false, reason: 'composer-empty-after-write' };
        }
      } else {
        await sleep(300);
      }

      ToolboxShell.appendLog(`[COMPOSER_DRAFT][WRITE_OK] source=${source} chars=${content.length}`);
      return { ok: true, reason: 'ok' };
    }

    function buildPromptSendTraceContext(rawText, options = {}) {
      const source = String(options.source || 'quick-prompt').trim() || 'quick-prompt';
      const promptTitle = String(options.promptTitle || '').trim() || '-';
      const composerTextRaw = (typeof ComposerApi !== 'undefined'
        && ComposerApi
        && typeof ComposerApi.getComposerText === 'function')
        ? String(ComposerApi.getComposerText() || '')
        : '';
      const composerTextLen = String(composerTextRaw || '').trim().length;
      const cap = typeof getUploadPageCapabilityLight === 'function'
        ? getUploadPageCapabilityLight()
        : {};
      const clickState = typeof resolveComposerSendClickState === 'function'
        ? resolveComposerSendClickState(source, cap)
        : null;
      const sendReady = clickState
        ? !!clickState.sendReady
        : (getUploadNativeSendButtonReadyState().ready === true);
      const responseState = String(cap && cap.response_state ? cap.response_state : '');
      const sendPhase = typeof getSendTaskPhase === 'function' ? String(getSendTaskPhase() || '') : '';
      const uploadPhase = typeof getUploadTaskState === 'function'
        ? String((getUploadTaskState() || {}).phase || '')
        : String(state && state.uploadPhase ? state.uploadPhase : '');

      return {
        source,
        promptTitle,
        rawTextLen: String(rawText || '').length,
        composerTextLen,
        sendReady,
        responseState,
        sendPhase,
        uploadPhase,
        waitingSend: !!state.waitingSend,
        waitingReply: !!state.waitingReply,
        cancelWaitingSend: !!state.cancelWaitingSend,
        messageSendCancelRequested: !!state.messageSendCancelRequested,
      };
    }

    function logPromptSendTrace(event, rawText, options = {}) {
      const ev = String(event || '').trim() || '-';
      const ctx = buildPromptSendTraceContext(rawText, options);
      const reason = options && options.reason ? String(options.reason) : '';
      const extra = reason ? ` reason=${reason}` : '';
      ToolboxShell.appendLog(
        `[PROMPT_SEND_TRACE] event=${ev} source=${ctx.source} promptTitle=${ctx.promptTitle} `
        + `rawTextLen=${ctx.rawTextLen} composerTextLen=${ctx.composerTextLen} sendReady=${ctx.sendReady ? 1 : 0} `
        + `responseState=${ctx.responseState || '-'} sendPhase=${ctx.sendPhase || '-'} uploadPhase=${ctx.uploadPhase || '-'} `
        + `waitingSend=${ctx.waitingSend ? 1 : 0} waitingReply=${ctx.waitingReply ? 1 : 0} `
        + `cancelWaitingSend=${ctx.cancelWaitingSend ? 1 : 0} messageSendCancelRequested=${ctx.messageSendCancelRequested ? 1 : 0}${extra}`,
      );
      return ctx;
    }

    function clearQuickPromptStaleCancelStateIfSafe(rawText, options = {}) {
      const source = String(options.source || 'quick-prompt-click').trim() || 'quick-prompt-click';
      const promptTitle = String(options.promptTitle || '').trim() || '-';

      if (isSendPipelineBusy()) {
        return false;
      }

      const changed = resetSendCancelStateForNewRun('quick-prompt-prepare', { source });

      // If the send phase is idle but the action lock is somehow still held, release it proactively.
      if (typeof getSendTaskPhase === 'function') {
        const sendPhaseNow = String(getSendTaskPhase() || '').trim() || 'idle';
        const sendPhaseIdle = sendPhaseNow === 'idle'
          || sendPhaseNow === 'failed'
          || sendPhaseNow === 'cancelled'
          || sendPhaseNow === 'completed'
          || sendPhaseNow === 'success';
        if (sendPhaseIdle) {
          releaseUploadActionLock('send-message');
        }
      }

      if (changed) {
        ToolboxShell.appendLog(
          `[PROMPT][SEND_PREPARE_CLEAN_STALE_STATE] source=${source} title=${promptTitle} cleared=1 via=resetSendCancelStateForNewRun`,
        );
      }
      logPromptSendTrace('SEND_PREPARE_CLEAN_STALE_STATE', rawText, {
        source,
        promptTitle,
        reason: changed ? 'cleared' : 'noop',
      });
      return changed;
    }

    function normalizeQuickPromptComposerText(value) {
      return String(value || '')
        .replace(/\u00A0/g, ' ')
        .replace(/[\u200B-\u200D\uFEFF]/g, '')
        .replace(/\r\n/g, '\n')
        .replace(/\r/g, '\n')
        .replace(/[ \t]+\n/g, '\n')
        .replace(/\n[ \t]+/g, '\n')
        .replace(/[ \t]+/g, ' ')
        .replace(/\n{2,}/g, '\n')
        .trim();
    }

    async function waitQuickPromptSendReady(rawText, options = {}) {
      const source = String(options.source || 'quick-prompt-click').trim() || 'quick-prompt-click';
      const promptTitle = String(options.promptTitle || '').trim() || '-';
      const timeoutMs = Math.max(500, Number(options.timeoutMs || 5000));
      const pollMs = Math.max(60, Number(options.pollMs || 120));

      const expected = String(rawText ?? '');
      const expectedLen = expected.length;
      const expectedTrimLen = expected.trim().length;
      const expectedNorm = normalizeQuickPromptComposerText(expected);
      const startedAt = Date.now();
      let lastLogAt = 0;
      let lastStateKey = '';

      while (Date.now() - startedAt <= timeoutMs) {
        const composerTextRaw = (typeof ComposerApi !== 'undefined'
          && ComposerApi
          && typeof ComposerApi.getComposerText === 'function')
          ? String(ComposerApi.getComposerText() || '')
          : '';
        const composerTextTrim = String(composerTextRaw || '').trim();
        const composerLen = composerTextTrim.length;
        const composerNorm = normalizeQuickPromptComposerText(composerTextRaw);

        const nativeReadyProbe = getUploadNativeSendButtonReadyState();
        const sendReady = !!(nativeReadyProbe && nativeReadyProbe.ready);

        const cap = typeof getUploadPageCapabilityLight === 'function'
          ? getUploadPageCapabilityLight()
          : {};
        const responseState = String(cap && cap.response_state ? cap.response_state : '');
        const isGenerating = responseState === 'generating';

        let apiSynced = false;
        if (
          typeof ComposerApi !== 'undefined'
          && ComposerApi
          && typeof ComposerApi.isComposerTextSynced === 'function'
        ) {
          apiSynced = ComposerApi.isComposerTextSynced(expected);
        }

        const normalizedSynced = composerNorm === expectedNorm
          || (
            expectedNorm.length >= 8
            && composerNorm.length >= 8
            && (
              composerNorm.includes(expectedNorm.slice(0, 120))
              || expectedNorm.includes(composerNorm.slice(0, 120))
            )
          );

        const strictSynced = !!(apiSynced || normalizedSynced);
        const expectedHead = expectedNorm.slice(0, Math.min(80, expectedNorm.length));
        const expectedTail = expectedNorm.slice(Math.max(0, expectedNorm.length - 80));
        const lenDelta = Math.abs(composerNorm.length - expectedNorm.length);
        const allowedLenDelta = Math.max(8, Math.ceil(expectedNorm.length * 0.05));
        const relaxedSynced = (
          expectedNorm.length > 0
          && composerNorm.length > 0
          && (
            composerNorm === expectedNorm
            || (expectedHead && composerNorm.includes(expectedHead))
            || (expectedTail && composerNorm.includes(expectedTail))
            || lenDelta <= allowedLenDelta
          )
        );

        const textSynced = !!(strictSynced || relaxedSynced);

        const textMismatchButSendable = sendReady
          && !isGenerating
          && composerLen > 0
          && expectedTrimLen > 0
          && !textSynced;
        const ok = sendReady
          && !isGenerating
          && composerLen > 0
          && expectedTrimLen > 0;

        const now = Date.now();
        const stateKey = [
          sendReady ? '1' : '0',
          isGenerating ? '1' : '0',
          composerLen > 0 ? '1' : '0',
          expectedTrimLen > 0 ? '1' : '0',
          textSynced ? '1' : '0',
        ].join('');

        const shouldLog = (stateKey !== lastStateKey) || (now - lastLogAt >= 2000);
        if (shouldLog) {
          lastStateKey = stateKey;
          lastLogAt = now;
          ToolboxShell.appendLog(
            `[PROMPT][SEND_READY_WAIT] source=${source} title=${promptTitle} `
            + `textLen=${composerLen} expectedLen=${expectedLen} expectedTrimLen=${expectedTrimLen} `
            + `actualNormLen=${composerNorm.length} expectedNormLen=${expectedNorm.length} `
            + `sendReady=${sendReady ? 1 : 0} responseState=${responseState || '-'} `
            + `textSynced=${textSynced ? 1 : 0} strictSynced=${strictSynced ? 1 : 0} relaxedSynced=${relaxedSynced ? 1 : 0} `
            + `textMismatchButSendable=${textMismatchButSendable ? 1 : 0} `
            + `isGenerating=${isGenerating ? 1 : 0} readySource=${nativeReadyProbe && nativeReadyProbe.source ? nativeReadyProbe.source : '-'}`,
          );
          logPromptSendTrace('SEND_READY_WAIT', rawText, {
            source,
            promptTitle,
            reason: ok ? 'ready' : 'waiting',
            textSynced,
            textMismatchButSendable,
            composerLen,
            expectedTrimLen,
          });
        }

        if (ok) {
          return {
            ok: true,
            reason: textMismatchButSendable
              ? 'send-ready-text-sync-mismatch-allowed'
              : 'send-ready',
            waitedMs: now - startedAt,
            textSynced,
            textMismatchButSendable,
            composerLen,
            expectedTrimLen,
          };
        }

        // Nudge React/composer state by re-setting draft value (idempotent).
        if (typeof ComposerApi !== 'undefined'
          && ComposerApi
          && typeof ComposerApi.setComposerValue === 'function'
          && (now - startedAt) > 200
          && composerLen < expectedTrimLen
        ) {
          try {
            ComposerApi.setComposerValue(expected);
          } catch (e) {
            console.warn('[ChatGPT toolbox] quick prompt composer nudge failed', e);
            if (typeof ToolboxShell !== 'undefined' && typeof ToolboxShell.appendLog === 'function') {
              ToolboxShell.appendLog(
                `[PROMPT][COMPOSER_NUDGE_FAILED] source=${source} title=${promptTitle} error=${e && e.message ? e.message : String(e)}`,
              );
            }
          }
        }

        await sleep(pollMs);
      }

      ToolboxShell.appendLog(
        `[PROMPT][AUTO_SEND_TIMEOUT] source=${source} title=${promptTitle} reason=send-button-not-ready-after-draft-sync timeoutMs=${timeoutMs}`,
      );
      logPromptSendTrace('AUTO_SEND_TIMEOUT', rawText, {
        source,
        promptTitle,
        reason: 'send-button-not-ready-after-draft-sync',
      });
      return { ok: false, reason: 'send-button-not-ready-after-draft-sync', waitedMs: Date.now() - startedAt };
    }

    async function sendCurrentComposerMessageLight(options = {}) {
      const source = String(options.source || 'send-current-composer-light').trim() || 'send-current-composer-light';
      const shouldStop = typeof options.shouldStop === 'function' ? options.shouldStop : () => false;
      const timeoutMs = Math.max(200, Number(options.timeoutMs || 5000));
      const pollMs = Math.max(60, Number(options.pollMs || 120));
      const startedAt = Date.now();

      if (shouldStop()) {
        return { ok: false, reason: 'cancelled' };
      }
      if (state && (state.cancelWaitingSend || state.messageSendCancelRequested)) {
        ToolboxShell.appendLog(
          `[COMPOSER_SEND_CURRENT_LIGHT][REAL_CANCEL_DETECTED] source=${source} cancelWaitingSend=${state.cancelWaitingSend ? 1 : 0} messageSendCancelRequested=${state.messageSendCancelRequested ? 1 : 0}`,
        );
        return { ok: false, reason: 'cancelled' };
      }

      while (Date.now() - startedAt <= timeoutMs) {
        if (shouldStop()) {
          return { ok: false, reason: 'cancelled' };
        }
        if (state && (state.cancelWaitingSend || state.messageSendCancelRequested)) {
          return { ok: false, reason: 'cancelled' };
        }

        const cap = typeof getUploadPageCapabilityLight === 'function'
          ? getUploadPageCapabilityLight()
          : (typeof getUploadPageCapability === 'function' ? getUploadPageCapability({ heavy: false }) : {});
        const responseState = String(cap && cap.response_state ? cap.response_state : '');
        const isGenerating = responseState === 'generating'
          || Boolean(cap && (cap.isResponding || cap.is_responding));
        if (isGenerating) {
          return { ok: false, reason: 'assistant_busy' };
        }

        const composerText = (typeof ComposerApi !== 'undefined'
          && ComposerApi
          && typeof ComposerApi.getComposerText === 'function')
          ? String(ComposerApi.getComposerText() || '').trim()
          : '';
        const hasAttachment = typeof ComposerApi !== 'undefined'
          && ComposerApi
          && typeof ComposerApi.hasComposerAttachmentUnified === 'function'
          && ComposerApi.hasComposerAttachmentUnified();
        if (!composerText && !hasAttachment) {
          return { ok: false, reason: 'composer_empty' };
        }

        const clickState = resolveComposerSendClickState(source, cap);

        if (clickState.canDirectClick) {
          if (!assertNativeButtonIsSendButton(clickState.btn, `composer-send-current-light:${source}`)) {
            await sleep(pollMs);
            continue;
          }
          try {
            clickState.btn.click();
          } catch (e) {
            ToolboxShell.appendLog(
              `[COMPOSER_SEND_CURRENT_LIGHT][CLICK_FAILED] source=${source} error=${e && e.message ? e.message : String(e)}`,
            );
            return { ok: false, reason: 'send_click_failed' };
          }
          return {
            ok: true,
            reason: clickState.nativeReady && !clickState.enabled
              ? 'clicked-by-native-ready'
              : 'clicked-enabled-button',
            waitedMs: Date.now() - startedAt,
          };
        }

        if (clickState.canFallback && typeof sendCurrentComposerMessage === 'function') {
          ToolboxShell.appendLog(
            `[COMPOSER_SEND_CURRENT_LIGHT][FALLBACK] source=${source} reason=${clickState.reason} `
            + `enabled=${clickState.enabled ? 1 : 0} nativeReady=${clickState.nativeReady ? 1 : 0} `
            + `capReady=${clickState.capReady ? 1 : 0} sendReady=${clickState.sendReady ? 1 : 0} `
            + `canDirectClick=${clickState.canDirectClick ? 1 : 0} canFallback=${clickState.canFallback ? 1 : 0}`,
          );
          const fallback = await sendCurrentComposerMessage({
            source,
            shouldStop,
            timeoutMs: Math.max(timeoutMs, 8000),
          });
          if (fallback && fallback.ok) {
            return {
              ok: true,
              reason: 'fallback-send-current-composer',
              waitedMs: Date.now() - startedAt,
            };
          }
        }

        if (clickState.capReady && Date.now() - startedAt >= 600) {
          ToolboxShell.appendLog(
            `[COMPOSER_SEND_CURRENT_LIGHT][WAIT_NOT_CLICKABLE] source=${source} reason=${clickState.reason} `
            + `buttonFound=${clickState.btn ? 1 : 0} enabled=${clickState.enabled ? 1 : 0} `
            + `nativeReady=${clickState.nativeReady ? 1 : 0} capReady=${clickState.capReady ? 1 : 0} `
            + `sendReady=${clickState.sendReady ? 1 : 0} canDirectClick=${clickState.canDirectClick ? 1 : 0} `
            + `canFallback=${clickState.canFallback ? 1 : 0}`,
          );
        }

        await sleep(pollMs);
      }

      return { ok: false, reason: 'send_button_not_ready', waitedMs: Date.now() - startedAt };
    }

    async function sendTextOnlyMessage(text, options = {}) {
      const source = String(options.source || 'text-only-send').trim() || 'text-only-send';
      const title = String(options.title || '').trim() || '-';
      const rawText = String(text ?? '');
      const shouldStop = typeof options.shouldStop === 'function' ? options.shouldStop : () => false;

      if (!rawText.trim()) {
        return { ok: false, reason: 'empty_text', sent: false };
      }

      ToolboxShell.appendLog(`[PROMPT][WRITE_START] source=${source} title=${title} chars=${rawText.length}`);
      const draft = await writeComposerDraftCore(rawText, { source });
      if (!draft || !draft.ok) {
        return { ok: false, reason: (draft && draft.reason) || 'composer_not_found', sent: false };
      }
      ToolboxShell.appendLog(`[PROMPT][WRITE_OK] source=${source} title=${title} chars=${rawText.length}`);

      const readyWait = await waitQuickPromptSendReady(rawText, {
        source,
        promptTitle: title,
        timeoutMs: Math.max(500, Number(options.timeoutMs || 5000)),
      });
      if (!readyWait || readyWait.ok !== true) {
        return { ok: false, reason: readyWait && readyWait.reason ? readyWait.reason : 'send-ready-timeout', sent: false };
      }

      ToolboxShell.appendLog(`[PROMPT][SEND_ATTEMPT] source=${source} title=${title}`);
      const result = await sendCurrentComposerMessageLight({
        source,
        timeoutMs: 6000,
        shouldStop,
      });
      ToolboxShell.appendLog(
        `[PROMPT][SEND_RESULT] source=${source} title=${title} ok=${result && result.ok ? 1 : 0} reason=${result && result.reason ? result.reason : '-'}`,
      );
      return { ok: !!(result && result.ok), reason: result && result.reason ? result.reason : 'send_failed', sent: !!(result && result.ok) };
    }

    async function sendOrFillQuickPrompt(prompt, options = {}) {
      const cfg = getCompactUiConfig();
      const source = String(options.source || 'quick-prompt-click').trim() || 'quick-prompt-click';
      const payload = normalizePromptPayload(prompt);
      const rawText = payload.rawText;
      const title = String(prompt && prompt.title ? prompt.title : '未命名').trim() || '未命名';
      let shouldSend;

      if (options.send === true) {
        shouldSend = true;
      } else if (options.send === false) {
        shouldSend = false;
      } else {
        shouldSend = shouldQuickPromptAutoSend(cfg);
      }

      const action = shouldSend ? 'send' : 'fill';

      ToolboxShell.appendLog(
        `[PROMPT][CLICK] source=${source} title=${title} text_len=${rawText.length} action=${action} auto_send=${shouldSend ? 1 : 0} sendBusy=${isSendPipelineBusy() ? 1 : 0}`,
      );
      logPromptSendTrace('CLICK', rawText, { source, promptTitle: title, reason: action });

      if (payload.isEmpty) {
        setStatus(`Prompt 内容为空：${title}`, 'warn');
        ToolboxShell.appendLog(`[PROMPT][CLICK][SKIP] source=${source} reason=empty_prompt`);
        logPromptSendTrace('SEND_FAILED', rawText, { source, promptTitle: title, reason: 'empty_prompt' });
        return;
      }

      if (shouldSend && isSendPipelineBusy()) {
        shouldSend = false;
        ToolboxShell.appendLog(`[PROMPT][CLICK][BUSY_FALLBACK_FILL] source=${source} reason=send_pipeline_busy`);
        logPromptSendTrace('SEND_FAILED', rawText, { source, promptTitle: title, reason: 'send_pipeline_busy_fallback_fill' });
      }

      const existingRawText = typeof ComposerApi.getComposerText === 'function'
        ? String(ComposerApi.getComposerText() || '')
        : '';

      if (existingRawText && existingRawText !== rawText && cfg.confirmPromptDraftOverwrite === true) {
        const okReplace = window.confirm(
          `ChatGPT 输入框已有 ${existingRawText.length} 个字符，是否覆盖为快捷 Prompt：${title}？`
        );

        if (!okReplace) {
          setStatus('已取消：未覆盖输入框草稿', 'warn');
          ToolboxShell.appendLog(
            `[PROMPT][CLICK][SKIP] source=${source} reason=draft_overwrite_cancelled existingChars=${existingRawText.length} newChars=${rawText.length}`,
          );
          return;
        }
      } else if (existingRawText && existingRawText !== rawText) {
        ToolboxShell.appendLog(
          `[PROMPT][CLICK][OVERWRITE_DRAFT] source=${source} existingChars=${existingRawText.length} newChars=${rawText.length}`,
        );
      }

      setStatus(shouldSend ? `正在写入并准备发送 Prompt：${title}` : '正在写入 Prompt...', 'running');
      ToolboxShell.appendLog(`[PROMPT][WRITE_START] source=${source} title=${title} chars=${rawText.length}`);
      logPromptSendTrace('WRITE_START', rawText, { source, promptTitle: title });

      const draft = await writeComposerDraftCore(rawText, { source });
      if (!draft.ok) {
        console.warn('[ChatGPT toolbox] quick prompt: write draft failed', { prompt, draft });
        setStatus('Prompt 写入失败：未找到或无法同步 ChatGPT 输入框', 'error');
        ToolboxShell.appendLog(`[PROMPT][CLICK][WRITE_FAILED] source=${source} reason=${draft.reason || 'composer_not_found'}`);
        logPromptSendTrace('WRITE_FAILED', rawText, { source, promptTitle: title, reason: draft.reason || 'composer_not_found' });
        return {
          ok: false,
          reason: draft.reason || 'composer_not_found',
          sent: false,
        };
      }

      ToolboxShell.appendLog(
        `[PROMPT][FILL] id=${prompt && prompt.id ? prompt.id : '-'} chars=${rawText.length} send=${shouldSend ? 1 : 0}`,
      );
      logPromptSendTrace('WRITE_OK', rawText, { source, promptTitle: title, reason: 'draft_write_ok' });

      if (!shouldSend) {
        setStatus(`已填入 Prompt：${title}`, 'success');
        logPromptSendTrace('DRAFT_SYNC_OK', rawText, { source, promptTitle: title, reason: 'filled_only' });
        return { ok: true, reason: 'filled', sent: false };
      }

      clearQuickPromptStaleCancelStateIfSafe(rawText, { source, promptTitle: title });

      logPromptSendTrace('SEND_READY_WAIT', rawText, { source, promptTitle: title, reason: 'enter' });
      const readyWait = await waitQuickPromptSendReady(rawText, {
        source,
        promptTitle: title,
        timeoutMs: 5000,
      });
      if (!readyWait || readyWait.ok !== true) {
        setStatus('Prompt 已填入，但发送按钮短时间内不可用，未自动发送', 'warn');
        logPromptSendTrace('SEND_FAILED', rawText, {
          source,
          promptTitle: title,
          reason: readyWait && readyWait.reason ? readyWait.reason : 'send-ready-timeout',
        });
        return { ok: true, reason: 'filled_send_not_ready_timeout', sent: false };
      }

      logPromptSendTrace('SEND_ATTEMPT', rawText, { source, promptTitle: title });
      const result = await sendCurrentComposerMessageLight({
        source,
        timeoutMs: 6000,
        shouldStop: () => false,
      });

      const sentOk = !!(result && result.ok);
      ToolboxShell.appendLog(
        `[PROMPT][SEND_RESULT] ok=${sentOk ? '1' : '0'} reason=${result && result.reason ? result.reason : '-'}`,
      );

      if (sentOk) {
        setStatus(`Prompt 已发送：${title}`, 'success');
        logPromptSendTrace('SEND_SUCCESS', rawText, { source, promptTitle: title, reason: result && result.reason ? result.reason : 'ok' });
        return { ok: true, reason: 'sent_by_send_current_composer', sent: true };
      }

      if (result && result.reason === 'cancelled') {
        setStatus('Prompt 已填入，但自动发送被取消', 'warn');
        logPromptSendTrace('SEND_FAILED', rawText, { source, promptTitle: title, reason: 'cancelled' });
        return { ok: false, reason: 'cancelled', sent: false };
      }

      setStatus(`Prompt 已填入，但自动发送失败：${result && result.reason ? result.reason : 'unknown'}`, 'warn');
      logPromptSendTrace('SEND_FAILED', rawText, { source, promptTitle: title, reason: result && result.reason ? result.reason : 'unknown' });
      return { ok: false, reason: (result && result.reason) || 'send_current_composer_failed', sent: false };
    }

    function isInsideToolboxOrPanel(el) {
      if (!(el instanceof HTMLElement)) {
        return false;
      }
      const appRootSelector = typeof APP !== 'undefined' && APP && APP.rootId
        ? `#${APP.rootId}`
        : null;
      return !!(
        (appRootSelector && el.closest(appRootSelector))
        || el.closest('.cgpt-toolbox-page')
        || el.closest('.cgpt-autoq-log-content')
        || el.closest('.cgpt-log-panel')
        || el.closest('[data-cgpt-log-panel]')
        || el.closest('.cgpt-autoq-task-list')
        || el.closest('[data-cgpt-task-list]')
        || el.closest('.cgpt-upload-list')
        || el.closest('[role="dialog"]')
        || el.closest('pre, code')
      );
    }

    function findNearestScrollableParent(el) {
      let cur = el instanceof HTMLElement ? el.parentElement : null;
      while (cur && cur !== document.body && cur !== document.documentElement) {
        if (isInsideToolboxOrPanel(cur)) {
          cur = cur.parentElement;
          continue;
        }
        const style = window.getComputedStyle(cur);
        const overflowY = String(style.overflowY || '').toLowerCase();
        const canScroll = cur.scrollHeight > cur.clientHeight + 24;
        if (canScroll && /auto|scroll|overlay/.test(overflowY)) {
          return cur;
        }
        cur = cur.parentElement;
      }
      return null;
    }

    function resolveChatScrollContainer() {
      const turnList = document.querySelector('[data-testid="conversation-turn-list"]');
      if (turnList instanceof HTMLElement) {
        const parent = findNearestScrollableParent(turnList);
        if (parent) {
          return parent;
        }
      }
      const main = document.querySelector('main, [role="main"]');
      if (main instanceof HTMLElement) {
        const parent = findNearestScrollableParent(main);
        if (parent) {
          return parent;
        }
      }
      return document.scrollingElement || document.documentElement;
    }

    function getBottomDistance(el) {
      if (!el) {
        return Number.POSITIVE_INFINITY;
      }
      return Math.max(
        0,
        Number(el.scrollHeight || 0) - Number(el.scrollTop || 0) - Number(el.clientHeight || 0),
      );
    }

    async function scrollChatToBottom(reason, options = {}) {
      const reasonText = String(reason || 'unknown');
      const maxAttempts = Math.max(1, Math.min(3, Number(options.maxAttempts || 2)));
      const thresholdPx = Math.max(8, Number(options.thresholdPx || 24));
      const delayMs = Math.max(30, Number(options.delayMs || 80));
      const target = resolveChatScrollContainer();
      if (!target) {
        ToolboxShell.appendLog(`[SCROLL][BOTTOM_SKIP] reason=${reasonText} detail=no-target`);
        return {
          ok: false,
          reason: 'no-target',
          attempts: 0,
        };
      }

      let attempts = 0;
      let lastTop = -1;
      let lastHeight = -1;
      let stuckRounds = 0;

      for (let i = 0; i < maxAttempts; i += 1) {
        attempts += 1;
        const beforeTop = Number(target.scrollTop || 0);
        const beforeHeight = Number(target.scrollHeight || 0);
        try {
          target.scrollTop = target.scrollHeight;
        } catch (err) {
          const errText = err && err.message ? err.message : String(err);
          console.error('[ChatGPT toolbox] scrollChatToBottom target failed', err);
          ToolboxShell.appendLog(`[SCROLL][BOTTOM_FAILED] reason=${reasonText} error=${errText}`);
          return {
            ok: false,
            reason: 'scroll-failed',
            attempts,
            error: errText,
          };
        }

        await new Promise((resolve) => setTimeout(resolve, delayMs));

        const afterTop = Number(target.scrollTop || 0);
        const afterHeight = Number(target.scrollHeight || 0);
        const bottomDistance = getBottomDistance(target);

        if (bottomDistance <= thresholdPx) {
          ToolboxShell.appendLog(
            `[SCROLL][BOTTOM_OK] reason=${reasonText} attempts=${attempts} distance=${Math.round(bottomDistance)} top=${Math.round(afterTop)} height=${Math.round(afterHeight)}`,
          );
          return {
            ok: true,
            reason: 'bottom',
            attempts,
            bottomDistance,
          };
        }

        const moved = Math.abs(afterTop - beforeTop) > 2 || Math.abs(afterHeight - beforeHeight) > 2;
        const sameAsLast = Math.abs(afterTop - lastTop) <= 2 && Math.abs(afterHeight - lastHeight) <= 2;
        if (!moved || sameAsLast) {
          stuckRounds += 1;
        } else {
          stuckRounds = 0;
        }
        lastTop = afterTop;
        lastHeight = afterHeight;

        if (stuckRounds >= 1) {
          ToolboxShell.appendLog(
            `[SCROLL][BOTTOM_STUCK_STOP] reason=${reasonText} attempts=${attempts} distance=${Math.round(bottomDistance)} top=${Math.round(afterTop)} height=${Math.round(afterHeight)}`,
          );
          return {
            ok: false,
            reason: 'stuck',
            attempts,
            bottomDistance,
          };
        }
      }

      const finalDistance = getBottomDistance(target);
      ToolboxShell.appendLog(
        `[SCROLL][BOTTOM_LIMIT_STOP] reason=${reasonText} attempts=${attempts} distance=${Math.round(finalDistance)}`,
      );
      return {
        ok: finalDistance <= thresholdPx,
        reason: finalDistance <= thresholdPx ? 'bottom' : 'max-attempts',
        attempts,
        bottomDistance: finalDistance,
      };
    }

    async function forceScrollChatToBottomForCopy(reason, stage) {
      const reasonText = String(reason || 'copy');
      const stageText = String(stage || 'unknown');
      try {
        const result = await scrollChatToBottom(`${reasonText}:${stageText}`, {
          maxAttempts: 2,
          thresholdPx: 24,
          delayMs: 80,
        });
        ToolboxShell.appendLog(
          `[COPY][FORCE_SCROLL_BOTTOM] reason=${reasonText} stage=${stageText} ok=${result && result.ok ? 1 : 0} detail=${result && result.reason ? result.reason : '-'}`,
        );
        return result;
      } catch (err) {
        const errText = err && err.message ? err.message : String(err);
        console.error('[COPY][FORCE_SCROLL_BOTTOM_FAILED]', err);
        ToolboxShell.appendLog(`[COPY][FORCE_SCROLL_BOTTOM_FAILED] reason=${reasonText} stage=${stageText} error=${errText}`);
        return {
          ok: false,
          reason: 'exception',
          error: errText,
        };
      }
    }

    // LEGACY WRAPPER: 旧调用仍返回纯文本；新逻辑请用 getLatestAssistantReplyText()
    function getLastAssistantReplyText() {
      const picked = getLatestAssistantReplyText({ label: 'getLastAssistantReplyText', forceRefresh: true });
      return picked && picked.ok ? String(picked.text || '').trim() : '';
    }

    function getLatestAssistantReplyText(options = {}) {
      if (typeof CopyPipeline === 'undefined' || typeof CopyPipeline.getLatestAssistantReplyText !== 'function') {
        return { ok: false, text: '', reason: 'copy_pipeline_missing' };
      }
      return CopyPipeline.getLatestAssistantReplyText(options);
    }

    async function writeClipboardAndVerify(text, options = {}) {
      if (typeof CopyPipeline === 'undefined' || typeof CopyPipeline.writeClipboardAndVerify !== 'function') {
        return { ok: false, reason: 'copy_pipeline_missing' };
      }
      return CopyPipeline.writeClipboardAndVerify(text, options);
    }

    async function copyLatestAssistantReplyUnified(options) {
      const opts = Object.assign({
        reason: 'copy-latest',
        prefilledText: '',
        scrollBeforeCopy: true,
        scrollFinally: false,
      }, options || {});

      const reasonText = opts.reason || 'copy-latest';

      ToolboxShell.appendLog(`[COPY][UNIFIED_START] reason=${reasonText}`);

      if (
        options
        && (
          options.scrollBeforeCopy === false
          || options.scrollAfterCopy === false
        )
      ) {
        ToolboxShell.appendLog(
          `[COPY][SCROLL_OPTION_IGNORED] reason=${reasonText} scrollBeforeCopy=${options.scrollBeforeCopy} scrollAfterCopy=${options.scrollAfterCopy}`,
        );
      }

      try {
        if (opts.scrollBeforeCopy !== false) {
          await forceScrollChatToBottomForCopy(reasonText, 'before-copy');
          await new Promise((resolve) => setTimeout(resolve, 120));
        }

        let text = String(opts.prefilledText || '').trim();
        let pickReason = 'prefilled';

        if (!text) {
          const picked = getLatestAssistantReplyText({ label: reasonText, forceRefresh: true });
          if (!picked || !picked.ok) {
            const failReason = picked && picked.reason ? picked.reason : 'read-failed';
            ToolboxShell.appendLog(`[COPY_LATEST][FAIL] label=${reasonText} reason=${failReason}`);
            setStatus('复制失败：无法读取最后回复', 'error');
            return {
              ok: false,
              reason: failReason,
              error: picked && picked.error ? picked.error : '',
            };
          }
          text = String(picked.text || '').trim();
          pickReason = picked.reason || 'ok';
        }

        if (!text) {
          ToolboxShell.appendLog(`[COPY][LATEST_EMPTY] reason=${reasonText}`);
          setStatus('复制失败：最后回复为空', 'error');
          return { ok: false, reason: 'latest_assistant_reply_empty' };
        }

        const copied = await writeClipboardAndVerify(text, { label: reasonText });
        if (!copied || !copied.ok) {
          const failReason = copied && copied.reason ? copied.reason : 'clipboard-failed';
          ToolboxShell.appendLog(`[COPY_LATEST][FAIL] label=${reasonText} reason=${failReason} pick=${pickReason}`);
          setStatus('复制失败：剪贴板写入失败', 'error');
          return {
            ok: false,
            reason: failReason,
            error: copied && copied.error ? copied.error : '',
          };
        }

        ToolboxShell.appendLog(`[COPY_LATEST][OK] label=${reasonText} len=${text.length}`);
        setStatus(`已复制最后回复：${text.length} 字`, 'success');

        return {
          ok: true,
          text,
          chars: text.length,
        };
      } finally {
        if (opts.scrollFinally === true) {
          await forceScrollChatToBottomForCopy(reasonText, 'finally');
        }
      }
    }

    function normalizeClipboardTextForCompare(text) {
      if (typeof CopyPipeline !== 'undefined'
        && CopyPipeline
        && typeof CopyPipeline.normalizeClipboardTextForCompare === 'function') {
        return CopyPipeline.normalizeClipboardTextForCompare(text);
      }
      return '';
    }

    function waitClipboardHotkeyDelay(ms) {
      return new Promise((resolve) => {
        window.setTimeout(resolve, Math.max(0, Number(ms) || 0));
      });
    }

    async function ensureClipboardReadyBeforeSystemHotkey(expectedText, reason = 'copy-hotkey') {
      const reasonText = String(reason || 'copy-hotkey').trim() || 'copy-hotkey';
      const expected = String(expectedText || '');
      const expectedNormalized = normalizeClipboardTextForCompare(expected);

      if (!expectedNormalized) {
        ToolboxShell.appendLog(`[COPY_ACTION][CLIPBOARD_READY_FAILED] reason=${reasonText} error=empty-expected-text`);
        return {
          ok: false,
          verified: false,
          reason: 'empty-expected-text',
        };
      }

      await waitClipboardHotkeyDelay(220);

      const canReadClipboard = !!(
        navigator.clipboard
        && typeof navigator.clipboard.readText === 'function'
        && (!document.hasFocus || document.hasFocus())
      );

      if (!canReadClipboard) {
        ToolboxShell.appendLog(
          `[COPY_ACTION][CLIPBOARD_READY_SKIP_VERIFY] reason=${reasonText} chars=${expected.length} readText=unavailable`,
        );
        return {
          ok: true,
          verified: false,
          reason: 'readText-unavailable',
        };
      }

      const deadline = Date.now() + 900;
      let lastText = '';
      let lastError = '';

      while (Date.now() < deadline) {
        try {
          lastText = String(await navigator.clipboard.readText() || '');
          if (normalizeClipboardTextForCompare(lastText) === expectedNormalized) {
            ToolboxShell.appendLog(
              `[COPY_ACTION][CLIPBOARD_READY_OK] reason=${reasonText} chars=${expected.length} verified=1`,
            );
            return {
              ok: true,
              verified: true,
              reason: 'ok',
            };
          }
        } catch (error) {
          lastError = error && error.message ? error.message : String(error);
          console.error('[COPY_ACTION][CLIPBOARD_READ_FAILED]', {
            error_type: error && error.name ? error.name : 'Error',
            error: lastError,
            stack: error && error.stack ? error.stack : '',
          });
          ToolboxShell.appendLog(
            `[COPY_ACTION][CLIPBOARD_READ_FAILED] reason=${reasonText} error=${lastError}`,
          );
          await waitClipboardHotkeyDelay(180);
          return {
            ok: true,
            verified: false,
            reason: 'readText-failed',
            error: lastError,
          };
        }

        await waitClipboardHotkeyDelay(90);
      }

      ToolboxShell.appendLog(
        `[COPY_ACTION][CLIPBOARD_READY_FAILED] reason=${reasonText} error=clipboard-mismatch expectedChars=${expected.length} actualChars=${lastText.length} lastError=${lastError || '-'}`,
      );

      try {
        await copyTextUnified(expected, `${reasonText}:recopy`);
        await waitClipboardHotkeyDelay(260);

        const verifyDeadline = Date.now() + 900;
        while (Date.now() < verifyDeadline) {
          try {
            lastText = String(await navigator.clipboard.readText() || '');
            if (normalizeClipboardTextForCompare(lastText) === expectedNormalized) {
              ToolboxShell.appendLog(
                `[COPY_ACTION][CLIPBOARD_RECOPY_OK] reason=${reasonText} chars=${expected.length} verified=1`,
              );
              return {
                ok: true,
                verified: true,
                reason: 'recopy-verified',
              };
            }
          } catch (recheckError) {
            lastError = recheckError && recheckError.message
              ? recheckError.message
              : String(recheckError);
            console.error('[ChatGPT toolbox] clipboard recopy verify read failed', recheckError);
            ToolboxShell.appendLog(
              `[COPY_ACTION][CLIPBOARD_RECOPY_VERIFY_FAILED] reason=${reasonText} error=${lastError}`,
            );
            break;
          }

          await waitClipboardHotkeyDelay(90);
        }

        ToolboxShell.appendLog(
          `[COPY_ACTION][CLIPBOARD_RECOPY_OK] reason=${reasonText} chars=${expected.length} verified=0`,
        );
        return {
          ok: true,
          verified: false,
          reason: 'recopy-ok',
        };
      } catch (error) {
        const errText = error && error.message ? error.message : String(error);
        console.error('[ChatGPT toolbox] clipboard recopy before hotkey failed', error);
        ToolboxShell.appendLog(
          `[COPY_ACTION][CLIPBOARD_RECOPY_FAILED] reason=${reasonText} error=${errText}`,
        );
        return {
          ok: false,
          verified: false,
          reason: 'recopy-failed',
          error: errText,
        };
      }
    }

    async function triggerCopyThenTargetHotkeyOnce(options = {}) {
      const source = String(options.source || 'copy-then-hotkey').trim() || 'copy-then-hotkey';
      const targetLabel = typeof getCopyThenShortcutTargetLabel === 'function'
        ? getCopyThenShortcutTargetLabel()
        : '';
      const combo = typeof getCopyThenShortcutTargetCombo === 'function'
        ? getCopyThenShortcutTargetCombo()
        : '';

      if (!combo) {
        ToolboxShell.appendLog(
          `[COPY_THEN_HOTKEY][TARGET_TRIGGER] key=- source=${source} reason=empty-target`,
        );
        setStatus('复制后目标快捷键未设置', 'error');
        return false;
      }

      ToolboxShell.appendLog(
        `[COPY_THEN_HOTKEY][TARGET_TRIGGER] key=${targetLabel || combo} source=${source}`,
      );
      setStatus(`正在请求 GUI 发送 ${targetLabel || combo}`, 'running');

      try {
        const result = await BridgeModule.sendSystemHotkey(combo);
        setStatus(`已请求 GUI 发送 ${targetLabel || combo}`, 'success');
        ToolboxShell.appendLog(
          `[COPY_THEN_HOTKEY][TARGET_DONE] key=${targetLabel || combo} combo=${combo} result=${JSON.stringify(result).slice(0, 200)}`,
        );
        return true;
      } catch (err) {
        const errText = err && err.message ? err.message : String(err);
        console.error('[COPY_THEN_HOTKEY][TARGET_FAILED]', {
          source,
          combo,
          key: targetLabel,
          error_type: err && err.name,
          error: errText,
          stack: err && err.stack,
        });
        setStatus(`GUI 目标快捷键失败：${errText}`, 'error');
        ToolboxShell.appendLog(
          `[COPY_THEN_HOTKEY][TARGET_FAILED] key=${targetLabel || combo} error=${errText}`,
        );
        return false;
      }
    }

    async function sendConfiguredHotkey(reason) {
      const reasonText = String(reason || 'copy-hotkey').trim() || 'copy-hotkey';
      if (typeof blurActiveElementIfInsideToolbox === 'function') {
        blurActiveElementIfInsideToolbox();
      }
      if (typeof waitClipboardHotkeyDelay === 'function') {
        await waitClipboardHotkeyDelay(80);
      }
      const hotkeyOk = await triggerCopyThenTargetHotkeyOnce({ source: reasonText });
      ToolboxShell.appendLog(
        `[COPY_ACTION][HOTKEY] reason=${reasonText} ok=${hotkeyOk ? 1 : 0}`,
      );
      return {
        ok: !!hotkeyOk,
        reason: hotkeyOk ? 'ok' : 'hotkey-failed',
        hotkeySent: !!hotkeyOk,
      };
    }

    async function sendHotkeyAfterCopy(options = {}) {
      const {
        copiedText = '',
        reason = 'copy-hotkey',
        shouldStop = () => false,
        gateState = null,
        skipHotkeyGate = false,
      } = options;

      if (shouldStop()) {
        return {
          ok: false,
          reason: 'cancelled',
          detail: '',
          hotkeySent: false,
        };
      }

      const clipboardReady = await ensureClipboardReadyBeforeSystemHotkey(
        copiedText,
        reason,
      );

      if (!clipboardReady || clipboardReady.ok !== true) {
        return {
          ok: false,
          reason: clipboardReady && clipboardReady.reason
            ? clipboardReady.reason
            : 'clipboard-not-ready',
          detail: clipboardReady && clipboardReady.error ? clipboardReady.error : '',
          hotkeySent: false,
        };
      }

      if (shouldStop()) {
        return {
          ok: false,
          reason: 'cancelled',
          detail: '',
          hotkeySent: false,
        };
      }

      if (!skipHotkeyGate && shouldApplyHotkeyAfterCopyGate(reason)) {
        const gatePayload = Object.assign(
          {},
          gateState && typeof gateState === 'object' ? gateState : buildSendCopyHotkeyHotkeyGateState(),
          {
            copied: !!(gateState && gateState.copied) || !!String(copiedText || '').trim(),
            replyDone: !!(gateState && gateState.replyDone) || !!String(copiedText || '').trim(),
          },
        );
        const gateResult = canSendHotkeyAfterCopy(gatePayload);
        if (!gateResult.ok) {
          logSendCopyHotkeyHotkeyGateDecision(gatePayload, gateResult, 'HOTKEY_BLOCKED');
          return {
            ok: false,
            reason: gateResult.reason,
            detail: '',
            hotkeySent: false,
          };
        }
        logSendCopyHotkeyHotkeyGateDecision(gatePayload, gateResult, 'HOTKEY_SEND_ALLOWED');
      }

      const hotkeyResult = await sendConfiguredHotkey(reason);

      if (!hotkeyResult || !hotkeyResult.ok) {
        return {
          ok: false,
          reason: 'hotkey-failed',
          detail: '',
          hotkeySent: false,
        };
      }

      return {
        ok: true,
        reason: 'ok',
        detail: '',
        hotkeySent: true,
      };
    }

    async function sendContinuePromptFromUnifiedPipeline(reason, options = {}) {
      const reasonText = String(reason || 'copy-continue').trim() || 'copy-continue';
      const continueResult = await sendContinueMessageOnly(reasonText, options);
      const ok = !!(continueResult && continueResult.ok);
      ToolboxShell.appendLog(
        `[COPY_ACTION][CONTINUE] reason=${reasonText} ok=${ok ? 1 : 0}`,
      );
      return Object.assign({}, continueResult || {}, {
        ok,
        continueSent: ok,
      });
    }

    const COPY_TOOLBAR_BUTTON_SELECTORS = Object.freeze({
      'copy-last-reply': '#cgpt-copy-last-message-scroll-bottom',
      'copy-hotkey': '#cgpt-copy-hotkey-once',
      'copy-continue': '#cgpt-upload-continue-once',
      'copy-hotkey-continue': '#cgpt-copy-hotkey-continue-once',
      'continuous-copy-hotkey-continue': '#cgpt-copy-hotkey-continue-loop',
      [CLOSED_LOOP_ACTIONS.WITH_HOTKEY.toolbarKey]: CLOSED_LOOP_ACTIONS.WITH_HOTKEY.selector,
      [CLOSED_LOOP_ACTIONS.WITH_HOTKEY_EVERY_ROUND.toolbarKey]: CLOSED_LOOP_ACTIONS.WITH_HOTKEY_EVERY_ROUND.selector,
      [CLOSED_LOOP_ACTIONS.WITHOUT_HOTKEY.toolbarKey]: CLOSED_LOOP_ACTIONS.WITHOUT_HOTKEY.selector,
      'closed-loop-upload-continue-hotkey': CLOSED_LOOP_ACTIONS.WITH_HOTKEY.selector,
      'closed-loop-upload-continue': CLOSED_LOOP_ACTIONS.WITHOUT_HOTKEY.selector,
    });

    const COPY_TOOLBAR_ACTION_ALIASES = (() => {
      const map = {
        'copy-only': 'copy-last-reply',
        'copy-last-message': 'copy-last-reply',
        'copy-and-hotkey': 'copy-hotkey',
        'copy-and-continue': 'copy-continue',
        'loop-copy-hotkey-continue': 'continuous-copy-hotkey-continue',
      };
      Object.values(CLOSED_LOOP_ACTIONS).forEach((def) => {
        map[def.action] = def.toolbarKey;
      });
      return Object.freeze(map);
    })();

    function normalizeToolbarCopyAction(action) {
      const key = String(action || '').trim();
      return COPY_TOOLBAR_ACTION_ALIASES[key] || key;
    }

    async function runCopyAction(actionType, options = {}) {
      const type = String(actionType || 'copy-only').trim() || 'copy-only';
      const source = String(options.source || 'runCopyAction').trim() || 'runCopyAction';
      const flowOptions = options && typeof options === 'object' ? options : {};

      ToolboxShell.appendLog(`[COPY_ACTION][START] type=${type}`);

      if (type === 'copy-only') {
        const result = await copyLastReplyWithState(source);
        ToolboxShell.appendLog(`[COPY_ACTION][DONE] type=${type} ok=${result ? 1 : 0}`);
        return result;
      }

      if (type === 'copy-and-continue') {
        const result = await copyLastMessageAndContinue(source);
        ToolboxShell.appendLog(
          `[COPY_ACTION][CONTINUE_DONE] type=${type} ok=${result ? 1 : 0}`,
        );
        return result;
      }

      if (type === 'copy-and-hotkey') {
        const result = await runCopyAndHotkeyAction(source, flowOptions);
        ToolboxShell.appendLog(
          `[COPY_ACTION][HOTKEY_DONE] type=${type} ok=${result && result.ok ? 1 : 0}`,
        );
        return result;
      }

      if (type === 'copy-hotkey-continue') {
        const result = await copyHotkeyAndContinueOnce(source, flowOptions);
        ToolboxShell.appendLog(
          `[COPY_ACTION][DONE] type=${type} ok=${result && result.ok ? 1 : 0}`,
        );
        return result;
      }

      if (type === 'loop-copy-hotkey-continue') {
        return runCopyHotkeyContinueLoop(source);
      }

      if (getClosedLoopModeFromAction(type)) {
        return dispatchClosedLoopAction(type, source);
      }

      ToolboxShell.appendLog(`[COPY_ACTION][UNKNOWN_TYPE] type=${type}`);
      return {
        ok: false,
        reason: 'unknown-action-type',
      };
    }

    async function waitAssistantStableForCopyContinue(source = 'copy-continue', options = {}) {
      const shouldStop = typeof options.shouldStop === 'function' ? options.shouldStop : () => false;

      if (shouldStop()) {
        return {
          ok: false,
          reason: 'cancelled',
        };
      }

      ToolboxShell.appendLog(
        `[UPLOAD_COPY_CONTINUE][wait-start] source=${String(source || '-')}`,
      );

      setStatus('正在等待当前回复完成...', 'danger', {
        persist: true,
        shortText: '等回复',
      });

      if (
        typeof ChatMessageExtractor === 'undefined'
        || typeof ChatMessageExtractor.waitLatestAssistantStable !== 'function'
      ) {
        ToolboxShell.appendLog('[UPLOAD_COPY_CONTINUE][wait-failed] reason=waitLatestAssistantStable-missing');
        return {
          ok: false,
          reason: 'waitLatestAssistantStable-missing',
        };
      }

      const pendingReplyContext = typeof BridgeModule !== 'undefined'
        && BridgeModule
        && typeof BridgeModule.getPendingReplyContext === 'function'
        ? BridgeModule.getPendingReplyContext()
        : null;

      const result = await ChatMessageExtractor.waitLatestAssistantStable({
        timeoutMs: COPY_CONTINUE_WAIT_TIMEOUT_MS,
        intervalMs: COPY_CONTINUE_STABLE_INTERVAL_MS,
        stableRounds: COPY_CONTINUE_STABLE_ROUNDS,
        pendingReplyContext,
        shouldStop,
        isGenerating: () => {
          return typeof ComposerApi !== 'undefined'
            && typeof ComposerApi.isAssistantLikelyBusy === 'function'
            && ComposerApi.isAssistantLikelyBusy();
        },
      });

      const trimmedText = String(result && result.text ? result.text : '').trim();

      if (!result || !result.ok || !trimmedText) {
        const reason = result && result.reason ? result.reason : 'unknown';

        ToolboxShell.appendLog(
          `[UPLOAD_COPY_CONTINUE][wait-failed] reason=${reason}`,
        );

        setStatus(`等待回复完成失败：${reason}`, 'warn');

        return {
          ok: false,
          reason,
          result,
        };
      }

      if (typeof isInvalidAssistantReplyText === 'function' && isInvalidAssistantReplyText(trimmedText)) {
        ToolboxShell.appendLog(
          `[UPLOAD_COPY_CONTINUE][wait-failed] reason=invalid-assistant-text preview=${trimmedText.slice(0, 40)}`,
        );

        setStatus('等待回复完成失败：回复尚未就绪', 'warn');

        return {
          ok: false,
          reason: 'invalid-assistant-text',
          result,
        };
      }

      ToolboxShell.appendLog(
        `[UPLOAD_COPY_CONTINUE][wait-ok] chars=${trimmedText.length} reason=${result.reason || '-'}`,
      );

      return {
        ok: true,
        text: trimmedText,
        record: result.record || null,
        result,
      };
    }

    async function waitAndCopyLatestAssistant(options = {}) {
      const {
        source = 'button',
        reason = 'copy',
        shouldStop = () => false,
      } = options;

      if (
        options
        && (
          options.scrollBeforeCopy === false
          || options.scrollAfterCopy === false
        )
      ) {
        ToolboxShell.appendLog(
          `[COPY_WAIT][SCROLL_OPTION_IGNORED] reason=${reason} scrollBeforeCopy=${options.scrollBeforeCopy} scrollAfterCopy=${options.scrollAfterCopy}`,
        );
      }

      try {
        const waitResult = await waitAssistantStableForCopyContinue(source, { shouldStop });

        if (!waitResult || !waitResult.ok) {
          const failReason = waitResult && waitResult.reason ? waitResult.reason : 'wait-assistant-failed';
          ToolboxShell.appendLog(
            `[COPY_WAIT][COPY_FAILED] reason=${failReason} stage=wait-assistant source=${String(source || '-')}`,
          );
          return {
            ok: false,
            reason: failReason,
            detail: '',
            copied: false,
            text: '',
            chars: 0,
            waitResult,
            copyResult: null,
          };
        }

        if (!String(waitResult.text || '').trim()) {
          ToolboxShell.appendLog(
            `[COPY_WAIT][COPY_FAILED] reason=empty-assistant-text stage=wait-assistant source=${String(source || '-')}`,
          );
          return {
            ok: false,
            reason: 'empty-assistant-text',
            detail: '',
            copied: false,
            text: '',
            chars: 0,
            waitResult,
            copyResult: null,
          };
        }

        if (shouldStop()) {
          ToolboxShell.appendLog(
            `[COPY_WAIT][COPY_FAILED] reason=cancelled stage=pre-copy source=${String(source || '-')}`,
          );
          return {
            ok: false,
            reason: 'cancelled',
            detail: '',
            copied: false,
            text: '',
            chars: 0,
            waitResult,
            copyResult: null,
          };
        }

        const copyResult = await copyLatestAssistantReplyUnified({
          reason,
          prefilledText: waitResult.text,
        });

        if (!copyResult || copyResult.ok !== true) {
          const failReason = copyResult && copyResult.reason ? copyResult.reason : 'copy-failed';
          const failDetail = copyResult && copyResult.error ? copyResult.error : '';
          ToolboxShell.appendLog(
            `[COPY_WAIT][COPY_FAILED] reason=${failReason} detail=${failDetail || '-'} source=${String(source || '-')}`,
          );
          return {
            ok: false,
            reason: failReason,
            detail: failDetail,
            copied: false,
            text: '',
            chars: 0,
            waitResult,
            copyResult,
          };
        }

        ToolboxShell.appendLog(
          `[COPY_WAIT][COPY_OK] chars=${copyResult.chars || 0} source=${String(source || '-')}`,
        );

        return {
          ok: true,
          reason: 'ok',
          detail: '',
          copied: true,
          text: copyResult.text || waitResult.text,
          chars: copyResult.chars || 0,
          waitResult,
          copyResult,
        };
      } finally {
        if (options && options.scrollFinally === true) {
          await forceScrollChatToBottomForCopy(reason, 'wait-finally');
        }
      }
    }

    const COPY_LAST_BUTTON_EXTRA_CLASSES = [
      'cgpt-btn-idle',
      'cgpt-btn-waiting',
      'cgpt-btn-running',
      'cgpt-btn-uploading',
      'cgpt-btn-waiting-send',
      'cgpt-btn-waiting-reply',
      'cgpt-btn-copying',
      'cgpt-btn-cancelling',
      'cgpt-btn-success',
      'cgpt-btn-failed',
      'cgpt-btn-danger',
      'cgpt-btn-cancelled',
      'cgpt-btn-disabled',
      'cgpt-btn-ok',
      'cgpt-btn-error',
      'cgpt-btn-waiting-danger',
      'cgpt-waiting-answer',
      'waiting',
      'success',
      'danger',
      'warning',
      'busy',
      'cgpt-btn-busy',
      'primary',
    ];

    function isCopyLastButtonManagedLocally(btn) {
      if (!btn) {
        return false;
      }
      const copyState = String(btn.dataset.copyState || 'idle').trim();
      return copyState !== 'idle';
    }

    function setCopyLastButtonState(stateName, reason = '') {
      const btn = rootElRef
        ? qs(UploadSelectors.copyLastMessageBtn, rootElRef)
        : document.querySelector(UploadSelectors.copyLastMessageBtn);

      if (!btn) {
        ToolboxShell.appendLog(
          `[COPY_LAST][BUTTON_STATE_SKIP] state=${stateName} reason=${reason || '-'} detail=missing-button`,
        );
        return;
      }

      if (copyLastButtonResetTimer) {
        window.clearTimeout(copyLastButtonResetTimer);
        copyLastButtonResetTimer = 0;
      }

      if (typeof ButtonState !== 'undefined' && typeof ButtonState.clearButtonStateClasses === 'function') {
        ButtonState.clearButtonStateClasses(btn);
      }

      COPY_LAST_BUTTON_EXTRA_CLASSES.forEach((cls) => {
        btn.classList.remove(cls);
      });

      btn.classList.remove(
        'cgpt-copy-last-idle',
        'cgpt-copy-last-running',
        'cgpt-copy-last-success',
        'cgpt-copy-last-failed',
      );

      btn.removeAttribute('aria-busy');
      btn.disabled = false;
      btn.removeAttribute('disabled');
      delete btn.dataset.waitDanger;
      delete btn.dataset.waitDangerReason;

      if (stateName === 'running') {
        btn.textContent = '复制中';
        btn.title = '正在复制最后一条回复';
        btn.disabled = true;
        btn.setAttribute('aria-busy', 'true');
        btn.classList.add('cgpt-btn-busy');
        btn.classList.add('cgpt-copy-last-running');
        btn.dataset.copyState = 'running';

        ToolboxShell.appendLog(
          `[COPY_LAST][BUTTON_STATE] state=running reason=${reason || '-'}`,
        );

        return;
      }

      if (stateName === 'success') {
        btn.textContent = '复制最后回复';
        btn.title = '等待最后一条 assistant 回复稳定后复制到剪贴板';
        btn.dataset.copyState = 'idle';
        btn.classList.add('cgpt-copy-last-idle');

        ToolboxShell.appendLog(
          `[COPY_LAST][BUTTON_STATE] state=success reason=${reason || '-'}`,
        );

        return;
      }

      if (stateName === 'failed') {
        btn.textContent = '复制失败';
        btn.title = reason ? `复制失败：${reason}` : '复制失败';
        btn.classList.add('cgpt-copy-last-failed');
        btn.dataset.copyState = 'failed';

        ToolboxShell.appendLog(
          `[COPY_LAST][BUTTON_STATE] state=failed reason=${reason || '-'}`,
        );

        return;
      }

      btn.textContent = '复制最后回复';
      btn.title = '复制最后一条回复';
      btn.classList.add('cgpt-copy-last-idle');
      btn.dataset.copyState = 'idle';
    }

    function resetCopyLastButtonSoon(delay = 900) {
      if (copyLastButtonResetTimer) {
        window.clearTimeout(copyLastButtonResetTimer);
        copyLastButtonResetTimer = 0;
      }
      copyLastButtonResetTimer = window.setTimeout(() => {
        copyLastButtonResetTimer = 0;
        setCopyLastButtonState('idle', 'reset-after-copy');
        renderUploadButtonsOnly();
      }, Math.max(300, Number(delay) || 900));
    }

    function setCopyLastTaskPhase(phase, reason = '') {
      const normalized = String(phase || 'idle').trim().toLowerCase() || 'idle';

      state.copyTask = Object.assign({}, state.copyTask || {}, {
        phase: normalized,
        reason: String(reason || ''),
        updatedAt: Date.now(),
        ownerAction: 'copy-only',
        ownerButtonId: 'cgpt-copy-last-message-scroll-bottom',
      });

      if (typeof ButtonTasks !== 'undefined' && typeof ButtonTasks.setTaskPhase === 'function') {
        ButtonTasks.setTaskPhase('copy', normalized, reason || 'copy-last', {
          subPhase: 'copy_last_reply',
          ownerAction: 'copy-only',
          ownerButtonId: 'cgpt-copy-last-message-scroll-bottom',
        });
      }

      logButtonTasksMigration('copyLastReplyTaskRunning', 'copy', normalized);
      logButtonTasksMigration('copyLastMessageTaskRunning', 'copy', normalized);

      ToolboxShell.appendLog(
        `[COPY_LAST_TASK][PHASE] phase=${normalized} reason=${reason || '-'}`,
      );
    }

    async function copyLastReplyWithState(source = 'button') {
      if (copyLastReplyTaskRunning) {
        const runningMs = Date.now() - Number(copyLastReplyTaskStartedAt || 0);
        if (runningMs <= 90000) {
          ToolboxShell.appendLog(
            `[COPY_LAST_REPLY][skip] reason=task-running runningMs=${runningMs}`,
          );
          return false;
        }
        ToolboxShell.appendLog(
          `[COPY_LAST_REPLY][stale-release] runningMs=${runningMs}`,
        );
        copyLastReplyTaskRunning = false;
        copyLastReplyTaskStartedAt = 0;
        copyLastReplyTaskStatus = '';
        copyLastMessageTaskRunning = false;
        copyLastMessageTaskStartedAt = 0;
        copyLastMessageTaskStatus = '';
        copyLastMessageWaiting = false;
        setCopyLastTaskPhase('idle', 'stale-release');
      }

      copyLastReplyTaskRunning = true;
      copyLastReplyTaskStartedAt = Date.now();
      copyLastReplyTaskStatus = 'waiting';
      copyLastMessageTaskRunning = true;
      copyLastMessageTaskStartedAt = copyLastReplyTaskStartedAt;
      copyLastMessageTaskStatus = 'waiting';
      copyLastMessageTaskSource = String(source || 'button');
      copyLastMessageWaiting = true;
      setCopyLastTaskPhase('waiting', `copy-only:${String(source || '-')}`);
      setCopyLastButtonState('running', `copy-only:${String(source || '-')}`);
      renderUploadButtonsOnly();

      if (typeof markLatestAssistantMessageCacheDirty === 'function') {
        markLatestAssistantMessageCacheDirty();
      }

      try {
        ToolboxShell.appendLog(
          `[COPY_LAST_REPLY][start] source=${String(source || '-')}`,
        );
        setStatus('正在等待最后回复稳定...', 'running');

        copyLastReplyTaskStatus = 'copying';
        copyLastMessageTaskStatus = 'copying';
        copyLastMessageWaiting = false;
        setCopyLastTaskPhase('copying', 'copying');
        setCopyLastButtonState('running', 'copying');
        renderUploadButtonsOnly();

        const waitCopyResult = await waitAndCopyLatestAssistant({
          source,
          reason: `copy-only:${String(source || '-')}`,
        });

        if (!waitCopyResult.ok) {
          const reason = waitCopyResult.reason || 'copy-failed';
          const detail = waitCopyResult.detail ? ` detail=${waitCopyResult.detail}` : '';
          ToolboxShell.appendLog(
            `[COPY_LAST_REPLY][abort] reason=${reason}${detail}`,
          );
          setStatus(`复制最后回复失败：${reason}`, 'warn');
          copyLastReplyTaskStatus = 'failed';
          copyLastMessageTaskStatus = 'failed';
          copyLastMessageWaiting = false;
          setCopyLastTaskPhase('failed', reason);
          setCopyLastButtonState('failed', reason);
          resetCopyLastButtonSoon(1600);
          renderUploadButtonsOnly();
          return false;
        }

        copyLastReplyTaskStatus = 'success';
        copyLastMessageTaskStatus = 'success';
        setCopyLastTaskPhase('success', 'copy-only-ok');
        setCopyLastButtonState('success', 'copy-only-ok');
        resetCopyLastButtonSoon(900);
        renderUploadButtonsOnly();

        ToolboxShell.appendLog(
          `[COPY_LAST_REPLY][done] chars=${waitCopyResult.chars || 0}`,
        );
        if (typeof playCopySuccessBeepSafe === 'function') {
          void playCopySuccessBeepSafe(source || '-', 'copyLastReply');
        }
        return true;
      } catch (error) {
        const errText = typeof formatToolboxError === 'function'
          ? formatToolboxError(error)
          : String(error && error.message ? error.message : error);
        console.error('[ChatGPT toolbox] copy last message failed', error);
        ToolboxShell.appendLog(`[COPY_LAST][FAILED] error=${errText}`);
        setStatus(`复制最后回复失败：${errText}`, 'error');
        copyLastReplyTaskStatus = 'failed';
        copyLastMessageTaskStatus = 'failed';
        copyLastMessageWaiting = false;
        setCopyLastTaskPhase('failed', errText);
        setCopyLastButtonState('failed', errText);
        resetCopyLastButtonSoon(1600);
        renderUploadButtonsOnly();
        return false;
      } finally {
        const resetDelay = copyLastReplyTaskStatus === 'success' ? 800 : 1200;
        window.setTimeout(() => {
          copyLastReplyTaskRunning = false;
          copyLastReplyTaskStartedAt = 0;
          copyLastReplyTaskStatus = '';
          copyLastMessageTaskRunning = false;
          copyLastMessageTaskStartedAt = 0;
          copyLastMessageTaskStatus = '';
          copyLastMessageTaskSource = '';
          copyLastMessageWaiting = false;
          setCopyLastTaskPhase('idle', 'reset-after-copy');
          renderUploadButtonsOnly();
        }, resetDelay);
      }
    }

    function isCurrentClosedLoopSendTask() {
      const task = state && state.sendTask ? state.sendTask : null;
      const source = String(task && task.source ? task.source : '');
      if (!closedLoopContinueState || !closedLoopContinueState.running) {
        return false;
      }
      return (
        source.startsWith('closed-loop-every5-')
        || source.startsWith('closed-loop-every-n-')
        || source.startsWith('closed-loop-every-round-')
        || source.startsWith('upload-verify-loop-')
        || source.includes('closed-loop')
        || source.includes('continue')
      );
    }

    function isSameAutoQueueContinueSendTask(sourceText) {
      const currentSource = state && state.sendTask && state.sendTask.source
        ? String(state.sendTask.source)
        : '';
      const nextSource = String(sourceText || '');

      if (!currentSource || !nextSource) {
        return false;
      }

      if (currentSource === nextSource) {
        return true;
      }

      if (currentSource.startsWith('autoq-task-') && nextSource.startsWith('autoq-task-')) {
        return true;
      }

      if (currentSource.includes('autoq-task') && nextSource.includes('autoq-task')) {
        return true;
      }

      return false;
    }

    async function sendContinueMessageOnly(source = 'button', options = {}) {
      const sourceText = String(source || '');
      const isLoopMode = (
        sourceText.startsWith('loop-')
        || sourceText.includes('continue')
        || sourceText.includes('closed-loop')
        || sourceText.includes('autoq-task')
        || sourceText.includes('upload-verify-loop')
        || sourceText.includes('copy-hotkey')
      );
      const shouldStop = typeof options.shouldStop === 'function' ? options.shouldStop : () => false;

      if (shouldStop()) {
        return {
          ok: false,
          reason: 'cancelled',
          assistantDoneSignal: false,
        };
      }

      safeAppendLog(`[UPLOAD_CONTINUE][SEND_START] source=${sourceText}`);
      console.warn('[UPLOAD_CONTINUE][SEND_START]', { source: sourceText });

      const skipDoneBeforeSendCheck = (
        options.skipDoneSignalBeforeSendCheck === true
        || options.allowSendAfterDoneSignal === true
      );

      if (!skipDoneBeforeSendCheck) {
        const assistantRawBeforeSend = getLastAssistantMessageTextForStopSignal();
        const doneBeforeSend = checkUploadDoneSignalWithLog(
          assistantRawBeforeSend,
          'UPLOAD_CONTINUE',
          'before-send',
          `source=${sourceText}`,
          options,
        );

        if (doneBeforeSend) {
          const preview = formatDoneSignalPreview(assistantRawBeforeSend);
          const skipLine = `[UPLOAD_CONTINUE][skip] reason=task-done-signal-before-send source=${sourceText} preview=${preview}`;
          safeAppendLog(skipLine);
          if (typeof ToolboxShell !== 'undefined' && typeof ToolboxShell.appendLog === 'function') {
            ToolboxShell.appendLog(skipLine);
          }
          console.warn('[UPLOAD_CONTINUE][skip]', {
            source: sourceText,
            reason: 'task-done-signal-before-send',
            preview,
          });
          return {
            ok: false,
            reason: 'task-done-signal-before-send',
            assistantDoneSignal: true,
          };
        }
      } else {
        safeAppendLog(`[UPLOAD_CONTINUE][before-send-done-check-skip] source=${sourceText} reason=allow-send-after-done-signal`);
        if (typeof ToolboxShell !== 'undefined' && typeof ToolboxShell.appendLog === 'function') {
          ToolboxShell.appendLog(`[UPLOAD_CONTINUE][before-send-done-check-skip] source=${sourceText} reason=allow-send-after-done-signal`);
        }
      }

      if (isSendTaskBusy() || isWaitingSendButton()) {
        if (isCurrentClosedLoopSendTask() || isSameAutoQueueContinueSendTask(sourceText)) {
          ToolboxShell.appendLog(
            `[UPLOAD_CONTINUE][BUSY_SKIP_CANCEL_SELF] source=${sourceText} reason=${isCurrentClosedLoopSendTask() ? 'same-closed-loop-send-task' : 'same-autoq-send-task'}`,
            'warn',
          );
          return {
            ok: false,
            reason: isCurrentClosedLoopSendTask()
              ? 'send-task-busy-same-closed-loop'
              : 'send-task-busy-same-autoq',
            assistantDoneSignal: false,
            retryable: true,
            wait: true,
          };
        }
        cancelWaitingSend('copy-continue');
      }

      const continuePromptText = getCopyHotkeyContinuePromptText({ ...options, logContinuePrompt: false });
      logContinuePromptBuild(continuePromptText, { source: sourceText, logSource: sourceText });
      const promptPreview = formatContinuePromptPreview(continuePromptText, 160);
      const previewLine = `[UPLOAD_CONTINUE][PROMPT_PREVIEW] chars=${continuePromptText.length} preview=${promptPreview}`;
      safeAppendLog(previewLine);
      console.warn('[UPLOAD_CONTINUE][PROMPT_PREVIEW]', {
        chars: continuePromptText.length,
        preview: promptPreview,
      });

      let result = await sendContinueMessageOnceOnly(sourceText, options);
      let reason = result && result.reason ? result.reason : '';

      if (isSendResultAcceptable(result)) {
        safeAppendLog(
          `[UPLOAD_CONTINUE][SEND_OK] source=${sourceText || '-'} reason=${reason || '-'} `
          + `sent=${result && result.sent ? 1 : 0} verified=${result && result.verified ? 1 : 0} `
          + `cancelledAfterSend=${result && result.cancelledAfterSend ? 1 : 0}`,
        );
        return Object.assign({}, result, { ok: true });
      }

      if (
        isLoopMode
        && (
          isAssistantBusyReason(reason)
          || reason === 'waiting_real_send_button'
          || reason === 'send_not_confirmed_composer_still_has_payload'
          || String(reason || '').startsWith('send_not_confirmed:')
        )
      ) {
        const composerText = (
          typeof ComposerApi !== 'undefined'
          && ComposerApi
          && typeof ComposerApi.getComposerText === 'function'
        )
          ? String(ComposerApi.getComposerText() || '').trim()
          : '';

        let busyNow = false;
        try {
          busyNow = (
            typeof ComposerApi !== 'undefined'
            && ComposerApi
            && typeof ComposerApi.isAssistantLikelyBusy === 'function'
            && ComposerApi.isAssistantLikelyBusy()
          );
        } catch (busyCheckErr) {
          console.error('[UPLOAD_CONTINUE][BUSY_CHECK_FAILED]', {
            source: sourceText,
            error_type: busyCheckErr && busyCheckErr.name,
            error: busyCheckErr && busyCheckErr.message,
            stack: busyCheckErr && busyCheckErr.stack,
          });
          busyNow = false;
        }

        if (busyNow || !composerText) {
          safeAppendLog(
            `[UPLOAD_CONTINUE][BUSY_AFTER_SEND_TREAT_AS_ACCEPTED] source=${sourceText} reason=${reason || '-'} busyNow=${busyNow ? '1' : '0'} composerChars=${composerText.length}`,
          );

          console.warn('[UPLOAD_CONTINUE][BUSY_AFTER_SEND_TREAT_AS_ACCEPTED]', {
            source: sourceText,
            reason,
            result,
            busyNow,
            composerChars: composerText.length,
          });

          return {
            ok: true,
            reason: 'send-accepted-assistant-busy',
            detail: reason || '',
            assistantBusyAfterSend: busyNow,
          };
        }

        safeAppendLog(
          `[UPLOAD_CONTINUE][SEND_FAILED] source=${sourceText} reason=continue-send-not-confirmed detail=${reason || '-'}`,
        );
        console.warn('[UPLOAD_CONTINUE][SEND_FAILED]', {
          source: sourceText,
          reason: 'continue-send-not-confirmed',
          detail: reason,
          composerText,
          busyNow,
          result,
        });

        return {
          ok: false,
          reason: 'continue-send-not-confirmed',
          detail: reason || '',
        };
      }

      safeAppendLog(
        `[UPLOAD_CONTINUE][SEND_FAILED] source=${sourceText || '-'} reason=${reason || 'unknown'} `
        + `sent=${result && result.sent ? 1 : 0} verified=${result && result.verified ? 1 : 0} `
        + `verifyReason=${result && result.verifyReason ? result.verifyReason : '-'}`,
      );
      console.warn('[UPLOAD_CONTINUE][SEND_FAILED]', {
        source: sourceText,
        reason,
        result,
      });

      return {
        ok: false,
        reason: reason || 'send-failed',
        detail: reason || '',
      };
    }

    async function sendContinueMessageOnceOnly(source, options = {}) {
      const sourceText = String(source || '');
      const shouldStop = typeof options.shouldStop === 'function'
        ? options.shouldStop
        : () => false;
      const text = getCopyHotkeyContinuePromptText({ ...options, logContinuePrompt: false });
      const stopSignal = getCopyHotkeyContinueStopSignal(options);
      logContinuePromptBuild(text, { source: sourceText, logSource: sourceText });
      const continuePayloadVerify = options.payloadVerify
        || buildContinuePromptPayloadVerify(text, stopSignal);

      if (shouldStop()) {
        return {
          ok: false,
          reason: 'cancelled',
        };
      }

      const capBeforeContinueSend = typeof getUploadPageCapabilityLight === 'function'
        ? getUploadPageCapabilityLight()
        : null;

      const composerTextBeforeContinue = (
        typeof ComposerApi !== 'undefined'
        && ComposerApi
        && typeof ComposerApi.getComposerText === 'function'
      )
        ? String(ComposerApi.getComposerText() || '')
        : '';

      const activeEl = typeof document !== 'undefined' ? document.activeElement : null;

      ToolboxShell.appendLog(
        `[UPLOAD_CONTINUE][BEFORE_SEND_DIAG] source=${sourceText || '-'} `
        + `continueChars=${text.length} `
        + `composerChars=${composerTextBeforeContinue.length} `
        + `hidden=${document.hidden ? 1 : 0} `
        + `hasFocus=${document.hasFocus && document.hasFocus() ? 1 : 0} `
        + `activeTag=${activeEl && activeEl.tagName ? activeEl.tagName : '-'} `
        + `activeId=${activeEl && activeEl.id ? activeEl.id : '-'} `
        + `sendable=${capBeforeContinueSend && capBeforeContinueSend.sendable ? 1 : 0} `
        + `inputable=${capBeforeContinueSend && capBeforeContinueSend.inputable ? 1 : 0} `
        + `responseState=${capBeforeContinueSend && capBeforeContinueSend.response_state ? capBeforeContinueSend.response_state : '-'}`,
      );

      ToolboxShell.appendLog(
        `[UPLOAD_CONTINUE][SEND_VIA_SEND_BUTTON_CORE] source=${sourceText} chars=${text.length}`,
      );

      try {
        const result = await sendTextBySendMessageButtonCore(text, {
          source: sourceText || 'copy-continue',
          allowReplaceDraft: true,
          shouldStop,
          timeoutMs: typeof SEND_WAIT_TIMEOUT_MS === 'number' ? SEND_WAIT_TIMEOUT_MS : 120000,
          payloadVerify: continuePayloadVerify,
        });

        if (shouldStop()) {
          if (isSendResultAcceptable(result)) {
            return {
              ok: true,
              sent: true,
              verified: true,
              cancelledAfterSend: true,
              reason: 'sent-before-cancelled',
              verifyReason: result && result.verifyReason ? result.verifyReason : 'already-sent',
            };
          }
          return {
            ok: false,
            reason: 'cancelled',
            cancelled: true,
          };
        }

        if (!isSendResultAcceptable(result)) {
          const reason = result && result.reason ? result.reason : 'send-message-button-core-failed';

          setStatus(`发送继续失败，准备尝试直写输入框兜底：${reason}`, 'warn');

          console.warn('[UPLOAD_CONTINUE][SEND_FAILED_BEFORE_FALLBACK]', {
            source: sourceText,
            reason,
            result,
          });

          safeAppendLog(`[UPLOAD_CONTINUE][send-failed-before-fallback] reason=${reason}`);
          safeAppendLog(`[UPLOAD_CONTINUE][SEND_FAILED_BEFORE_FALLBACK] source=${sourceText} reason=${reason}`);

          if (typeof sendTextToChatGPTComposerDirectly === 'function') {
            const fallbackResult = await sendTextToChatGPTComposerDirectly(text, {
              source: `${sourceText || 'copy-continue'}:direct-fallback`,
            });

            safeAppendLog(
              `[UPLOAD_CONTINUE][DIRECT_FALLBACK_RESULT] source=${sourceText || '-'} `
              + `ok=${fallbackResult && fallbackResult.ok ? 1 : 0} `
              + `reason=${fallbackResult && fallbackResult.reason ? fallbackResult.reason : '-'}`,
            );

            console.warn('[UPLOAD_CONTINUE][DIRECT_FALLBACK_RESULT]', {
              source: sourceText,
              reason,
              fallbackResult,
            });

            if (fallbackResult && fallbackResult.ok) {
              setStatus('已通过直写输入框兜底发送继续指令', 'success');

              return {
                ok: true,
                reason: `direct-fallback-after:${reason}`,
                fallback: true,
              };
            }
          }

          setStatus(`发送继续失败：${reason}`, 'warn');

          return {
            ok: false,
            reason,
          };
        }

        setStatus('已发送继续指令', 'success');
        console.warn('[UPLOAD_CONTINUE][SEND_OK]', {
          source: sourceText,
          reason: result.reason,
        });
        safeAppendLog(`[UPLOAD_CONTINUE][sent] chars=${text.length} stopSignal=${stopSignal}`);
        safeAppendLog(
          `[UPLOAD_CONTINUE][SEND_OK] source=${sourceText} reason=${result.reason || '-'}`,
        );

        return {
          ok: true,
          reason: result.reason || 'send-message-button-core',
        };
      } catch (err) {
        const errText = formatToolboxError(err);
        console.error('[ChatGPT toolbox] send continue via send button core failed', err);
        setStatus(`发送继续失败：${errText}`, 'error');
        safeAppendLog(`[UPLOAD_CONTINUE][send-failed] error=${errText}`);
        safeAppendLog(`[UPLOAD_CONTINUE][SEND_FAILED] source=${sourceText} reason=${errText}`);
        return {
          ok: false,
          reason: errText,
        };
      }
    }

    function resetClosedLoopOwnWaitingSendState(source = 'closed-loop-reset-waiting-send') {
      const sourceText = String(source || 'closed-loop-reset-waiting-send');
      const oldPhase = state && state.sendTask && state.sendTask.phase
        ? String(state.sendTask.phase)
        : '-';
      const oldSource = state && state.sendTask && state.sendTask.source
        ? String(state.sendTask.source)
        : '-';
      if (
        state
        && state.sendTask
        && (
          oldSource.startsWith('closed-loop-every5-')
          || oldSource === '-'
          || oldSource === ''
        )
      ) {
        state.cancelWaitingSend = false;
        state.messageSendCancelRequested = false;
        state.sendTask.phase = 'idle';
        state.sendTask.cancelRequested = false;
        state.sendTask.source = '';
        state.sendTask.owner = '';
      }
      ToolboxShell.appendLog(
        `[CLOSED_LOOP][RESET_OWN_WAITING_SEND] source=${sourceText} oldPhase=${oldPhase} oldSource=${oldSource}`,
      );
    }

    function logSendCorePayloadDroppedDiag(source, expectedLen, actualLen) {
      const sourceText = String(source || '-');
      let activeTag = '-';
      let activeId = '-';
      let activeClass = '-';
      if (typeof document !== 'undefined' && document.activeElement) {
        const el = document.activeElement;
        activeTag = el && el.tagName ? String(el.tagName) : '-';
        activeId = el && el.id ? String(el.id) : '-';
        activeClass = el && el.className ? String(el.className).slice(0, 80) : '-';
      }
      const composerLen = (
        typeof ComposerApi !== 'undefined'
        && ComposerApi
        && typeof ComposerApi.getComposerText === 'function'
      )
        ? String(ComposerApi.getComposerText() || '').length
        : 0;
      const clickState = typeof resolveComposerSendClickState === 'function'
        ? resolveComposerSendClickState(sourceText)
        : null;
      const btn = clickState && clickState.btn;
      const sendBtnExists = btn instanceof HTMLButtonElement ? 1 : 0;
      const sendBtnDisabled = btn instanceof HTMLButtonElement
        ? ((btn.disabled || btn.getAttribute('aria-disabled') === 'true') ? 1 : 0)
        : '-';
      const cap = typeof getUploadPageCapabilityLight === 'function'
        ? getUploadPageCapabilityLight()
        : {};
      const responseState = String(cap.response_state || '-');
      const inputable = cap.inputable !== undefined
        ? (cap.inputable ? 1 : 0)
        : (cap.canSendNow || cap.can_send_now ? 1 : 0);
      const sendable = cap.sendable ? 1 : 0;
      const hidden = typeof document !== 'undefined' && document.hidden ? 1 : 0;
      const focus = typeof document !== 'undefined' && document.hasFocus && document.hasFocus() ? 1 : 0;
      const sendPhase = typeof getSendTaskPhase === 'function'
        ? String(getSendTaskPhase() || '-')
        : '-';

      ToolboxShell.appendLog(
        `[SEND_CORE][PAYLOAD_DROPPED_DIAG] source=${sourceText} expectedLen=${expectedLen} actualLen=${actualLen} `
        + `activeTag=${activeTag} activeId=${activeId} activeClass=${activeClass} composerLen=${composerLen} `
        + `sendBtn=${sendBtnExists} disabled=${sendBtnDisabled} responseState=${responseState} `
        + `inputable=${inputable} sendable=${sendable} sendPhase=${sendPhase} hidden=${hidden} focus=${focus}`,
      );
    }

    function isHotkeyContinueDirectSendRetryReason(reason) {
      const text = String(reason || '').trim();
      if (!text) return false;
      return (
        text === 'payload_dropped'
        || text.includes('payload_dropped')
        || text === 'send-task-busy-same-closed-loop'
        || text.includes('send-task-busy-same-closed-loop')
        || text === 'continue-send-failed'
        || text.includes('continue-send-failed')
      );
    }

    function sleepMs(ms) {
      return new Promise((resolve) => window.setTimeout(resolve, Math.max(0, Number(ms) || 0)));
    }

    function findChatGPTComposerEditor() {
      const selectors = [
        '#prompt-textarea',
        'div#prompt-textarea[contenteditable="true"]',
        'div[contenteditable="true"][data-testid="prompt-textarea"]',
        'div[contenteditable="true"][role="textbox"]',
        'textarea[data-testid="prompt-textarea"]',
        'textarea#prompt-textarea',
      ];

      for (const selector of selectors) {
        const el = document.querySelector(selector);
        if (el) {
          return el;
        }
      }

      const candidates = Array.from(document.querySelectorAll('textarea, div[contenteditable="true"], [role="textbox"]'));
      for (const el of candidates) {
        const rect = el.getBoundingClientRect();
        if (rect.width > 100 && rect.height > 20) {
          return el;
        }
      }

      return null;
    }

    function focusChatGPTComposerEditor(editor, source) {
      if (!editor) {
        return false;
      }

      editor.scrollIntoView({
        block: 'center',
        inline: 'nearest',
      });

      editor.focus();

      const active = document.activeElement;
      const ok = active === editor || editor.contains(active);

      ToolboxShell.appendLog(
        `[COMPOSER_DIRECT_SEND][FOCUS] source=${source || '-'} ok=${ok ? 1 : 0} tag=${editor.tagName || '-'} id=${editor.id || '-'}`,
      );

      return ok;
    }

    function setChatGPTComposerText(editor, text, source) {
      const value = String(text || '');

      if (blockComposerWriteIfOriginalAfterInitial(value, source)) {
        return false;
      }

      if (!editor) {
        return false;
      }

      if (editor.tagName === 'TEXTAREA' || editor.tagName === 'INPUT') {
        const setter = Object.getOwnPropertyDescriptor(window.HTMLTextAreaElement.prototype, 'value')
          || Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value');

        if (setter && setter.set) {
          setter.set.call(editor, value);
        } else {
          editor.value = value;
        }

        editor.dispatchEvent(new InputEvent('input', {
          bubbles: true,
          inputType: 'insertText',
          data: value,
        }));

        editor.dispatchEvent(new Event('change', {
          bubbles: true,
        }));

        return true;
      }

      if (editor.isContentEditable || editor.getAttribute('contenteditable') === 'true') {
        editor.focus();

        editor.textContent = value;

        editor.dispatchEvent(new InputEvent('input', {
          bubbles: true,
          inputType: 'insertText',
          data: value,
        }));

        editor.dispatchEvent(new Event('change', {
          bubbles: true,
        }));

        return true;
      }

      ToolboxShell.appendLog(
        `[COMPOSER_DIRECT_SEND][UNSUPPORTED_EDITOR] source=${source || '-'} tag=${editor.tagName || '-'} id=${editor.id || '-'}`,
      );

      return false;
    }

    function readChatGPTComposerText(editor) {
      if (!editor) {
        return '';
      }

      if (editor.tagName === 'TEXTAREA' || editor.tagName === 'INPUT') {
        return String(editor.value || '');
      }

      return String(editor.innerText || editor.textContent || '');
    }

    async function sendTextToChatGPTComposerDirectly(text, options = {}) {
      const source = String(options.source || 'direct-send').trim();
      const value = String(text || '').trim();

      if (blockComposerWriteIfOriginalAfterInitial(value, source)) {
        return {
          ok: false,
          reason: 'original_prompt_after_initial_blocked',
          blocked: true,
        };
      }

      if (!value) {
        return {
          ok: false,
          reason: 'empty_text',
        };
      }

      const editor = findChatGPTComposerEditor();
      if (!editor) {
        ToolboxShell.appendLog(
          `[COMPOSER_DIRECT_SEND][EDITOR_NOT_FOUND] source=${source}`,
        );
        return {
          ok: false,
          reason: 'composer_editor_not_found',
        };
      }

      const focusOk = focusChatGPTComposerEditor(editor, source);
      if (!focusOk) {
        ToolboxShell.appendLog(
          `[COMPOSER_DIRECT_SEND][FOCUS_FAILED] source=${source}`,
        );
        return {
          ok: false,
          reason: 'composer_focus_failed',
        };
      }

      const setOk = setChatGPTComposerText(editor, value, source);
      if (!setOk) {
        ToolboxShell.appendLog(
          `[COMPOSER_DIRECT_SEND][SET_TEXT_FAILED] source=${source} chars=${value.length}`,
        );
        return {
          ok: false,
          reason: 'composer_set_text_failed',
        };
      }

      await sleepMs(120);

      const actualText = readChatGPTComposerText(editor);
      if (!actualText || !actualText.includes(value.slice(0, Math.min(30, value.length)))) {
        ToolboxShell.appendLog(
          `[COMPOSER_DIRECT_SEND][VERIFY_TEXT_FAILED] source=${source} expectedChars=${value.length} actualChars=${actualText ? actualText.length : 0}`,
        );
        return {
          ok: false,
          reason: 'composer_verify_text_failed',
        };
      }

      const sendButton = typeof findRealChatGPTSendButton === 'function'
        ? findRealChatGPTSendButton()
        : null;
      if (!sendButton) {
        ToolboxShell.appendLog(
          `[COMPOSER_DIRECT_SEND][SEND_BUTTON_NOT_FOUND] source=${source}`,
        );
        return {
          ok: false,
          reason: 'send_button_not_found',
        };
      }

      if (sendButton.disabled || sendButton.getAttribute('aria-disabled') === 'true') {
        ToolboxShell.appendLog(
          `[COMPOSER_DIRECT_SEND][SEND_BUTTON_DISABLED] source=${source} textChars=${actualText.length}`,
        );
        return {
          ok: false,
          reason: 'send_button_disabled',
        };
      }

      sendButton.click();

      await sleepMs(300);

      ToolboxShell.appendLog(
        `[COMPOSER_DIRECT_SEND][CLICK_SEND_OK] source=${source} chars=${value.length}`,
      );

      await sleepMs(500);

      const afterText = readChatGPTComposerText(editor);
      const assistantBusy = typeof isAssistantBusy === 'function'
        ? isAssistantBusy()
        : (
          typeof ComposerApi !== 'undefined'
          && ComposerApi
          && typeof ComposerApi.isAssistantLikelyBusy === 'function'
          && ComposerApi.isAssistantLikelyBusy()
        );
      const stopButton = document.querySelector('[data-testid="stop-button"], button[aria-label*="停止"], button[aria-label*="Stop"]');

      if (!afterText.trim() || assistantBusy || stopButton) {
        ToolboxShell.appendLog(
          `[COMPOSER_DIRECT_SEND][VERIFY_SEND_OK] source=${source} afterTextChars=${afterText.trim().length} assistantBusy=${assistantBusy ? 1 : 0} stopButton=${stopButton ? 1 : 0}`,
        );
        return {
          ok: true,
          reason: 'send_verified',
        };
      }

      ToolboxShell.appendLog(
        `[COMPOSER_DIRECT_SEND][VERIFY_SEND_FAILED] source=${source} afterTextChars=${afterText.trim().length}`,
      );

      return {
        ok: false,
        reason: 'send_not_verified',
      };
    }

    async function focusComposerForClosedLoop(source = '') {
      const sourceText = String(source || '').trim() || '-';
      const selectors = [
        'textarea[data-testid="composer-text-input"]',
        'textarea#prompt-textarea',
        '#prompt-textarea',
        'div.ProseMirror[contenteditable="true"]',
        'form [contenteditable="true"]',
        '[role="textbox"][contenteditable="true"]',
        '[contenteditable="true"][id="prompt-textarea"]',
      ];

      let focused = false;

      if (
        typeof ComposerApi !== 'undefined'
        && ComposerApi
        && typeof ComposerApi.focusComposer === 'function'
      ) {
        try {
          ComposerApi.focusComposer();
          focused = true;
        } catch (error) {
          const errText = formatToolboxError(error);
          console.error('[CLOSED_LOOP][FOCUS_COMPOSER_API_FAILED]', error);
          ToolboxShell.appendLog(
            `[CLOSED_LOOP][FOCUS_COMPOSER_API_FAILED] source=${sourceText} error=${errText}`,
          );
        }
      }

      if (!focused && typeof document !== 'undefined') {
        for (const selector of selectors) {
          const nodes = Array.from(document.querySelectorAll(selector));
          for (const node of nodes) {
            if (!(node instanceof HTMLElement)) {
              continue;
            }
            if (rootElRef && rootElRef.contains(node)) {
              continue;
            }
            const rect = node.getBoundingClientRect();
            if (rect.width <= 0 || rect.height <= 0) {
              continue;
            }
            try {
              node.focus();
              focused = true;
              break;
            } catch (error) {
              const errText = formatToolboxError(error);
              console.error('[CLOSED_LOOP][FOCUS_COMPOSER_DOM_FAILED]', error);
              ToolboxShell.appendLog(
                `[CLOSED_LOOP][FOCUS_COMPOSER_DOM_FAILED] source=${sourceText} selector=${selector} error=${errText}`,
              );
            }
          }
          if (focused) {
            break;
          }
        }
      }

      const hidden = typeof document !== 'undefined' && !!document.hidden;
      const hasFocus = typeof document === 'undefined'
        ? true
        : (!document.hasFocus || document.hasFocus());
      ToolboxShell.appendLog(
        `[CLOSED_LOOP][FOCUS_COMPOSER] source=${sourceText} focused=${focused ? 1 : 0} hidden=${hidden ? 1 : 0} hasFocus=${hasFocus ? 1 : 0}`,
      );
      return focused;
    }

    async function runSharedComposerSendFlow(options = {}) {
      const sourceText = String(options.source || 'shared-composer-send').trim() || 'shared-composer-send';
      const logPrefix = String(options.logPrefix || 'SHARED_COMPOSER').trim() || 'SHARED_COMPOSER';
      const promptText = String(options.promptText || '');
      if (promptText.trim() && blockComposerWriteIfOriginalAfterInitial(promptText, sourceText)) {
        return {
          ok: false,
          reason: 'original_prompt_after_initial_blocked',
          detail: '',
          sent: false,
          attachmentReady: false,
          textLen: promptText.length,
          source: sourceText,
          blocked: true,
        };
      }
      const shouldStop = typeof options.shouldStop === 'function' ? options.shouldStop : () => false;
      const uploadBeforeSend = options.uploadBeforeSend === true;
      const waitAttachmentStable = options.waitAttachmentStable === true;
      const requireAttachmentReady = options.requireAttachmentReady === true;
      const allowReplaceDraft = options.allowReplaceDraft !== false;
      const sendExistingComposer = options.sendExistingComposer === true;
      const promptAlreadyWritten = options.promptAlreadyWritten === true;
      const attachmentAlreadyReady = options.attachmentAlreadyReady === true;
      const onPhase = typeof options.onPhase === 'function' ? options.onPhase : null;
      const payloadVerify = options.payloadVerify || null;

      const emitPhase = (phase, detail) => {
        if (onPhase) {
          try {
            onPhase(phase, detail || {});
          } catch (phaseErr) {
            const phaseErrText = phaseErr && phaseErr.message ? phaseErr.message : String(phaseErr);
            console.error(`[${logPrefix}][SEND_FLOW][ON_PHASE_FAILED]`, phaseErr);
            ToolboxShell.appendLog(
              `[${logPrefix}][SEND_FLOW][ON_PHASE_FAILED] source=${sourceText} phase=${phase} error=${phaseErrText}`,
            );
          }
        }
      };

      if (shouldStop()) {
        ToolboxShell.appendLog(`[${logPrefix}][SEND_FLOW][CANCELLED] source=${sourceText} stage=enter`);
        return { ok: false, reason: 'cancelled', detail: '', sent: false, attachmentReady: false, textLen: 0, source: sourceText };
      }

      if (state && (state.cancelWaitingSend || state.messageSendCancelRequested)) {
        ToolboxShell.appendLog(
          `[${logPrefix}][SEND_FLOW][CANCELLED] source=${sourceText} cancelWaitingSend=${state.cancelWaitingSend ? 1 : 0} `
          + `messageSendCancelRequested=${state.messageSendCancelRequested ? 1 : 0}`,
        );
        return { ok: false, reason: 'cancelled', detail: '', sent: false, attachmentReady: false, textLen: 0, source: sourceText };
      }

      if (isSendMessageTaskAborted()) {
        ToolboxShell.appendLog(`[${logPrefix}][SEND_FLOW][CANCELLED] source=${sourceText} reason=send-message-task-aborted`);
        return { ok: false, reason: 'cancelled', detail: '', sent: false, attachmentReady: false, textLen: 0, source: sourceText };
      }

      if (typeof document !== 'undefined') {
        const hasFocus = !document.hasFocus || document.hasFocus();
        const hidden = !!document.hidden;
        if (hidden) {
          return { ok: false, reason: 'page-hidden', detail: '', sent: false, attachmentReady: false, textLen: 0, source: sourceText };
        }
        if (!hasFocus) {
          ToolboxShell.appendLog(
            `[${logPrefix}][FOCUS_SOFT_RECOVER] source=${sourceText} hidden=${hidden ? 1 : 0} hasFocus=${hasFocus ? 1 : 0}`,
          );
          await focusComposerForClosedLoop(sourceText);
          await new Promise((resolve) => setTimeout(resolve, 300));
        }
      }

      if (isSendMessageTaskAborted()) {
        return { ok: false, reason: 'cancelled', detail: '', sent: false, attachmentReady: false, textLen: 0, source: sourceText };
      }

      emitPhase('focus-composer', { source: sourceText });
      await focusComposerForClosedLoop(sourceText);

      if (shouldStop() || isSendMessageTaskAborted()) {
        return { ok: false, reason: 'cancelled', detail: '', sent: false, attachmentReady: false, textLen: 0, source: sourceText };
      }

      let attachmentEvidence = null;
      const readAttachmentEvidence = (tag) => {
        if (
          typeof ComposerAttachments !== 'undefined'
          && ComposerAttachments
          && typeof ComposerAttachments.getSharedComposerAttachmentEvidence === 'function'
        ) {
          return ComposerAttachments.getSharedComposerAttachmentEvidence(tag || sourceText, {
            heavy: true,
            forceRefresh: true,
          });
        }
        if (typeof getUnifiedComposerAttachmentState === 'function') {
          const unified = getUnifiedComposerAttachmentState(tag || sourceText, { heavy: true });
          return {
            hasAttachment: !!unified.hasAttachment,
            count: Math.max(0, Number(unified.fileCount) || 0),
            readyCount: unified.ready ? Math.max(0, Number(unified.fileCount) || 0) : 0,
            uploadingCount: unified.uploading ? 1 : 0,
            textLen: 0,
            filenames: Array.isArray(unified.filenames) ? unified.filenames : [],
            source: String(unified.source || 'unified-fallback'),
          };
        }
        return {
          hasAttachment: false,
          count: 0,
          readyCount: 0,
          uploadingCount: 0,
          textLen: 0,
          filenames: [],
          source: 'unavailable',
        };
      };

      if (uploadBeforeSend) {
        emitPhase('upload-before-send', { source: sourceText });
        ToolboxShell.appendLog(
          `[${logPrefix}][SEND_FLOW][UPLOAD_BEFORE_SEND] source=${sourceText} action=delegated-to-caller`,
        );
      }

      attachmentEvidence = readAttachmentEvidence(`pre-send:${sourceText}`);

      const rawAttachCount = Math.max(
        0,
        Number(attachmentEvidence.rawCount != null ? attachmentEvidence.rawCount : attachmentEvidence.count) || 0,
      );
      const normalizedAttachCount = Math.max(
        0,
        Number(attachmentEvidence.normalizedCount != null ? attachmentEvidence.normalizedCount : attachmentEvidence.count) || 0,
      );
      if (rawAttachCount > 1 && normalizedAttachCount <= 1) {
        ToolboxShell.appendLog(
          `[${logPrefix}][DUPLICATE_ATTACHMENT_RAW_IGNORED] raw=${rawAttachCount} normalized=${normalizedAttachCount} source=${sourceText}`,
        );
      }
      if (normalizedAttachCount > 1) {
        ToolboxShell.appendLog(
          `[${logPrefix}][DUPLICATE_ATTACHMENT_DETECTED] count=${normalizedAttachCount} raw=${rawAttachCount} action=skip-reupload source=${sourceText}`,
        );
      }

      if (attachmentAlreadyReady) {
        ToolboxShell.appendLog(
          `[SHARED_SEND][SKIP_ATTACHMENT_WAIT_ALREADY_READY] source=${sourceText} reason=autoq-initial-fast-path`,
        );
      } else if (waitAttachmentStable && normalizedAttachCount > 0) {
        emitPhase('wait-attachment-stable', { count: attachmentEvidence.count });
        if (typeof waitAttachmentsStableForSend === 'function') {
          const attachWaitMs = typeof MAX_ATTACHMENT_SEND_WAIT_MS === 'number'
            ? MAX_ATTACHMENT_SEND_WAIT_MS
            : 120000;
          await waitAttachmentsStableForSend(
            attachWaitMs,
            shouldStop,
            { source: `${logPrefix.toLowerCase()}-pre-send-attach-stable:${sourceText}` },
          );
        }
        attachmentEvidence = readAttachmentEvidence(`post-attach-wait:${sourceText}`);
      }

      const attachmentReady = attachmentAlreadyReady
        || (normalizedAttachCount > 0 && attachmentEvidence.uploadingCount === 0);
      if (requireAttachmentReady && normalizedAttachCount > 0 && !attachmentReady) {
        ToolboxShell.appendLog(
          `[${logPrefix}][SEND_FLOW][ATTACHMENT_NOT_READY] source=${sourceText} count=${normalizedAttachCount} `
          + `uploading=${attachmentEvidence.uploadingCount}`,
        );
        return {
          ok: false,
          reason: 'waiting_attachment_upload_done',
          detail: 'attachment-still-uploading',
          sent: false,
          attachmentReady: false,
          textLen: promptText.length,
          source: sourceText,
          wait: true,
          retryable: true,
        };
      }

      if (!promptText.trim() && !sendExistingComposer && !promptAlreadyWritten) {
        ToolboxShell.appendLog(`[${logPrefix}][SEND_FLOW][EMPTY_PROMPT] source=${sourceText}`);
        return {
          ok: false,
          reason: 'empty-prompt',
          detail: '',
          sent: false,
          attachmentReady,
          textLen: 0,
          source: sourceText,
        };
      }

      emitPhase('write-and-send', { textLen: promptText.length, attachmentReady: attachmentReady ? 1 : 0 });
      const sendCoreResult = sendExistingComposer || promptAlreadyWritten
        ? await sendExistingComposerBySendMessageButtonCore({
          source: sourceText,
          rawSource: sourceText,
          shouldStop,
          timeoutMs: typeof SEND_WAIT_TIMEOUT_MS === 'number' ? SEND_WAIT_TIMEOUT_MS : 120000,
          text: '',
          allowReplaceDraft: false,
          payloadVerify,
        })
        : await sendTextBySendMessageButtonCore(promptText, {
          source: sourceText,
          rawSource: sourceText,
          allowReplaceDraft,
          shouldStop,
          timeoutMs: typeof SEND_WAIT_TIMEOUT_MS === 'number' ? SEND_WAIT_TIMEOUT_MS : 120000,
          payloadVerify,
        });

      let ok = !!(sendCoreResult && sendCoreResult.ok === true);
      let reason = String((sendCoreResult && sendCoreResult.reason) || (ok ? 'sent' : 'send-failed'));
      const detail = String((sendCoreResult && sendCoreResult.detail) || '');

      if (
        !ok
        && (
          reason === 'composer_empty'
          || reason === 'payload_dropped'
          || reason === 'empty-prompt'
          || reason === 'send_not_confirmed_composer_still_has_payload'
        )
        && typeof confirmSharedMessageSubmitted === 'function'
      ) {
        const submitted = await confirmSharedMessageSubmitted(
          sourceText,
          promptText || options.expectedPromptText || '',
          Object.assign({}, options.sendVerifyBefore || {}, {
            timeoutMs: 1500,
            sendKind: options.sendKind,
          }),
        );
        if (submitted && submitted.ok === true) {
          ok = true;
          reason = submitted.reason || 'message-submitted-composer-cleared';
          ToolboxShell.appendLog(
            `[${logPrefix}][SEND_FLOW][COMPOSER_EMPTY_ACCEPTED] source=${sourceText} reason=${reason} `
            + `detail=${submitted.detailReason || '-'}`,
          );
        }
      }

      const reportTextLen = (() => {
        if (promptText.length > 0) {
          return promptText.length;
        }
        const evidenceTextLen = Math.max(0, Number(attachmentEvidence && attachmentEvidence.textLen) || 0);
        if (evidenceTextLen > 0) {
          return evidenceTextLen;
        }
        if (
          typeof ComposerApi !== 'undefined'
          && ComposerApi
          && typeof ComposerApi.getComposerText === 'function'
        ) {
          return String(ComposerApi.getComposerText() || '').trim().length;
        }
        return 0;
      })();

      if (
        promptAlreadyWritten
        && promptText.length === 0
        && reportTextLen > 0
      ) {
        ToolboxShell.appendLog(
          `[AUTOQ][SEND_TEXTLEN_INCONSISTENT] source=${sourceText} promptTextLen=0 composerTextLen=${reportTextLen} `
          + `action=use-composer-text-len`,
        );
      }

      if (
        (promptAlreadyWritten || sendExistingComposer)
        && reportTextLen === 0
        && !ok
      ) {
        const postFailEvidence = readAttachmentEvidence(`post-send-fail:${sourceText}`);
        const postFailTextLen = Math.max(0, Number(postFailEvidence && postFailEvidence.textLen) || 0);
        if (postFailTextLen > 0) {
          ToolboxShell.appendLog(
            `[AUTOQ][SEND_TEXTLEN_INCONSISTENT] source=${sourceText} promptTextLen=0 composerTextLen=${postFailTextLen} `
            + `reason=${reason || '-'} action=report-composer-len`,
          );
        }
      }

      ToolboxShell.appendLog(
        `[${logPrefix}][SEND_FLOW][DONE] source=${sourceText} ok=${ok ? 1 : 0} reason=${reason} `
        + `attachmentReady=${attachmentReady ? 1 : 0} textLen=${reportTextLen}`,
      );

      const acceptable = isSendResultAcceptable(sendCoreResult) || ok;
      if (acceptable && !ok) {
        ok = true;
        if (sendCoreResult && sendCoreResult.reason) {
          reason = sendCoreResult.reason;
        } else {
          reason = 'sent-before-cancelled';
        }
      }

      return {
        ok,
        reason,
        detail,
        sent: ok || !!(sendCoreResult && sendCoreResult.sent),
        verified: ok || !!(sendCoreResult && sendCoreResult.verified),
        cancelledAfterSend: !!(sendCoreResult && sendCoreResult.cancelledAfterSend),
        verifyReason: sendCoreResult && sendCoreResult.verifyReason ? sendCoreResult.verifyReason : '',
        attachmentReady,
        textLen: reportTextLen,
        source: sourceText,
        wait: !ok && sendCoreResult && sendCoreResult.wait === true,
        retryable: !ok && (
          (sendCoreResult && sendCoreResult.retryable === true)
          || String(reason || '').startsWith('send-action-lock:')
        ),
        shouldWaitReply: ok && (options.sendKind === 'initial' || options.sendKind === 'continue' || options.sendKind === 'verification'),
      };
    }

    async function runSharedSendAndWaitEntryFlow(options = {}) {
      const sourceText = String(options.source || 'shared-send-wait-entry').trim() || 'shared-send-wait-entry';
      const logPrefix = String(options.logPrefix || 'SHARED_SEND').trim() || 'SHARED_SEND';
      const promptText = String(options.promptText || '');
      const shouldStop = typeof options.shouldStop === 'function' ? options.shouldStop : () => false;
      const confirmTimeoutMs = Math.max(1500, Number(options.confirmTimeoutMs || options.timeoutMs) || 3000);

      const readAttachmentEvidence = (tag) => {
        if (
          typeof ComposerAttachments !== 'undefined'
          && ComposerAttachments
          && typeof ComposerAttachments.getSharedComposerAttachmentEvidence === 'function'
        ) {
          return ComposerAttachments.getSharedComposerAttachmentEvidence(tag || sourceText, {
            heavy: true,
            forceRefresh: true,
          });
        }
        if (typeof getUnifiedComposerAttachmentState === 'function') {
          const unified = getUnifiedComposerAttachmentState(tag || sourceText, { heavy: true });
          const fileCount = Math.max(0, Number(unified.fileCount) || 0);
          return {
            hasAttachment: !!unified.hasAttachment,
            count: fileCount,
            normalizedCount: fileCount,
            readyCount: unified.ready ? fileCount : 0,
            uploadingCount: unified.uploading ? 1 : 0,
          };
        }
        return {
          hasAttachment: false,
          count: 0,
          normalizedCount: 0,
          readyCount: 0,
          uploadingCount: 0,
        };
      };

      let attachmentEvidence = readAttachmentEvidence(`pre-send-wait-entry:${sourceText}`);
      let normalizedCount = Math.max(
        0,
        Number(attachmentEvidence.normalizedCount != null ? attachmentEvidence.normalizedCount : attachmentEvidence.count) || 0,
      );
      let composerAttached = normalizedCount > 0 && Number(attachmentEvidence.uploadingCount || 0) === 0;

      const sendResult = await runSharedComposerSendFlow(Object.assign({}, options, {
        source: sourceText,
        promptText,
        shouldStop,
        logPrefix,
      }));

      const readConversationId = () => {
        if (typeof parseConversationIdFromPath === 'function') {
          return String(parseConversationIdFromPath(location.pathname || '') || '').trim();
        }
        return '';
      };
      const readTurnCount = () => {
        if (typeof getCurrentPageTurnCountSafe === 'function') {
          const turn = Number(getCurrentPageTurnCountSafe());
          return Number.isFinite(turn) ? turn : 0;
        }
        return 0;
      };

      let submitted = null;
      let conversationSent = false;
      let canEnterWaitingReply = false;

      if (sendResult && sendResult.ok === true) {
        try {
          submitted = await confirmSharedMessageSubmitted(
            sourceText,
            promptText || options.expectedPromptText || '',
            Object.assign({}, options.sendVerifyBefore || {}, {
              timeoutMs: confirmTimeoutMs,
              sendKind: options.sendKind,
              turnCountBefore: options.turnCountBefore || options.beforeTurnCount,
              beforeTurnCount: options.beforeTurnCount || options.turnCountBefore,
              beforeConversationId: options.beforeConversationId || options.conversationIdBefore,
              conversationIdBefore: options.conversationIdBefore || options.beforeConversationId,
              taskTitle: options.expectedTaskTitle || options.taskTitle,
            }),
          );
        } catch (confirmErr) {
          console.error(`[${logPrefix}][SEND_WAIT_ENTRY][CONFIRM_FAILED]`, confirmErr);
          const errText = confirmErr && confirmErr.message ? confirmErr.message : String(confirmErr);
          ToolboxShell.appendLog(
            `[${logPrefix}][SEND_WAIT_ENTRY][CONFIRM_FAILED] source=${sourceText} error=${errText}`,
          );
          submitted = {
            ok: false,
            reason: errText || 'confirm-failed',
          };
        }

        canEnterWaitingReply = !!(submitted && submitted.ok === true);
        conversationSent = canEnterWaitingReply || !!(submitted && submitted.attachmentInConversation);

        if (canEnterWaitingReply) {
          ToolboxShell.appendLog(
            `[SEND_VERIFY][CONVERSATION_SUBMITTED_OK] source=${sourceText} reason=${submitted.reason || '-'} `
            + `detail=${submitted.detailReason || '-'} kind=${options.sendKind || '-'}`,
          );
        }
      }

      attachmentEvidence = readAttachmentEvidence(`post-send-wait-entry:${sourceText}`);
      normalizedCount = Math.max(
        0,
        Number(attachmentEvidence.normalizedCount != null ? attachmentEvidence.normalizedCount : attachmentEvidence.count) || 0,
      );
      composerAttached = normalizedCount > 0 && Number(attachmentEvidence.uploadingCount || 0) === 0;
      if (!composerAttached && sendResult && sendResult.attachmentReady === true) {
        composerAttached = true;
        if (normalizedCount <= 0) {
          normalizedCount = 1;
        }
      }

      let composerTextLen = Math.max(0, Number(sendResult && sendResult.textLen) || 0);
      if (
        typeof ComposerApi !== 'undefined'
        && ComposerApi
        && typeof ComposerApi.getComposerText === 'function'
      ) {
        composerTextLen = Math.max(
          composerTextLen,
          String(ComposerApi.getComposerText() || '').trim().length,
        );
      }

      const conversationId = readConversationId();
      const turnCount = readTurnCount();
      const flowOk = !!(sendResult && sendResult.ok === true && canEnterWaitingReply);
      const flowReason = flowOk
        ? String((submitted && submitted.reason) || 'submitted-confirmed')
        : String(
          (submitted && submitted.reason)
          || (sendResult && sendResult.reason)
          || 'not-submitted',
        );

      const composerAttachedCount = composerAttached
        ? Math.max(normalizedCount, 1)
        : 0;

      ToolboxShell.appendLog(
        `[${logPrefix}][SEND_WAIT_ENTRY][DONE] source=${sourceText} ok=${flowOk ? 1 : 0} `
        + `submitted=${canEnterWaitingReply ? 1 : 0} composerAttached=${composerAttachedCount} `
        + `conversationId=${conversationId || '-'} turnCount=${turnCount}`,
      );

      return {
        ok: flowOk,
        reason: flowReason,
        submitted: canEnterWaitingReply,
        composerAttached: composerAttachedCount > 0,
        conversationSent,
        canEnterWaitingReply,
        composerTextLen,
        attachmentCount: normalizedCount,
        conversationId,
        turnCount,
        sendResult,
        submittedDetail: submitted,
      };
    }

    async function sendClosedLoopContinuePrompt(promptText, context = {}) {
      const sourceText = String(context.source || 'closed-loop-continue').trim() || 'closed-loop-continue';
      const shouldStop = typeof context.shouldStop === 'function' ? context.shouldStop : () => false;
      const doneSignal = getCopyHotkeyContinueStopSignal(context);
      const prompt = normalizeClosedLoopContinuePromptText(
        promptText,
        `sendClosedLoopContinuePrompt:${sourceText}`,
      );

      logContinuePromptBuild(prompt, { source: sourceText, logSource: sourceText });

      return runSharedComposerSendFlow({
        source: sourceText,
        promptText: prompt,
        uploadBeforeSend: false,
        // 闭环继续发送前必须等待附件稳定，尤其是「每1轮上传」模式。
        // 不能只依赖 ChatGPT 发送按钮是否变亮。
        waitAttachmentStable: true,
        requireAttachmentReady: true,
        shouldStop,
        logPrefix: 'CLOSED_LOOP',
        allowReplaceDraft: true,
        payloadVerify: buildContinuePromptPayloadVerify(prompt, doneSignal),
      });
    }

    function resolveComposerSendClickState(source, capability) {
      const sourceText = String(source || '-').trim() || '-';
      const cap = capability && typeof capability === 'object'
        ? capability
        : (typeof getUploadPageCapability === 'function' ? getUploadPageCapability({ heavy: false }) : {});

      const helperBtn = (typeof findUploadComposerSendButton === 'function')
        ? findUploadComposerSendButton()
        : null;
      const directBtn = typeof document !== 'undefined'
        ? document.querySelector('button#composer-submit-button, button[data-testid="send-button"]')
        : null;
      const btn = helperBtn instanceof HTMLButtonElement
        ? helperBtn
        : (directBtn instanceof HTMLButtonElement ? directBtn : null);

      const nativeReadyState = typeof getUploadNativeSendButtonReadyState === 'function'
        ? getUploadNativeSendButtonReadyState()
        : null;
      const nativeReady = !!(nativeReadyState && nativeReadyState.ready === true);
      const capReady = !!(cap && (cap.canSendNow || cap.can_send_now));

      const isStopButton = isNativeButtonStopButton(btn);
      const enabled = btn instanceof HTMLButtonElement && !isStopButton
        ? (
          typeof ComposerApi !== 'undefined'
          && ComposerApi
          && typeof ComposerApi.isSendButtonReady === 'function'
            ? ComposerApi.isSendButtonReady(btn)
            : (!btn.disabled && btn.getAttribute('aria-disabled') !== 'true')
        )
        : false;

      const sendReady = !isStopButton && (enabled || nativeReady || capReady);
      const canDirectClick = btn instanceof HTMLButtonElement && !isStopButton && (enabled || nativeReady);
      const canFallback = sendReady && !canDirectClick;

      const reason = canDirectClick
        ? (enabled ? 'click_enabled' : 'click_native_ready')
        : (btn ? (capReady ? 'cap_ready_but_button_disabled' : 'button_disabled') : (sendReady ? 'send_ready_but_button_missing' : 'send_not_ready'));

      return {
        btn,
        enabled,
        nativeReady,
        capReady,
        sendReady,
        canDirectClick,
        canFallback,
        reason,
        source: sourceText,
      };
    }

    async function sendClosedLoopContinuePromptLoose(promptText, context = {}) {
      const sourceText = String(context.source || 'closed-loop-continue-loose').trim() || 'closed-loop-continue-loose';
      const shouldStop = typeof context.shouldStop === 'function' ? context.shouldStop : () => false;
      const prompt = String(promptText || '');

      if (!prompt.trim()) {
        ToolboxShell.appendLog(`[CLOSED_LOOP][CONTINUE_PROMPT_EMPTY] source=${sourceText}`);
        appendClosedLoopSimple('CONTINUE_PREPARE', { round: closedLoopContinueState.round, promptLen: 0, reason: 'empty' });
        return { ok: false, reason: 'continue_prompt_empty' };
      }

      if (shouldStop()) {
        ToolboxShell.appendLog(
          `[CLOSED_LOOP][REAL_CANCEL_DETECTED] source=${sourceText} stage=enter shouldStop=1`,
        );
        return { ok: false, reason: 'cancelled' };
      }

      if (state && (state.cancelWaitingSend || state.messageSendCancelRequested)) {
        ToolboxShell.appendLog(
          `[CLOSED_LOOP][REAL_CANCEL_DETECTED] source=${sourceText} stage=enter `
          + `cancelWaitingSend=${state.cancelWaitingSend ? 1 : 0} messageSendCancelRequested=${state.messageSendCancelRequested ? 1 : 0}`,
        );
        return { ok: false, reason: 'cancelled' };
      }

      // Wait assistant not generating.
      for (let i = 0; i < 40; i += 1) {
        if (shouldStop()) {
          return { ok: false, reason: 'cancelled' };
        }
        const cap = getUploadPageCapability({ heavy: false });
        const isGenerating = !!(cap && (cap.isResponding || String(cap.response_state || '') === 'generating'));
        if (!isGenerating) break;
        appendClosedLoopSimple('WAIT_ASSISTANT_BUSY', {
          round: closedLoopContinueState.round,
          reason: String(cap && cap.response_state_reason ? cap.response_state_reason : 'assistant_busy'),
        });
        await new Promise((r) => setTimeout(r, 250));
      }

      // Write composer (no strict verify, only ensure non-empty).
      let wroteOk = false;
      for (let w = 0; w < 2; w += 1) {
        if (shouldStop()) return { ok: false, reason: 'cancelled' };
        if (!ComposerApi || typeof ComposerApi.setComposerValue !== 'function' || typeof ComposerApi.getComposerText !== 'function') {
          ToolboxShell.appendLog(`[CLOSED_LOOP][SEND_FAILED] source=${sourceText} reason=composer-api-missing`);
          return { ok: false, reason: 'composer-api-missing' };
        }

        ComposerApi.setComposerValue(prompt);

        // Trigger common composer events (best-effort).
        const composerEl = document.querySelector('#prompt-textarea, [data-testid="prompt-textarea"], main form [contenteditable="true"], main form textarea, main [role="textbox"]');
        if (composerEl) {
          try { composerEl.focus(); } catch (e) {
            const errText = e && e.message ? e.message : String(e);
            console.warn('[CLOSED_LOOP][COMPOSER_EVENT_FAILED]', e);
            ToolboxShell.appendLog(`[CLOSED_LOOP][COMPOSER_EVENT_FAILED] source=${sourceText} event=focus error=${errText}`);
          }
          try { composerEl.dispatchEvent(new Event('beforeinput', { bubbles: true })); } catch (e) {
            const errText = e && e.message ? e.message : String(e);
            console.warn('[CLOSED_LOOP][COMPOSER_EVENT_FAILED]', e);
            ToolboxShell.appendLog(`[CLOSED_LOOP][COMPOSER_EVENT_FAILED] source=${sourceText} event=beforeinput error=${errText}`);
          }
          try { composerEl.dispatchEvent(new Event('input', { bubbles: true })); } catch (e) {
            const errText = e && e.message ? e.message : String(e);
            console.warn('[CLOSED_LOOP][COMPOSER_EVENT_FAILED]', e);
            ToolboxShell.appendLog(`[CLOSED_LOOP][COMPOSER_EVENT_FAILED] source=${sourceText} event=input error=${errText}`);
          }
          try { composerEl.dispatchEvent(new Event('change', { bubbles: true })); } catch (e) {
            const errText = e && e.message ? e.message : String(e);
            console.warn('[CLOSED_LOOP][COMPOSER_EVENT_FAILED]', e);
            ToolboxShell.appendLog(`[CLOSED_LOOP][COMPOSER_EVENT_FAILED] source=${sourceText} event=change error=${errText}`);
          }
          try { composerEl.dispatchEvent(new Event('compositionend', { bubbles: true })); } catch (e) {
            const errText = e && e.message ? e.message : String(e);
            console.warn('[CLOSED_LOOP][COMPOSER_EVENT_FAILED]', e);
            ToolboxShell.appendLog(`[CLOSED_LOOP][COMPOSER_EVENT_FAILED] source=${sourceText} event=compositionend error=${errText}`);
          }
        }

        const waitMs = 300 + Math.floor(Math.random() * 500);
        await new Promise((r) => setTimeout(r, waitMs));

        const actual = String(ComposerApi.getComposerText() || '').trim();
        const actualLen = actual.length;
        const expectedLen = prompt.length;
        const lenDiff = expectedLen - actualLen;
        appendClosedLoopSimple('COMPOSER_WRITE', {
          round: closedLoopContinueState.round,
          promptLen: expectedLen,
          composerLen: actualLen,
          lenDiff,
          action: actualLen > 0 ? 'send-anyway' : 'rewrite',
        });

        if (actualLen > 0) {
          // Ignore any len/hash/whitespace diffs; only log if differs.
          if (expectedLen !== actualLen) {
            ToolboxShell.appendLog(
              `[SEND_PAYLOAD][LEN_DIFF_IGNORED] source=${sourceText} expectedLen=${expectedLen} actualLen=${actualLen} action=continue-anyway`,
            );
          }
          wroteOk = true;
          break;
        }
      }

      if (!wroteOk) {
        ToolboxShell.appendLog(`[CLOSED_LOOP][SEND_FAILED] source=${sourceText} reason=composer_empty`);
        return { ok: false, reason: 'composer_empty' };
      }

      // Find send button and click when ready (wait up to 60s).
      const startTs = Date.now();
      let lastWaitLogTs = 0;
      for (;;) {
        if (shouldStop()) return { ok: false, reason: 'cancelled' };
        if (state && (state.cancelWaitingSend || state.messageSendCancelRequested)) {
          ToolboxShell.appendLog(
            `[CLOSED_LOOP][REAL_CANCEL_DETECTED] source=${sourceText} stage=send-wait `
            + `cancelWaitingSend=${state.cancelWaitingSend ? 1 : 0} messageSendCancelRequested=${state.messageSendCancelRequested ? 1 : 0}`,
          );
          return { ok: false, reason: 'cancelled' };
        }
        const elapsedMs = Date.now() - startTs;
        if (elapsedMs > 60000) break;

        const capNow = getUploadPageCapability({ heavy: false });
        const isGenerating = !!(capNow && (capNow.isResponding || String(capNow.response_state || '') === 'generating'));
        if (isGenerating) {
          appendClosedLoopSimple('SEND_FAILED', { round: closedLoopContinueState.round, reason: 'assistant_busy' });
          return { ok: false, reason: 'assistant_busy' };
        }

        const clickState = resolveComposerSendClickState(sourceText, capNow);
        const btn = clickState.btn;
        const enabled = clickState.enabled;
        const nativeReady = clickState.nativeReady;
        const capReady = clickState.capReady;
        const sendReady = clickState.sendReady;

        if (clickState.canDirectClick) {
          if (!assertNativeButtonIsSendButton(btn, `closed-loop-continue:${sourceText}`)) {
            await new Promise((resolve) => window.setTimeout(resolve, 200));
            continue;
          }
          appendClosedLoopSimple('SEND_CLICK', {
            round: closedLoopContinueState.round,
            sendReady: true,
            buttonFound: true,
          });
          ToolboxShell.appendLog('[CLOSED_LOOP][CONTINUE_SEND_CLICK]');
          try { btn.click(); } catch (e) {
            ToolboxShell.appendLog(
              `[CLOSED_LOOP][CONTINUE_SEND_CLICK_FAILED] source=${sourceText} error=${e && e.message ? e.message : String(e)}`,
            );
          }
          appendClosedLoopSimple('WAIT_REPLY', { round: closedLoopContinueState.round });
          return {
            ok: true,
            sent: true,
            reason: (nativeReady && !enabled) ? 'clicked-by-native-ready' : 'clicked-enabled-button',
          };
        }

        let waitReason = clickState.reason || (btn
          ? (enabled ? 'ready-but-not-clicked' : 'button-disabled')
          : (nativeReady ? 'button-not-found-native-ready' : 'button-not-found'));
        if (capNow && capNow.response_state_reason) {
          waitReason = String(capNow.response_state_reason);
        }
        try {
          const payload = typeof getComposerPayloadStateForInitialSend === 'function'
            ? getComposerPayloadStateForInitialSend()
            : null;
          if (payload && payload.hasAttachment) {
            if (waitReason === 'button-disabled') {
              waitReason = 'send_button_disabled_with_payload';
            }
          }
        } catch (e) {
          const errText = e && e.message ? e.message : String(e);
          console.warn('[CLOSED_LOOP][PAYLOAD_STATE_READ_FAILED]', e);
          ToolboxShell.appendLog(
            `[CLOSED_LOOP][PAYLOAD_STATE_READ_FAILED] source=${sourceText} error=${errText}`,
          );
        }

        if (Date.now() - lastWaitLogTs >= 1000) {
          lastWaitLogTs = Date.now();
          ToolboxShell.appendLog(
            `[CLOSED_LOOP][SEND_BUTTON_WAIT_AFTER_UPLOAD] round=${closedLoopContinueState.round} elapsedMs=${elapsedMs} reason=${waitReason} `
            + `enabled=${enabled ? 1 : 0} nativeReady=${nativeReady ? 1 : 0} capReady=${capReady ? 1 : 0} `
            + `sendReady=${sendReady ? 1 : 0} canDirectClick=${clickState.canDirectClick ? 1 : 0} `
            + `canFallback=${clickState.canFallback ? 1 : 0} clickReason=${clickState.reason}`,
          );
        }

        appendClosedLoopSimple('SEND_CLICK', {
          round: closedLoopContinueState.round,
          sendReady,
          buttonFound: btn ? 1 : 0,
          reason: waitReason,
        });

        // If we believe it's sendable (nativeReady/capReady) but cannot click directly,
        // fall back to unified send helper when available (including: button exists but disabled).
        if (clickState.canFallback) {
          ToolboxShell.appendLog(
            `[CLOSED_LOOP][SEND_FALLBACK] source=${sourceText} reason=${clickState.reason} `
            + `buttonFound=${btn ? 1 : 0} enabled=${enabled ? 1 : 0} nativeReady=${nativeReady ? 1 : 0} capReady=${capReady ? 1 : 0} `
            + `sendReady=${sendReady ? 1 : 0} canDirectClick=${clickState.canDirectClick ? 1 : 0} canFallback=${clickState.canFallback ? 1 : 0}`,
          );
          let fallback = null;
          if (typeof sendCurrentComposerMessage === 'function') {
            fallback = await sendCurrentComposerMessage({
              source: sourceText,
              timeoutMs: 8000,
              shouldStop,
            });
          } else if (typeof sendCurrentComposerMessageLight === 'function') {
            fallback = await sendCurrentComposerMessageLight({
              source: sourceText,
              timeoutMs: 8000,
              shouldStop,
            });
          }
          if (fallback && fallback.ok) {
            appendClosedLoopSimple('WAIT_REPLY', { round: closedLoopContinueState.round, reason: 'fallback_send_current_composer_ok' });
            return { ok: true, sent: true, reason: 'fallback_send_current_composer' };
          }
        }

        // Re-dispatch input/change to wake sendability, then wait.
        const composerEl = document.querySelector('#prompt-textarea, [data-testid="prompt-textarea"], main form [contenteditable="true"], main form textarea, main [role="textbox"]');
        if (composerEl) {
          try { composerEl.dispatchEvent(new Event('input', { bubbles: true })); } catch (e) {
            const errText = e && e.message ? e.message : String(e);
            console.warn('[CLOSED_LOOP][COMPOSER_EVENT_FAILED]', e);
            ToolboxShell.appendLog(`[CLOSED_LOOP][COMPOSER_EVENT_FAILED] source=${sourceText} event=input_retry error=${errText}`);
          }
          try { composerEl.dispatchEvent(new Event('change', { bubbles: true })); } catch (e) {
            const errText = e && e.message ? e.message : String(e);
            console.warn('[CLOSED_LOOP][COMPOSER_EVENT_FAILED]', e);
            ToolboxShell.appendLog(`[CLOSED_LOOP][COMPOSER_EVENT_FAILED] source=${sourceText} event=change_retry error=${errText}`);
          }
        }
        await new Promise((r) => setTimeout(r, 500));
      }

      ToolboxShell.appendLog(`[CLOSED_LOOP][PAUSE_AFTER_SEND_FAILED] source=${sourceText} reason=send_button_not_ready`);
      return { ok: false, reason: 'send_button_not_ready' };
    }

    function getLastAssistantMessageTextForStopSignal() {
      try {
        if (typeof getLatestAssistantReplyText === 'function') {
          const picked = getLatestAssistantReplyText({
            label: 'stop-signal',
            forceRefresh: true,
          });
          if (picked && picked.ok && picked.text) {
            return String(picked.text || '').trim();
          }
        }
      } catch (error) {
        const errText = formatToolboxError(error);
        console.error('[STOP_SIGNAL][LATEST_ASSISTANT_READ_FAILED]', error);
        if (typeof ToolboxShell !== 'undefined' && typeof ToolboxShell.appendLog === 'function') {
          ToolboxShell.appendLog(
            `[STOP_SIGNAL][LATEST_ASSISTANT_READ_FAILED] error=${errText}`,
          );
        }
      }

      const assistantNodes = Array.from(
        document.querySelectorAll('[data-message-author-role="assistant"]'),
      );

      const lastNode = assistantNodes.length > 0
        ? assistantNodes[assistantNodes.length - 1]
        : null;

      if (!lastNode) {
        return '';
      }

      return String(lastNode.innerText || lastNode.textContent || '').trim();
    }

    function detectCopyHotkeyLoopStopSignal(cycleIndex) {
      const indexText = String(cycleIndex == null ? '-' : cycleIndex);
      const candidates = [];

      const domText = getLastAssistantMessageTextForStopSignal();
      if (domText) {
        candidates.push({ source: 'dom-latest-assistant', text: domText });
      }

      try {
        if (
          typeof ChatMessageExtractor !== 'undefined'
          && ChatMessageExtractor
          && typeof ChatMessageExtractor.getLatestAssistantAfterLatestUser === 'function'
          && (typeof ChatMessageExtractor.getFastTailMessageRecords === 'function'
            || typeof ChatMessageExtractor.buildRecords === 'function')
        ) {
          const records = typeof ChatMessageExtractor.getFastTailMessageRecords === 'function'
            ? ChatMessageExtractor.getFastTailMessageRecords({ includeHidden: false })
            : ChatMessageExtractor.buildRecords({ includeEmpty: false });
          const picked = ChatMessageExtractor.getLatestAssistantAfterLatestUser(records);
          if (picked && picked.ok && picked.record) {
            const recordText = String(picked.record.text || '').trim();
            if (recordText) {
              candidates.push({ source: 'extractor-record', text: recordText });
            }
          }
        }
      } catch (error) {
        const errText = formatToolboxError(error);
        console.error('[COPY_HOTKEY_CONTINUE_LOOP][detect-stop-signal-error]', {
          index: cycleIndex,
          error_type: error && error.name,
          error: error && error.message,
          stack: error && error.stack,
        });
        safeAppendLog(
          `[COPY_HOTKEY_CONTINUE_LOOP][detect-stop-signal-error] index=${indexText} error=${errText}`,
        );
        if (typeof ToolboxShell !== 'undefined' && typeof ToolboxShell.appendLog === 'function') {
          ToolboxShell.appendLog(
            `[COPY_HOTKEY_CONTINUE_LOOP][detect-stop-signal-error] index=${indexText} error=${errText}`,
          );
        }
      }

      for (let i = 0; i < candidates.length; i += 1) {
        const candidate = candidates[i];
        const terminal = checkClosedLoopTerminalSignalWithLog(
          candidate.text,
          'COPY_HOTKEY_CONTINUE_LOOP',
          'loop-detect',
          `index=${indexText} source=${candidate.source}`,
        );
        if (terminal.matched) {
          const preview = formatDoneSignalPreview(candidate.text);
          const hitLine =
            `[COPY_HOTKEY_CONTINUE_LOOP][assistant-terminal-signal] `
            + `index=${indexText} status=${terminal.status || '-'} `
            + `source=${candidate.source} reason=${terminal.reason || '-'} `
            + `preview=${preview}`;
          safeAppendLog(hitLine);
          if (typeof ToolboxShell !== 'undefined' && typeof ToolboxShell.appendLog === 'function') {
            ToolboxShell.appendLog(hitLine);
          }
          return {
            matched: true,
            reason: terminal.reason || 'assistant-terminal-signal',
            status: terminal.status || 'done',
            source: candidate.source,
          };
        }
      }

      return {
        matched: false,
        reason: 'not-matched',
        status: 'continue',
      };
    }

    function isAssistantBusyReason(reason) {
      const text = String(reason || '').toLowerCase();
      return (
        text.includes('assistant_busy')
        || text.includes('busy')
        || text.includes('generating')
        || text.includes('send_not_confirmed')
      );
    }

    async function copyLastMessageAndContinue(source = 'button') {
      const btn = rootElRef ? qs(UploadSelectors.copyContinueBtn, rootElRef) : null;

      if (copyContinueTaskRunning) {
        const runningMs = Date.now() - Number(copyContinueTaskStartedAt || 0);

        if (runningMs <= 90000) {
          ToolboxShell.appendLog(
            `[UPLOAD_COPY_CONTINUE][skip] reason=task-running runningMs=${runningMs}`,
          );
          return false;
        }

        ToolboxShell.appendLog(
          `[UPLOAD_COPY_CONTINUE][stale-release] runningMs=${runningMs}`,
        );
        copyContinueTaskRunning = false;
        copyContinueTaskStartedAt = 0;
      }

      if (btn) {
        const busyState = clearStaleUploadButtonBusy(btn, {
          action: 'copy-continue',
          source: String(source || '-'),
          logTag: 'UPLOAD_COPY_CONTINUE',
        });
        if (busyState.skipped) {
          ToolboxShell.appendLog(
            `[UPLOAD_COPY_CONTINUE][skip] reason=button-busy busyMs=${busyState.busyMs}`,
          );
          return false;
        }
      }

      copyContinueTaskRunning = true;
      copyContinueTaskStartedAt = Date.now();
      copyTaskStatus = 'waiting_assistant';
      state.copyContinueTask.runId = createId('copy_continue');
      state.copyContinueTask.cancelRequested = false;
      state.copyContinueTask.stopRequested = false;
      state.copyContinueTask.phase = 'waiting_reply';

      void unlockToolboxAudio('copy-continue-start');

      if (btn && btn.dataset.busy === '1') {
        ToolboxShell.appendLog('[UPLOAD_COPY_CONTINUE][skip] reason=button-busy-after-claim');
        copyContinueTaskRunning = false;
        copyContinueTaskStartedAt = 0;
        copyTaskStatus = 'idle';
        return false;
      }

      const assistantBusy = typeof ComposerApi !== 'undefined'
        && typeof ComposerApi.isAssistantLikelyBusy === 'function'
        && ComposerApi.isAssistantLikelyBusy();

      setCopyContinueButtonBusy(btn, true, {
        startedAt: copyContinueTaskStartedAt,
        assistantBusy,
      });

      ToolboxShell.appendLog(
        `[UPLOAD_COPY_CONTINUE][start] source=${String(source || '-')} assistantBusy=${assistantBusy ? '1' : '0'}`,
      );

      try {
        copyTaskStatus = 'copying';
        state.copyContinueTask.phase = 'copying';
        renderUploadButtonsOnly({ buttonTasksReason: 'copy-continue-copying' });

        const waitCopyResult = await waitAndCopyLatestAssistant({
          source,
          reason: `copy-and-continue:${String(source || '-')}`,
        });

        if (!waitCopyResult.ok) {
          ToolboxShell.appendLog(
            `[UPLOAD_COPY_CONTINUE][abort] reason=${waitCopyResult.reason || 'wait-assistant-failed'} detail=${waitCopyResult.detail || '-'}`,
          );
          return false;
        }

        copyTaskStatus = 'copied';

        ToolboxShell.appendLog(
          `[UPLOAD_COPY_CONTINUE][copied] chars=${waitCopyResult.chars || 0}`,
        );

        void playCopySuccessBeepSafe(source || '-', 'copyContinue');

        copyTaskStatus = 'sending_continue';
        state.copyContinueTask.phase = 'sending_continue';
        renderUploadButtonsOnly({ buttonTasksReason: 'copy-continue-sending' });

        const sentResult = await sendContinuePromptFromUnifiedPipeline('copy-continue-after-wait');

        if (!sentResult || !sentResult.ok) {
          ToolboxShell.appendLog('[UPLOAD_COPY_CONTINUE][failed] reason=continue-send-failed');
          return false;
        }

        copyTaskStatus = 'done';
        state.copyContinueTask.phase = 'success';
        setStatus('已复制最后回复，并发送：继续', 'success');
        ToolboxShell.appendLog('[UPLOAD_COPY_CONTINUE][done] copied=1 sent=1');
        setButtonTemporaryOk(btn);

        return true;
      } catch (error) {
        copyTaskStatus = 'failed';
        state.copyContinueTask.phase = 'failed';
        const errText = formatToolboxError(error);
        console.error('[ChatGPT toolbox] copyLastMessageAndContinue failed', error);
        ToolboxShell.appendLog(`[UPLOAD_COPY_CONTINUE][failed] error=${errText}`);
        setStatus(`复制并继续失败：${errText}`, 'error');
        setButtonTemporaryError(btn, '复制失败', 1200);
        return false;
      } finally {
        copyContinueTaskRunning = false;
        copyContinueTaskStartedAt = 0;
        if (copyTaskStatus !== 'done' && copyTaskStatus !== 'failed') {
          copyTaskStatus = 'idle';
          state.copyContinueTask.phase = 'idle';
        }
        state.copyContinueTask.runId = '';
        state.copyContinueTask.cancelRequested = false;
        state.copyContinueTask.stopRequested = false;

        setCopyContinueButtonBusy(btn, false);

        if (btn && typeof clearButtonLongWaitDangerTimer === 'function') {
          clearButtonLongWaitDangerTimer(btn, 'task_done');
        }

        renderUploadButtonsOnly();
      }
    }


    function hashShort(value) {
      return hashStringTiny(value);
    }

    function getLatestAssistantTurnIdLightweight() {
      const turns = Array.from(document.querySelectorAll(
        '[data-testid^="conversation-turn-"], [data-message-author-role="assistant"]',
      ));
      for (let i = turns.length - 1; i >= 0; i -= 1) {
        const el = turns[i];
        if (!el) {
          continue;
        }
        const testId = el.getAttribute('data-testid') || '';
        if (testId) {
          return testId;
        }
        const closestTurn = el.closest('[data-testid^="conversation-turn-"]');
        if (closestTurn) {
          return closestTurn.getAttribute('data-testid') || '';
        }
      }
      return '';
    }

    function isAssistantBusyFromClosedLoopWaitState(busyState) {
      if (!busyState || typeof busyState !== 'object') {
        return false;
      }
      return !!(
        busyState.assistantBusy === true
        || busyState.detectBusy === true
        || busyState.stopButton === true
        || String(busyState.responseState || '').trim().toLowerCase() === 'generating'
      );
    }

    function getAssistantBusyStateForClosedLoopWait(source) {
      const sourceText = String(source || 'closed-loop-wait').trim() || 'closed-loop-wait';
      let responseState = {};
      try {
        responseState = typeof detectComposerResponseState === 'function'
          ? (detectComposerResponseState({ light: true }) || detectComposerResponseState() || {})
          : {};
      } catch (error) {
        const errText = formatToolboxError(error);
        console.error('[COPY_HOTKEY_CONTINUE_LOOP][busy-state-response-failed]', {
          source: sourceText,
          error_type: error && error.name,
          error: errText,
          stack: error && error.stack,
        });
        if (typeof ToolboxShell !== 'undefined' && typeof ToolboxShell.appendLog === 'function') {
          ToolboxShell.appendLog(
            `[COPY_HOTKEY_CONTINUE_LOOP][busy-state-response-failed] source=${sourceText} error=${errText}`,
          );
        }
        responseState = {};
      }

      const responseStateText = String(
        responseState.response_state
          || responseState.state
          || responseState.reason
          || '',
      ).trim().toLowerCase();

      let stopButton = false;
      let composerBusy = false;
      try {
        stopButton = (
          (typeof hasRealChatGPTStopGeneratingButton === 'function' && hasRealChatGPTStopGeneratingButton())
          || (
            typeof ComposerApi !== 'undefined'
            && ComposerApi
            && typeof ComposerApi.isAssistantLikelyBusy === 'function'
            && ComposerApi.isAssistantLikelyBusy()
          )
        );
        composerBusy = stopButton;
      } catch (error) {
        const errText = formatToolboxError(error);
        console.error('[COPY_HOTKEY_CONTINUE_LOOP][busy-state-composer-failed]', {
          source: sourceText,
          error_type: error && error.name,
          error: errText,
          stack: error && error.stack,
        });
        if (typeof ToolboxShell !== 'undefined' && typeof ToolboxShell.appendLog === 'function') {
          ToolboxShell.appendLog(
            `[COPY_HOTKEY_CONTINUE_LOOP][busy-state-composer-failed] source=${sourceText} error=${errText}`,
          );
        }
        stopButton = false;
        composerBusy = false;
      }

      const responseGenerating = responseStateText === 'generating'
        || String(responseState.response_state_reason || responseState.reason || '').trim().toLowerCase() === 'assistant_busy'
        || responseState.is_responding === true
        || responseState.responding === true
        || responseState.busy === true;

      const assistantBusy = composerBusy || responseGenerating;

      return {
        assistantBusy,
        detectBusy: assistantBusy,
        stopButton,
        responseState: responseStateText,
        composerBusy,
        source: sourceText,
      };
    }

    function finishClosedLoopWaitCycle(sourceText, prevKey, nextKey, doneTag) {
      const round = Number(closedLoopContinueState.round || 0);
      const finalKey = String(nextKey || '');
      if (
        closedLoopContinueState.lastProcessedRound === round
        && closedLoopContinueState.lastProcessedReplyKey === finalKey
        && finalKey
      ) {
        safeAppendLog(
          `[CLOSED_LOOP][FINAL_REPLY_DUPLICATE_SKIP] runId=${closedLoopContinueState.runId || '-'} round=${round} finalHash=${hashShort(finalKey)}`,
        );
        return true;
      }

      let finalText = '';
      try {
        finalText = String(getLastAssistantMessageTextForStopSignal() || '').trim();
      } catch (error) {
        const errText = formatToolboxError(error);
        console.error('[COPY_HOTKEY_CONTINUE_LOOP][reply-final-read-failed]', {
          source: sourceText,
          error_type: error && error.name,
          error: errText,
          stack: error && error.stack,
        });
        safeAppendLog(
          `[COPY_HOTKEY_CONTINUE_LOOP][reply-final-read-failed] source=${sourceText} error=${errText}`,
        );
      }

      const turnId = getLatestAssistantTurnIdLightweight() || '-';
      safeAppendLog(
        `[COPY_HOTKEY_CONTINUE_LOOP][reply-final-picked] turnId=${turnId} len=${finalText.length} hash=${hashShort(finalText)} tag=${doneTag || '-'}`,
      );
      if (closedLoopContinueState.running) {
        safeAppendLog(
          `[CLOSED_LOOP][FINAL_REPLY_PROCESS] runId=${closedLoopContinueState.runId || '-'} round=${round} finalHash=${hashShort(finalKey)} finalLen=${finalText.length}`,
        );
      }

      closedLoopContinueState.lastProcessedRound = round;
      closedLoopContinueState.lastProcessedReplyKey = finalKey;

      safeAppendLog(
        `[COPY_HOTKEY_CONTINUE_LOOP][${doneTag || 'wait-cycle-done'}] source=${sourceText} previousHash=${hashShort(prevKey)} previousLen=${String(prevKey || '').length} nextHash=${hashShort(finalKey)} nextLen=${finalKey.length}`,
      );
      return true;
    }

    function buildAssistantMessageKeyFromRecord(record, textOverride = '') {
      const recordObj = record && typeof record === 'object' ? record : null;
      if (!recordObj) {
        return '';
      }
      const text = typeof ChatMessageExtractor !== 'undefined'
        && typeof ChatMessageExtractor.cleanMessageText === 'function'
        ? ChatMessageExtractor.cleanMessageText(textOverride || recordObj.text || '').trim()
        : String(textOverride || recordObj.text || '').trim();
      const turnId = String(recordObj.turn_id || '').trim();
      if (turnId) {
        return turnId;
      }
      return [
        turnId,
        text,
        String(recordObj.char_count || 0),
        String(recordObj.no_space_char_count || 0),
      ].join('||');
    }

    function getLastAssistantMessageKeySafe() {
      try {
        if (
          typeof ChatMessageExtractor === 'undefined'
          || typeof ChatMessageExtractor.getLatestAssistantAfterLatestUser !== 'function'
          || (typeof ChatMessageExtractor.getFastTailMessageRecords !== 'function'
            && typeof ChatMessageExtractor.buildRecords !== 'function')
        ) {
          return '';
        }
        const records = typeof ChatMessageExtractor.getFastTailMessageRecords === 'function'
          ? ChatMessageExtractor.getFastTailMessageRecords({ includeHidden: false })
          : ChatMessageExtractor.buildRecords({ includeEmpty: false });
        const picked = ChatMessageExtractor.getLatestAssistantAfterLatestUser(records);
        if (!picked || !picked.ok || !picked.record) {
          return '';
        }
        return buildAssistantMessageKeyFromRecord(picked.record);
      } catch (error) {
        console.error('[COPY_HOTKEY_CONTINUE_LOOP][get-key-failed]', {
          error_type: error && error.name,
          error: error && error.message,
          stack: error && error.stack,
        });
        return '';
      }
    }

    function logCopyHotkeyContinueStep(sourceText, step) {
      ToolboxShell.appendLog(
        `[COPY_HOTKEY_CONTINUE][STEP] source=${sourceText || '-'} step=${step}`,
      );
      console.warn('[COPY_HOTKEY_CONTINUE][STEP]', {
        source: sourceText || '-',
        step,
      });
    }

    function isCopyAndHotkeyShortcut(event) {
      const item = getCopyAndHotkeyShortcutConfig();
      return isShortcutEventMatched(event, item);
    }

    async function runCopyHotkeyOnce(source = 'unknown', event = null) {
      const src = String(source || 'unknown').trim() || 'unknown';
      ToolboxShell.appendLog(`[COPY_HOTKEY_ONCE][run] source=${src}`);
      try {
        return await handleCopyHotkeyOnceTrigger(src, event);
      } finally {
        scheduleRenderUpload(`copy-hotkey-once:${src}`);
      }
    }

    async function handleCopyHotkeyOnceTrigger(source = 'button', event = null) {
      if (event) {
        event.preventDefault();
        event.stopPropagation();
        if (typeof event.stopImmediatePropagation === 'function') {
          event.stopImmediatePropagation();
        }
      }

      const sourceText = String(source || 'button').trim() || 'button';
      const actionSource = sourceText === 'delegated-click' ? 'button' : sourceText;

      if (actionSource === 'shortcut') {
        ToolboxShell.appendLog('[COPY_HOTKEY_ONCE][shortcut-trigger]');
      } else {
        ToolboxShell.appendLog('[COPY_HOTKEY_ONCE][click] source=button');
      }

      try {
        return await runCopyAndHotkeyAction(actionSource, {
          waitForCurrentReply: true,
          allowDuringGenerating: true,
          ownerButtonId: COPY_HOTKEY_ONCE_OWNER_BUTTON_ID,
        });
      } catch (error) {
        const errText = error && error.message ? error.message : String(error);
        const failTag = actionSource === 'shortcut'
          ? '[COPY_HOTKEY_ONCE][SHORTCUT_FAILED]'
          : '[COPY_HOTKEY_ONCE][CLICK_FAILED]';

        console.error(failTag, {
          error_type: error && error.name,
          error: errText,
          stack: error && error.stack,
        });
        ToolboxShell.appendLog(`${failTag} ${errText}`);
        setStatus(`复制+快捷键失败：${errText}`, 'error');

        return {
          ok: false,
          reason: 'exception',
          detail: errText,
          copied: false,
          hotkeySent: false,
        };
      }
    }

    function bindCopyAndHotkeyShortcut() {
      if (isUnifiedToolboxShortcutEnabled()) {
        ToolboxShell.appendLog('[SHORTCUT][bind-skip] copyAndHotkeyOnce=unified-registry');
        return;
      }
      if (window.__xzCopyAndHotkeyShortcutBound) {
        ToolboxShell.appendLog('[SHORTCUT][bind-skip] copyAndHotkeyOnce=already-bound');
        return;
      }

      window.__xzCopyAndHotkeyShortcutBound = true;

      window.addEventListener(
        'keydown',
        (event) => {
          if (!isCopyAndHotkeyShortcut(event)) {
            return;
          }

          if (event.repeat) {
            event.preventDefault();
            event.stopPropagation();
            return;
          }

          if (shouldIgnoreToolboxShortcutTarget(event.target)) {
            return;
          }

          event.preventDefault();
          event.stopPropagation();

          void handleCopyHotkeyOnceTrigger('shortcut', event);
        },
        true,
      );

      const item = getCopyAndHotkeyShortcutConfig();
      ToolboxShell.appendLog('[SHORTCUT][bind] copyAndHotkeyOnce=configurable');
      console.log('[TOOLBOX][COPY_HOTKEY][SHORTCUT_BOUND]', {
        shortcut: item.label || '-',
      });
    }

    function isSendCopyAndHotkeyShortcut(event) {
      const cfg = getShortcutConfig();
      const item = cfg && cfg.sendCopyAndHotkeyOnce ? cfg.sendCopyAndHotkeyOnce : null;
      if (typeof isShortcutConfigEventMatched === 'function') {
        return isShortcutConfigEventMatched(event, item);
      }
      return isShortcutEventMatched(event, item);
    }

    function handleSendCopyAndHotkeyShortcut(event, source = 'document') {
      if (!isSendCopyAndHotkeyShortcut(event)) {
        return false;
      }
      if (event.__cgptSendCopyHotkeyHandled) {
        ToolboxShell.appendLog(
          `[SHORTCUT][SEND_COPY_HOTKEY_SKIP] reason=already-handled source=${source || '-'}`
        );
        return true;
      }
      event.__cgptSendCopyHotkeyHandled = true;

      const keyLabel = typeof formatShortcutFromEvent === 'function'
        ? formatShortcutFromEvent(event)
        : `${event.ctrlKey ? 'Ctrl+' : ''}${event.altKey ? 'Alt+' : ''}${event.shiftKey ? 'Shift+' : ''}${event.metaKey ? 'Meta+' : ''}${event.key || event.code || '-'}`;

      ToolboxShell.appendLog(
        `[SHORTCUT][SEND_COPY_HOTKEY_MATCH] source=${source || '-'} key=${keyLabel}`,
      );

      if (event.repeat) {
        event.preventDefault();
        event.stopPropagation();
        ToolboxShell.appendLog('[SHORTCUT][SEND_COPY_HOTKEY_SKIP] reason=repeat');
        return true;
      }

      if (shouldIgnoreToolboxShortcutTarget(event.target)) {
        ToolboxShell.appendLog('[SHORTCUT][SEND_COPY_HOTKEY_SKIP] reason=toolbox-editing');
        return false;
      }

      event.preventDefault();
      event.stopPropagation();
      if (typeof event.stopImmediatePropagation === 'function') {
        event.stopImmediatePropagation();
      }

      const btn = rootElRef ? qs(UploadSelectors.sendCopyHotkeyBtn, rootElRef) : null;
      if (!btn) {
        ToolboxShell.appendLog('[SHORTCUT][SEND_COPY_HOTKEY_SKIP] reason=button-missing');
        setStatus('发送+复制+快捷键按钮未找到，无法通过快捷键触发', 'warn');
        return true;
      }

      const runtimeAction = resolveUploadButtonRuntimeAction(btn, 'send-copy-hotkey');
      ToolboxShell.appendLog(
        `[SHORTCUT][SEND_COPY_HOTKEY_TRIGGER] source=${source || '-'} action=${runtimeAction || 'send-copy-hotkey'}`,
      );
      dispatchToolboxActionSafe(runtimeAction || 'send-copy-hotkey', {
        button: btn,
        source: `shortcut-send-copy-hotkey:${source || 'document'}`,
        event,
      });
      return true;
    }

    function bindSendCopyAndHotkeyShortcut() {
      if (isUnifiedToolboxShortcutEnabled()) {
        ToolboxShell.appendLog('[SHORTCUT][bind-skip] sendCopyAndHotkeyOnce=unified-registry');
        return;
      }
      if (window.__xzSendCopyAndHotkeyShortcutBound) {
        ToolboxShell.appendLog('[SHORTCUT][bind-skip] sendCopyAndHotkeyOnce=already-bound');
        return;
      }

      window.__xzSendCopyAndHotkeyShortcutBound = true;

      window.addEventListener(
        'keydown',
        (event) => {
          handleSendCopyAndHotkeyShortcut(event, 'window');
        },
        true,
      );

      document.addEventListener(
        'keydown',
        (event) => {
          handleSendCopyAndHotkeyShortcut(event, 'document');
        },
        true,
      );

      const cfg = getShortcutConfig();
      const item = cfg && cfg.sendCopyAndHotkeyOnce ? cfg.sendCopyAndHotkeyOnce : null;
      ToolboxShell.appendLog(
        `[SHORTCUT][bind] sendCopyAndHotkeyOnce=configurable label=${item && item.label ? item.label : '-'} priority=high action=send-copy-hotkey`,
      );
    }

    function paintCopyHotkeyOnceButtonRunningNow(btn, reason = '-') {
      if (!(btn instanceof HTMLButtonElement)) {
        return false;
      }
      const title = '正在等待回复完成；再次点击将取消本次复制+快捷键任务';
      btn.dataset.busy = '1';
      btn.dataset.cgptTaskPhase = 'waiting_reply';
      btn.dataset.cgptButtonPhase = 'waiting_reply';
      btn.dataset.cgptRuntimeAction = 'cancel';
      btn.dataset.cgptButtonAction = 'cancel';
      btn.dataset.cgptCopyHotkeyImmediatePaint = '1';
      btn.disabled = false;
      btn.textContent = '等待回复后复制';
      btn.title = title;
      btn.setAttribute('aria-busy', 'true');
      btn.classList.remove(
        'cgpt-upload-idle',
        'cgpt-btn-idle',
        'cgpt-btn-disabled',
        'cgpt-btn-failed',
        'cgpt-upload-failed',
        'cgpt-upload-success',
      );
      btn.classList.add(
        'danger',
        'cgpt-btn-danger',
        'cgpt-btn-stop',
        'cgpt-btn-busy',
        'cgpt-btn-waiting-danger',
        'cgpt-action-running',
      );
      if (typeof ToolboxShell !== 'undefined' && ToolboxShell && typeof ToolboxShell.appendLog === 'function') {
        ToolboxShell.appendLog(
          `[COPY_HOTKEY_ONCE][IMMEDIATE_BUTTON_RUNNING] id=${btn.id || '-'} reason=${reason || '-'} text=${String(btn.textContent || '').trim()}`,
        );
      }
      return true;
    }

    async function runCopyAndHotkeyAction(source = 'button', options = {}) {
      const sourceText = String(source || '').trim() || 'button';
      if (sourceText === 'send-copy-hotkey' || sourceText.includes('send-copy-hotkey')) {
        ToolboxShell.appendLog(
          `[COPY_HOTKEY_ONCE][DENY] source=${sourceText} reason=send-copy-hotkey-must-use-dedicated-flow`,
        );
        return {
          ok: false,
          reason: 'send-copy-hotkey-dedicated-flow-required',
          copied: false,
          hotkeySent: false,
        };
      }
      const flowOptions = options && typeof options === 'object' ? options : {};
      const allowDuringGenerating = flowOptions.allowDuringGenerating === true;
      const waitForCurrentReply = flowOptions.waitForCurrentReply !== false;
      const ownerButtonId = String(
        flowOptions.ownerButtonId || COPY_HOTKEY_ONCE_OWNER_BUTTON_ID,
      ).trim() || COPY_HOTKEY_ONCE_OWNER_BUTTON_ID;
      const externalShouldStop = typeof flowOptions.shouldStop === 'function'
        ? flowOptions.shouldStop
        : () => false;

      const isGenerating = isAssistantGeneratingNow('copy-hotkey-start');
      if (isGenerating && !allowDuringGenerating) {
        ToolboxShell.appendLog(
          `[COPY_HOTKEY_ONCE][DENY] source=${sourceText} reason=generating-not-allowed`,
        );
        return {
          ok: false,
          reason: 'generating-not-allowed',
          copied: false,
          hotkeySent: false,
        };
      }

      const task = ensureCopyHotkeyOnceTask();
      const currentPhase = String(task.phase || 'idle').trim().toLowerCase();
      if (COPY_HOTKEY_ONCE_CANCELLABLE_PHASES.has(currentPhase) || currentPhase === 'cancelling') {
        cancelCopyHotkeyOnce(sourceText);
        return {
          ok: false,
          reason: 'cancel-requested',
          copied: false,
          hotkeySent: false,
        };
      }

      const startPhase = isGenerating ? 'waiting_reply' : 'checking_reply';
      const runId = createUploadTaskRunId('copy_hotkey_once');
      task.runId = runId;
      task.cancelRequested = false;
      task.lastError = null;
      task.source = sourceText;
      task.waitForCurrentReply = waitForCurrentReply;
      task.abortController = typeof AbortController !== 'undefined' ? new AbortController() : null;
      task.startedAt = Date.now();
      copyHotkeyOnceTaskStartedAt = task.startedAt;
      const shouldStop = () => externalShouldStop() || isCopyHotkeyOnceCancelled(runId);

      const btn = rootElRef ? qs(UploadSelectors.copyHotkeyOnceBtn, rootElRef) : null;

      const actionLock = claimUploadActionLock('copy-hotkey-once');
      if (!actionLock.ok) {
        ToolboxShell.appendLog(
          `[COPY_HOTKEY_ONCE][skip] reason=${actionLock.reason} runningMs=${actionLock.runningMs || 0}`,
        );
        return {
          ok: false,
          reason: actionLock.reason || 'task-running',
          copied: false,
          hotkeySent: false,
        };
      }

      if (
        isCopyHotkeyContinueActive()
        || isCopyHotkeyLoopActive()
        || isCopyHotkeyUploadVerifyLoopActive()
      ) {
        releaseUploadActionLock('copy-hotkey-once');
        ToolboxShell.appendLog(
          `[COPY_HOTKEY_ONCE][skip] reason=copy-hotkey-continue-running continueTask=${isCopyHotkeyContinueActive() ? '1' : '0'} loop=${isCopyHotkeyLoopActive() ? '1' : '0'} uploadVerifyLoop=${isCopyHotkeyUploadVerifyLoopActive() ? '1' : '0'}`,
        );
        setStatus('复制+快捷键失败：当前已有复制+快捷键任务运行中', 'warn');
        return {
          ok: false,
          reason: 'copy-hotkey-continue-running',
          copied: false,
          hotkeySent: false,
        };
      }

      task.running = true;
      task.action = COPY_HOTKEY_ONCE_ACTION;
      task.taskKey = COPY_HOTKEY_ONCE_TASK_KEY;
      task.ownerButtonId = ownerButtonId;
      setCopyHotkeyOncePhase(
        startPhase === 'checking_reply' ? 'waiting_reply' : startPhase,
        sourceText || 'start',
      );
      ToolboxShell.appendLog(
        `[COPY_HOTKEY_ONCE][START] source=${sourceText} phase=${task.phase} owner=${ownerButtonId} generating=${isGenerating ? 1 : 0}`,
      );
      ToolboxShell.appendLog(
        `[COPY_HOTKEY_ONCE][OWNER_SET] owner=${ownerButtonId} action=${COPY_HOTKEY_ONCE_ACTION} phase=${task.phase}`,
      );
      renderUploadButtonsOnly(`copy-hotkey-start:${sourceText}`);
      if (btn) {
        paintCopyHotkeyOnceButtonRunningNow(btn, sourceText || 'start');
      }
      setStatus(
        isGenerating
          ? '正在等待回答完成，然后复制并发送快捷键'
          : '正在执行复制+快捷键...',
        'running',
      );
      console.log('[TOOLBOX][COPY_HOTKEY][START]', {
        source: sourceText,
        phase: task.phase,
        generating: isGenerating,
        ownerButtonId,
      });

      if (btn && typeof startButtonLongWaitDangerTimer === 'function') {
        startButtonLongWaitDangerTimer(btn, 'long_wait_reply_or_hotkey', BUTTON_LONG_WAIT_DANGER_MS);
      }

      try {
        if (isGenerating || isAssistantGeneratingNow('copy-hotkey-wait')) {
          ToolboxShell.appendLog(
            `[COPY_HOTKEY_ONCE][WAIT_REPLY] source=${sourceText} responseState=generating`,
          );
        }

        const waitCopyResult = await waitAndCopyLatestAssistant({
          source,
          reason: `copy-and-hotkey:${sourceText || '-'}`,
          shouldStop,
        });

        if (waitCopyResult && waitCopyResult.ok) {
          ToolboxShell.appendLog(
            `[COPY_HOTKEY_ONCE][COPY_AFTER_REPLY_DONE] source=${sourceText}`,
          );
        }

        if (!waitCopyResult.ok) {
          const reason = waitCopyResult.reason || 'copy-failed';
          const errText = waitCopyResult.detail || reason;
          ToolboxShell.appendLog(`[COPY_HOTKEY_ONCE][abort] reason=${reason} detail=${errText}`);
          if (reason === 'cancelled' || shouldStop()) {
            setStatus('已取消复制+快捷键等待任务', 'warn');
            finishCopyHotkeyOnceTask('cancelled', runId, sourceText || 'button');
          } else {
            task.lastError = errText;
            setStatus(`复制+快捷键失败：${reason}`, 'warn');
            finishCopyHotkeyOnceTask('failed', runId, sourceText || 'button');
          }
          return {
            ok: false,
            reason,
            detail: errText,
            copied: false,
            hotkeySent: false,
            continueSent: false,
            assistantDoneSignal: false,
          };
        }

        ToolboxShell.appendLog(
          `[COPY_HOTKEY_ONCE][copied] chars=${waitCopyResult.chars || 0}`,
        );

        if (typeof playCopySuccessBeepSafe === 'function') {
          void playCopySuccessBeepSafe(sourceText || '-', 'copyHotkeyOnce');
        }

        setCopyHotkeyOncePhase('copying', `${sourceText || 'start'}:copying`);
        setCopyHotkeyOncePhase('confirming_clipboard', `${sourceText || 'start'}:clipboard`);

        if (shouldStop()) {
          ToolboxShell.appendLog('[COPY_HOTKEY_ONCE][abort] reason=cancelled-after-copy');
          finishCopyHotkeyOnceTask('cancelled', runId, sourceText || 'button');
          return {
            ok: false,
            reason: 'cancelled',
            copied: true,
            hotkeySent: false,
            continueSent: false,
            assistantDoneSignal: false,
          };
        }

        setCopyHotkeyOncePhase('sending_hotkey', `${sourceText || 'start'}:send-hotkey`);

        const hotkeyGateState = {
          responseState: readLiveHotkeyGateSignals().responseState,
          waitingReply: false,
          replyDone: true,
          copied: true,
          runId: runId,
          ownerButtonId,
          phase: 'sending_hotkey',
        };
        const hotkeyFlow = await sendHotkeyAfterCopy({
          copiedText: waitCopyResult.text,
          reason: 'copy-and-hotkey',
          gateState: hotkeyGateState,
          shouldStop,
        });

        if (!hotkeyFlow.ok) {
          const failReason = hotkeyFlow.reason || 'hotkey-failed';
          const errText = hotkeyFlow.detail || failReason;
          const targetLabel = typeof getCopyThenShortcutTargetLabel === 'function'
            ? getCopyThenShortcutTargetLabel()
            : 'Ctrl+Alt+I';
          ToolboxShell.appendLog(`[COPY_HOTKEY_ONCE][failed] reason=${failReason} detail=${errText}`);
          setStatus(
            hotkeyFlow.reason === 'clipboard-not-ready'
              ? `复制+快捷键失败：剪贴板未就绪：${errText}`
              : `复制成功，但 ${targetLabel || '目标快捷键'} 执行失败`,
            'error',
          );
          task.lastError = errText;
          finishCopyHotkeyOnceTask('failed', runId, sourceText || 'button');
          return {
            ok: false,
            reason: failReason,
            detail: errText,
            copied: true,
            hotkeySent: false,
            continueSent: false,
            assistantDoneSignal: false,
          };
        }

        const targetLabelDone = typeof getCopyThenShortcutTargetLabel === 'function'
          ? getCopyThenShortcutTargetLabel()
          : 'Ctrl+Alt+I';
        ToolboxShell.appendLog('[COPY_HOTKEY_ONCE][done] copied=1 hotkey=1 continue=0');
        setStatus(`已复制最后回复，并发送 ${targetLabelDone || '目标快捷键'}`, 'success');

        finishCopyHotkeyOnceTask('success', runId, `${sourceText || 'start'}:done`);

        if (btn) {
          setButtonTemporaryOk(btn);
        }

        return {
          ok: true,
          reason: 'ok',
          copied: true,
          hotkeySent: true,
          continueSent: false,
          assistantDoneSignal: false,
          copied_text: String(waitCopyResult.text || ''),
        };
      } catch (error) {
        const errText = formatToolboxError(error);

        console.error('[COPY_HOTKEY_ONCE][ERROR]', {
          source: sourceText,
          error_type: error && error.name,
          error: errText,
          stack: error && error.stack,
        });

        ToolboxShell.appendLog(`[COPY_HOTKEY_ONCE][failed] source=${sourceText || '-'} error=${errText}`);
        setStatus(`复制+快捷键失败：${errText}`, 'error');
        if (task.runId === runId) {
          task.lastError = errText;
          finishCopyHotkeyOnceTask('failed', runId, sourceText || 'button');
        }

        if (btn) {
          setButtonTemporaryError(btn, '执行失败', 1200);
        }

        return {
          ok: false,
          reason: 'exception',
          detail: errText,
          copied: false,
          hotkeySent: false,
        };
      } finally {
        releaseUploadActionLock('copy-hotkey-once');

        if (btn && typeof clearButtonLongWaitDangerTimer === 'function') {
          clearButtonLongWaitDangerTimer(btn, 'finally');
        }

        if (btn) {
          delete btn.dataset.cgptCopyHotkeyImmediatePaint;
          delete btn.dataset.cgptButtonAction;
          btn.dataset.busy = '0';
          btn.removeAttribute('aria-busy');
        }

        renderUploadButtonsOnly();
      }
    }

    async function runClosedLoopContinueOnce(source, options = {}) {
      const useHotkey = options.useHotkey !== false;

      ToolboxShell.appendLog(
        `[CLOSED_LOOP][RUN_ONCE] source=${source} useHotkey=${useHotkey ? 1 : 0} mode=${options.sourceMode || '-'}`,
      );

      if (useHotkey) {
        return copyHotkeyAndContinueOnce(source, options);
      }

      return copyAndContinueOnceWithoutHotkey(source, options);
    }

    function buildCopyHotkeyContinueContext(source, options = {}) {
      const sourceText = String(source || '');
      const flowOptions = options && typeof options === 'object' ? options : {};
      const managedPhase = flowOptions.managedPhase === true;
      const flowRunId = String(flowOptions.runId || '').trim();
      const shouldStop = typeof flowOptions.shouldStop === 'function'
        ? flowOptions.shouldStop
        : () => (managedPhase ? isCopyHotkeyContinueCancelled(flowRunId) : false);
      const isClosedLoopIsolated = flowOptions.isolated === true
        || isClosedLoopStepSource(sourceText);
      const isUploadVerifyLoopMode = !isClosedLoopIsolated
        && sourceText.startsWith('upload-verify-loop-');
      const isLegacyLoopMode = sourceText.startsWith('loop-');
      const isLoopMode = isLegacyLoopMode || isUploadVerifyLoopMode || isClosedLoopIsolated;
      const loopCycleIndex = isLoopMode
        ? Number(
          String(
            isClosedLoopIsolated
              ? parseClosedLoopStepRound(sourceText)
              : (isUploadVerifyLoopMode
                ? sourceText.match(/upload-verify-loop-(\d+)/)?.[1]
                : sourceText.match(/loop-(\d+)/)?.[1]),
          ) || (isClosedLoopIsolated
            ? closedLoopContinueState.round
            : (isUploadVerifyLoopMode
              ? copyHotkeyUploadVerifyLoopCount
              : copyHotkeyContinueLoopCount)),
        ) || 0
        : 0;

      const syncLoopPhase = (phase, subtask = '') => {
        if (!isLoopMode || isClosedLoopIsolated) {
          return;
        }
        if (isUploadVerifyLoopMode) {
          setCopyHotkeyUploadVerifyLoopPhase(phase, `${sourceText}:${subtask || phase}`, {
            cycleIndex: loopCycleIndex,
            currentSubtask: subtask || phase,
          });
          return;
        }
        setCopyHotkeyContinueLoopPhase(phase, `${sourceText}:${subtask || phase}`, {
          cycleIndex: loopCycleIndex,
          currentSubtask: subtask || phase,
        });
      };

      return {
        sourceText,
        flowOptions,
        managedPhase,
        flowRunId,
        shouldStop,
        isClosedLoopIsolated,
        isUploadVerifyLoopMode,
        isLegacyLoopMode,
        isLoopMode,
        loopCycleIndex,
        syncLoopPhase,
      };
    }

    async function copyLastAssistantReplyForContinue(source, options = {}, ctx = null) {
      const context = ctx || buildCopyHotkeyContinueContext(source, options);
      const {
        sourceText,
        flowOptions,
        managedPhase,
        shouldStop,
        isLoopMode,
        syncLoopPhase,
      } = context;

      if (managedPhase && !isLoopMode) {
        setCopyHotkeyContinuePhase('copying', `${sourceText}:copying`);
      }
      if (isLoopMode) {
        syncLoopPhase('copying', 'copying');
      }

      const waitCopyResult = await waitAndCopyLatestAssistant({
        source,
        reason: `copy-hotkey-continue:${sourceText || '-'}`,
        shouldStop,
      });

      if (!waitCopyResult.ok) {
        const reason = waitCopyResult.reason || 'wait-assistant-failed';
        const errText = waitCopyResult.detail || reason;
        ToolboxShell.appendLog(
          `[COPY_HOTKEY_CONTINUE][abort] reason=${reason} detail=${errText || '-'}`,
        );
        if (!isLoopMode) {
          const statusMsg = reason === 'empty-assistant-text'
            ? '复制+快捷键+继续失败：最后回复为空'
            : `复制+快捷键+继续失败：${reason}`;
          setStatus(statusMsg, 'warn');
        }
        return {
          ok: false,
          assistantDoneSignal: false,
          reason: reason || 'wait-assistant-failed',
          detail: errText,
          source: sourceText,
          loopMode: isLoopMode,
          copied: !!waitCopyResult.copied,
          hotkeySent: false,
          continueSent: false,
          assistantMessageKey: '',
        };
      }

      const waitResult = waitCopyResult.waitResult || null;
      const assistantMessageKey = buildAssistantMessageKeyFromRecord(
        waitResult && waitResult.record,
        waitCopyResult.text || (waitResult && waitResult.text),
      ) || getLastAssistantMessageKeySafe();

      const assistantRawText = String(waitCopyResult.text || (waitResult && waitResult.text) || '').trim();

      const strictTerminal = checkClosedLoopTerminalSignalWithLog(
        assistantRawText,
        'COPY_HOTKEY_CONTINUE',
        'after-wait-strict-terminal',
        `source=${sourceText || '-'}`,
        flowOptions,
      );

      if (strictTerminal.matched) {
        const terminalLine =
          `[COPY_HOTKEY_CONTINUE][assistant-terminal-signal] `
          + `source=${sourceText || '-'} status=${strictTerminal.status || '-'} `
          + `reason=${strictTerminal.reason || '-'} key=${assistantMessageKey || '-'}`;
        safeAppendLog(terminalLine);
        if (typeof ToolboxShell !== 'undefined' && typeof ToolboxShell.appendLog === 'function') {
          ToolboxShell.appendLog(terminalLine);
        }
        setStatus(
          '检测到停止信号，准备进入闭环二次确认',
          'success',
        );
        return {
          ok: true,
          assistantDoneSignal: true,
          assistantBatchTerminalStop: false,
          batchReplyClassifyStatus: 'done',
          batchReplyClassifyReason: strictTerminal.reason || 'terminal-signal-detected',
          reason: 'task-done-signal',
          source: sourceText,
          loopMode: isLoopMode,
          copied: !!waitCopyResult.copied,
          hotkeySent: false,
          continueSent: false,
          assistantMessageKey,
          waitCopyResult,
        };
      }

      if (
        flowOptions.disableBatchTextTerminalStop !== true
        && typeof classifyBatchReply === 'function'
      ) {
        const replyClassify = classifyBatchReply(assistantRawText);
        ToolboxShell.appendLog(
          `[BATCH][REPLY_CLASSIFY] shouldStop=${replyClassify.shouldStop ? 1 : 0} `
          + `status=${replyClassify.status} reason=${replyClassify.reason} source=${sourceText || '-'}`,
        );
        if (
          replyClassify.shouldStop
          && replyClassify.status !== 'done'
          && replyClassify.status !== 'empty'
        ) {
          const terminalLine = `[COPY_HOTKEY_CONTINUE][batch-terminal-stop] status=${replyClassify.status} reason=${replyClassify.reason} source=${sourceText || '-'}`;
          safeAppendLog(terminalLine);
          if (typeof ToolboxShell !== 'undefined' && typeof ToolboxShell.appendLog === 'function') {
            ToolboxShell.appendLog(terminalLine);
          }
          setStatus(
            replyClassify.status === 'no_more_content'
              ? '检测到无更多内容终态，已停止自动继续'
              : '检测到阻塞终态，已停止自动继续',
            'warn',
          );
          return {
            ok: true,
            assistantDoneSignal: false,
            assistantBatchTerminalStop: true,
            batchReplyClassifyStatus: replyClassify.status,
            batchReplyClassifyReason: replyClassify.reason,
            reason: `batch-reply-${replyClassify.status}`,
            source: sourceText,
            loopMode: isLoopMode,
            copied: !!waitCopyResult.copied,
            hotkeySent: false,
            continueSent: false,
            assistantMessageKey,
            waitCopyResult,
          };
        }
      }

      const assistantDoneSignalMatched = checkUploadDoneSignalWithLog(
        assistantRawText,
        'COPY_HOTKEY_CONTINUE',
        'after-wait',
        `source=${sourceText || '-'}`,
        flowOptions,
      );

      if (assistantDoneSignalMatched) {
        const doneSignalLine = `[COPY_HOTKEY_CONTINUE][task-done-signal] source=${sourceText || '-'} key=${assistantMessageKey || '-'}`;
        safeAppendLog(doneSignalLine);
        console.warn('[COPY_HOTKEY_CONTINUE][task-done-signal]', {
          source: sourceText || '-',
          key: assistantMessageKey || '-',
          preview: formatDoneSignalPreview(assistantRawText),
        });
        if (typeof ToolboxShell !== 'undefined' && typeof ToolboxShell.appendLog === 'function') {
          ToolboxShell.appendLog(doneSignalLine);
        }

        setStatus('检测到终止信号，任务已完成，不再继续', 'success');

        return {
          ok: true,
          assistantDoneSignal: true,
          reason: 'task-done-signal',
          source: sourceText,
          loopMode: isLoopMode,
          copied: !!waitCopyResult.copied,
          hotkeySent: false,
          continueSent: false,
          assistantMessageKey,
          waitCopyResult,
        };
      }

      if (shouldStop()) {
        return {
          ok: false,
          assistantDoneSignal: false,
          reason: 'cancelled',
          source: sourceText,
          loopMode: isLoopMode,
          copied: !!waitCopyResult.copied,
          hotkeySent: false,
          continueSent: false,
          assistantMessageKey,
          waitCopyResult,
        };
      }

      logCopyHotkeyContinueStep(sourceText, 'copy-last-reply');

      ToolboxShell.appendLog(
        `[COPY_HOTKEY_CONTINUE][copied] chars=${waitCopyResult.chars || 0}`,
      );

      if (typeof playCopySuccessBeepSafe === 'function') {
        void playCopySuccessBeepSafe(sourceText || '-', 'copyHotkeyContinue');
      }

      return {
        ok: true,
        assistantDoneSignal: false,
        reason: 'copy-ok',
        source: sourceText,
        loopMode: isLoopMode,
        copied: true,
        hotkeySent: false,
        continueSent: false,
        assistantMessageKey,
        waitCopyResult,
      };
    }

    async function triggerContinueHotkeyForContinue(source, options = {}, ctx = null, copyStage = null) {
      const context = ctx || buildCopyHotkeyContinueContext(source, options);
      const {
        sourceText,
        managedPhase,
        shouldStop,
        isLoopMode,
        syncLoopPhase,
      } = context;
      const waitCopyResult = copyStage && copyStage.waitCopyResult
        ? copyStage.waitCopyResult
        : null;

      if (!waitCopyResult) {
        return {
          ok: false,
          assistantDoneSignal: false,
          reason: 'missing-copy-result',
          source: sourceText,
          loopMode: isLoopMode,
          copied: false,
          hotkeySent: false,
          continueSent: false,
          assistantMessageKey: copyStage && copyStage.assistantMessageKey ? copyStage.assistantMessageKey : '',
        };
      }

      if (shouldStop()) {
        return {
          ok: false,
          assistantDoneSignal: false,
          reason: 'cancelled',
          source: sourceText,
          loopMode: isLoopMode,
          copied: true,
          hotkeySent: false,
          continueSent: false,
          assistantMessageKey: copyStage.assistantMessageKey || '',
        };
      }

      logCopyHotkeyContinueStep(sourceText, 'send-hotkey');
      if (managedPhase && !isLoopMode) {
        setCopyHotkeyContinuePhase('sending_hotkey', `${sourceText}:send-hotkey`);
      }
      if (isLoopMode) {
        syncLoopPhase('sending_hotkey', 'send-hotkey');
      }

      const hotkeyFlow = await sendHotkeyAfterCopy({
        copiedText: waitCopyResult.text,
        reason: 'copy-hotkey-continue',
        shouldStop,
      });

      if (!hotkeyFlow.ok) {
        const failReason = hotkeyFlow.reason || 'hotkey-failed';
        const errText = hotkeyFlow.detail || failReason;
        ToolboxShell.appendLog(`[COPY_HOTKEY_CONTINUE][failed] reason=${failReason} detail=${errText}`);
        if (!isLoopMode) {
          const targetLabelContinue = typeof getCopyThenShortcutTargetLabel === 'function'
            ? getCopyThenShortcutTargetLabel()
            : 'Ctrl+Alt+I';
          setStatus(
            hotkeyFlow.reason === 'clipboard-not-ready'
              ? `复制+快捷键+继续失败：剪贴板未就绪：${errText}`
              : `复制成功，但 ${targetLabelContinue || '目标快捷键'} 执行失败`,
            'error',
          );
        }
        return {
          ok: false,
          assistantDoneSignal: false,
          reason: failReason,
          detail: errText,
          clipboardReadyReason: failReason,
          continueReason: '',
          source: sourceText,
          loopMode: isLoopMode,
          copied: true,
          hotkeySent: false,
          continueSent: false,
          assistantMessageKey: copyStage.assistantMessageKey || '',
        };
      }

      await sleep(300);

      if (typeof focusComposerForClosedLoop === 'function') {
        await focusComposerForClosedLoop(sourceText || 'after-hotkey');
        await sleep(200);
      }
      ToolboxShell.appendLog(
        `[COPY_HOTKEY_CONTINUE][AFTER_HOTKEY_FOCUS_RECOVER] source=${sourceText || '-'}`,
      );

      return {
        ok: true,
        hotkeySent: true,
        assistantMessageKey: copyStage.assistantMessageKey || '',
        clipboardReadyReason: hotkeyFlow && hotkeyFlow.reason ? hotkeyFlow.reason : 'ok',
        waitCopyResult,
      };
    }

    async function sendContinueForContinue(source, options = {}, ctx = null, prior = {}) {
      const context = ctx || buildCopyHotkeyContinueContext(source, options);
      const {
        sourceText,
        flowOptions,
        managedPhase,
        shouldStop,
        isLoopMode,
        syncLoopPhase,
      } = context;
      const hotkeySent = !!prior.hotkeySent;
      const assistantMessageKey = prior.assistantMessageKey || '';
      const waitCopyResult = prior.waitCopyResult || null;
      const copiedText = waitCopyResult && waitCopyResult.text
        ? String(waitCopyResult.text)
        : '';

      if (shouldStop()) {
        return {
          ok: false,
          assistantDoneSignal: false,
          reason: 'cancelled',
          source: sourceText,
          loopMode: isLoopMode,
          copied: !!copiedText,
          hotkeySent,
          continueSent: false,
          assistantMessageKey,
        };
      }

      logCopyHotkeyContinueStep(sourceText, 'send-continue');
      if (managedPhase && !isLoopMode) {
        setCopyHotkeyContinuePhase('sending_continue', `${sourceText}:send-continue`);
      }
      if (isLoopMode) {
        syncLoopPhase('sending_continue', 'send-continue');
      }

      const continueSource = sourceText || 'copy-hotkey-continue-once';
      const loopContinuePromptTxt = getCopyHotkeyContinuePromptText({ ...flowOptions, logContinuePrompt: false });
      safeAppendLog(`[COPY_HOTKEY_CONTINUE_LOOP][continue-prompt] index=${copyHotkeyContinueLoopCount + 1} length=${loopContinuePromptTxt.length}`);
      const continueResult = await sendContinuePromptFromUnifiedPipeline(continueSource, flowOptions);

      if (!isSendResultAcceptable(continueResult)) {
        const detail = continueResult && continueResult.reason ? continueResult.reason : '';
        if (
          detail === 'task-done-signal-before-send'
          || detail === 'assistant-done-signal-before-send'
          || (continueResult && continueResult.assistantDoneSignal === true)
        ) {
          safeAppendLog(
            `[COPY_HOTKEY_CONTINUE][task-done-signal] source=${sourceText || '-'} reason=${detail || 'task-done-signal-before-send'}`,
          );
          setStatus('检测到完成标记，任务已完成，不再继续', 'success');
          return {
            ok: true,
            assistantDoneSignal: true,
            reason: detail || 'task-done-signal-before-send',
            source: sourceText,
            loopMode: isLoopMode,
            copied: !!copiedText,
            hotkeySent,
            continueSent: false,
            assistantMessageKey,
          };
        }
        const continueFailReason = detail || 'unknown';

        ToolboxShell.appendLog(
          `[COPY_HOTKEY_CONTINUE][failed] reason=continue-send-failed `
          + `detail=${continueFailReason} `
          + `source=${sourceText || '-'} `
          + `copied=${copiedText ? 1 : 0} `
          + `hotkeySent=${hotkeySent ? 1 : 0} `
          + `assistantMessageKey=${assistantMessageKey || '-'}`,
        );

        console.warn('[COPY_HOTKEY_CONTINUE][continue-send-failed]', {
          source: sourceText || '-',
          detail: continueFailReason,
          copied: !!copiedText,
          hotkeySent,
          assistantMessageKey,
          continueResult,
        });

        if (!isLoopMode) {
          setStatus(`复制和快捷键已完成，但发送继续指令失败：${continueFailReason}`, 'error');
        }
        return {
          ok: false,
          assistantDoneSignal: false,
          reason: 'continue-send-failed',
          detail,
          source: sourceText,
          loopMode: isLoopMode,
          copied: !!copiedText,
          hotkeySent,
          continueSent: false,
          assistantMessageKey,
        };
      }

      return {
        ok: true,
        assistantDoneSignal: false,
        reason: 'ok',
        source: sourceText,
        loopMode: isLoopMode,
        copied_text: copiedText,
        assistantMessageKey,
        continueSent: true,
        continueReason: continueResult && continueResult.reason ? continueResult.reason : 'ok',
        clipboardReadyReason: prior.clipboardReadyReason || (hotkeySent ? 'ok' : ''),
        hotkeySent,
        copied: !!copiedText,
      };
    }

    async function copyAndContinueOnceWithoutHotkey(source = 'closed-loop-no-hotkey', options = {}) {
      const context = buildCopyHotkeyContinueContext(source, options);
      const {
        sourceText,
        flowOptions,
        managedPhase,
        shouldStop,
        isClosedLoopIsolated,
        isLoopMode,
        syncLoopPhase,
      } = context;

      const btn = managedPhase || isLoopMode
        ? null
        : (rootElRef ? qs(UploadSelectors.copyHotkeyContinueOnceBtn, rootElRef) : null);

      ToolboxShell.appendLog(`[CLOSED_LOOP][NO_HOTKEY_ONCE_ENTER] source=${sourceText}`);

      const continueLock = claimUploadActionLock('copy-hotkey-continue', {
        forceRelease: isLoopMode,
      });
      if (!continueLock.ok) {
        ToolboxShell.appendLog(
          `[COPY_HOTKEY_CONTINUE][skip] reason=${continueLock.reason} runningMs=${continueLock.runningMs || 0}`,
        );
        return {
          ok: false,
          assistantDoneSignal: false,
          reason: continueLock.reason || 'task-running',
          source: sourceText,
          loopMode: isLoopMode,
          copied: false,
          hotkeySent: false,
          continueSent: false,
          assistantMessageKey: '',
        };
      }

      try {
        if (shouldStop()) {
          return {
            ok: false,
            reason: 'cancelled',
            assistantDoneSignal: false,
            source: sourceText,
            loopMode: isLoopMode,
            copied: false,
            hotkeySent: false,
            continueSent: false,
            assistantMessageKey: '',
          };
        }

        const assistantRawBeforeSend = getLastAssistantMessageTextForStopSignal();
        const doneBeforeSend = checkUploadDoneSignalWithLog(
          assistantRawBeforeSend,
          'CLOSED_LOOP_NO_HOTKEY',
          'before-send',
          `source=${sourceText}`,
          flowOptions,
        );

        if (doneBeforeSend) {
          ToolboxShell.appendLog(`[CLOSED_LOOP][NO_HOTKEY_ONCE_SKIP] source=${sourceText} reason=assistant-done-signal-before-send`);
          return {
            ok: false,
            reason: 'assistant-done-signal-before-send',
            assistantDoneSignal: true,
            source: sourceText,
            loopMode: isLoopMode,
            copied: false,
            hotkeySent: false,
            continueSent: false,
            assistantMessageKey: '',
          };
        }

        if (managedPhase && !isLoopMode) {
          setCopyHotkeyContinuePhase('waiting_reply', `${sourceText}:wait-reply`);
        }
        if (isLoopMode && !isClosedLoopIsolated) {
          syncLoopPhase('waiting_reply', 'wait-reply');
        }

        const copyResult = await copyLastAssistantReplyForContinue(source, options, context);
        if (!copyResult || copyResult.ok === false) {
          const reason = copyResult && copyResult.reason ? copyResult.reason : 'copy-failed';
          ToolboxShell.appendLog(`[CLOSED_LOOP][NO_HOTKEY_COPY_FAILED] source=${sourceText} reason=${reason}`);
          return copyResult || {
            ok: false,
            reason,
            assistantDoneSignal: false,
            source: sourceText,
            loopMode: isLoopMode,
            copied: false,
            hotkeySent: false,
            continueSent: false,
            assistantMessageKey: '',
          };
        }

        if (copyResult.assistantDoneSignal === true) {
          return copyResult;
        }

        if (shouldStop()) {
          return {
            ok: false,
            reason: 'cancelled',
            assistantDoneSignal: false,
            source: sourceText,
            loopMode: isLoopMode,
            copied: !!copyResult.copied,
            hotkeySent: false,
            continueSent: false,
            assistantMessageKey: copyResult.assistantMessageKey || '',
          };
        }

        ToolboxShell.appendLog(`[CLOSED_LOOP][NO_HOTKEY_SKIP_HOTKEY] source=${sourceText}`);

        const sendResult = await sendContinueForContinue(source, options, context, {
          hotkeySent: false,
          assistantMessageKey: copyResult.assistantMessageKey || '',
          waitCopyResult: copyResult.waitCopyResult || null,
        });

        if (!sendResult || !sendResult.ok) {
          const reason = sendResult && sendResult.reason ? sendResult.reason : 'continue-send-failed';
          ToolboxShell.appendLog(`[CLOSED_LOOP][NO_HOTKEY_SEND_FAILED] source=${sourceText} reason=${reason}`);
          return sendResult || {
            ok: false,
            reason,
            assistantDoneSignal: !!(sendResult && sendResult.assistantDoneSignal),
            source: sourceText,
            loopMode: isLoopMode,
            copied: !!copyResult.copied,
            hotkeySent: false,
            continueSent: false,
            assistantMessageKey: copyResult.assistantMessageKey || '',
          };
        }

        ToolboxShell.appendLog(`[CLOSED_LOOP][NO_HOTKEY_ONCE_DONE] source=${sourceText}`);

        return {
          ok: true,
          reason: 'no-hotkey-continue-sent',
          assistantDoneSignal: false,
          source: sourceText,
          loopMode: isLoopMode,
          copied: true,
          hotkeySent: false,
          continueSent: true,
          assistantMessageKey: copyResult.assistantMessageKey || '',
          copied_text: sendResult.copied_text || '',
        };
      } catch (error) {
        const errText = formatToolboxError(error);
        console.error('[CLOSED_LOOP][NO_HOTKEY_ONCE_FAILED]', error);
        ToolboxShell.appendLog(`[CLOSED_LOOP][NO_HOTKEY_ONCE_FAILED] source=${sourceText} error=${errText}`);
        return {
          ok: false,
          assistantDoneSignal: false,
          reason: 'exception',
          detail: errText,
          source: sourceText,
          loopMode: isLoopMode,
          copied: false,
          hotkeySent: false,
          continueSent: false,
          assistantMessageKey: '',
        };
      } finally {
        if (!managedPhase) {
          releaseUploadActionLock('copy-hotkey-continue');
        }
        if (btn) {
          btn.dataset.busy = '0';
        }
        if (isClosedLoopIsolated) {
          renderClosedLoopContinueButtons();
        } else if (!isLoopMode && !managedPhase) {
          renderUploadButtonsOnly();
        }
      }
    }

    async function copyHotkeyAndContinueOnce(source = 'button', options = {}) {
      const context = buildCopyHotkeyContinueContext(source, options);
      const {
        sourceText,
        flowOptions,
        managedPhase,
        flowRunId,
        shouldStop,
        isClosedLoopIsolated,
        isLoopMode,
        syncLoopPhase,
      } = context;
      const btn = managedPhase || isLoopMode
        ? null
        : (rootElRef ? qs(UploadSelectors.copyHotkeyContinueOnceBtn, rootElRef) : null);

      const continueLock = claimUploadActionLock('copy-hotkey-continue', {
        forceRelease: isLoopMode,
      });
      if (!continueLock.ok) {
        ToolboxShell.appendLog(
          `[COPY_HOTKEY_CONTINUE][skip] reason=${continueLock.reason} runningMs=${continueLock.runningMs || 0}`,
        );
        return {
          ok: false,
          assistantDoneSignal: false,
          reason: continueLock.reason || 'task-running',
          source: sourceText,
          loopMode: isLoopMode,
          copied: false,
          hotkeySent: false,
          continueSent: false,
          assistantMessageKey: '',
        };
      }
      const loopOnceBtn = isLoopMode && !isClosedLoopIsolated && rootElRef
        ? qs(UploadSelectors.copyHotkeyContinueOnceBtn, rootElRef)
        : null;
      const waitDangerBtn = (!isLoopMode && !managedPhase && btn) ? btn : loopOnceBtn;
      if (waitDangerBtn && typeof startButtonLongWaitDangerTimer === 'function') {
        startButtonLongWaitDangerTimer(waitDangerBtn, 'long_wait_reply_or_send', BUTTON_LONG_WAIT_DANGER_MS);
      }
      try {
        if (managedPhase && !isLoopMode) {
          setCopyHotkeyContinuePhase('waiting_reply', `${sourceText}:wait-reply`);
        }
        if (isLoopMode) {
          syncLoopPhase('waiting_reply', 'wait-reply');
        }
        if (!isLoopMode && !managedPhase) {
          setStatus('正在等待回答完成，然后复制并发送快捷键', 'running');
        }
        ToolboxShell.appendLog(
          `[COPY_HOTKEY_CONTINUE][start] source=${sourceText || '-'}`,
        );

        logCopyHotkeyContinueStep(sourceText, 'wait-reply');

        if (shouldStop()) {
          return {
            ok: false,
            assistantDoneSignal: false,
            reason: 'cancelled',
            source: sourceText,
            loopMode: isLoopMode,
            copied: false,
            hotkeySent: false,
            continueSent: false,
            assistantMessageKey: '',
          };
        }

        const copyStage = await copyLastAssistantReplyForContinue(source, options, context);
        if (!copyStage || copyStage.ok === false) {
          return copyStage;
        }
        if (copyStage.assistantDoneSignal === true || copyStage.assistantBatchTerminalStop === true) {
          return copyStage;
        }

        const hotkeyStage = await triggerContinueHotkeyForContinue(source, options, context, copyStage);
        if (!hotkeyStage || hotkeyStage.ok === false) {
          return {
            ok: false,
            assistantDoneSignal: false,
            reason: hotkeyStage && hotkeyStage.reason ? hotkeyStage.reason : 'hotkey-failed',
            detail: hotkeyStage && hotkeyStage.detail ? hotkeyStage.detail : '',
            clipboardReadyReason: hotkeyStage && hotkeyStage.clipboardReadyReason
              ? hotkeyStage.clipboardReadyReason
              : '',
            continueReason: '',
            source: sourceText,
            loopMode: isLoopMode,
            copied: true,
            hotkeySent: false,
            continueSent: false,
            assistantMessageKey: copyStage.assistantMessageKey || '',
          };
        }

        if (shouldStop()) {
          return {
            ok: false,
            assistantDoneSignal: false,
            reason: 'cancelled',
            source: sourceText,
            loopMode: isLoopMode,
            copied: true,
            hotkeySent: true,
            continueSent: false,
            assistantMessageKey: copyStage.assistantMessageKey || '',
          };
        }

        const sendStage = await sendContinueForContinue(source, options, context, {
          hotkeySent: true,
          assistantMessageKey: copyStage.assistantMessageKey || '',
          waitCopyResult: copyStage.waitCopyResult || null,
          clipboardReadyReason: hotkeyStage.clipboardReadyReason || 'ok',
        });

        if (!sendStage || sendStage.ok === false) {
          return sendStage;
        }

        ToolboxShell.appendLog('[COPY_HOTKEY_CONTINUE][done] copied=1 hotkey=1 continue=1');
        if (!isLoopMode) {
          const targetLabelSuccess = typeof getCopyThenShortcutTargetLabel === 'function'
            ? getCopyThenShortcutTargetLabel()
            : 'Ctrl+Alt+I';
          setStatus(
            `已复制最后回复，已发送 ${targetLabelSuccess || '目标快捷键'}，并发送继续指令`,
            'success',
          );
        }
        return sendStage;
      } catch (error) {
        const errText = formatToolboxError(error);
        console.error('[COPY_HOTKEY_CONTINUE][ERROR]', {
          source: sourceText,
          loopMode: isLoopMode,
          error_type: error && error.name,
          error: errText,
          stack: error && error.stack,
        });
        ToolboxShell.appendLog(`[COPY_HOTKEY_CONTINUE][failed] source=${sourceText} error=${errText}`);
        if (!isLoopMode) {
          setStatus(`复制+快捷键+继续失败：${errText}`, 'error');
        }
        return {
          ok: false,
          assistantDoneSignal: false,
          reason: 'exception',
          detail: errText,
          source: sourceText,
          loopMode: isLoopMode,
          copied: false,
          hotkeySent: false,
          continueSent: false,
          assistantMessageKey: '',
        };
      } finally {
        if (!managedPhase) {
          releaseUploadActionLock('copy-hotkey-continue');
        }

        if (waitDangerBtn && typeof clearButtonLongWaitDangerTimer === 'function') {
          clearButtonLongWaitDangerTimer(
            waitDangerBtn,
            isLoopMode ? 'loop-cycle-finally' : 'finally',
          );
        }

        if (!isLoopMode && !managedPhase) {
          renderUploadButtonsOnly();
        } else if (isClosedLoopIsolated) {
          renderClosedLoopContinueButtons();
        } else if (isLoopMode) {
          safeAppendLog(`[COPY_HOTKEY_CONTINUE][KEEP_LOOP_STATE] source=${sourceText}`);
          console.warn('[COPY_HOTKEY_CONTINUE][KEEP_LOOP_STATE]', {
            source: sourceText,
            running: copyHotkeyContinueLoopRunning,
          });
        }
      }
    }

    async function runCopyHotkeyContinueOnceForTaskQueue(options = {}) {
      const flowOptions = options && typeof options === 'object' ? options : {};
      const source = String(flowOptions.source || 'task-queue').trim() || 'task-queue';
      const result = await copyHotkeyAndContinueOnce(source, flowOptions);
      const clipboardReadyReason = result && result.clipboardReadyReason
        ? String(result.clipboardReadyReason)
        : (result && result.hotkeySent ? 'ok' : '');
      const continueReason = result && result.continueReason
        ? String(result.continueReason)
        : (result && result.continueSent ? 'ok' : '');
      const continueSent = !!(result && result.continueSent);
      // continueSent=true 时消息已由 enterUploadWaitingReplyAfterSend->recordMessageSentAfterConfirmed 记录
      // 外层不应再调用 recordTaskSendRateLimitHit，否则会重复计数
      const quotaRecorded = continueSent;
      if (continueSent) {
        ToolboxShell.appendLog(
          `[MESSAGE_QUOTA][RECORD_SOURCE] source=${source} quotaRecorded=1`,
        );
      }
      return {
        ok: !!(result && result.ok),
        assistantDoneSignal: !!(result && result.assistantDoneSignal),
        reason: result && result.reason ? String(result.reason) : (result && result.ok ? 'ok' : 'unknown'),
        detail: result && result.detail ? String(result.detail) : '',
        clipboardReadyReason,
        continueReason,
        copied: !!(result && result.copied),
        hotkeySent: !!(result && result.hotkeySent),
        continueSent,
        quotaRecorded,
        copied_text: result && result.copied_text ? String(result.copied_text) : '',
        assistantMessageKey: result && result.assistantMessageKey ? String(result.assistantMessageKey) : '',
      };
    }

    async function waitAssistantCycleAfterContinue(source, previousKey, options = {}) {
      const sourceText = String(source || '');
      const prevKey = String(previousKey || '');
      const prevHash = hashShort(prevKey);
      const prevLen = prevKey.length;
      const flowOptions = options && typeof options === 'object' ? options : {};
      const shouldStop = typeof flowOptions.shouldStop === 'function'
        ? flowOptions.shouldStop
        : () => !!(
          copyHotkeyContinueLoopStopRequested
          || copyHotkeyUploadVerifyLoopStopRequested
          || ensureCopyHotkeyContinueLoopTask().stopRequested
          || ensureCopyHotkeyUploadVerifyLoopTask().stopRequested
        );
      const startedAt = Date.now();
      const maxWaitMs = 180000;
      const waitPollMs = 1500;
      const finalStableMs = 800;
      let sawBusy = false;

      if (typeof window !== 'undefined') {
        window.__cgptClosedLoopWaitPollActive = true;
      }

      try {
        safeAppendLog(
          `[COPY_HOTKEY_CONTINUE_LOOP][wait-cycle-start] source=${sourceText} previousHash=${prevHash} previousLen=${prevLen}`,
        );

        while (Date.now() - startedAt < maxWaitMs) {
          if (typeof isToolboxPageNavigating === 'function' && isToolboxPageNavigating()) {
            safeAppendLog('[COPY_HOTKEY_CONTINUE_LOOP][wait-cycle-page-navigating]');
            return false;
          }

          if (shouldStop()) {
            const uploadVerifyStopped = copyHotkeyUploadVerifyLoopStopRequested
              || ensureCopyHotkeyUploadVerifyLoopTask().stopRequested;
            safeAppendLog(
              uploadVerifyStopped
                ? '[CLOSED_LOOP][wait-cycle-stop-requested]'
                : '[COPY_HOTKEY_CONTINUE_LOOP][wait-cycle-stop-requested]',
            );
            return false;
          }

          const busyState = getAssistantBusyStateForClosedLoopWait(sourceText);
          const assistantBusy = isAssistantBusyFromClosedLoopWaitState(busyState);

          if (assistantBusy) {
            sawBusy = true;
            const latestTurnId = getLatestAssistantTurnIdLightweight() || '-';
            safeAppendLog(
              `[COPY_HOTKEY_CONTINUE_LOOP][wait-cycle-poll] phase=waiting_reply busy=1 responseState=${busyState.responseState || '-'} latestTurnId=${latestTurnId} action=skip-copy-scan sawBusy=1`,
            );
            await sleep(waitPollMs);
            continue;
          }

          if (sawBusy) {
            await sleep(finalStableMs);
            const busyAfterStable = getAssistantBusyStateForClosedLoopWait(`${sourceText}:post-stable`);
            if (isAssistantBusyFromClosedLoopWaitState(busyAfterStable)) {
              safeAppendLog(
                `[COPY_HOTKEY_CONTINUE_LOOP][wait-cycle-poll] phase=waiting_reply busy=1 responseState=${busyAfterStable.responseState || '-'} latestTurnId=${getLatestAssistantTurnIdLightweight() || '-'} action=skip-copy-scan-recheck sawBusy=1`,
              );
              await sleep(waitPollMs);
              continue;
            }
          }

          const nextKey = getLastAssistantMessageKeySafe();
          const nextHash = hashShort(nextKey);
          const nextLen = nextKey.length;
          const keyChanged = !!(nextKey && prevKey && nextKey !== prevKey);
          const same = !!(nextKey && prevKey && nextKey === prevKey);

          if (!nextKey && sawBusy) {
            safeAppendLog(
              `[COPY_HOTKEY_CONTINUE_LOOP][WAIT_KEY_PENDING] source=${sourceText} previousHash=${prevHash} nextKey=- action=skip-same-check sawBusy=1`,
            );
            await sleep(waitPollMs);
            continue;
          }

          safeAppendLog(
            `[COPY_HOTKEY_CONTINUE_LOOP][wait-cycle-poll] phase=check_reply busy=0 previousHash=${prevHash} previousLen=${prevLen} nextHash=${nextHash || '-'} nextLen=${nextLen} same=${same ? '1' : '0'} sawBusy=${sawBusy ? '1' : '0'}`,
          );

          if (keyChanged) {
            await sleep(600);
            return finishClosedLoopWaitCycle(sourceText, prevKey, nextKey, 'wait-cycle-done-by-poll');
          }

          const keyReady = !prevKey || !nextKey || keyChanged;
          if (nextKey && (keyReady || sawBusy)) {
            let latestText = '';
            try {
              latestText = String(getLastAssistantMessageTextForStopSignal() || '').trim();
            } catch (error) {
              const errText = formatToolboxError(error);
              console.error('[COPY_HOTKEY_CONTINUE_LOOP][wait-text-read-failed]', {
                source: sourceText,
                error_type: error && error.name,
                error: errText,
                stack: error && error.stack,
              });
              safeAppendLog(
                `[COPY_HOTKEY_CONTINUE_LOOP][wait-text-read-failed] source=${sourceText} error=${errText}`,
              );
            }
            if (latestText) {
              await sleep(finalStableMs);
              const busyAfterTextWait = getAssistantBusyStateForClosedLoopWait(`${sourceText}:post-text`);
              if (!isAssistantBusyFromClosedLoopWaitState(busyAfterTextWait)) {
                safeAppendLog(
                  `[COPY_HOTKEY_CONTINUE_LOOP][wait-cycle-done-by-text] source=${sourceText} previousHash=${prevHash} nextHash=${nextHash} textLen=${latestText.length}`,
                );
                return finishClosedLoopWaitCycle(sourceText, prevKey, nextKey || prevKey, 'wait-cycle-done-by-text');
              }
            }
          }

          if (sawBusy && (!prevKey || keyChanged)) {
            const keyAfterIdle = nextKey || getLastAssistantMessageKeySafe();
            if (!prevKey || keyAfterIdle !== prevKey) {
              return finishClosedLoopWaitCycle(sourceText, prevKey, keyAfterIdle, 'wait-cycle-done');
            }
          }

          await sleep(waitPollMs);
        }

        safeAppendLog(
          `[COPY_HOTKEY_CONTINUE_LOOP][wait-cycle-timeout] source=${sourceText} previousHash=${prevHash} previousLen=${prevLen} maxWaitMs=${maxWaitMs}`,
        );
        setStatus('连续复制+快捷键+继续：等待下一轮回复超时', 'warn');
        return false;
      } finally {
        if (typeof window !== 'undefined') {
          window.__cgptClosedLoopWaitPollActive = false;
        }
      }
    }


    const DEFAULT_UNIFIED_CONTINUE_HOME_NAV = Object.freeze({
      enabled: true,
      interval: 20,
      url: 'https://chatgpt.com/',
    });

    let lastUnifiedContinueHomeConfigLogKey = '';

    function getUnifiedContinueHomeNavigationConfig(mode = 'unknown') {
      const defaultConfig = {
        enabled: DEFAULT_UNIFIED_CONTINUE_HOME_NAV.enabled,
        interval: DEFAULT_UNIFIED_CONTINUE_HOME_NAV.interval,
        url: DEFAULT_UNIFIED_CONTINUE_HOME_NAV.url,
        mode: String(mode || 'unknown'),
      };

      const automationConfig = typeof getCopyHotkeyLoopAutomationConfig === 'function'
        ? getCopyHotkeyLoopAutomationConfig()
        : null;

      const config = {
        ...defaultConfig,
      };

      if (automationConfig) {
        if (typeof automationConfig.homeNavEnabled === 'boolean') {
          config.enabled = automationConfig.homeNavEnabled;
        }

        if (Number(automationConfig.homeNavInterval) > 0) {
          config.interval = Number(automationConfig.homeNavInterval);
        }

        if (automationConfig.homeNavUrl) {
          config.url = String(automationConfig.homeNavUrl);
        }
      }

      if (!Number.isFinite(config.interval) || config.interval <= 0) {
        config.interval = defaultConfig.interval;
      }

      config.interval = Math.max(1, Math.floor(config.interval));

      const logKey = `${config.mode}|${config.enabled ? 1 : 0}|${config.interval}|${config.url}`;
      if (logKey !== lastUnifiedContinueHomeConfigLogKey) {
        lastUnifiedContinueHomeConfigLogKey = logKey;
        ToolboxShell.appendLog(
          `[UNIFIED_CONTINUE_HOME][CONFIG] mode=${config.mode || '-'} enabled=${config.enabled ? 1 : 0} interval=${config.interval} url=${config.url}`,
        );
      }

      return config;
    }

    function shouldRunUnifiedContinueHomeNavigation(round, mode = 'unknown') {
      const config = getUnifiedContinueHomeNavigationConfig(mode);
      const currentRound = Number(round || 0);
      if (!config.enabled) {
        return {
          ok: false,
          reason: 'disabled',
          config,
        };
      }
      if (!Number.isFinite(currentRound) || currentRound <= 0) {
        return {
          ok: false,
          reason: 'invalid-round',
          config,
        };
      }
      if (currentRound % config.interval !== 0) {
        return {
          ok: false,
          reason: 'interval-not-reached',
          config,
        };
      }
      return {
        ok: true,
        reason: 'interval-reached',
        config,
      };
    }

    async function runUnifiedContinueHomeNavigation(mode, round, reason = 'interval') {
      const config = getUnifiedContinueHomeNavigationConfig(mode);
      ToolboxShell.appendLog(
        `[UNIFIED_CONTINUE_HOME][START] mode=${mode || '-'} round=${round || 0} reason=${reason || '-'} interval=${config.interval} url=${config.url}`,
      );
      setStatus(
        `连续运行已满 ${config.interval} 轮，准备回到首页后继续`,
        'warn',
      );
      let result = null;
      if (typeof goHomeByClickNewChat === 'function') {
        result = await goHomeByClickNewChat(`unified-continue-home:${mode || 'unknown'}`);
      } else if (typeof requestCopyHotkeyLoopHomeNavigation === 'function') {
        result = await requestCopyHotkeyLoopHomeNavigation({
          reason: `unified-continue-home:${mode || 'unknown'}`,
          url: config.url,
        });
      } else if (typeof runJumpHome === 'function') {
        result = await runJumpHome(`unified-continue-home:${mode || 'unknown'}`);
      } else {
        window.location.assign(config.url);
        result = {
          ok: true,
          method: 'window.location.assign',
        };
      }
      const normalized = result && typeof result === 'object'
        ? {
          ok: result.ok === true,
          reason: result.reason || (result.ok === true ? 'ok' : 'failed'),
          method: result.method || '-',
        }
        : {
          ok: false,
          reason: 'no-result',
          method: '-',
        };
      ToolboxShell.appendLog(
        `[UNIFIED_CONTINUE_HOME][DONE] mode=${mode || '-'} round=${round || 0} ok=${normalized.ok ? 1 : 0} method=${normalized.method} reason=${reason || '-'}`,
      );
      return normalized;
    }

    function stopAutoContinueUnifiedHomeWatcher(reason = 'unknown') {
      ToolboxShell.appendLog(`[AUTO_CONTINUE_HOME][WATCHER_STOP] reason=${reason || '-'}`);
      autoContinueUnifiedHomeState.active = false;
      autoContinueUnifiedHomeState.mode = '';
      autoContinueUnifiedHomeState.round = 0;
      autoContinueUnifiedHomeState.prevWaitingReply = false;
      autoContinueUnifiedHomeState.homeNavigationRunning = false;
      autoContinueUnifiedHomeState.skipNextHomeCheck = false;
    }

    function isAutoQueueContinueLoopActive(autoState) {
      if (!autoState || !autoState.running) {
        return false;
      }
      if (
        typeof AutoQueueModule === 'undefined'
        || !AutoQueueModule
        || typeof AutoQueueModule.getConfig !== 'function'
      ) {
        return false;
      }
      const autoCfg = AutoQueueModule.getConfig();
      if (!autoCfg || autoCfg.promptMode !== 'continue') {
        return false;
      }
      const modeSettings = autoCfg.modeSettings && autoCfg.modeSettings.continue
        ? autoCfg.modeSettings.continue
        : null;
      return !!(modeSettings && modeSettings.loopMode);
    }

    function getAutoContinueUnifiedHomeMode(autoState) {
      if (autoState && autoState.continueUntilDoneStrict) {
        return 'auto-continue-until-done';
      }
      return 'auto-continue';
    }

    async function maybeRunAutoContinueUnifiedHomeBeforeSend(autoState) {
      if (!autoContinueUnifiedHomeState.active || autoContinueUnifiedHomeState.homeNavigationRunning) {
        return { ok: true, skipped: true, reason: 'inactive' };
      }
      if (!isAutoQueueContinueLoopActive(autoState)) {
        stopAutoContinueUnifiedHomeWatcher('auto-queue-not-continue-loop');
        return { ok: true, skipped: true, reason: 'not-continue-loop' };
      }
      if (autoContinueUnifiedHomeState.skipNextHomeCheck) {
        autoContinueUnifiedHomeState.skipNextHomeCheck = false;
        return { ok: true, skipped: true, reason: 'skip-next' };
      }

      const nextRound = Math.max(0, Number(autoContinueUnifiedHomeState.round) || 0) + 1;
      const mode = autoContinueUnifiedHomeState.mode || getAutoContinueUnifiedHomeMode(autoState);
      const homeCheck = shouldRunUnifiedContinueHomeNavigation(nextRound, mode);
      if (!homeCheck.ok) {
        return { ok: true, skipped: true, reason: homeCheck.reason || 'not-due' };
      }

      autoContinueUnifiedHomeState.homeNavigationRunning = true;
      const homeResult = await runUnifiedContinueHomeNavigation(mode, nextRound, 'interval');
      autoContinueUnifiedHomeState.homeNavigationRunning = false;

      if (!homeResult || homeResult.ok !== true) {
        ToolboxShell.appendLog(
          `[AUTO_CONTINUE_HOME][FAILED] mode=${mode} round=${nextRound} reason=${homeResult && homeResult.reason ? homeResult.reason : 'unknown'}`,
        );
        return { ok: false, reason: homeResult && homeResult.reason ? homeResult.reason : 'home-failed' };
      }

      autoContinueUnifiedHomeState.skipNextHomeCheck = true;
      ToolboxShell.appendLog(
        `[AUTO_CONTINUE_HOME][OK] mode=${mode} round=${nextRound} next=continue-current-round`,
      );
      return { ok: true, reason: 'home-nav-ok', round: nextRound };
    }

    ToolboxShell.appendLog('[AUTO_CONTINUE_HOME][DEAD_WATCHER_REMOVED]');

    function getCopyHotkeyLoopAutomationConfig() {
      const closedLoopCfg = getClosedLoopAutomationConfig();
      const cfg = getCompactUiConfig();
      const continueAutomation = (cfg && typeof cfg.continueAutomation === 'object')
        ? cfg.continueAutomation
        : {};

      const unifiedHomeNavEnabled = continueAutomation.homeNavEnabled !== false;
      const unifiedHomeNavIntervalRaw = Number(
        continueAutomation.homeNavInterval > 0
          ? continueAutomation.homeNavInterval
          : 20,
      );
      const unifiedHomeNavInterval = Number.isFinite(unifiedHomeNavIntervalRaw) && unifiedHomeNavIntervalRaw > 0
        ? Math.floor(unifiedHomeNavIntervalRaw)
        : DEFAULT_UNIFIED_CONTINUE_HOME_NAV.interval;
      const unifiedHomeNavUrl = String(
        continueAutomation.homeNavUrl || DEFAULT_UNIFIED_CONTINUE_HOME_NAV.url,
      ).trim() || DEFAULT_UNIFIED_CONTINUE_HOME_NAV.url;

      return {
        autoUploadEnabled: closedLoopCfg.autoUploadEnabled,
        autoUploadInterval: closedLoopCfg.autoUploadInterval,
        homeNavEnabled: closedLoopCfg.homeNavEnabled && unifiedHomeNavEnabled,
        homeNavInterval: closedLoopCfg.homeNavInterval || unifiedHomeNavInterval,
        homeNavUrl: closedLoopCfg.homeNavUrl || unifiedHomeNavUrl,
      };
    }

    function isCopyHotkeyLoopIntervalHit(cycleIndex, enabled, interval) {
      const index = Number(cycleIndex) || 0;
      const step = Number(interval) || 0;

      return enabled === true && index > 0 && step > 0 && index % step === 0;
    }

    async function requestCopyHotkeyLoopHomeNavigation(cycleIndexOrOptions, cfgMaybe) {
      let cycleIndex = cycleIndexOrOptions;
      let cfg = cfgMaybe;
      if (cycleIndexOrOptions && typeof cycleIndexOrOptions === 'object') {
        const opts = cycleIndexOrOptions;
        cycleIndex = Number(opts.round || opts.cycleIndex || 0);
        cfg = {
          homeNavUrl: opts.url || 'https://chatgpt.com/',
        };
      }

      const targetUrl = String(
        cfg && cfg.homeNavUrl ? cfg.homeNavUrl : 'https://chatgpt.com/'
      ).trim() || 'https://chatgpt.com/';

      ToolboxShell.appendLog(
        `[COPY_HOTKEY_CONTINUE_LOOP][home-nav-request] index=${cycleIndex} url=${targetUrl}`
      );

      setStatus(
        `第 ${cycleIndex} 轮：正在返回 ChatGPT 首页...`,
        'running'
      );

      if (typeof goHomeByClickNewChat === 'function') {
        const clickResult = await goHomeByClickNewChat(`copy-hotkey-loop-home:${cycleIndex}`);
        if (clickResult && clickResult.ok === true) {
          return {
            ok: true,
            reason: clickResult.reason || 'clicked_new_chat',
            method: clickResult.method || 'goHomeByClickNewChat',
          };
        }
      }

      return new Promise((resolve) => {
        window.setTimeout(() => {
          try {
            window.location.assign(targetUrl);
            resolve({
              ok: true,
              reason: 'location-assign-scheduled',
              method: 'window.location.assign',
            });
          } catch (error) {
            const errText = error && error.message ? error.message : String(error);
            console.error('[COPY_HOTKEY_CONTINUE_LOOP][home-nav-failed]', {
              cycleIndex,
              targetUrl,
              error_type: error && error.name,
              error: errText,
              stack: error && error.stack,
            });
            ToolboxShell.appendLog(
              `[COPY_HOTKEY_CONTINUE_LOOP][home-nav-failed] index=${cycleIndex} error=${errText}`
            );
            setStatus(`返回首页失败：${errText}`, 'error');
            resolve({
              ok: false,
              reason: errText,
              method: 'window.location.assign',
            });
          }
        }, 600);
      });
    }

    async function runCopyHotkeyLoopPostCycleActions(cycleIndex) {
      const cfg = getCopyHotkeyLoopAutomationConfig();

      const homeCheck = shouldRunUnifiedContinueHomeNavigation(
        cycleIndex,
        'copy-hotkey-continue-loop',
      );

      if (homeCheck.ok) {
        ToolboxShell.appendLog(
          `[COPY_HOTKEY_CONTINUE_LOOP][post-cycle] action=home-nav index=${cycleIndex} uploadSkipped=1`
        );

        setCopyHotkeyContinueLoopPhase('home_navigation', `cycle-${cycleIndex}-home-nav`, {
          cycleIndex,
          currentSubtask: 'home_navigation',
        });

        const homeResult = await runUnifiedContinueHomeNavigation(
          'copy-hotkey-continue-loop',
          cycleIndex,
          'interval',
        );

        ToolboxShell.appendLog(
          `[COPY_HOTKEY_CONTINUE_LOOP][home-nav-done] index=${cycleIndex} ok=${homeResult && homeResult.ok ? 1 : 0} method=${homeResult && homeResult.method ? homeResult.method : '-'}`,
        );

        return {
          stop: false,
          reason: 'home-nav',
          homeResult,
        };
      }

      const shouldAutoUpload = isCopyHotkeyLoopIntervalHit(
        cycleIndex,
        cfg.autoUploadEnabled,
        cfg.autoUploadInterval,
      );

      if (!shouldAutoUpload) {
        return {
          stop: false,
          reason: 'no-action',
        };
      }

      ToolboxShell.appendLog(
        `[COPY_HOTKEY_CONTINUE_LOOP][post-cycle] action=auto-upload index=${cycleIndex} interval=${cfg.autoUploadInterval}`
      );

      setStatus(
        `第 ${cycleIndex} 轮：正在自动上传...`,
        'running'
      );

      const loopTask = ensureCopyHotkeyContinueLoopTask();
      setCopyHotkeyContinueLoopPhase('auto_uploading', `cycle-${cycleIndex}-auto-upload`, {
        cycleIndex,
        currentSubtask: 'auto_upload',
      });

      try {
        const uploadResult = await runStartUploadButtonCore({
          source: 'closed-loop-hotkey-every5-upload',
          reason: 'closed-loop-hotkey-every5',
          parentTask: 'copyHotkeyContinueLoop',
          cycleIndex,
          shouldStop: () => !!(
            copyHotkeyContinueLoopStopRequested
            || loopTask.stopRequested
          ),
        });

        ToolboxShell.appendLog(
          `[COPY_HOTKEY_CONTINUE_LOOP][auto-upload-done] index=${cycleIndex} ok=${uploadResult && uploadResult.ok ? '1' : '0'} uploaded=${uploadResult && uploadResult.uploadedCount != null ? uploadResult.uploadedCount : '-'} failed=${uploadResult && uploadResult.failedCount != null ? uploadResult.failedCount : '-'} skipped=${uploadResult && uploadResult.skippedCount != null ? uploadResult.skippedCount : '-'} reason=${uploadResult && uploadResult.reason ? uploadResult.reason : '-'}`
        );

        return {
          stop: false,
          reason: 'auto-upload-done',
          uploadResult,
        };
      } catch (error) {
        const errText = error && error.message ? error.message : String(error);

        console.error('[COPY_HOTKEY_CONTINUE_LOOP][auto-upload-failed]', {
          cycleIndex,
          error_type: error && error.name,
          error: errText,
          stack: error && error.stack,
        });

        ToolboxShell.appendLog(
          `[COPY_HOTKEY_CONTINUE_LOOP][auto-upload-failed] index=${cycleIndex} error=${errText}`
        );

        setStatus(`第 ${cycleIndex} 轮自动上传失败：${errText}`, 'error');

        return {
          stop: false,
          reason: 'auto-upload-failed',
          error: errText,
        };
      } finally {
        if (
          copyHotkeyContinueLoopRunning
          && !copyHotkeyContinueLoopStopRequested
          && loopTask.phase === 'auto_uploading'
        ) {
          setCopyHotkeyContinueLoopPhase('running', `cycle-${cycleIndex}-auto-upload-done`, {
            cycleIndex,
          });
        }
      }
    }

    async function toggleCopyHotkeyContinueLoop(source = 'button') {
      const src = String(source || 'button').trim() || 'button';
      const loopTask = ensureCopyHotkeyContinueLoopTask();

      if (COPY_HOTKEY_LOOP_STOP_PHASES.has(loopTask.phase) || copyHotkeyContinueLoopRunning) {
        return requestCopyHotkeyContinueLoopStop(src);
      }

      const loopLock = claimUploadActionLock('copy-hotkey-loop', { timeoutMs: 600000 });
      if (!loopLock.ok) {
        ToolboxShell.appendLog(
          `[COPY_HOTKEY_CONTINUE_LOOP][skip] source=${src} reason=${loopLock.reason} runningMs=${loopLock.runningMs || 0}`,
        );
        return false;
      }

      copyHotkeyContinueLoopRunGeneration += 1;
      const runId = createUploadTaskRunId('copy_hotkey_loop');
      loopTask.runId = runId;
      loopTask.stopRequested = false;
      loopTask.lastError = null;
      loopTask.abortController = typeof AbortController !== 'undefined' ? new AbortController() : null;
      copyHotkeyContinueLoopStopRequested = false;
      copyHotkeyContinueLoopCount = 0;
      copyHotkeyContinueLoopStartedAt = Date.now();
      loopTask.startedAt = copyHotkeyContinueLoopStartedAt;

      setCopyHotkeyContinueLoopPhase('running', src, { cycleIndex: 0 });
      setStatus('连续复制+快捷键+继续已启动', 'running');
      safeAppendLog(
        `[COPY_HOTKEY_CONTINUE_LOOP][START] source=${src} runId=${runId} runGen=${copyHotkeyContinueLoopRunGeneration}`,
      );
      let loopStopReason = 'natural-end';
      try {
        while (!copyHotkeyContinueLoopStopRequested && loopTask.runId === runId) {
          if (abortCopyHotkeyContinueLoopAtCheckpoint(runId, 'cycle-start', src)) {
            loopStopReason = 'user-stop';
            break;
          }

          copyHotkeyContinueLoopCount += 1;
          loopTask.cycleIndex = copyHotkeyContinueLoopCount;
          setCopyHotkeyContinueLoopPhase('waiting_reply', `cycle-${copyHotkeyContinueLoopCount}`, {
            cycleIndex: copyHotkeyContinueLoopCount,
            currentSubtask: 'cycle',
          });
          safeAppendLog(
            `[COPY_HOTKEY_CONTINUE_LOOP][cycle-start] index=${copyHotkeyContinueLoopCount}`,
          );

          const shouldStop = buildCopyHotkeyContinueLoopShouldStop(runId);

          setCopyHotkeyContinueLoopPhase('copying', `cycle-${copyHotkeyContinueLoopCount}`, {
            cycleIndex: copyHotkeyContinueLoopCount,
          });

          const result = await copyHotkeyAndContinueOnce(`loop-${copyHotkeyContinueLoopCount}`, {
            shouldStop,
          });

          if (
            result
            && (
              result.assistantDoneSignal === true
              || result.reason === 'task-done-signal'
              || result.reason === 'assistant-done-signal'
              || result.reason === 'task-done-signal-before-send'
              || result.reason === 'assistant-done-signal-before-send'
            )
          ) {
            loopStopReason = 'task-done-signal';
            safeAppendLog(
              `[COPY_HOTKEY_CONTINUE_LOOP][stop] reason=task-done-signal index=${copyHotkeyContinueLoopCount}`,
            );
            console.warn('[COPY_HOTKEY_CONTINUE_LOOP][stop]', {
              reason: 'task-done-signal',
              index: copyHotkeyContinueLoopCount,
            });
            break;
          }

          if (!result || result.ok === false) {
            const reason = result && result.reason ? result.reason : 'once-failed';
            const detail = result && result.detail ? result.detail : '';

            loopStopReason = `cycle-stop:${reason}`;

            safeAppendLog(
              `[COPY_HOTKEY_CONTINUE_LOOP][cycle-stop] reason=${reason} detail=${detail || '-'} index=${copyHotkeyContinueLoopCount}`,
            );

            console.warn('[COPY_HOTKEY_CONTINUE_LOOP][CYCLE_STOP]', {
              reason,
              detail,
              index: copyHotkeyContinueLoopCount,
              result,
            });

            break;
          }

          if (copyHotkeyContinueLoopStopRequested) {
            loopStopReason = 'user-stop';
            safeAppendLog(
              `[COPY_HOTKEY_CONTINUE_LOOP][cycle-stop] reason=user-stop index=${copyHotkeyContinueLoopCount}`,
            );
            break;
          }

          safeAppendLog(
            `[COPY_HOTKEY_CONTINUE_LOOP][before-wait-next] index=${copyHotkeyContinueLoopCount} keyHash=${hashShort(result.assistantMessageKey || '')} keyLen=${String(result.assistantMessageKey || '').length} reason=${result.continueReason || '-'}`,
          );

          setCopyHotkeyContinueLoopPhase('waiting_next_reply', `cycle-${copyHotkeyContinueLoopCount}`, {
            cycleIndex: copyHotkeyContinueLoopCount,
            currentSubtask: 'wait-next-reply',
          });

          const waited = await waitAssistantCycleAfterContinue(
            `loop-${copyHotkeyContinueLoopCount}`,
            result.assistantMessageKey || '',
            { shouldStop: buildCopyHotkeyContinueLoopShouldStop(runId) },
          );
          if (!waited) {
            loopStopReason = shouldStop()
              ? 'user-stop'
              : 'wait-next-reply-failed';
            safeAppendLog(
              `[COPY_HOTKEY_CONTINUE_LOOP][stop] reason=${loopStopReason} index=${copyHotkeyContinueLoopCount}`,
            );
            if (loopStopReason === 'wait-next-reply-failed') {
              console.warn('[COPY_HOTKEY_CONTINUE_LOOP][WAIT_NEXT_FAILED]', {
                index: copyHotkeyContinueLoopCount,
                previousHash: hashShort(result.assistantMessageKey || ''),
                previousLen: String(result.assistantMessageKey || '').length,
              });
            }
            break;
          }

          const stopSignalResult = detectCopyHotkeyLoopStopSignal(copyHotkeyContinueLoopCount);

          if (stopSignalResult && stopSignalResult.matched) {
            loopStopReason = stopSignalResult.reason || 'task-done-signal';

            safeAppendLog(
              `[COPY_HOTKEY_CONTINUE_LOOP][stop] reason=${loopStopReason} index=${copyHotkeyContinueLoopCount}`,
            );

            break;
          }

          const postCycleAction = await runCopyHotkeyLoopPostCycleActions(copyHotkeyContinueLoopCount);

          if (postCycleAction && postCycleAction.stop) {
            loopStopReason = postCycleAction.reason || 'post-cycle-stop';

            safeAppendLog(
              `[COPY_HOTKEY_CONTINUE_LOOP][stop] reason=${loopStopReason} index=${copyHotkeyContinueLoopCount}`
            );

            break;
          }
        }
      } catch (error) {
        const errText = formatToolboxError(error);
        loopStopReason = `exception:${errText}`;
        console.error('[COPY_HOTKEY_CONTINUE_LOOP][FAILED]', {
          error_type: error && error.name,
          error: errText,
          stack: error && error.stack,
        });
        safeAppendLog(`[COPY_HOTKEY_CONTINUE_LOOP][failed] error=${errText}`);
        setStatus(`连续复制+快捷键+继续失败：${errText}`, 'error');
      } finally {
        const stoppedByUser = copyHotkeyContinueLoopStopRequested || loopTask.stopRequested;
        loopTask.stopRequested = false;
        loopTask.abortController = null;
        copyHotkeyContinueLoopStopRequested = false;

        if (loopTask.runId === runId) {
          if (stoppedByUser) {
            setCopyHotkeyContinueLoopPhase('stopped', 'finally', { cycleIndex: copyHotkeyContinueLoopCount });
          } else if (
            loopStopReason.startsWith('cycle-stop:')
            || loopStopReason.startsWith('exception:')
            || loopStopReason === 'wait-next-reply-failed'
          ) {
            setCopyHotkeyContinueLoopPhase('failed', loopStopReason, {
              cycleIndex: copyHotkeyContinueLoopCount,
            });
          } else {
            setCopyHotkeyContinueLoopPhase('success', 'finally', {
              cycleIndex: copyHotkeyContinueLoopCount,
            });
          }

          window.setTimeout(() => {
            if (state.copyHotkeyContinueLoopTask && state.copyHotkeyContinueLoopTask.runId === runId) {
              state.copyHotkeyContinueLoopTask.runId = '';
              setCopyHotkeyContinueLoopPhase('idle', 'auto-reset');
            }
          }, 1500);
        }

        if (stoppedByUser && loopStopReason === 'natural-end') {
          loopStopReason = 'user-stop';
        }
        if (loopStopReason === 'task-done-signal' || loopStopReason === 'assistant-done-signal') {
          setStatus(
            `检测到终止信号，连续复制+快捷键+继续已结束，共执行 ${copyHotkeyContinueLoopCount} 轮`,
            'success',
          );
        } else if (stoppedByUser || loopStopReason === 'user-stop') {
          setStatus(
            `连续复制+快捷键+继续已停止，共执行 ${copyHotkeyContinueLoopCount} 轮`,
            'warn',
          );
        } else if (
          loopStopReason.startsWith('cycle-stop:')
          || loopStopReason.startsWith('exception:')
          || loopStopReason === 'wait-next-reply-failed'
        ) {
          setStatus(
            `连续复制+快捷键+继续已结束，共执行 ${copyHotkeyContinueLoopCount} 轮（${loopStopReason}）`,
            'warn',
          );
        } else {
          setStatus(
            `连续复制+快捷键+继续已结束，共执行 ${copyHotkeyContinueLoopCount} 轮`,
            'success',
          );
        }
        safeAppendLog(`[COPY_HOTKEY_CONTINUE_LOOP][finally] reason=${loopStopReason}`);
        safeAppendLog(
          `[COPY_HOTKEY_CONTINUE_LOOP][done] cycles=${copyHotkeyContinueLoopCount} stoppedByUser=${stoppedByUser ? '1' : '0'} reason=${loopStopReason}`,
        );
        const loopOnceBtn = rootElRef
          ? qs(UploadSelectors.copyHotkeyContinueOnceBtn, rootElRef)
          : null;
        if (loopOnceBtn && typeof clearButtonLongWaitDangerTimer === 'function') {
          clearButtonLongWaitDangerTimer(loopOnceBtn, 'loop-finally');
        }
        renderUploadButtonsOnly();
        releaseUploadActionLock('copy-hotkey-loop');
      }
      return true;
    }


    function buildFlaskUploadListHtml(...args) {
      return ensureUploadRenderList().buildFlaskUploadListHtml(...args);
    }

    function buildDropSignature(dataTransfer) {
      const files = Array.from(dataTransfer && dataTransfer.files ? dataTransfer.files : []);

      return files
        .map((file) => [
          String(file.name || '').trim().toLowerCase(),
          Number(file.size) || 0,
          Number(file.lastModified) || 0,
          String(file.type || '').trim().toLowerCase(),
        ].join('::'))
        .sort()
        .join('||');
    }

    function shouldSkipRecentDuplicateDrop(dataTransfer) {
      const signature = buildDropSignature(dataTransfer);

      if (!signature) return false;

      const now = Date.now();

      if (signature === lastDropSignature && now - lastDropSignatureAt < 1200) {
        ToolboxShell.appendLog(
          `[UPLOAD_DIAG][drop:skip-recent-duplicate] signature=${signature}`
        );
        return true;
      }

      lastDropSignature = signature;
      lastDropSignatureAt = now;
      return false;
    }

    const UPLOAD_DRAG_DEPTH_PROP = '__cgptUploadDragDepthV1';
    const UPLOAD_DRAG_BIND_CLEANUP_PROP = '__cgptUploadDragBindCleanupV1';
    const MULTI_UPLOAD_DRAG_OVER_LOG_INTERVAL_MS = 800;
    const MULTI_UPLOAD_DRAG_OVER_THROTTLE_MS = 250;
    let lastMultiUploadDragOverLogAt = 0;
    let lastMultiUploadDragProcessAt = 0;
    let lastMultiUploadDragVisualOn = false;

    function getDragEventTargetTag(e) {
      const target = e && e.target instanceof Element ? e.target : null;
      if (!target) return '-';
      const id = target.id ? `#${target.id}` : '';
      const cls = target.classList && target.classList.length
        ? `.${Array.from(target.classList).slice(0, 2).join('.')}`
        : '';
      return `${target.tagName.toLowerCase()}${id}${cls}`;
    }

    function getDragTransferMeta(e) {
      const transfer = e && e.dataTransfer ? e.dataTransfer : null;
      const items = transfer && transfer.items ? Array.from(transfer.items) : [];
      const files = transfer && transfer.files ? Array.from(transfer.files) : [];
      const hasFiles = hasDraggedFiles(e);
      return {
        has_files: hasFiles,
        items_len: items.length,
        files_len: files.length,
      };
    }

    function hasDraggedFiles(e) {
      const transfer = e && e.dataTransfer ? e.dataTransfer : null;
      if (!transfer) return false;

      if (transfer.files && transfer.files.length > 0) {
        return true;
      }

      const types = transfer.types ? Array.from(transfer.types) : [];
      if (types.includes('Files')) {
        return true;
      }

      const items = transfer.items ? Array.from(transfer.items) : [];
      return items.some((item) => item && item.kind === 'file');
    }

    function isEventInToolbox(e) {
      const target = e && e.target instanceof Element ? e.target : null;
      if (!target || typeof target.closest !== 'function') {
        return false;
      }

      if (typeof isInToolbox === 'function' && isInToolbox(target)) {
        return true;
      }

      return !!target.closest(`#${APP.rootId}, #${APP.panelId}`);
    }

    function shouldLetNativeChatGptHandleUploadDrop(e) {
      if (typeof shouldLetNativeChatGptHandleDrop !== 'function') {
        console.error('[MULTI_UPLOAD][DROP_ERROR] shouldLetNativeChatGptHandleDrop missing');
        return false;
      }

      try {
        return shouldLetNativeChatGptHandleDrop(e, {
          includeFileInput: true,
          includeForm: true,
          isInToolbox: isEventInToolbox,
        });
      } catch (error) {
        console.error('[MULTI_UPLOAD][DROP_ERROR]', {
          error_type: error && error.name,
          error: error && error.message,
          stack: error && error.stack,
        });
        return false;
      }
    }

    function claimUploadDropEvent(e, source) {
      if (!e) return false;

      if (e[UPLOAD_DROP_HANDLED_PROP]) {
        ToolboxShell.appendLog(
          `[UPLOAD_DIAG][drop:skip-already-handled] source=${source || '-'}`
        );
        return false;
      }

      e[UPLOAD_DROP_HANDLED_PROP] = {
        source: source || '',
        at: Date.now(),
      };

      return true;
    }

    function prepareUploadDragEvent(e, options = {}) {
      if (!hasDraggedFiles(e)) {
        return false;
      }

      if (shouldLetNativeChatGptHandleUploadDrop(e)) {
        if (isUploadDebugEnabled()) {
          ToolboxShell.appendLog(`[UPLOAD_DND][NATIVE_PASS] source=${String(options.source || '-')} reason=native-area`);
        }
        return false;
      }

      e.preventDefault();
      e.stopPropagation();

      const sourceText = String(options.source || '-');
      const inToolbox = sourceText !== 'global-drop' && isEventInToolbox(e);
      if (inToolbox && typeof e.stopImmediatePropagation === 'function') {
        e.stopImmediatePropagation();
      }

      if (e.dataTransfer) {
        e.dataTransfer.dropEffect = options.dropEffect || 'copy';
      }

      return true;
    }

    function setMultiUploadDragOverVisual(on) {
      const nextOn = !!on;
      if (lastMultiUploadDragVisualOn === nextOn) {
        return;
      }
      lastMultiUploadDragVisualOn = nextOn;

      if (!uploadListCachedDropTargets.length) {
        const targets = [];
        if (rootElRef) targets.push(rootElRef);
        if (listEl) targets.push(listEl);
        if (rootElRef && typeof rootElRef.querySelectorAll === 'function') {
          rootElRef.querySelectorAll(
            '.toolbox-upload-drop-zone, .toolbox-upload-file-list, .toolbox-upload-empty-state',
          ).forEach((el) => {
            targets.push(el);
          });
        }
        if (panelDropEl) targets.push(panelDropEl);
        uploadListCachedDropTargets = targets.filter(Boolean);
      }

      const seen = new Set();
      uploadListCachedDropTargets.forEach((el) => {
        if (!el || seen.has(el)) return;
        seen.add(el);
        el.classList.toggle('is-drag-over', nextOn);
        el.classList.toggle('cgpt-upload-dragging', nextOn);
      });

      if (panelDropEl) {
        panelDropEl.classList.toggle('cgpt-toolbox-file-dragover', nextOn);
      }
    }

    function adjustMultiUploadDragDepth(hostEl, delta) {
      if (!hostEl) return 0;

      const next = Math.max(0, Number(hostEl[UPLOAD_DRAG_DEPTH_PROP] || 0) + delta);
      hostEl[UPLOAD_DRAG_DEPTH_PROP] = next;
      return next;
    }

    async function collectDroppedFilesWithHandles(transfer) {
      const result = [];
      const entryByKey = new Map();

      function upsertEntry(file, handle) {
        if (!file) return;

        const key = buildQueueFileKey(file) || buildQueueLooseFileKey(file);
        const normalizedHandle = isFileHandleLike(handle) ? handle : null;

        if (key && entryByKey.has(key)) {
          const entry = entryByKey.get(key);
          // 允许把后续通过 items 拿到的 handle 补齐到前面已有的 transfer.files entry。
          if (normalizedHandle && !entry.handle) {
            entry.handle = normalizedHandle;
          }
          return;
        }

        const entry = {
          file,
          handle: normalizedHandle,
        };
        result.push(entry);
        if (key) {
          entryByKey.set(key, entry);
        }
      }

      const directFiles = Array.from(transfer && transfer.files ? transfer.files : []).filter(Boolean);
      directFiles.forEach((file) => {
        upsertEntry(file, null);
      });

      const items = Array.from(transfer && transfer.items ? transfer.items : []);
      for (const item of items) {
        if (!item || item.kind !== 'file') {
          continue;
        }

        let handle = null;
        if (typeof item.getAsFileSystemHandle === 'function') {
          try {
            handle = await item.getAsFileSystemHandle();
          } catch (handleError) {
            console.error('[MULTI_UPLOAD][DROP_ERROR]', {
              error_type: handleError && handleError.name,
              error: handleError && handleError.message,
              stack: handleError && handleError.stack,
            });
          }
        }

        const file = typeof item.getAsFile === 'function' ? item.getAsFile() : null;
        upsertEntry(file, handle);
      }

      return result;
    }

    async function ensureUploadProjectForDrop(source) {
      if (state.activeGroupId && state.groups.some((g) => g && g.id === state.activeGroupId)) {
        return state.activeGroupId;
      }

      if (state.groups.length) {
        ensureActiveUploadGroupIdValid(`drop-${source || 'drag'}`);
        if (state.activeGroupId) {
          return state.activeGroupId;
        }
      }

      await ensureDefaultGroupReady();

      if (state.activeGroupId) {
        return state.activeGroupId;
      }

      const dragGroup = {
        id: createId('upload_group'),
        name: '当前拖拽项目',
        key: '',
        createdAt: Date.now(),
        updatedAt: Date.now(),
      };
      dragGroup.key = deriveUploadGroupStableKey(dragGroup);

      state.groups.push(dragGroup);
      state.activeGroupId = dragGroup.id;
      state.selectedFileIdByGroup[dragGroup.id] = '';

      savePageSelectedUploadGroupId(dragGroup.id, `drop-${source || 'drag'}`);

      await persistGroups();
      await awaitPersistQueueBriefly('ensureUploadProjectForDrop', 300);
      saveCurrentToolboxBaseState(`drop-${source || 'drag'}`);
      syncUploadGroupAppState();
      render();

      ToolboxShell.appendLog(
        `[MULTI_UPLOAD][DROP][CREATE_PROJECT] project_id=${dragGroup.id} name=${dragGroup.name}`,
      );

      return dragGroup.id;
    }

    async function addDroppedFiles(dropped) {
      const entries = Array.isArray(dropped) ? dropped : [];
      const files = entries.map((entry) => entry && entry.file).filter(Boolean);
      const handles = entries.map((entry) => (entry && entry.handle) || null);

      await addFiles(files, {
        handles,
        sourceKind: 'drop',
      });
    }

    async function addDroppedFilesToCurrentUploadProject(files, source) {
      const list = Array.from(files || []).filter(Boolean);
      const validEntries = [];

      list.forEach((entryOrFile) => {
        const isEntry = entryOrFile && typeof entryOrFile === 'object' && 'file' in entryOrFile;
        const file = isEntry ? entryOrFile.file : entryOrFile;
        const handle = isEntry ? entryOrFile.handle : null;

        if (!file || Number(file.size) <= 0) {
          console.info('[MULTI_UPLOAD][DROP_SKIP_EMPTY_FILE]', {
            name: file && file.name ? file.name : '-',
            size: file && file.size,
          });
          return;
        }

        validEntries.push({
          file,
          handle: isFileHandleLike(handle) ? handle : null,
        });
      });

      if (!validEntries.length) {
        console.info('[MULTI_UPLOAD][DROP_EMPTY]');
        setStatus('没有检测到可添加的文件');
        return {
          project_id: state.activeGroupId || '',
          added_count: 0,
          total_count: getActiveGroupFiles().length,
        };
      }

      try {
        const projectId = await ensureUploadProjectForDrop(source || 'drag_drop_toolbox');
        const beforeCount = getActiveGroupFiles().length;
        await addDroppedFiles(validEntries);
        dedupeActiveGroupQueue('drop');

        const afterCount = getActiveGroupFiles().length;
        const addedCount = Math.max(0, afterCount - beforeCount);
        const afterNames = getActiveGroupFiles().map((item) => item.name || 'unknown').join('|');
        ToolboxShell.appendLog(
          `[MULTI_UPLOAD][DROP_ADD_DONE] beforeQueue=${beforeCount} afterQueue=${afterCount} added=${addedCount} names=${afterNames || '-'}`,
        );

        setStatus(`已拖入：${validEntries.length} 个文件，新增：${addedCount} 个`);

        const acceptedPayload = {
          project_id: projectId || state.activeGroupId || '',
          added_count: addedCount,
          total_count: afterCount,
        };
        console.info('[MULTI_UPLOAD][DROP_ACCEPTED]', acceptedPayload);
        ToolboxShell.appendLog(
          `[MULTI_UPLOAD][DROP_ACCEPTED] project_id=${acceptedPayload.project_id} added_count=${addedCount} total_count=${afterCount}`,
        );

        return acceptedPayload;
      } catch (error) {
        console.error('[MULTI_UPLOAD][DROP_ERROR]', {
          error_type: error && error.name,
          error: error && error.message,
          stack: error && error.stack,
        });
        setStatus(`拖拽添加失败：${error && error.message ? error.message : String(error)}`, 'error');
        throw error;
      }
    }

    function collectDroppedFilesFromFileList(files) {
      return Array.from(files || []).filter(Boolean).map((file) => ({
        file,
        handle: null,
      }));
    }

    async function handleUploadDropEvent(e, source) {
      e.preventDefault();
      e.stopPropagation();

      const transfer = e.dataTransfer;
      const sourceText = String(source || 'drag_drop_toolbox');

      if (!transfer) {
        setStatus('拖拽失败：没有文件数据');
        ToolboxShell.appendLog('[UPLOAD_DIAG][drop:failed] reason=no-dataTransfer');
        return;
      }

      const rawFiles = Array.from(transfer.files || []).filter(Boolean);
      const transferItems = Array.from(transfer.items || []);
      const rawNames = rawFiles.map((file) => file.name || 'unknown').join('|');
      ToolboxShell.appendLog(
        `[MULTI_UPLOAD][DROP_RAW] source=${sourceText} transferFiles=${rawFiles.length} transferItems=${transferItems.length} names=${rawNames || '-'}`,
      );
      console.info('[MULTI_UPLOAD][DROP]', {
        files_len: rawFiles.length,
        names: rawFiles.map((file) => file.name || 'unknown'),
        source: sourceText,
      });

      if (shouldSkipRecentDuplicateDrop(transfer)) {
        setStatus('已忽略重复拖拽事件');
        return;
      }

      const dropped = await collectDroppedFilesWithHandles(transfer);
      const collectedNames = dropped.map((entry) => (
        entry && entry.file && entry.file.name ? entry.file.name : 'unknown'
      )).join('|');
      const handleCount = dropped.filter((entry) => entry && entry.handle).length;
      ToolboxShell.appendLog(
        `[MULTI_UPLOAD][DROP_COLLECTED] source=${sourceText} collected=${dropped.length} handleCount=${handleCount} names=${collectedNames || '-'}`,
      );

      if (!dropped.length) {
        console.info('[MULTI_UPLOAD][DROP_EMPTY]');
        setStatus('没有检测到可添加的文件');
        ToolboxShell.appendLog('[UPLOAD_DIAG][drop:empty]');
        return;
      }

      dropped.forEach((entry) => {
        const name = entry && entry.file && entry.file.name ? entry.file.name : 'unknown';
        if (entry && entry.handle) {
          if (isUploadDebugEnabled()) {
            ToolboxShell.appendLog(`[MULTI_UPLOAD][DROP_HANDLE] name=${name} handle=1`);
          }
        } else if (isUploadDebugEnabled()) {
          ToolboxShell.appendLog(`[MULTI_UPLOAD][DROP_HANDLE_MISSING] name=${name} fallback=session-file`);
        }
      });

      await addDroppedFilesToCurrentUploadProject(dropped, sourceText);
    }

    function bindMultiUploadDragDrop(uploadRootEl) {
      if (!(uploadRootEl instanceof HTMLElement) && uploadRootEl !== document) {
        return;
      }

      const isDocumentTarget = uploadRootEl === document;
      if (!isDocumentTarget && uploadRootEl.dataset.dragDropBound === '1') {
        return;
      }
      if (isDocumentTarget && uploadRootEl[UPLOAD_DRAG_BIND_CLEANUP_PROP]) {
        return;
      }

      if (!isDocumentTarget) {
        uploadRootEl.dataset.dragDropBound = '1';
      }

      const allowGlobalCapture = isDocumentTarget;

      function shouldHandleDragEvent(e) {
        if (!hasDraggedFiles(e)) {
          return false;
        }

        if (allowGlobalCapture) {
          e.preventDefault();
          if (e.dataTransfer) {
            e.dataTransfer.dropEffect = 'copy';
          }
          return true;
        }

        if (!isEventInToolbox(e)) {
          return false;
        }

        const now = Date.now();
        if (now - lastMultiUploadDragProcessAt < MULTI_UPLOAD_DRAG_OVER_THROTTLE_MS) {
          return false;
        }
        lastMultiUploadDragProcessAt = now;
        return prepareUploadDragEvent(e, { source: 'toolbox' });
      }

      function onDragEnter(e) {
        if (!shouldHandleDragEvent(e)) {
          return;
        }

        if (allowGlobalCapture) {
          return;
        }

        const depth = adjustMultiUploadDragDepth(uploadRootEl, 1);
        if (depth === 1) {
          setMultiUploadDragOverVisual(true);
        }

        if (isUploadDebugEnabled()) {
          const meta = getDragTransferMeta(e);
          console.info('[MULTI_UPLOAD][DRAG_ENTER]', {
            target: getDragEventTargetTag(e),
            has_files: meta.has_files,
            items_len: meta.items_len,
          });
        }
      }

      function onDragOver(e) {
        if (!hasDraggedFiles(e)) {
          return;
        }

        const now = Date.now();
        if (now - lastMultiUploadDragProcessAt < MULTI_UPLOAD_DRAG_OVER_THROTTLE_MS) {
          if (allowGlobalCapture) {
            e.preventDefault();
          }
          return;
        }
        lastMultiUploadDragProcessAt = now;

        if (!shouldHandleDragEvent(e)) {
          return;
        }

        if (now - lastMultiUploadDragOverLogAt >= MULTI_UPLOAD_DRAG_OVER_LOG_INTERVAL_MS) {
          lastMultiUploadDragOverLogAt = now;
          if (isUploadDebugEnabled()) {
            const meta = getDragTransferMeta(e);
            console.info('[MULTI_UPLOAD][DRAG_OVER]', {
              target: getDragEventTargetTag(e),
              has_files: meta.has_files,
              items_len: meta.items_len,
            });
          }
        }
      }

      function onDragLeave(e) {
        if (!hasDraggedFiles(e)) {
          return;
        }

        const related = e.relatedTarget instanceof Node ? e.relatedTarget : null;
        if (related && uploadRootEl.contains(related)) {
          return;
        }

        const depth = adjustMultiUploadDragDepth(uploadRootEl, -1);
        if (depth <= 0) {
          uploadRootEl[UPLOAD_DRAG_DEPTH_PROP] = 0;
          setMultiUploadDragOverVisual(false);
        }
      }

      async function onDrop(e) {
        if (!hasDraggedFiles(e)) {
          return;
        }

        if (allowGlobalCapture) {
          if (!prepareUploadDragEvent(e, { source: 'global-drop' })) {
            return;
          }
        } else if (!isEventInToolbox(e)) {
          return;
        } else if (!prepareUploadDragEvent(e, { source: 'toolbox-drop' })) {
          return;
        }

        uploadRootEl[UPLOAD_DRAG_DEPTH_PROP] = 0;
        setMultiUploadDragOverVisual(false);

        if (!claimUploadDropEvent(e, allowGlobalCapture ? 'global' : 'toolbox')) {
          return;
        }

        try {
          await handleUploadDropEvent(e, 'drag_drop_toolbox');
        } catch (error) {
          console.error('[MULTI_UPLOAD][DROP_ERROR]', {
            error_type: error && error.name,
            error: error && error.message,
            stack: error && error.stack,
          });
        }
      }

      uploadRootEl.addEventListener('dragenter', onDragEnter, true);
      uploadRootEl.addEventListener('dragover', onDragOver, true);
      uploadRootEl.addEventListener('dragleave', onDragLeave, true);
      uploadRootEl.addEventListener('drop', onDrop, true);

      uploadRootEl[UPLOAD_DRAG_BIND_CLEANUP_PROP] = () => {
        uploadRootEl.removeEventListener('dragenter', onDragEnter, true);
        uploadRootEl.removeEventListener('dragover', onDragOver, true);
        uploadRootEl.removeEventListener('dragleave', onDragLeave, true);
        uploadRootEl.removeEventListener('drop', onDrop, true);
        uploadRootEl[UPLOAD_DRAG_DEPTH_PROP] = 0;
        if (!isDocumentTarget) {
          delete uploadRootEl.dataset.dragDropBound;
        }
        delete uploadRootEl[UPLOAD_DRAG_BIND_CLEANUP_PROP];
      };
    }

    function unbindMultiUploadDragDrop(uploadRootEl) {
      if (!(uploadRootEl instanceof HTMLElement) && uploadRootEl !== document) {
        return;
      }

      const cleanup = uploadRootEl[UPLOAD_DRAG_BIND_CLEANUP_PROP];
      if (typeof cleanup === 'function') {
        cleanup();
      }
    }

    function bindGlobalDropTarget(target, name) {
      if (!target) {
        console.warn('[ChatGPT toolbox] bindGlobalDropTarget: target 为空', name);
        return;
      }

      bindMultiUploadDragDrop(target);
    }

    function unbindGlobalDropTarget(target) {
      unbindMultiUploadDragDrop(target);
    }

    function syncGlobalDocumentDropBinding() {
      const cfg = getCompactUiConfig();
      const enableGlobalCapture = !!(cfg && cfg.globalDropCaptureEnabled === true);

      if (enableGlobalCapture) {
        bindGlobalDropTarget(document, 'document');
        return;
      }

      if (typeof ToolboxShell !== 'undefined' && typeof ToolboxShell.appendLogIfChanged === 'function') {
        ToolboxShell.appendLogIfChanged(
          'UPLOAD_DND:GLOBAL_SKIP',
          'globalDropCaptureDisabled',
          '[UPLOAD_DND][GLOBAL_SKIP] reason=globalDropCaptureDisabled',
          5000,
        );
      }
      unbindGlobalDropTarget(document);
    }

    function bindAllMultiUploadDragDropTargets() {
      panelDropEl = document.getElementById(APP.panelId) || panelDropEl;
      uploadListCachedDropTargets = [];

      if (rootElRef) {
        bindMultiUploadDragDrop(rootElRef);

        const uploadSection = rootElRef.querySelector('.toolbox-upload-drop-zone');
        if (uploadSection) {
          bindMultiUploadDragDrop(uploadSection);
        }
      }

      if (listEl) {
        bindMultiUploadDragDrop(listEl);
      }

      if (panelDropEl) {
        bindMultiUploadDragDrop(panelDropEl);
      }

      const toolboxRoot = document.getElementById(APP.rootId);
      if (toolboxRoot && toolboxRoot !== panelDropEl) {
        bindMultiUploadDragDrop(toolboxRoot);
      }

      syncGlobalDocumentDropBinding();
    }

    function bindUploadDropTargets(rootEl) {
      if (rootEl) {
        bindMultiUploadDragDrop(rootEl);
      }
      bindAllMultiUploadDragDropTargets();
    }

    async function ensureDefaultGroupReady() {
      if (state.activeGroupId) return;

      if (!state.groups.length) {
        const defaultGroup = createDefaultGroup();

        state.groups = [defaultGroup];
        state.activeGroupId = defaultGroup.id;

        await persistGroups();
        savePageSelectedUploadGroupId(state.activeGroupId, 'ensure-default-upload-group-created');
        await awaitPersistQueueBriefly('ensureDefaultGroupReady', 300);

        saveCurrentToolboxBaseState('ensure-default-upload-group');

        render();
        return;
      }

      const preferred = resolveUploadGroupSelection({
        reason: 'ensure-default-upload-group',
      });

      state.activeGroupId = preferred.resolvedGroupId || '';

      if (state.activeGroupId) {
        savePageSelectedUploadGroupId(state.activeGroupId, 'ensure-default-upload-group');
      }

      ToolboxShell.appendLog(
        `[UPLOAD_PAGE_STATE][ensure-default-group] groupId=${state.activeGroupId || '-'} source=${preferred.reason || '-'}`,
      );

      saveCurrentToolboxBaseState('ensure-default-upload-group');

      await loadQueueForActiveGroup();

      render();
    }
    function buildQueueFileKey(fileOrItem) {
      if (!fileOrItem) return '';

      const name = String(fileOrItem.name || '').trim().toLowerCase();
      const size = Number(fileOrItem.size) || 0;
      const lastModified = Number(fileOrItem.lastModified) || 0;
      const type = String(fileOrItem.type || '').trim().toLowerCase();
      const path = String(
        fileOrItem.webkitRelativePath
        || fileOrItem.displayPath
        || '',
      ).trim().toLowerCase();

      if (!name && !size && !lastModified && !path) {
        return '';
      }

      return `${name}::${size}::${lastModified}::${type}::${path}`;
    }


    function buildQueueLooseFileKey(fileOrItem) {
      if (!fileOrItem) return '';

      const name = String(fileOrItem.name || '').trim().toLowerCase();
      const size = Number(fileOrItem.size) || 0;

      if (!name && !size) {
        return '';
      }

      return `${name}::${size}`;
    }

    function getExistingComposerAttachmentNameSizeKeys(source) {
      const nameKeys = new Set();
      const nameSizeKeys = new Set();
      const sourceText = String(source || 'unknown');

      if (
        typeof ComposerApi !== 'undefined'
        && ComposerApi
        && typeof ComposerApi.getComposerAttachmentSnapshot === 'function'
      ) {
        try {
          const snap = ComposerApi.getComposerAttachmentSnapshot(`existing-attach:${sourceText}`) || {};
          const items = Array.isArray(snap.items) ? snap.items : [];
          for (const item of items) {
            const name = String(item && item.name || '').trim().toLowerCase();
            if (name) {
              nameKeys.add(name);
            }
          }
        } catch (err) {
          console.error('[ChatGPT toolbox] getExistingComposerAttachmentNameSizeKeys snapshot failed', err);
        }
      }

      if (
        typeof ComposerAttachments !== 'undefined'
        && ComposerAttachments
        && typeof ComposerAttachments.getSharedComposerAttachmentEvidence === 'function'
      ) {
        try {
          const evidence = ComposerAttachments.getSharedComposerAttachmentEvidence(`existing-attach:${sourceText}`) || {};
          const filenames = Array.isArray(evidence.filenames) ? evidence.filenames : [];
          filenames.forEach((rawName) => {
            const name = String(rawName || '').trim().toLowerCase();
            if (name) {
              nameKeys.add(name);
            }
          });
        } catch (err) {
          console.error('[ChatGPT toolbox] getExistingComposerAttachmentNameSizeKeys evidence failed', err);
        }
      }

      return { nameKeys, nameSizeKeys };
    }

    function isFileAlreadyAttachedInComposer(file, existing) {
      if (!file || !existing) {
        return false;
      }

      const looseKey = buildQueueLooseFileKey(file);
      if (looseKey && existing.nameSizeKeys.has(looseKey)) {
        return true;
      }

      const name = String(file.name || '').trim().toLowerCase();
      return !!(name && existing.nameKeys.has(name));
    }

    function filterFilesForComposerAttach(files, source) {
      const existing = getExistingComposerAttachmentNameSizeKeys(source);
      const toAttach = [];
      const skipped = [];

      for (const file of files || []) {
        if (!file) {
          continue;
        }
        if (isFileAlreadyAttachedInComposer(file, existing)) {
          skipped.push(file);
          continue;
        }
        toAttach.push(file);
        const looseKey = buildQueueLooseFileKey(file);
        const name = String(file.name || '').trim().toLowerCase();
        if (looseKey) {
          existing.nameSizeKeys.add(looseKey);
        }
        if (name) {
          existing.nameKeys.add(name);
        }
      }

      return {
        toAttach,
        skipped,
        existingCount: existing.nameKeys.size,
      };
    }

    function resolveQueueDedupeKey(item, options = {}) {
      const strongOnly = options.strongOnly === true;
      const strongKey = buildQueueFileKey(item);
      if (strongKey) {
        return { key: strongKey, keyKind: 'strong' };
      }
      if (strongOnly) {
        return { key: '', keyKind: '' };
      }
      const looseKey = buildQueueLooseFileKey(item);
      if (looseKey) {
        return { key: looseKey, keyKind: 'loose' };
      }
      return { key: '', keyKind: '' };
    }

    function dedupeActiveGroupQueue(reason, options = {}) {
      const groupId = state.activeGroupId;
      if (!groupId || !Array.isArray(state.queue)) return;
      const strongOnly = options.strongOnly === true;
      const seen = new Map();
      const keep = [];
      for (const item of state.queue) {
        if (!item || item.groupId !== groupId) {
          keep.push(item);
          continue;
        }
        const { key, keyKind } = resolveQueueDedupeKey(item, { strongOnly });
        if (!key) {
          keep.push(item);
          continue;
        }
        if (seen.has(key)) {
          const id = item.id || item._uploadId || '?';
          const removedId = id;
          const oldId = seen.get(key) || '-';
          const strongKey = buildQueueFileKey(item);
          const looseKey = buildQueueLooseFileKey(item);
          ToolboxShell.appendLog(
            `[UPLOAD_DIAG][dedupe-active-group:remove] reason=${reason} keyKind=${keyKind} name=${item.name || '-'} size=${item.size || 0} lastModified=${item.lastModified || 0} type=${item.type || item.mimeType || '-'} strongKey=${strongKey || '-'} looseKey=${looseKey || '-'} oldId=${oldId} removedId=${removedId}`,
          );
          continue;
        }
        seen.set(key, item.id || item._uploadId || '?');
        keep.push(item);
      }
      state.queue = keep;
    }

    async function addFiles(files, options = {}) {
      const addFilesStartedAt = (typeof performance !== 'undefined' && performance.now)
        ? performance.now()
        : Date.now();
      enterUploadCriticalMode('addFiles');

      const cleanFiles = Array.from(files || []).filter(Boolean);
      const handles = Array.isArray(options.handles) ? options.handles : [];
      const noHandleReadMode = options.noHandleReadMode
        ? String(options.noHandleReadMode).trim()
        : 'snapshot';

      if (!ensureActiveUploadGroupIdValid('add-files')) {
        if (!state.groups.length) {
          await ensureDefaultGroupReady();
        }
      }

      if (!state.activeGroupId) {
        setStatus('请先选择文件组');
        console.warn('[ChatGPT toolbox] addFiles blocked: activeGroupId empty');
        appendUploadGroupLog('ADD_FILE', { phase: 'blocked', reason: 'empty-activeGroupId' });
        return;
      }

      const existingKeys = new Set(
        state.queue
          .filter((item) => item.groupId === state.activeGroupId)
          .map((item) => buildQueueFileKey(item))
          .filter(Boolean)
      );

      const existingLooseKeys = new Set(
        state.queue
          .filter((item) => item.groupId === state.activeGroupId)
          .map((item) => buildQueueLooseFileKey(item))
          .filter(Boolean)
      );

      let addedCount = 0;

      cleanFiles.forEach((file, index) => {
        const fileKey = buildQueueFileKey(file);
        const fileLooseKey = buildQueueLooseFileKey(file);

        if (fileKey && existingKeys.has(fileKey)) {
          ToolboxShell.appendLog(
            `[UPLOAD_DIAG][add-file-skip-duplicate] index=${index} reason=strong-key name=${file.name || '-'} size=${file.size || 0} lastModified=${file.lastModified || 0} type=${file.type || '-'} fileKey=${fileKey}`,
          );
          return;
        }

        const handle = handles[index] || null;
        const hasHandle = isFileHandleLike(handle);
        const fileSize = Number(file.size) || 0;
        const canPersistBlob = isPersistUploadBlobEnabled()
          && fileSize > 0
          && fileSize <= APP.uploadBlobMaxBytes;

        const item = normalizeUploadItem({
          id: newId(),
          groupId: state.activeGroupId,
          name: file.name || 'unknown',
          size: file.size || 0,
          mimeType: file.type || 'application/octet-stream',
          type: file.type || 'application/octet-stream',
          lastModified: file.lastModified || Date.now(),
          file,
          sourceFile: file,
          originalFile: file,
          blob: file,
          sourceBlob: file,
          fileHandle: hasHandle ? handle : null,
          sourceKind: hasHandle
            ? 'local-handle'
            : (canPersistBlob ? 'cached-snapshot' : 'session-file'),
          readMode: hasHandle
            ? 'handle'
            : (canPersistBlob ? 'indexeddb-blob' : noHandleReadMode),
          state: UploadState.IDLE,
          status: 'pending',
          message: '',
          persistedKind: hasHandle
            ? UploadPersistedKind.FILE_SYSTEM_HANDLE
            : UploadPersistedKind.METADATA_ONLY,
          restoreState: UploadRestoreState.READY,
          handleKey: '',
          uploadName: '',
          persistedAttached: false,
        }, {
          groupId: state.activeGroupId,
        });
        item.handleKey = buildUploadHandleKey(item);

        state.queue.push(item);

        if (fileKey) {
          existingKeys.add(fileKey);
        }

        if (fileLooseKey) {
          existingLooseKeys.add(fileLooseKey);
        }

        addedCount += 1;

        if (isUploadDebugEnabled()) {
          ToolboxShell.appendLog(
            `[UPLOAD_DIAG][add-file] index=${index} name=${item.name || '-'} size=${item.size || 0} handle=${hasHandle ? 1 : 0} sourceKind=${item.sourceKind} readMode=${item.readMode}`,
          );
        }
      });

      dedupeActiveGroupQueue('add-files');
      syncActiveGroupCountInCache();

      setQueueRestorePhase('ready', {
        groupId: state.activeGroupId,
        loadedOnce: true,
        reason: 'add-files',
      });

      schedulePersistQueueLight('addFiles', 1500);
      scheduleRefreshUploadGroupCountsLight('addFiles', 2000);

      if (addedCount > 0) {
        const lastAdded = getActiveGroupFiles()[getActiveGroupFiles().length - 1];
        if (lastAdded && lastAdded.id) {
          setSelectedFileIdForActiveGroup(lastAdded.id, { reason: 'add-files' });
        }
      }

      renderUploadButtonsOnly({
        heavy: false,
        skipCapabilityScan: true,
        scope: 'upload-only',
        buttonTasksReason: 'addFiles-fast',
      });

      renderToolboxTopStatus({
        heavy: false,
        reason: 'addFiles-fast',
      });

      scheduleRenderUploadListOnly('addFiles-fast', 800);

      if (isUploadDebugEnabled()) {
        ToolboxShell.appendLog(
          `[UPLOAD_DIAG][addFiles:done] count=${addedCount} queue=${getActiveGroupFiles().length} group=${state.activeGroupId || '-'}`,
        );
      }
      if (addedCount > 0) {
        broadcastUploadGlobalStateChanged('add-files', {
          groupId: state.activeGroupId || '',
          addedCount,
        });
      }
      syncUploadGroupAppState();
      appendUploadGroupLog('ADD_FILE', {
        addedCount,
        groupId: state.activeGroupId || '-',
      });
      logSlowOperation('addFiles', addFilesStartedAt, `count=${addedCount}`);
    }


